const MODULE_DIR =
  typeof __dirname === "string" && __dirname ? __dirname : path.dirname(fileURLToPath(import.meta.url));
const RECENT_AGENT_ACTION_WINDOW_MS = 15 * 60 * 1000;

function looksLikeAuroraProjectRoot(candidate: string): boolean {
  return (
    existsSync(path.join(candidate, "package.json")) &&
    existsSync(path.join(candidate, "app")) &&
    existsSync(path.join(candidate, "lib"))
  );
}

function resolveAuroraProjectRoot(): string {
  const seeds = [process.cwd(), MODULE_DIR];

  for (const seed of seeds) {
    let cursor = path.resolve(seed);
    let previous = "";
    while (cursor !== previous) {
      if (looksLikeAuroraProjectRoot(cursor)) {
        return cursor;
      }
      previous = cursor;
      cursor = path.dirname(cursor);
    }
  }

  return path.resolve(process.cwd());
}

const PROJECT_ROOT = resolveAuroraProjectRoot();
const LEGACY_ROUTE_RUNTIME_DIR = path.join(path.resolve(MODULE_DIR, ".."), ".aurora");
const PROJECT_RUNTIME_DIR = path.join(PROJECT_ROOT, "runtime");
const PROJECT_MEMORY_DIR = path.join(PROJECT_ROOT, "MEMORY");
const PROJECT_HEALTH_RUNTIME_DIR = path.join(PROJECT_RUNTIME_DIR, "health");
const PROJECT_SELF_AWARENESS_RUNTIME_DIR = path.join(PROJECT_RUNTIME_DIR, "self-awareness");
const PROJECT_WORLD_PRESENCE_RUNTIME_DIR = path.join(PROJECT_RUNTIME_DIR, "world", "presence");

function uniquePathList(values: string[]): string[] {
  return Array.from(new Set(values.map((value) => value.trim()).filter(Boolean)));
}

function isRetriableAuroraIoError(error: unknown): boolean {
  if (!error || typeof error !== "object") {
    return false;
  }
  const errno = error as NodeJS.ErrnoException;
  const code = typeof errno.code === "string" ? errno.code.trim().toUpperCase() : "";
  const message = errno instanceof Error ? errno.message : String(error);
  return code === "EAGAIN" || /unknown system error -11|resource temporarily unavailable/i.test(message);
}

function auroraIoErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function annotateAuroraIoError(error: unknown, label: string): Error {
  const wrapped = new Error(`${label}: ${auroraIoErrorMessage(error)}`);
  const errno = error as NodeJS.ErrnoException;
  if (typeof errno?.code === "string" && errno.code.trim()) {
    (wrapped as NodeJS.ErrnoException).code = errno.code;
  }
  return wrapped;
}

function isSoftAuroraPersistenceError(error: unknown): boolean {
  const message = auroraIoErrorMessage(error);
  return (
    isRetriableAuroraIoError(error) ||
    /unknown system error -11|resource temporarily unavailable/i.test(message)
  );
}

function sleepIoRetry(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const AURORA_IO_RETRY_DELAYS_MS = [40, 120, 300] as const;

async function withAuroraIoRetry<T>(operation: () => Promise<T>, label = "aurora_io"): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt <= AURORA_IO_RETRY_DELAYS_MS.length; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      if (!isRetriableAuroraIoError(error) || attempt === AURORA_IO_RETRY_DELAYS_MS.length) {
        throw annotateAuroraIoError(error, label);
      }
      await sleepIoRetry(AURORA_IO_RETRY_DELAYS_MS[attempt]);
    }
  }
  throw annotateAuroraIoError(lastError, label);
}

function legacyRuntimeDirCandidates(): string[] {
  const candidates = [LEGACY_ROUTE_RUNTIME_DIR];
  const compiledApiRoot = path.join(PROJECT_ROOT, ".next", "server", "app", "api");

  if (existsSync(compiledApiRoot)) {
    for (const entry of readdirSync(compiledApiRoot, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        candidates.push(path.join(compiledApiRoot, entry.name, ".aurora"));
      }
    }
  }

  return uniquePathList(candidates).filter((candidate) => candidate !== path.join(PROJECT_ROOT, ".aurora"));
}

