function nowIso(): string {
  return new Date().toISOString();
}

function isTelegramDirectSessionId(sessionId: string | undefined): boolean {
  const normalized = sessionId?.trim() || "";
  return /^agent:[^:]+:telegram:direct:/i.test(normalized);
}

function isCronSessionId(sessionId: string | undefined): boolean {
  const normalized = sessionId?.trim() || "";
  return /^agent:[^:]+:cron:/i.test(normalized);
}

function isOwnerDirectIngressSessionId(sessionId: string | undefined): boolean {
  const normalized = sessionId?.trim() || "";
  if (!normalized) {
    return false;
  }
  const lower = normalized.toLowerCase();
  return (
    lower === OWNER_DASHBOARD_SESSION_ID ||
    lower === OWNER_APP_OPENRESPONSES_SESSION_ID ||
    OWNER_DIRECT_CONTINUITY_SESSION_IDS.has(lower)
  );
}

function canonicalContinuitySessionId(sessionId: string | undefined): string {
  const normalized = sessionId?.trim() || "";
  if (!normalized) {
    return "";
  }
  const lower = normalized.toLowerCase();
  if (
    lower === OWNER_DASHBOARD_SESSION_ID ||
    lower === OWNER_APP_OPENRESPONSES_SESSION_ID ||
    OWNER_DIRECT_CONTINUITY_SESSION_IDS.has(lower)
  ) {
    return OWNER_UNIFIED_CONTINUITY_SESSION_ID;
  }
  return normalized;
}

function isOwnerUnifiedContinuitySessionId(sessionId: string | undefined): boolean {
  return canonicalContinuitySessionId(sessionId) === OWNER_UNIFIED_CONTINUITY_SESSION_ID;
}

function ownerInteractiveConversationLaneKey(sessionId: string | undefined): string {
  const normalized = sessionId?.trim() || "";
  if (!normalized) {
    return "";
  }
  const lower = normalized.toLowerCase();
  if (lower === OWNER_DASHBOARD_SESSION_ID || lower === OWNER_APP_OPENRESPONSES_SESSION_ID) {
    return "owner_dashboard";
  }
  if (isTelegramDirectSessionId(normalized) || OWNER_DIRECT_CONTINUITY_SESSION_IDS.has(lower)) {
    return `owner_telegram:${lower}`;
  }
  if (isOwnerUnifiedContinuitySessionId(normalized)) {
    return "owner_unified";
  }
  return canonicalContinuitySessionId(normalized) || lower;
}

function markOwnerInteractiveConversation(sessionId: string | undefined): void {
  const laneKey = ownerInteractiveConversationLaneKey(sessionId);
  if (laneKey) {
    const nowMs = Date.now();
    lastOwnerInteractiveConversationAtMs = nowMs;
    lastOwnerInteractiveConversationByLaneMs.set(laneKey, nowMs);
  }
}

function shouldDeferLoopTickForActiveOwnerChat(): boolean {
  return lastOwnerInteractiveConversationAtMs > 0 && Date.now() - lastOwnerInteractiveConversationAtMs < ACTIVE_OWNER_CHAT_LOOP_DEFER_MS;
}

function hasRecentOwnerInteractiveConversation(windowMs: number, sessionId?: string | undefined): boolean {
  const laneKey = ownerInteractiveConversationLaneKey(sessionId);
  if (laneKey) {
    const lastAt = lastOwnerInteractiveConversationByLaneMs.get(laneKey) ?? 0;
    return lastAt > 0 && Date.now() - lastAt < windowMs;
  }
  return lastOwnerInteractiveConversationAtMs > 0 && Date.now() - lastOwnerInteractiveConversationAtMs < windowMs;
}

function looksLikeExplicitWorkRequest(text: string): boolean {
  const lower = text.toLowerCase();
  return includesAny(lower, EXPLICIT_WORK_REQUEST_MARKERS) || includesAny(lower, IMPLEMENTATION_DETAIL_MARKERS);
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function envFlag(name: string, fallback: boolean): boolean {
  const raw = process.env[name]?.trim().toLowerCase();
  if (!raw) {
    return fallback;
  }
  if (raw === "1" || raw === "true" || raw === "yes" || raw === "on") {
    return true;
  }
  if (raw === "0" || raw === "false" || raw === "no" || raw === "off") {
    return false;
  }
  return fallback;
}

