function ablationConfig(): AblationConfig {
  const enabled = envFlag("AURORA_ABLATION_ENABLED", false);
  const hardControl = envFlag("AURORA_ABLATION_HARD", true);
  const promptGrounding = envFlag("AURORA_ABLATION_PROMPT", true);
  let label: AblationVariantLabel = "full";
  if (enabled && hardControl && !promptGrounding) {
    label = "control_only";
  } else if (enabled && !hardControl && promptGrounding) {
    label = "prompt_only";
  } else if (enabled && !hardControl && !promptGrounding) {
    label = "baseline";
  }
  return {
    enabled,
    hardControl,
    promptGrounding,
    label
  };
}

