function applySeedNumberFields(
  target: Record<string, unknown>,
  seed: Record<string, number | string | undefined> | undefined,
  fields: string[]
): void {
  if (!seed) {
    return;
  }
  for (const field of fields) {
    const raw = seed[field];
    if (typeof raw !== "number" || !Number.isFinite(raw)) {
      continue;
    }
    if (field.toLowerCase().includes("warmth") || field.toLowerCase().includes("tension")) {
      target[field] = clampSigned(raw);
      continue;
    }
    target[field] = clamp(raw, 0, 1);
  }
}

