function relationshipChromaticNormalizedWeights(
  rawWeights: Partial<Record<RelationshipChromaticFamily, number>>
): Partial<Record<RelationshipChromaticFamily, number>> {
  const weights: Partial<Record<RelationshipChromaticFamily, number>> = {};
  for (const family of RELATIONSHIP_CHROMATIC_FAMILIES) {
    const value = rawWeights[family];
    if (typeof value === "number" && Number.isFinite(value) && value > 0.0001) {
      weights[family] = value;
    }
  }
  const total = Object.values(weights).reduce((sum, value) => sum + value, 0);
  if (total <= 0.0001) {
    return {};
  }
  return Object.fromEntries(
    Object.entries(weights).map(([family, value]) => [
      family,
      Number(((value as number) / total).toFixed(4))
    ])
  ) as Partial<Record<RelationshipChromaticFamily, number>>;
}

function relationshipChromaticDominantFamily(
  profile: RelationshipChromaticProfileState | null | undefined
): RelationshipChromaticFamily | null {
  if (!profile) {
    return null;
  }
  const entries = Object.entries(relationshipChromaticNormalizedWeights(profile.weightsByFamily))
    .filter((entry): entry is [RelationshipChromaticFamily, number] => typeof entry[1] === "number");
  if (entries.length === 0) {
    return null;
  }
  return entries.sort((left, right) => right[1] - left[1])[0]?.[0] ?? null;
}

