function defaultLearnedExperienceFeatureNames(): string[] {
  return [...LEARNED_EXPERIENCE_MANIFOLD_FEATURE_NAMES];
}

function learnedExperienceManifoldDims(): number {
  return LEARNED_EXPERIENCE_MANIFOLD_FEATURE_NAMES.length;
}

function seededUnitFloat(seed: string): number {
  const digest = createHash("sha1").update(seed).digest();
  return digest.readUInt32BE(0) / 0xffffffff;
}

function seededSignedFloat(seed: string): number {
  return seededUnitFloat(seed) * 2 - 1;
}

function defaultLearnedExperiencePrototype(createdAt: string, x: number, y: number): LearnedExperiencePrototype {
  const xNorm =
    LEARNED_EXPERIENCE_MANIFOLD_GRID_WIDTH <= 1 ? 0.5 : x / (LEARNED_EXPERIENCE_MANIFOLD_GRID_WIDTH - 1);
  const yNorm =
    LEARNED_EXPERIENCE_MANIFOLD_GRID_HEIGHT <= 1 ? 0.5 : y / (LEARNED_EXPERIENCE_MANIFOLD_GRID_HEIGHT - 1);
  const vector = defaultLearnedExperienceFeatureNames().map((featureName, index) => {
    const noise = seededUnitFloat(`${featureName}:${x}:${y}:${index}`);
    const axisBias =
      index % 4 === 0
        ? xNorm
        : index % 4 === 1
          ? yNorm
          : index % 4 === 2
            ? clamp((xNorm + yNorm) / 2, 0, 1)
            : clamp(1 - (xNorm + yNorm) / 2, 0, 1);
    return clamp(axisBias * 0.58 + noise * 0.42, 0, 1);
  });
  return {
    id: `xp_${x}_${y}`,
    x,
    y,
    vector,
    hits: 0,
    lastDistance: 0,
    lastUpdatedAt: createdAt,
    label: "untrained",
    exemplar: "",
    exemplarSource: "none",
    exemplarAt: null
  };
}

