function defaultLearnedExperienceManifoldState(createdAt: string): LearnedExperienceManifoldState {
  const prototypes: LearnedExperiencePrototype[] = [];
  for (let y = 0; y < LEARNED_EXPERIENCE_MANIFOLD_GRID_HEIGHT; y += 1) {
    for (let x = 0; x < LEARNED_EXPERIENCE_MANIFOLD_GRID_WIDTH; x += 1) {
      prototypes.push(defaultLearnedExperiencePrototype(createdAt, x, y));
    }
  }
  return {
    schemaVersion: "1.0",
    dims: learnedExperienceManifoldDims(),
    grid: {
      width: LEARNED_EXPERIENCE_MANIFOLD_GRID_WIDTH,
      height: LEARNED_EXPERIENCE_MANIFOLD_GRID_HEIGHT
    },
    featureNames: defaultLearnedExperienceFeatureNames(),
    prototypes,
    transitions: [],
    current: defaultLearnedExperienceCurrentState(createdAt),
    ema: defaultLearnedExperienceEMA(),
    history: [],
    training: defaultLearnedExperienceTrainingState(createdAt)
  };
}

function defaultOpaqueLatentVector(fill = 0): number[] {
  return new Array(OPAQUE_LATENT_E2E_DIM).fill(fill);
}

function defaultOpaqueLatentTokenEmbeddings(): number[][] {
  return Array.from({ length: OPAQUE_LATENT_E2E_TOKEN_BUCKETS }, (_, bucket) =>
    Array.from({ length: OPAQUE_LATENT_E2E_DIM }, (_, dim) =>
      Number((seededSignedFloat(`opaque_latent_token:${bucket}:${dim}`) * 0.08).toFixed(6))
    )
  );
}

function defaultOpaqueLatentSquareMatrix(label: string, diagonalBase: number, offDiagScale: number): number[][] {
  return Array.from({ length: OPAQUE_LATENT_E2E_DIM }, (_, row) =>
    Array.from({ length: OPAQUE_LATENT_E2E_DIM }, (_, col) => {
      if (row === col) {
        return Number((diagonalBase + seededSignedFloat(`${label}:diag:${row}`) * 0.04).toFixed(6));
      }
      return Number((seededSignedFloat(`${label}:${row}:${col}`) * offDiagScale).toFixed(6));
    })
  );
}

