function defaultUnifiedManifold32Vector(fill = 0): number[] {
  return new Array(LEARNED_UNIFIED_MANIFOLD_32_DIM).fill(fill);
}

function defaultUnifiedManifold32FeatureVector(fill = 0): number[] {
  return new Array(LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.length).fill(fill);
}

function defaultUnifiedManifold32Matrix(label: string, rows: number, cols: number, scale: number, diagonalBase = 0): number[][] {
  return Array.from({ length: rows }, (_, row) =>
    Array.from({ length: cols }, (_, col) => {
      if (rows === cols && row === col) {
        return Number((diagonalBase + seededSignedFloat(`${label}:diag:${row}`) * scale).toFixed(6));
      }
      return Number((seededSignedFloat(`${label}:${row}:${col}`) * scale).toFixed(6));
    })
  );
}

