function clampSigned(value: number): number {
  return clamp(value, -1, 1);
}

function mean(values: number[]): number {
  if (!values.length) {
    return 0;
  }
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function blendSigned(current: number, target: number, rate: number): number {
  return clampSigned(current + (target - current) * clamp(rate, 0, 1));
}

function positiveAxis(axis: number): number {
  return clamp((axis + 1) / 2, 0, 1);
}

function negativeAxis(axis: number): number {
  return clamp((-axis + 1) / 2, 0, 1);
}

