function coercePredictiveObservationFeatures(
  input: unknown,
  fallback: PredictiveObservationFeatures
): PredictiveObservationFeatures {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return { ...fallback };
  }
  const record = input as Record<string, unknown>;
  const channelValue = typeof record.channel === "string" ? record.channel.toLowerCase() : "";
  const channel: PredictiveObservationChannel = (
    ["user", "tool", "system", "assistant", "unknown"] as PredictiveObservationChannel[]
  ).includes(channelValue as PredictiveObservationChannel)
    ? (channelValue as PredictiveObservationChannel)
    : fallback.channel;
  const intentValue = typeof record.intentClass === "string" ? record.intentClass.toLowerCase() : "";
  const intentClass: PredictiveIntentClass = (
    ["question", "request", "affect", "repair", "confirm", "identity", "meta", "status", "error", "other"] as PredictiveIntentClass[]
  ).includes(intentValue as PredictiveIntentClass)
    ? (intentValue as PredictiveIntentClass)
    : fallback.intentClass;
  return {
    channel,
    intentClass,
    urgency: clamp(typeof record.urgency === "number" && Number.isFinite(record.urgency) ? record.urgency : fallback.urgency, 0, 1),
    topicKey:
      typeof record.topicKey === "string" && record.topicKey.trim()
        ? toSingleLine(record.topicKey, 64)
        : fallback.topicKey,
    topicHint:
      typeof record.topicHint === "string" && record.topicHint.trim()
        ? toSingleLine(record.topicHint, 96)
        : fallback.topicHint,
    valence: clampSigned(
      typeof record.valence === "number" && Number.isFinite(record.valence) ? record.valence : fallback.valence
    ),
    explicitPromise: typeof record.explicitPromise === "boolean" ? record.explicitPromise : fallback.explicitPromise,
    confidence: clamp(
      typeof record.confidence === "number" && Number.isFinite(record.confidence) ? record.confidence : fallback.confidence,
      0,
      1
    )
  };
}

function coerceUnitVector(input: unknown, dims: number, fallback: number[]): number[] {
  const fallbackVector = fallback.slice(0, dims);
  while (fallbackVector.length < dims) {
    fallbackVector.push(0.5);
  }
  if (!Array.isArray(input)) {
    return fallbackVector;
  }
  const vector = input
    .slice(0, dims)
    .map((value, index) =>
      clamp(
        typeof value === "number" && Number.isFinite(value) ? value : fallbackVector[index] ?? 0.5,
        0,
        1
      )
    );
  while (vector.length < dims) {
    vector.push(fallbackVector[vector.length] ?? 0.5);
  }
  return vector;
}

function coerceLearnedExperiencePrototype(
  input: unknown,
  fallback: LearnedExperiencePrototype,
  dims: number
): LearnedExperiencePrototype {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      vector: fallback.vector.slice()
    };
  }
  const record = input as Record<string, unknown>;
  return {
    id: typeof record.id === "string" && record.id.trim() ? toSingleLine(record.id, 40) : fallback.id,
    x: Math.max(0, Math.round(typeof record.x === "number" && Number.isFinite(record.x) ? record.x : fallback.x)),
    y: Math.max(0, Math.round(typeof record.y === "number" && Number.isFinite(record.y) ? record.y : fallback.y)),
    vector: coerceUnitVector(record.vector, dims, fallback.vector),
    hits: Math.max(0, Math.round(typeof record.hits === "number" && Number.isFinite(record.hits) ? record.hits : fallback.hits)),
    lastDistance: clamp(
      typeof record.lastDistance === "number" && Number.isFinite(record.lastDistance)
        ? record.lastDistance
        : fallback.lastDistance,
      0,
      1
    ),
    lastUpdatedAt:
      typeof record.lastUpdatedAt === "string" && record.lastUpdatedAt.trim()
        ? record.lastUpdatedAt
        : fallback.lastUpdatedAt,
    label: typeof record.label === "string" ? toSingleLine(record.label, 80) : fallback.label,
    exemplar: typeof record.exemplar === "string" ? toSingleLine(record.exemplar, 180) : fallback.exemplar,
    exemplarSource:
      typeof record.exemplarSource === "string" ? toSingleLine(record.exemplarSource, 40) : fallback.exemplarSource,
    exemplarAt:
      typeof record.exemplarAt === "string" && record.exemplarAt.trim() ? record.exemplarAt : fallback.exemplarAt
  };
}

