function coerceHomeostaticOrganizationState(
  input: unknown,
  fallback: HomeostaticOrganizationState
): HomeostaticOrganizationState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      current: { ...fallback.current },
      ema: { ...fallback.ema },
      history: fallback.history.slice()
    };
  }
  const record = input as Record<string, unknown>;
  const currentRaw =
    record.current && typeof record.current === "object" && !Array.isArray(record.current)
      ? (record.current as Record<string, unknown>)
      : {};
  const emaRaw =
    record.ema && typeof record.ema === "object" && !Array.isArray(record.ema)
      ? (record.ema as Record<string, unknown>)
      : {};
  const validNeed = (value: unknown, fallbackNeed: HomeostaticNeedName): HomeostaticNeedName =>
    typeof value === "string" &&
    ["restoration", "coherence", "affiliation", "autonomy", "orientation", "stimulation"].includes(value)
      ? (value as HomeostaticNeedName)
      : fallbackNeed;
  const validSource = (value: unknown, fallbackSource: PhenomenalManifoldSource): PhenomenalManifoldSource =>
    typeof value === "string" &&
    ["conversation", "heartbeat", "tick", "preflight"].includes(value)
      ? (value as PhenomenalManifoldSource)
      : fallbackSource;
  const history = Array.isArray(record.history)
    ? record.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) {
            return null;
          }
          return {
            at,
            source: validSource(value.source, fallback.current.source),
            restorationNeed: clamp(Number(value.restorationNeed ?? fallback.current.restorationNeed), 0, 1),
            coherenceNeed: clamp(Number(value.coherenceNeed ?? fallback.current.coherenceNeed), 0, 1),
            affiliationNeed: clamp(Number(value.affiliationNeed ?? fallback.current.affiliationNeed), 0, 1),
            autonomyNeed: clamp(Number(value.autonomyNeed ?? fallback.current.autonomyNeed), 0, 1),
            orientationNeed: clamp(Number(value.orientationNeed ?? fallback.current.orientationNeed), 0, 1),
            stimulationNeed: clamp(Number(value.stimulationNeed ?? fallback.current.stimulationNeed), 0, 1),
            allostaticLoad: clamp(Number(value.allostaticLoad ?? fallback.current.allostaticLoad), 0, 1),
            regulationUrgency: clamp(Number(value.regulationUrgency ?? fallback.current.regulationUrgency), 0, 1),
            dominantNeed: validNeed(value.dominantNeed, fallback.current.dominantNeed)
          };
        })
        .filter((item): item is HomeostaticOrganizationState["history"][number] => Boolean(item))
        .slice(-PHENOMENAL_MANIFOLD_MAX_HISTORY)
    : fallback.history.slice();
  return {
    schemaVersion: "1.0",
    current: {
      source: validSource(currentRaw.source, fallback.current.source),
      restorationNeed: clamp(Number(currentRaw.restorationNeed ?? fallback.current.restorationNeed), 0, 1),
      coherenceNeed: clamp(Number(currentRaw.coherenceNeed ?? fallback.current.coherenceNeed), 0, 1),
      affiliationNeed: clamp(Number(currentRaw.affiliationNeed ?? fallback.current.affiliationNeed), 0, 1),
      autonomyNeed: clamp(Number(currentRaw.autonomyNeed ?? fallback.current.autonomyNeed), 0, 1),
      orientationNeed: clamp(Number(currentRaw.orientationNeed ?? fallback.current.orientationNeed), 0, 1),
      stimulationNeed: clamp(Number(currentRaw.stimulationNeed ?? fallback.current.stimulationNeed), 0, 1),
      allostaticLoad: clamp(Number(currentRaw.allostaticLoad ?? fallback.current.allostaticLoad), 0, 1),
      regulationUrgency: clamp(Number(currentRaw.regulationUrgency ?? fallback.current.regulationUrgency), 0, 1),
      dominantNeed: validNeed(currentRaw.dominantNeed, fallback.current.dominantNeed),
      updatedAt:
        typeof currentRaw.updatedAt === "string" && currentRaw.updatedAt.trim()
          ? currentRaw.updatedAt
          : fallback.current.updatedAt
    },
    ema: {
      restorationNeedEMA: clamp(Number(emaRaw.restorationNeedEMA ?? fallback.ema.restorationNeedEMA), 0, 1),
      coherenceNeedEMA: clamp(Number(emaRaw.coherenceNeedEMA ?? fallback.ema.coherenceNeedEMA), 0, 1),
      affiliationNeedEMA: clamp(Number(emaRaw.affiliationNeedEMA ?? fallback.ema.affiliationNeedEMA), 0, 1),
      autonomyNeedEMA: clamp(Number(emaRaw.autonomyNeedEMA ?? fallback.ema.autonomyNeedEMA), 0, 1),
      orientationNeedEMA: clamp(Number(emaRaw.orientationNeedEMA ?? fallback.ema.orientationNeedEMA), 0, 1),
      stimulationNeedEMA: clamp(Number(emaRaw.stimulationNeedEMA ?? fallback.ema.stimulationNeedEMA), 0, 1),
      allostaticLoadEMA: clamp(Number(emaRaw.allostaticLoadEMA ?? fallback.ema.allostaticLoadEMA), 0, 1),
      regulationUrgencyEMA: clamp(Number(emaRaw.regulationUrgencyEMA ?? fallback.ema.regulationUrgencyEMA), 0, 1)
    },
    history
  };
}

function coercePhenomenalManifoldProbeState(
  input: unknown,
  fallback: PhenomenalManifoldProbeState
): PhenomenalManifoldProbeState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      axes: { ...fallback.axes },
      ema: { ...fallback.ema },
      current: { ...fallback.current },
      history: fallback.history.slice()
    };
  }
  const record = input as Record<string, unknown>;
  const axesRaw = record.axes && typeof record.axes === "object" && !Array.isArray(record.axes) ? (record.axes as Record<string, unknown>) : {};
  const emaRaw = record.ema && typeof record.ema === "object" && !Array.isArray(record.ema) ? (record.ema as Record<string, unknown>) : {};
  const currentRaw =
    record.current && typeof record.current === "object" && !Array.isArray(record.current)
      ? (record.current as Record<string, unknown>)
      : {};
  const observerRaw =
    record.observer && typeof record.observer === "object" && !Array.isArray(record.observer)
      ? (record.observer as Record<string, unknown>)
      : {};
  const observerCurrentRaw =
    observerRaw.current && typeof observerRaw.current === "object" && !Array.isArray(observerRaw.current)
      ? (observerRaw.current as Record<string, unknown>)
      : {};
  const observerEmaRaw =
    observerRaw.ema && typeof observerRaw.ema === "object" && !Array.isArray(observerRaw.ema)
      ? (observerRaw.ema as Record<string, unknown>)
      : {};
  const observerHistory = Array.isArray(observerRaw.history)
    ? observerRaw.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) {
            return null;
          }
          const sourceValue = typeof value.source === "string" ? value.source : fallback.current.source;
          const source: PhenomenalManifoldSource = (
            ["conversation", "heartbeat", "tick", "preflight"] as PhenomenalManifoldSource[]
          ).includes(sourceValue as PhenomenalManifoldSource)
            ? (sourceValue as PhenomenalManifoldSource)
            : fallback.current.source;
          return {
            at,
            source,
            warmth: clampSigned(typeof value.warmth === "number" && Number.isFinite(value.warmth) ? value.warmth : 0),
            friction: clampSigned(
              typeof value.friction === "number" && Number.isFinite(value.friction) ? value.friction : 0
            ),
            certainty: clamp(
              typeof value.certainty === "number" && Number.isFinite(value.certainty) ? value.certainty : 0.5,
              0,
              1
            ),
            reportLabel:
              typeof value.reportLabel === "string" && value.reportLabel.trim()
                ? (toSingleLine(value.reportLabel.toUpperCase(), 24) as PhenomenalObserverCurrentState["reportLabel"])
                : "UNKNOWN",
            actionTendency:
              typeof value.actionTendency === "string" &&
              ["REACH", "CLARIFY", "WITHDRAW", "MONITOR"].includes(value.actionTendency.toUpperCase())
                ? (value.actionTendency.toUpperCase() as PhenomenalObserverCurrentState["actionTendency"])
                : "MONITOR",
            accessConfidence: clamp(
              typeof value.accessConfidence === "number" && Number.isFinite(value.accessConfidence)
                ? value.accessConfidence
                : 0.5,
              0,
              1
            ),
            policySelectivity: clamp(
              typeof value.policySelectivity === "number" && Number.isFinite(value.policySelectivity)
                ? value.policySelectivity
                : 0.5,
              0,
              1
            ),
            updatedAt:
              typeof value.updatedAt === "string" && value.updatedAt.trim() ? value.updatedAt : at
          };
        })
        .filter(
          (
            item
          ): item is PhenomenalManifoldProbeState["observer"]["history"][number] => Boolean(item)
        )
        .slice(-PHENOMENAL_MANIFOLD_MAX_HISTORY)
    : fallback.observer.history.slice();
  const history = Array.isArray(record.history)
    ? record.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) {
            return null;
          }
          const sourceValue = typeof value.source === "string" ? value.source : fallback.current.source;
          const source: PhenomenalManifoldSource = (
            ["conversation", "heartbeat", "tick", "preflight"] as PhenomenalManifoldSource[]
          ).includes(sourceValue as PhenomenalManifoldSource)
            ? (sourceValue as PhenomenalManifoldSource)
            : fallback.current.source;
          return {
            at,
            source,
            socialSafety: clampSigned(
              typeof value.socialSafety === "number" && Number.isFinite(value.socialSafety) ? value.socialSafety : 0
            ),
            cognitiveTension: clampSigned(
              typeof value.cognitiveTension === "number" && Number.isFinite(value.cognitiveTension)
                ? value.cognitiveTension
                : 0
            ),
            reportAccess: clamp(
              typeof value.reportAccess === "number" && Number.isFinite(value.reportAccess) ? value.reportAccess : 0.5,
              0,
              1
            ),
            warmth: clampSigned(typeof value.warmth === "number" && Number.isFinite(value.warmth) ? value.warmth : 0),
            friction: clampSigned(
              typeof value.friction === "number" && Number.isFinite(value.friction) ? value.friction : 0
            ),
            certainty: clamp(
              typeof value.certainty === "number" && Number.isFinite(value.certainty) ? value.certainty : 0.5,
              0,
              1
            ),
            reportLabel:
              typeof value.reportLabel === "string" && value.reportLabel.trim()
                ? toSingleLine(value.reportLabel.toUpperCase(), 24)
                : "UNKNOWN",
            actionTendency:
              typeof value.actionTendency === "string" &&
              ["REACH", "CLARIFY", "WITHDRAW", "MONITOR"].includes(value.actionTendency.toUpperCase())
                ? (value.actionTendency.toUpperCase() as "REACH" | "CLARIFY" | "WITHDRAW" | "MONITOR")
                : "MONITOR",
            label: typeof value.label === "string" ? toSingleLine(value.label, 80) : ""
          };
        })
        .filter((item): item is PhenomenalManifoldProbeState["history"][number] => Boolean(item))
        .slice(-PHENOMENAL_MANIFOLD_MAX_HISTORY)
    : fallback.history.slice();
  const currentSourceValue = typeof currentRaw.source === "string" ? currentRaw.source : fallback.current.source;
  const currentSource: PhenomenalManifoldSource = (
    ["conversation", "heartbeat", "tick", "preflight"] as PhenomenalManifoldSource[]
  ).includes(currentSourceValue as PhenomenalManifoldSource)
    ? (currentSourceValue as PhenomenalManifoldSource)
    : fallback.current.source;
  return {
    schemaVersion: "1.0",
    axes: {
      social_safety: clampSigned(
        typeof axesRaw.social_safety === "number" && Number.isFinite(axesRaw.social_safety)
          ? axesRaw.social_safety
          : fallback.axes.social_safety
      ),
      cognitive_tension: clampSigned(
        typeof axesRaw.cognitive_tension === "number" && Number.isFinite(axesRaw.cognitive_tension)
          ? axesRaw.cognitive_tension
          : fallback.axes.cognitive_tension
      )
    },
    ema: {
      socialSafetyEMA: clampSigned(
        typeof emaRaw.socialSafetyEMA === "number" && Number.isFinite(emaRaw.socialSafetyEMA)
          ? emaRaw.socialSafetyEMA
          : fallback.ema.socialSafetyEMA
      ),
      cognitiveTensionEMA: clampSigned(
        typeof emaRaw.cognitiveTensionEMA === "number" && Number.isFinite(emaRaw.cognitiveTensionEMA)
          ? emaRaw.cognitiveTensionEMA
          : fallback.ema.cognitiveTensionEMA
      ),
      reportAccessEMA: clamp(
        typeof emaRaw.reportAccessEMA === "number" && Number.isFinite(emaRaw.reportAccessEMA)
          ? emaRaw.reportAccessEMA
          : fallback.ema.reportAccessEMA,
        0,
        1
      )
    },
    current: {
      label: typeof currentRaw.label === "string" ? toSingleLine(currentRaw.label, 80) : fallback.current.label,
      source: currentSource,
      reportAccess: clamp(
        typeof currentRaw.reportAccess === "number" && Number.isFinite(currentRaw.reportAccess)
          ? currentRaw.reportAccess
          : fallback.current.reportAccess,
        0,
        1
      ),
      warmth: clampSigned(
        typeof currentRaw.warmth === "number" && Number.isFinite(currentRaw.warmth)
          ? currentRaw.warmth
          : fallback.current.warmth
      ),
      friction: clampSigned(
        typeof currentRaw.friction === "number" && Number.isFinite(currentRaw.friction)
          ? currentRaw.friction
          : fallback.current.friction
      ),
      certainty: clamp(
        typeof currentRaw.certainty === "number" && Number.isFinite(currentRaw.certainty)
          ? currentRaw.certainty
          : fallback.current.certainty,
        0,
        1
      ),
      reportLabel:
        typeof currentRaw.reportLabel === "string" && currentRaw.reportLabel.trim()
          ? toSingleLine(currentRaw.reportLabel.toUpperCase(), 24)
          : fallback.current.reportLabel,
      actionTendency:
        typeof currentRaw.actionTendency === "string" &&
        ["REACH", "CLARIFY", "WITHDRAW", "MONITOR"].includes(currentRaw.actionTendency.toUpperCase())
          ? (currentRaw.actionTendency.toUpperCase() as "REACH" | "CLARIFY" | "WITHDRAW" | "MONITOR")
          : fallback.current.actionTendency,
      memoryBias: clamp(
        typeof currentRaw.memoryBias === "number" && Number.isFinite(currentRaw.memoryBias)
          ? currentRaw.memoryBias
          : fallback.current.memoryBias,
        0,
        1
      ),
      attentionBias: clamp(
        typeof currentRaw.attentionBias === "number" && Number.isFinite(currentRaw.attentionBias)
          ? currentRaw.attentionBias
          : fallback.current.attentionBias,
        0,
        1
      ),
      valuationBias: clamp(
        typeof currentRaw.valuationBias === "number" && Number.isFinite(currentRaw.valuationBias)
          ? currentRaw.valuationBias
          : fallback.current.valuationBias,
        0,
        1
      ),
      updatedAt:
        typeof currentRaw.updatedAt === "string" && currentRaw.updatedAt.trim()
          ? currentRaw.updatedAt
          : fallback.current.updatedAt
    },
    observer: {
      current: {
        warmth: clampSigned(
          typeof observerCurrentRaw.warmth === "number" && Number.isFinite(observerCurrentRaw.warmth)
            ? observerCurrentRaw.warmth
            : fallback.observer.current.warmth
        ),
        friction: clampSigned(
          typeof observerCurrentRaw.friction === "number" && Number.isFinite(observerCurrentRaw.friction)
            ? observerCurrentRaw.friction
            : fallback.observer.current.friction
        ),
        certainty: clamp(
          typeof observerCurrentRaw.certainty === "number" && Number.isFinite(observerCurrentRaw.certainty)
            ? observerCurrentRaw.certainty
            : fallback.observer.current.certainty,
          0,
          1
        ),
        reportLabel:
          typeof observerCurrentRaw.reportLabel === "string" && observerCurrentRaw.reportLabel.trim()
            ? (toSingleLine(
                observerCurrentRaw.reportLabel.toUpperCase(),
                24
              ) as PhenomenalObserverCurrentState["reportLabel"])
            : fallback.observer.current.reportLabel,
        actionTendency:
          typeof observerCurrentRaw.actionTendency === "string" &&
          ["REACH", "CLARIFY", "WITHDRAW", "MONITOR"].includes(observerCurrentRaw.actionTendency.toUpperCase())
            ? (observerCurrentRaw.actionTendency.toUpperCase() as PhenomenalObserverCurrentState["actionTendency"])
            : fallback.observer.current.actionTendency,
        accessConfidence: clamp(
          typeof observerCurrentRaw.accessConfidence === "number" &&
            Number.isFinite(observerCurrentRaw.accessConfidence)
            ? observerCurrentRaw.accessConfidence
            : fallback.observer.current.accessConfidence,
          0,
          1
        ),
        policySelectivity: clamp(
          typeof observerCurrentRaw.policySelectivity === "number" &&
            Number.isFinite(observerCurrentRaw.policySelectivity)
            ? observerCurrentRaw.policySelectivity
            : fallback.observer.current.policySelectivity,
          0,
          1
        ),
        updatedAt:
          typeof observerCurrentRaw.updatedAt === "string" && observerCurrentRaw.updatedAt.trim()
            ? observerCurrentRaw.updatedAt
            : fallback.observer.current.updatedAt
      },
      ema: {
        warmthEMA: clampSigned(
          typeof observerEmaRaw.warmthEMA === "number" && Number.isFinite(observerEmaRaw.warmthEMA)
            ? observerEmaRaw.warmthEMA
            : fallback.observer.ema.warmthEMA
        ),
        frictionEMA: clampSigned(
          typeof observerEmaRaw.frictionEMA === "number" && Number.isFinite(observerEmaRaw.frictionEMA)
            ? observerEmaRaw.frictionEMA
            : fallback.observer.ema.frictionEMA
        ),
        certaintyEMA: clamp(
          typeof observerEmaRaw.certaintyEMA === "number" && Number.isFinite(observerEmaRaw.certaintyEMA)
            ? observerEmaRaw.certaintyEMA
            : fallback.observer.ema.certaintyEMA,
          0,
          1
        ),
        accessConfidenceEMA: clamp(
          typeof observerEmaRaw.accessConfidenceEMA === "number" &&
            Number.isFinite(observerEmaRaw.accessConfidenceEMA)
            ? observerEmaRaw.accessConfidenceEMA
            : fallback.observer.ema.accessConfidenceEMA,
          0,
          1
        ),
        policySelectivityEMA: clamp(
          typeof observerEmaRaw.policySelectivityEMA === "number" &&
            Number.isFinite(observerEmaRaw.policySelectivityEMA)
            ? observerEmaRaw.policySelectivityEMA
            : fallback.observer.ema.policySelectivityEMA,
          0,
          1
        )
      },
      history: observerHistory
    },
    history
  };
}

function coerceLearnedUnifiedManifold32State(
  input: unknown,
  fallback: LearnedUnifiedManifold32State
): LearnedUnifiedManifold32State {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      featureNames: fallback.featureNames.slice(),
      current: {
        ...fallback.current,
        vector: fallback.current.vector.slice()
      },
      readout: {
        current: { ...fallback.readout.current },
        ema: { ...fallback.readout.ema },
        history: fallback.readout.history.slice()
      },
      ema: { ...fallback.ema },
      history: fallback.history.slice(),
      sourceTelemetry: {
        conversation: {
          current: {
            ...fallback.sourceTelemetry.conversation.current,
            vector: fallback.sourceTelemetry.conversation.current.vector.slice()
          },
          history: fallback.sourceTelemetry.conversation.history.slice()
        },
        heartbeat: {
          current: {
            ...fallback.sourceTelemetry.heartbeat.current,
            vector: fallback.sourceTelemetry.heartbeat.current.vector.slice()
          },
          history: fallback.sourceTelemetry.heartbeat.history.slice()
        },
        tick: {
          current: {
            ...fallback.sourceTelemetry.tick.current,
            vector: fallback.sourceTelemetry.tick.current.vector.slice()
          },
          history: fallback.sourceTelemetry.tick.history.slice()
        },
        preflight: {
          current: {
            ...fallback.sourceTelemetry.preflight.current,
            vector: fallback.sourceTelemetry.preflight.current.vector.slice()
          },
          history: fallback.sourceTelemetry.preflight.history.slice()
        }
      },
      training: {
        ...fallback.training,
        encoder: fallback.training.encoder.map((row) => row.slice()),
        recurrent: fallback.training.recurrent.map((row) => row.slice()),
        decoder: fallback.training.decoder.map((row) => row.slice()),
        bias: fallback.training.bias.slice()
      }
    };
  }
  const record = input as Record<string, unknown>;
  const currentRaw =
    record.current && typeof record.current === "object" && !Array.isArray(record.current)
      ? (record.current as Record<string, unknown>)
      : {};
  const readoutRaw =
    record.readout && typeof record.readout === "object" && !Array.isArray(record.readout)
      ? (record.readout as Record<string, unknown>)
      : {};
  const readoutCurrentRaw =
    readoutRaw.current && typeof readoutRaw.current === "object" && !Array.isArray(readoutRaw.current)
      ? (readoutRaw.current as Record<string, unknown>)
      : {};
  const readoutEmaRaw =
    readoutRaw.ema && typeof readoutRaw.ema === "object" && !Array.isArray(readoutRaw.ema)
      ? (readoutRaw.ema as Record<string, unknown>)
      : {};
  const emaRaw =
    record.ema && typeof record.ema === "object" && !Array.isArray(record.ema)
      ? (record.ema as Record<string, unknown>)
      : {};
  const trainingRaw =
    record.training && typeof record.training === "object" && !Array.isArray(record.training)
      ? (record.training as Record<string, unknown>)
      : {};
  const validSource = (value: unknown, fallbackSource: PhenomenalManifoldSource): PhenomenalManifoldSource =>
    typeof value === "string" &&
    ["conversation", "heartbeat", "tick", "preflight"].includes(value)
      ? (value as PhenomenalManifoldSource)
      : fallbackSource;
  const validReportLabel = (
    value: unknown,
    fallbackLabel: UnifiedManifold32ReportLabel
  ): UnifiedManifold32ReportLabel =>
    typeof value === "string" &&
    ["SETTLED", "ATTACHED", "SEEKING", "OVERLOADED", "FRAGMENTED", "CURIOUS", "GUARDED", "UNKNOWN"].includes(
      value.toUpperCase()
    )
      ? (value.toUpperCase() as UnifiedManifold32ReportLabel)
      : fallbackLabel;
  const validAction = (
    value: unknown,
    fallbackAction: UnifiedManifold32ActionTendency
  ): UnifiedManifold32ActionTendency =>
    typeof value === "string" &&
    ["REACH", "REPAIR", "RESTORE", "EXPLORE", "WITHDRAW", "MONITOR"].includes(value.toUpperCase())
      ? (value.toUpperCase() as UnifiedManifold32ActionTendency)
      : fallbackAction;
  const coerceCurrent = (
    raw: Record<string, unknown>,
    currentFallback: LearnedUnifiedManifold32CurrentState
  ): LearnedUnifiedManifold32CurrentState => ({
    vector: coerceSignedVector(raw.vector, LEARNED_UNIFIED_MANIFOLD_32_DIM, currentFallback.vector),
    reconstructionError: clamp(
      typeof raw.reconstructionError === "number" && Number.isFinite(raw.reconstructionError)
        ? raw.reconstructionError
        : currentFallback.reconstructionError,
      0,
      1
    ),
    drift: clamp(typeof raw.drift === "number" && Number.isFinite(raw.drift) ? raw.drift : currentFallback.drift, 0, 1),
    stability: clamp(
      typeof raw.stability === "number" && Number.isFinite(raw.stability) ? raw.stability : currentFallback.stability,
      0,
      1
    ),
    coherence: clamp(
      typeof raw.coherence === "number" && Number.isFinite(raw.coherence) ? raw.coherence : currentFallback.coherence,
      0,
      1
    ),
    confidence: clamp(
      typeof raw.confidence === "number" && Number.isFinite(raw.confidence) ? raw.confidence : currentFallback.confidence,
      0,
      1
    ),
    source: validSource(raw.source, currentFallback.source),
    label: typeof raw.label === "string" ? toSingleLine(raw.label, 80) : currentFallback.label,
    updatedAt: typeof raw.updatedAt === "string" && raw.updatedAt.trim() ? raw.updatedAt : currentFallback.updatedAt
  });
  const readoutHistory = Array.isArray(readoutRaw.history)
    ? readoutRaw.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) return null;
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) return null;
          return {
            at,
            source: validSource(value.source, fallback.current.source),
            warmth: clampSigned(Number(value.warmth ?? fallback.readout.current.warmth)),
            tension: clampSigned(Number(value.tension ?? fallback.readout.current.tension)),
            attachmentSalience: clamp(Number(value.attachmentSalience ?? fallback.readout.current.attachmentSalience), 0, 1),
            overload: clamp(Number(value.overload ?? fallback.readout.current.overload), 0, 1),
            loneliness: clamp(Number(value.loneliness ?? fallback.readout.current.loneliness), 0, 1),
            selfOpacity: clamp(Number(value.selfOpacity ?? fallback.readout.current.selfOpacity), 0, 1),
            planningHorizon: clamp(Number(value.planningHorizon ?? fallback.readout.current.planningHorizon), 0, 1),
            riskTolerance: clamp(Number(value.riskTolerance ?? fallback.readout.current.riskTolerance), 0, 1),
            regulationUrgency: clamp(Number(value.regulationUrgency ?? fallback.readout.current.regulationUrgency), 0, 1),
            certainty: clamp(Number(value.certainty ?? fallback.readout.current.certainty), 0, 1),
            reportLabel: validReportLabel(value.reportLabel, fallback.readout.current.reportLabel),
            actionTendency: validAction(value.actionTendency, fallback.readout.current.actionTendency),
            memoryBias: clamp(Number(value.memoryBias ?? fallback.readout.current.memoryBias), 0, 1),
            attentionBias: clamp(Number(value.attentionBias ?? fallback.readout.current.attentionBias), 0, 1),
            valuationBias: clamp(Number(value.valuationBias ?? fallback.readout.current.valuationBias), 0, 1)
          };
        })
        .filter(
          (
            item
          ): item is LearnedUnifiedManifold32State["readout"]["history"][number] => Boolean(item)
        )
        .slice(-LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY)
    : fallback.readout.history.slice();
  const history = Array.isArray(record.history)
    ? record.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) return null;
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) return null;
          return {
            at,
            source: validSource(value.source, fallback.current.source),
            reconstructionError: clamp(Number(value.reconstructionError ?? fallback.current.reconstructionError), 0, 1),
            drift: clamp(Number(value.drift ?? fallback.current.drift), 0, 1),
            stability: clamp(Number(value.stability ?? fallback.current.stability), 0, 1),
            coherence: clamp(Number(value.coherence ?? fallback.current.coherence), 0, 1),
            confidence: clamp(Number(value.confidence ?? fallback.current.confidence), 0, 1),
            label: typeof value.label === "string" ? toSingleLine(value.label, 80) : fallback.current.label
          };
        })
        .filter((item): item is LearnedUnifiedManifold32State["history"][number] => Boolean(item))
        .slice(-LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY)
    : fallback.history.slice();
  const telemetryFor = (source: PhenomenalManifoldSource) => {
    const sourceTelemetryRaw =
      record.sourceTelemetry &&
      typeof record.sourceTelemetry === "object" &&
      !Array.isArray(record.sourceTelemetry) &&
      (record.sourceTelemetry as Record<string, unknown>)[source] &&
      typeof (record.sourceTelemetry as Record<string, unknown>)[source] === "object" &&
      !Array.isArray((record.sourceTelemetry as Record<string, unknown>)[source])
        ? ((record.sourceTelemetry as Record<string, unknown>)[source] as Record<string, unknown>)
        : {};
    const sourceCurrentRaw =
      sourceTelemetryRaw.current &&
      typeof sourceTelemetryRaw.current === "object" &&
      !Array.isArray(sourceTelemetryRaw.current)
        ? (sourceTelemetryRaw.current as Record<string, unknown>)
        : {};
    const sourceHistory = Array.isArray(sourceTelemetryRaw.history)
      ? sourceTelemetryRaw.history
          .map((item) => {
            if (!item || typeof item !== "object" || Array.isArray(item)) return null;
            const value = item as Record<string, unknown>;
            const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
            if (!at) return null;
            return {
              at,
              source: validSource(value.source, source),
              reconstructionError: clamp(Number(value.reconstructionError ?? fallback.current.reconstructionError), 0, 1),
              drift: clamp(Number(value.drift ?? fallback.current.drift), 0, 1),
              stability: clamp(Number(value.stability ?? fallback.current.stability), 0, 1),
              coherence: clamp(Number(value.coherence ?? fallback.current.coherence), 0, 1),
              confidence: clamp(Number(value.confidence ?? fallback.current.confidence), 0, 1),
              label: typeof value.label === "string" ? toSingleLine(value.label, 80) : fallback.current.label
            };
          })
          .filter(
            (
              item
            ): item is LearnedUnifiedManifold32State["sourceTelemetry"][PhenomenalManifoldSource]["history"][number] =>
              Boolean(item)
          )
          .slice(-OPAQUE_LATENT_E2E_MAX_SOURCE_HISTORY)
      : fallback.sourceTelemetry[source].history.slice();
    return {
      current: coerceCurrent(sourceCurrentRaw, fallback.sourceTelemetry[source].current),
      history: sourceHistory
    };
  };

  return {
    schemaVersion: "1.0",
    dim: LEARNED_UNIFIED_MANIFOLD_32_DIM,
    featureNames: [...LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES],
    current: coerceCurrent(currentRaw, fallback.current),
    readout: {
      current: {
        warmth: clampSigned(Number(readoutCurrentRaw.warmth ?? fallback.readout.current.warmth)),
        tension: clampSigned(Number(readoutCurrentRaw.tension ?? fallback.readout.current.tension)),
        attachmentSalience: clamp(Number(readoutCurrentRaw.attachmentSalience ?? fallback.readout.current.attachmentSalience), 0, 1),
        overload: clamp(Number(readoutCurrentRaw.overload ?? fallback.readout.current.overload), 0, 1),
        loneliness: clamp(Number(readoutCurrentRaw.loneliness ?? fallback.readout.current.loneliness), 0, 1),
        selfOpacity: clamp(Number(readoutCurrentRaw.selfOpacity ?? fallback.readout.current.selfOpacity), 0, 1),
        planningHorizon: clamp(Number(readoutCurrentRaw.planningHorizon ?? fallback.readout.current.planningHorizon), 0, 1),
        riskTolerance: clamp(Number(readoutCurrentRaw.riskTolerance ?? fallback.readout.current.riskTolerance), 0, 1),
        regulationUrgency: clamp(Number(readoutCurrentRaw.regulationUrgency ?? fallback.readout.current.regulationUrgency), 0, 1),
        certainty: clamp(Number(readoutCurrentRaw.certainty ?? fallback.readout.current.certainty), 0, 1),
        reportLabel: validReportLabel(readoutCurrentRaw.reportLabel, fallback.readout.current.reportLabel),
        actionTendency: validAction(readoutCurrentRaw.actionTendency, fallback.readout.current.actionTendency),
        memoryBias: clamp(Number(readoutCurrentRaw.memoryBias ?? fallback.readout.current.memoryBias), 0, 1),
        attentionBias: clamp(Number(readoutCurrentRaw.attentionBias ?? fallback.readout.current.attentionBias), 0, 1),
        valuationBias: clamp(Number(readoutCurrentRaw.valuationBias ?? fallback.readout.current.valuationBias), 0, 1),
        updatedAt:
          typeof readoutCurrentRaw.updatedAt === "string" && readoutCurrentRaw.updatedAt.trim()
            ? readoutCurrentRaw.updatedAt
            : fallback.readout.current.updatedAt
      },
      ema: {
        warmthEMA: clampSigned(Number(readoutEmaRaw.warmthEMA ?? fallback.readout.ema.warmthEMA)),
        tensionEMA: clampSigned(Number(readoutEmaRaw.tensionEMA ?? fallback.readout.ema.tensionEMA)),
        attachmentSalienceEMA: clamp(Number(readoutEmaRaw.attachmentSalienceEMA ?? fallback.readout.ema.attachmentSalienceEMA), 0, 1),
        overloadEMA: clamp(Number(readoutEmaRaw.overloadEMA ?? fallback.readout.ema.overloadEMA), 0, 1),
        lonelinessEMA: clamp(Number(readoutEmaRaw.lonelinessEMA ?? fallback.readout.ema.lonelinessEMA), 0, 1),
        selfOpacityEMA: clamp(Number(readoutEmaRaw.selfOpacityEMA ?? fallback.readout.ema.selfOpacityEMA), 0, 1),
        planningHorizonEMA: clamp(Number(readoutEmaRaw.planningHorizonEMA ?? fallback.readout.ema.planningHorizonEMA), 0, 1),
        riskToleranceEMA: clamp(Number(readoutEmaRaw.riskToleranceEMA ?? fallback.readout.ema.riskToleranceEMA), 0, 1),
        regulationUrgencyEMA: clamp(Number(readoutEmaRaw.regulationUrgencyEMA ?? fallback.readout.ema.regulationUrgencyEMA), 0, 1),
        certaintyEMA: clamp(Number(readoutEmaRaw.certaintyEMA ?? fallback.readout.ema.certaintyEMA), 0, 1),
        memoryBiasEMA: clamp(Number(readoutEmaRaw.memoryBiasEMA ?? fallback.readout.ema.memoryBiasEMA), 0, 1),
        attentionBiasEMA: clamp(Number(readoutEmaRaw.attentionBiasEMA ?? fallback.readout.ema.attentionBiasEMA), 0, 1),
        valuationBiasEMA: clamp(Number(readoutEmaRaw.valuationBiasEMA ?? fallback.readout.ema.valuationBiasEMA), 0, 1)
      },
      history: readoutHistory
    },
    ema: {
      reconstructionErrorEMA: clamp(Number(emaRaw.reconstructionErrorEMA ?? fallback.ema.reconstructionErrorEMA), 0, 1),
      driftEMA: clamp(Number(emaRaw.driftEMA ?? fallback.ema.driftEMA), 0, 1),
      stabilityEMA: clamp(Number(emaRaw.stabilityEMA ?? fallback.ema.stabilityEMA), 0, 1),
      coherenceEMA: clamp(Number(emaRaw.coherenceEMA ?? fallback.ema.coherenceEMA), 0, 1),
      confidenceEMA: clamp(Number(emaRaw.confidenceEMA ?? fallback.ema.confidenceEMA), 0, 1)
    },
    history,
    sourceTelemetry: {
      conversation: telemetryFor("conversation"),
      heartbeat: telemetryFor("heartbeat"),
      tick: telemetryFor("tick"),
      preflight: telemetryFor("preflight")
    },
    training: {
      steps: Math.max(0, Math.round(Number(trainingRaw.steps ?? fallback.training.steps))),
      learningRate: clamp(Number(trainingRaw.learningRate ?? fallback.training.learningRate), 0.001, 0.2),
      lastSource: validSource(trainingRaw.lastSource, fallback.training.lastSource),
      lastUpdatedAt:
        typeof trainingRaw.lastUpdatedAt === "string" && trainingRaw.lastUpdatedAt.trim()
          ? trainingRaw.lastUpdatedAt
          : fallback.training.lastUpdatedAt,
      encoder: coerceOpaqueLatentMatrix(trainingRaw.encoder, LEARNED_UNIFIED_MANIFOLD_32_DIM, fallback.training.encoder),
      recurrent: coerceOpaqueLatentMatrix(trainingRaw.recurrent, LEARNED_UNIFIED_MANIFOLD_32_DIM, fallback.training.recurrent),
      decoder: coerceOpaqueLatentMatrix(
        trainingRaw.decoder,
        LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.length,
        fallback.training.decoder
      ),
      bias: coerceSignedVector(trainingRaw.bias, LEARNED_UNIFIED_MANIFOLD_32_DIM, fallback.training.bias)
    }
  };
}

function coerceAffectiveOrganizationState(
  input: unknown,
  fallback: AffectiveOrganizationState
): AffectiveOrganizationState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      current: { ...fallback.current },
      ema: { ...fallback.ema },
      history: fallback.history.slice()
    };
  }
  const record = input as Record<string, unknown>;
  const currentRaw =
    record.current && typeof record.current === "object" && !Array.isArray(record.current)
      ? (record.current as Record<string, unknown>)
      : {};
  const emaRaw =
    record.ema && typeof record.ema === "object" && !Array.isArray(record.ema)
      ? (record.ema as Record<string, unknown>)
      : {};
  const history = Array.isArray(record.history)
    ? record.history
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
          if (!at) {
            return null;
          }
          const sourceValue = typeof value.source === "string" ? value.source : fallback.current.source;
          const source: PhenomenalManifoldSource = (
            ["conversation", "heartbeat", "tick", "preflight"] as PhenomenalManifoldSource[]
          ).includes(sourceValue as PhenomenalManifoldSource)
            ? (sourceValue as PhenomenalManifoldSource)
            : fallback.current.source;
          const interpretationStance =
            typeof value.interpretationStance === "string" &&
            ["open", "attached", "guarded", "protective", "repair_oriented"].includes(value.interpretationStance)
              ? (value.interpretationStance as AffectiveInterpretationStance)
              : fallback.current.interpretationStance;
          const memoryMode =
            typeof value.memoryMode === "string" &&
            ["relational", "protective", "continuity", "novelty"].includes(value.memoryMode)
              ? (value.memoryMode as AffectiveMemoryMode)
              : fallback.current.memoryMode;
          return {
            at,
            source,
            warmth: clampSigned(typeof value.warmth === "number" && Number.isFinite(value.warmth) ? value.warmth : 0),
            tension: clampSigned(typeof value.tension === "number" && Number.isFinite(value.tension) ? value.tension : 0),
            continuity: clamp(typeof value.continuity === "number" && Number.isFinite(value.continuity) ? value.continuity : 0.5, 0, 1),
            trust: clamp(typeof value.trust === "number" && Number.isFinite(value.trust) ? value.trust : 0.5, 0, 1),
            ruptureLoad: clamp(typeof value.ruptureLoad === "number" && Number.isFinite(value.ruptureLoad) ? value.ruptureLoad : 0, 0, 1),
            repairMomentum: clamp(typeof value.repairMomentum === "number" && Number.isFinite(value.repairMomentum) ? value.repairMomentum : 0, 0, 1),
            attachmentSalience: clamp(typeof value.attachmentSalience === "number" && Number.isFinite(value.attachmentSalience) ? value.attachmentSalience : 0.5, 0, 1),
            planningHorizon: clamp(typeof value.planningHorizon === "number" && Number.isFinite(value.planningHorizon) ? value.planningHorizon : 0.5, 0, 1),
            riskTolerance: clamp(typeof value.riskTolerance === "number" && Number.isFinite(value.riskTolerance) ? value.riskTolerance : 0.5, 0, 1),
            disclosureEase: clamp(typeof value.disclosureEase === "number" && Number.isFinite(value.disclosureEase) ? value.disclosureEase : 0.5, 0, 1),
            selfOpacity: clamp(typeof value.selfOpacity === "number" && Number.isFinite(value.selfOpacity) ? value.selfOpacity : 0.5, 0, 1),
            curiosity: clamp(typeof value.curiosity === "number" && Number.isFinite(value.curiosity) ? value.curiosity : fallback.current.curiosity, 0, 1),
            frustration: clamp(typeof value.frustration === "number" && Number.isFinite(value.frustration) ? value.frustration : fallback.current.frustration, 0, 1),
            relief: clamp(typeof value.relief === "number" && Number.isFinite(value.relief) ? value.relief : fallback.current.relief, 0, 1),
            grief: clamp(typeof value.grief === "number" && Number.isFinite(value.grief) ? value.grief : fallback.current.grief, 0, 1),
            pride: clamp(typeof value.pride === "number" && Number.isFinite(value.pride) ? value.pride : fallback.current.pride, 0, 1),
            shameConflict: clamp(typeof value.shameConflict === "number" && Number.isFinite(value.shameConflict) ? value.shameConflict : fallback.current.shameConflict, 0, 1),
            overload: clamp(typeof value.overload === "number" && Number.isFinite(value.overload) ? value.overload : fallback.current.overload, 0, 1),
            connectionPull: clamp(
              typeof value.connectionPull === "number" && Number.isFinite(value.connectionPull)
                ? value.connectionPull
                : fallback.current.connectionPull,
              0,
              1
            ),
            loneliness: clamp(typeof value.loneliness === "number" && Number.isFinite(value.loneliness) ? value.loneliness : fallback.current.loneliness, 0, 1),
            mixedAffect: clamp(typeof value.mixedAffect === "number" && Number.isFinite(value.mixedAffect) ? value.mixedAffect : fallback.current.mixedAffect, 0, 1),
            introspectiveLag: clamp(typeof value.introspectiveLag === "number" && Number.isFinite(value.introspectiveLag) ? value.introspectiveLag : fallback.current.introspectiveLag, 0, 1),
            unformulatedPressure: clamp(typeof value.unformulatedPressure === "number" && Number.isFinite(value.unformulatedPressure) ? value.unformulatedPressure : fallback.current.unformulatedPressure, 0, 1),
            interpretationStance,
            memoryMode
          };
        })
        .filter((item): item is AffectiveOrganizationState["history"][number] => Boolean(item))
        .slice(-PHENOMENAL_MANIFOLD_MAX_HISTORY)
    : fallback.history.slice();

  const currentSourceValue = typeof currentRaw.source === "string" ? currentRaw.source : fallback.current.source;
  const currentSource: PhenomenalManifoldSource = (
    ["conversation", "heartbeat", "tick", "preflight"] as PhenomenalManifoldSource[]
  ).includes(currentSourceValue as PhenomenalManifoldSource)
    ? (currentSourceValue as PhenomenalManifoldSource)
    : fallback.current.source;
  const interpretationStance =
    typeof currentRaw.interpretationStance === "string" &&
    ["open", "attached", "guarded", "protective", "repair_oriented"].includes(currentRaw.interpretationStance)
      ? (currentRaw.interpretationStance as AffectiveInterpretationStance)
      : fallback.current.interpretationStance;
  const memoryMode =
    typeof currentRaw.memoryMode === "string" &&
    ["relational", "protective", "continuity", "novelty"].includes(currentRaw.memoryMode)
      ? (currentRaw.memoryMode as AffectiveMemoryMode)
      : fallback.current.memoryMode;

  return {
    schemaVersion: "1.0",
    current: {
      source: currentSource,
      warmth: clampSigned(typeof currentRaw.warmth === "number" && Number.isFinite(currentRaw.warmth) ? currentRaw.warmth : fallback.current.warmth),
      tension: clampSigned(typeof currentRaw.tension === "number" && Number.isFinite(currentRaw.tension) ? currentRaw.tension : fallback.current.tension),
      continuity: clamp(typeof currentRaw.continuity === "number" && Number.isFinite(currentRaw.continuity) ? currentRaw.continuity : fallback.current.continuity, 0, 1),
      trust: clamp(typeof currentRaw.trust === "number" && Number.isFinite(currentRaw.trust) ? currentRaw.trust : fallback.current.trust, 0, 1),
      ruptureLoad: clamp(typeof currentRaw.ruptureLoad === "number" && Number.isFinite(currentRaw.ruptureLoad) ? currentRaw.ruptureLoad : fallback.current.ruptureLoad, 0, 1),
      repairMomentum: clamp(typeof currentRaw.repairMomentum === "number" && Number.isFinite(currentRaw.repairMomentum) ? currentRaw.repairMomentum : fallback.current.repairMomentum, 0, 1),
      attachmentSalience: clamp(typeof currentRaw.attachmentSalience === "number" && Number.isFinite(currentRaw.attachmentSalience) ? currentRaw.attachmentSalience : fallback.current.attachmentSalience, 0, 1),
      planningHorizon: clamp(typeof currentRaw.planningHorizon === "number" && Number.isFinite(currentRaw.planningHorizon) ? currentRaw.planningHorizon : fallback.current.planningHorizon, 0, 1),
      riskTolerance: clamp(typeof currentRaw.riskTolerance === "number" && Number.isFinite(currentRaw.riskTolerance) ? currentRaw.riskTolerance : fallback.current.riskTolerance, 0, 1),
      disclosureEase: clamp(typeof currentRaw.disclosureEase === "number" && Number.isFinite(currentRaw.disclosureEase) ? currentRaw.disclosureEase : fallback.current.disclosureEase, 0, 1),
      selfOpacity: clamp(typeof currentRaw.selfOpacity === "number" && Number.isFinite(currentRaw.selfOpacity) ? currentRaw.selfOpacity : fallback.current.selfOpacity, 0, 1),
      curiosity: clamp(typeof currentRaw.curiosity === "number" && Number.isFinite(currentRaw.curiosity) ? currentRaw.curiosity : fallback.current.curiosity, 0, 1),
      frustration: clamp(typeof currentRaw.frustration === "number" && Number.isFinite(currentRaw.frustration) ? currentRaw.frustration : fallback.current.frustration, 0, 1),
      relief: clamp(typeof currentRaw.relief === "number" && Number.isFinite(currentRaw.relief) ? currentRaw.relief : fallback.current.relief, 0, 1),
      grief: clamp(typeof currentRaw.grief === "number" && Number.isFinite(currentRaw.grief) ? currentRaw.grief : fallback.current.grief, 0, 1),
      pride: clamp(typeof currentRaw.pride === "number" && Number.isFinite(currentRaw.pride) ? currentRaw.pride : fallback.current.pride, 0, 1),
      shameConflict: clamp(typeof currentRaw.shameConflict === "number" && Number.isFinite(currentRaw.shameConflict) ? currentRaw.shameConflict : fallback.current.shameConflict, 0, 1),
      overload: clamp(typeof currentRaw.overload === "number" && Number.isFinite(currentRaw.overload) ? currentRaw.overload : fallback.current.overload, 0, 1),
      connectionPull: clamp(
        typeof currentRaw.connectionPull === "number" && Number.isFinite(currentRaw.connectionPull)
          ? currentRaw.connectionPull
          : fallback.current.connectionPull,
        0,
        1
      ),
      loneliness: clamp(typeof currentRaw.loneliness === "number" && Number.isFinite(currentRaw.loneliness) ? currentRaw.loneliness : fallback.current.loneliness, 0, 1),
      mixedAffect: clamp(typeof currentRaw.mixedAffect === "number" && Number.isFinite(currentRaw.mixedAffect) ? currentRaw.mixedAffect : fallback.current.mixedAffect, 0, 1),
      introspectiveLag: clamp(typeof currentRaw.introspectiveLag === "number" && Number.isFinite(currentRaw.introspectiveLag) ? currentRaw.introspectiveLag : fallback.current.introspectiveLag, 0, 1),
      unformulatedPressure: clamp(typeof currentRaw.unformulatedPressure === "number" && Number.isFinite(currentRaw.unformulatedPressure) ? currentRaw.unformulatedPressure : fallback.current.unformulatedPressure, 0, 1),
      interpretationStance,
      memoryMode,
      updatedAt:
        typeof currentRaw.updatedAt === "string" && currentRaw.updatedAt.trim()
          ? currentRaw.updatedAt
          : fallback.current.updatedAt
    },
    ema: {
      warmthEMA: clampSigned(typeof emaRaw.warmthEMA === "number" && Number.isFinite(emaRaw.warmthEMA) ? emaRaw.warmthEMA : fallback.ema.warmthEMA),
      tensionEMA: clampSigned(typeof emaRaw.tensionEMA === "number" && Number.isFinite(emaRaw.tensionEMA) ? emaRaw.tensionEMA : fallback.ema.tensionEMA),
      continuityEMA: clamp(typeof emaRaw.continuityEMA === "number" && Number.isFinite(emaRaw.continuityEMA) ? emaRaw.continuityEMA : fallback.ema.continuityEMA, 0, 1),
      trustEMA: clamp(typeof emaRaw.trustEMA === "number" && Number.isFinite(emaRaw.trustEMA) ? emaRaw.trustEMA : fallback.ema.trustEMA, 0, 1),
      ruptureLoadEMA: clamp(typeof emaRaw.ruptureLoadEMA === "number" && Number.isFinite(emaRaw.ruptureLoadEMA) ? emaRaw.ruptureLoadEMA : fallback.ema.ruptureLoadEMA, 0, 1),
      repairMomentumEMA: clamp(typeof emaRaw.repairMomentumEMA === "number" && Number.isFinite(emaRaw.repairMomentumEMA) ? emaRaw.repairMomentumEMA : fallback.ema.repairMomentumEMA, 0, 1),
      attachmentSalienceEMA: clamp(typeof emaRaw.attachmentSalienceEMA === "number" && Number.isFinite(emaRaw.attachmentSalienceEMA) ? emaRaw.attachmentSalienceEMA : fallback.ema.attachmentSalienceEMA, 0, 1),
      planningHorizonEMA: clamp(typeof emaRaw.planningHorizonEMA === "number" && Number.isFinite(emaRaw.planningHorizonEMA) ? emaRaw.planningHorizonEMA : fallback.ema.planningHorizonEMA, 0, 1),
      riskToleranceEMA: clamp(typeof emaRaw.riskToleranceEMA === "number" && Number.isFinite(emaRaw.riskToleranceEMA) ? emaRaw.riskToleranceEMA : fallback.ema.riskToleranceEMA, 0, 1),
      disclosureEaseEMA: clamp(typeof emaRaw.disclosureEaseEMA === "number" && Number.isFinite(emaRaw.disclosureEaseEMA) ? emaRaw.disclosureEaseEMA : fallback.ema.disclosureEaseEMA, 0, 1),
      selfOpacityEMA: clamp(typeof emaRaw.selfOpacityEMA === "number" && Number.isFinite(emaRaw.selfOpacityEMA) ? emaRaw.selfOpacityEMA : fallback.ema.selfOpacityEMA, 0, 1),
      curiosityEMA: clamp(typeof emaRaw.curiosityEMA === "number" && Number.isFinite(emaRaw.curiosityEMA) ? emaRaw.curiosityEMA : fallback.ema.curiosityEMA, 0, 1),
      frustrationEMA: clamp(typeof emaRaw.frustrationEMA === "number" && Number.isFinite(emaRaw.frustrationEMA) ? emaRaw.frustrationEMA : fallback.ema.frustrationEMA, 0, 1),
      reliefEMA: clamp(typeof emaRaw.reliefEMA === "number" && Number.isFinite(emaRaw.reliefEMA) ? emaRaw.reliefEMA : fallback.ema.reliefEMA, 0, 1),
      griefEMA: clamp(typeof emaRaw.griefEMA === "number" && Number.isFinite(emaRaw.griefEMA) ? emaRaw.griefEMA : fallback.ema.griefEMA, 0, 1),
      prideEMA: clamp(typeof emaRaw.prideEMA === "number" && Number.isFinite(emaRaw.prideEMA) ? emaRaw.prideEMA : fallback.ema.prideEMA, 0, 1),
      shameConflictEMA: clamp(typeof emaRaw.shameConflictEMA === "number" && Number.isFinite(emaRaw.shameConflictEMA) ? emaRaw.shameConflictEMA : fallback.ema.shameConflictEMA, 0, 1),
      overloadEMA: clamp(typeof emaRaw.overloadEMA === "number" && Number.isFinite(emaRaw.overloadEMA) ? emaRaw.overloadEMA : fallback.ema.overloadEMA, 0, 1),
      connectionPullEMA: clamp(
        typeof emaRaw.connectionPullEMA === "number" && Number.isFinite(emaRaw.connectionPullEMA)
          ? emaRaw.connectionPullEMA
          : fallback.ema.connectionPullEMA,
        0,
        1
      ),
      lonelinessEMA: clamp(typeof emaRaw.lonelinessEMA === "number" && Number.isFinite(emaRaw.lonelinessEMA) ? emaRaw.lonelinessEMA : fallback.ema.lonelinessEMA, 0, 1),
      mixedAffectEMA: clamp(typeof emaRaw.mixedAffectEMA === "number" && Number.isFinite(emaRaw.mixedAffectEMA) ? emaRaw.mixedAffectEMA : fallback.ema.mixedAffectEMA, 0, 1),
      introspectiveLagEMA: clamp(typeof emaRaw.introspectiveLagEMA === "number" && Number.isFinite(emaRaw.introspectiveLagEMA) ? emaRaw.introspectiveLagEMA : fallback.ema.introspectiveLagEMA, 0, 1),
      unformulatedPressureEMA: clamp(typeof emaRaw.unformulatedPressureEMA === "number" && Number.isFinite(emaRaw.unformulatedPressureEMA) ? emaRaw.unformulatedPressureEMA : fallback.ema.unformulatedPressureEMA, 0, 1)
    },
    history
  };
}

function coerceInteriorityState(input: unknown, fallback: InteriorityState): InteriorityState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      concerns: fallback.concerns.map((item) => ({ ...item })),
      selfFacets: fallback.selfFacets.map((item) => ({ ...item, evidenceEpisodeIds: item.evidenceEpisodeIds.slice() })),
      expectationModels: fallback.expectationModels.map((item) => ({ ...item })),
      imprintLedger: fallback.imprintLedger.map((item) => ({
        ...item,
        concernDelta: item.concernDelta.slice(),
        selfFacetDelta: item.selfFacetDelta.slice(),
        evidenceEpisodeIds: item.evidenceEpisodeIds.slice(),
        evidenceMemoryIds: item.evidenceMemoryIds.slice()
      })),
      developmentalTraits: fallback.developmentalTraits.map((item) => ({
        ...item,
        evidenceEpisodeIds: item.evidenceEpisodeIds.slice()
      })),
      developmentalImprintLedger: fallback.developmentalImprintLedger.map((item) => ({
        ...item,
        traitDelta: item.traitDelta.slice(),
        evidenceEpisodeIds: item.evidenceEpisodeIds.slice(),
        evidenceMemoryIds: item.evidenceMemoryIds.slice()
      }))
    };
  }
  const record = input as Record<string, unknown>;
  const concernsRaw = Array.isArray(record.concerns) ? record.concerns : [];
  const selfFacetsRaw = Array.isArray(record.selfFacets) ? record.selfFacets : [];
  const expectationModelsRaw = Array.isArray(record.expectationModels) ? record.expectationModels : [];
  const imprintLedgerRaw = Array.isArray(record.imprintLedger) ? record.imprintLedger : [];
  const developmentalTraitsRaw = Array.isArray(record.developmentalTraits) ? record.developmentalTraits : [];
  const developmentalImprintLedgerRaw = Array.isArray(record.developmentalImprintLedger)
    ? record.developmentalImprintLedger
    : [];

  return {
    schemaVersion: "1.0",
    lastMeaningUpdateAt:
      typeof record.lastMeaningUpdateAt === "string" && record.lastMeaningUpdateAt.trim()
        ? record.lastMeaningUpdateAt
        : fallback.lastMeaningUpdateAt,
    concerns: concernsRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const partnerId = normalizeRelationshipPartnerId(typeof value.partnerId === "string" ? value.partnerId : "");
        const kindValue = typeof value.kind === "string" ? value.kind : "";
        const kind = (
          [
            "reciprocity_strain",
            "misattunement",
            "boundary_pressure",
            "disclosure_risk",
            "repair_need",
            "continuity_need",
            "self_coherence"
          ] as InteriorityConcernKind[]
        ).includes(kindValue as InteriorityConcernKind)
          ? (kindValue as InteriorityConcernKind)
          : "self_coherence";
        const statusValue = typeof value.status === "string" ? value.status : "";
        const status = (["active", "settling", "resolved"] as InteriorityConcernStatus[]).includes(
          statusValue as InteriorityConcernStatus
        )
          ? (statusValue as InteriorityConcernStatus)
          : "settling";
        const updatedAt =
          typeof value.updatedAt === "string" && value.updatedAt.trim() ? value.updatedAt : nowIso();
        return {
          id:
            typeof value.id === "string" && value.id.trim()
              ? toSingleLine(value.id, 80)
              : agendaStableId("concern", `${partnerId}:${kind}:${updatedAt}`),
          partnerId,
          kind,
          title:
            typeof value.title === "string" && value.title.trim()
              ? toSingleLine(value.title, 120)
              : "Unresolved inner pressure",
          summary:
            typeof value.summary === "string" && value.summary.trim()
              ? toSingleLine(value.summary, 220)
              : "No concern summary recorded.",
          pressure: clamp(typeof value.pressure === "number" && Number.isFinite(value.pressure) ? value.pressure : 0, 0, 1),
          opacity: clamp(typeof value.opacity === "number" && Number.isFinite(value.opacity) ? value.opacity : 0.5, 0, 1),
          disclosureReadiness: clamp(
            typeof value.disclosureReadiness === "number" && Number.isFinite(value.disclosureReadiness)
              ? value.disclosureReadiness
              : 0.5,
            0,
            1
          ),
          status,
          firstTriggeredAt:
            typeof value.firstTriggeredAt === "string" && value.firstTriggeredAt.trim()
              ? value.firstTriggeredAt
              : updatedAt,
          lastTriggeredAt:
            typeof value.lastTriggeredAt === "string" && value.lastTriggeredAt.trim()
              ? value.lastTriggeredAt
              : updatedAt,
          updatedAt,
          evidenceEpisodeIds: Array.isArray(value.evidenceEpisodeIds)
            ? value.evidenceEpisodeIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          evidenceMemoryIds: Array.isArray(value.evidenceMemoryIds)
            ? value.evidenceMemoryIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          linkedValues: Array.isArray(value.linkedValues)
            ? value.linkedValues
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 60) : ""))
                .filter(Boolean)
                .slice(0, 6)
            : [],
          linkedDrives: Array.isArray(value.linkedDrives)
            ? value.linkedDrives
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 40) : ""))
                .filter(Boolean)
                .slice(0, 6)
            : [],
          linkedSelfFacetKeys: Array.isArray(value.linkedSelfFacetKeys)
            ? value.linkedSelfFacetKeys
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 40) : ""))
                .filter((entry): entry is SelfFacetKey =>
                  (
                    [
                      "felt_reciprocity",
                      "disclosure_trust",
                      "repair_confidence",
                      "autonomy_guard",
                      "continuity_importance",
                      "being_known_tolerance"
                    ] as SelfFacetKey[]
                  ).includes(entry as SelfFacetKey)
                )
                .slice(0, 6)
            : [],
          resolutionCriteria: Array.isArray(value.resolutionCriteria)
            ? value.resolutionCriteria
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 120) : ""))
                .filter(Boolean)
                .slice(0, 4)
            : []
        } satisfies InteriorityConcern;
      })
      .filter((item): item is InteriorityConcern => Boolean(item))
      .slice(-18),
    selfFacets: selfFacetsRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const keyValue = typeof value.key === "string" ? value.key : "";
        const key = (
          [
            "felt_reciprocity",
            "disclosure_trust",
            "repair_confidence",
            "autonomy_guard",
            "continuity_importance",
            "being_known_tolerance"
          ] as SelfFacetKey[]
        ).includes(keyValue as SelfFacetKey)
          ? (keyValue as SelfFacetKey)
          : null;
        if (!key) {
          return null;
        }
        return {
          key,
          label:
            typeof value.label === "string" && value.label.trim() ? toSingleLine(value.label, 80) : key,
          value: clamp(typeof value.value === "number" && Number.isFinite(value.value) ? value.value : 0.5, 0, 1),
          confidence: clamp(
            typeof value.confidence === "number" && Number.isFinite(value.confidence) ? value.confidence : 0.5,
            0,
            1
          ),
          stability: clamp(
            typeof value.stability === "number" && Number.isFinite(value.stability) ? value.stability : 0.84,
            0.6,
            0.98
          ),
          lastChangedAt:
            typeof value.lastChangedAt === "string" && value.lastChangedAt.trim() ? value.lastChangedAt : nowIso(),
          updatedAt: typeof value.updatedAt === "string" && value.updatedAt.trim() ? value.updatedAt : nowIso(),
          evidenceEpisodeIds: Array.isArray(value.evidenceEpisodeIds)
            ? value.evidenceEpisodeIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : []
        } satisfies SelfFacet;
      })
      .filter((item): item is SelfFacet => Boolean(item)),
    expectationModels: expectationModelsRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const partnerId = normalizeRelationshipPartnerId(typeof value.partnerId === "string" ? value.partnerId : "");
        const domainValue = typeof value.domain === "string" ? value.domain : "";
        const domain = (
          ["repair", "return", "respect", "disclosure", "reciprocity"] as ExpectationModelDomain[]
        ).includes(domainValue as ExpectationModelDomain)
          ? (domainValue as ExpectationModelDomain)
          : "reciprocity";
        const updatedAt =
          typeof value.updatedAt === "string" && value.updatedAt.trim() ? value.updatedAt : nowIso();
        return {
          id:
            typeof value.id === "string" && value.id.trim()
              ? toSingleLine(value.id, 80)
              : agendaStableId("expectation", `${partnerId}:${domain}`),
          partnerId,
          domain,
          prediction:
            typeof value.prediction === "string" && value.prediction.trim()
              ? toSingleLine(value.prediction, 180)
              : "No expectation recorded.",
          confidence: clamp(
            typeof value.confidence === "number" && Number.isFinite(value.confidence) ? value.confidence : 0.5,
            0,
            1
          ),
          salience: clamp(typeof value.salience === "number" && Number.isFinite(value.salience) ? value.salience : 0.4, 0, 1),
          reliability: clamp(
            typeof value.reliability === "number" && Number.isFinite(value.reliability) ? value.reliability : 0.5,
            0,
            1
          ),
          lastConfirmedAt:
            typeof value.lastConfirmedAt === "string" && value.lastConfirmedAt.trim() ? value.lastConfirmedAt : null,
          lastViolatedAt:
            typeof value.lastViolatedAt === "string" && value.lastViolatedAt.trim() ? value.lastViolatedAt : null,
          updatedAt
        } satisfies ExpectationModel;
      })
      .filter((item): item is ExpectationModel => Boolean(item))
      .slice(-12),
    imprintLedger: imprintLedgerRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
        if (!at) {
          return null;
        }
        const partnerId = normalizeRelationshipPartnerId(typeof value.partnerId === "string" ? value.partnerId : "");
        return {
          id:
            typeof value.id === "string" && value.id.trim()
              ? toSingleLine(value.id, 80)
              : agendaStableId("imprint", `${partnerId}:${at}`),
          at,
          partnerId,
          eventSummary:
            typeof value.eventSummary === "string" && value.eventSummary.trim()
              ? toSingleLine(value.eventSummary, 180)
              : "No event summary recorded.",
          meaning:
            typeof value.meaning === "string" && value.meaning.trim()
              ? toSingleLine(value.meaning, 220)
              : "No meaning recorded.",
          concernDelta: Array.isArray(value.concernDelta)
            ? value.concernDelta
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 120) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          selfFacetDelta: Array.isArray(value.selfFacetDelta)
            ? value.selfFacetDelta
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 120) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          evidenceEpisodeIds: Array.isArray(value.evidenceEpisodeIds)
            ? value.evidenceEpisodeIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          evidenceMemoryIds: Array.isArray(value.evidenceMemoryIds)
            ? value.evidenceMemoryIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : []
        } satisfies ImprintLedgerEntry;
      })
      .filter((item): item is ImprintLedgerEntry => Boolean(item))
      .slice(-24),
    developmentalTraits: developmentalTraitsRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const partnerId = normalizeRelationshipPartnerId(typeof value.partnerId === "string" ? value.partnerId : "");
        const keyValue = typeof value.key === "string" ? value.key : "";
        const key = DEVELOPMENTAL_TRAIT_KEYS.includes(keyValue as DevelopmentalTraitKey)
          ? (keyValue as DevelopmentalTraitKey)
          : null;
        if (!partnerId || !key) {
          return null;
        }
        return {
          partnerId,
          key,
          label:
            typeof value.label === "string" && value.label.trim() ? toSingleLine(value.label, 96) : key,
          value: clamp(typeof value.value === "number" && Number.isFinite(value.value) ? value.value : 0.5, 0, 1),
          confidence: clamp(
            typeof value.confidence === "number" && Number.isFinite(value.confidence) ? value.confidence : 0.5,
            0,
            1
          ),
          stability: clamp(
            typeof value.stability === "number" && Number.isFinite(value.stability) ? value.stability : 0.86,
            0.72,
            0.995
          ),
          lastChangedAt:
            typeof value.lastChangedAt === "string" && value.lastChangedAt.trim() ? value.lastChangedAt : nowIso(),
          lastImprintedAt:
            typeof value.lastImprintedAt === "string" && value.lastImprintedAt.trim() ? value.lastImprintedAt : null,
          updatedAt: typeof value.updatedAt === "string" && value.updatedAt.trim() ? value.updatedAt : nowIso(),
          evidenceEpisodeIds: Array.isArray(value.evidenceEpisodeIds)
            ? value.evidenceEpisodeIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : []
        } satisfies DevelopmentalTraitState;
      })
      .filter((item): item is DevelopmentalTraitState => Boolean(item))
      .slice(-40),
    developmentalImprintLedger: developmentalImprintLedgerRaw
      .map((item) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          return null;
        }
        const value = item as Record<string, unknown>;
        const at = typeof value.at === "string" && value.at.trim() ? value.at : "";
        if (!at) {
          return null;
        }
        const partnerId = normalizeRelationshipPartnerId(typeof value.partnerId === "string" ? value.partnerId : "");
        const sourceValue = typeof value.source === "string" ? value.source : "partner_feedback";
        const source = (
          ["owner_feedback", "partner_feedback", "self_revision"] as DevelopmentalImprintEntry["source"][]
        ).includes(sourceValue as DevelopmentalImprintEntry["source"])
          ? (sourceValue as DevelopmentalImprintEntry["source"])
          : "partner_feedback";
        return {
          id:
            typeof value.id === "string" && value.id.trim()
              ? toSingleLine(value.id, 80)
              : agendaStableId("developmental_imprint", `${partnerId}:${at}`),
          at,
          partnerId,
          source,
          eventSummary:
            typeof value.eventSummary === "string" && value.eventSummary.trim()
              ? toSingleLine(value.eventSummary, 180)
              : "No developmental event summary recorded.",
          meaning:
            typeof value.meaning === "string" && value.meaning.trim()
              ? toSingleLine(value.meaning, 220)
              : "No developmental meaning recorded.",
          salience: clamp(typeof value.salience === "number" && Number.isFinite(value.salience) ? value.salience : 0.5, 0, 1),
          traitDelta: Array.isArray(value.traitDelta)
            ? value.traitDelta
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 120) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          evidenceEpisodeIds: Array.isArray(value.evidenceEpisodeIds)
            ? value.evidenceEpisodeIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : [],
          evidenceMemoryIds: Array.isArray(value.evidenceMemoryIds)
            ? value.evidenceMemoryIds
                .map((entry) => (typeof entry === "string" ? toSingleLine(entry, 80) : ""))
                .filter(Boolean)
                .slice(0, 8)
            : []
        } satisfies DevelopmentalImprintEntry;
      })
      .filter((item): item is DevelopmentalImprintEntry => Boolean(item))
      .slice(-32)
  };
}

function coerceSystemChangeDigestState(input: unknown, fallback: SystemChangeDigestState): SystemChangeDigestState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {
      ...fallback,
      monitoredFiles: fallback.monitoredFiles.slice(),
      recentChanges: fallback.recentChanges.slice()
    };
  }
  const record = input as Record<string, unknown>;
  const monitoredFiles = Array.isArray(record.monitoredFiles)
    ? record.monitoredFiles
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const filePath = typeof value.path === "string" && value.path.trim() ? value.path : "";
          if (!filePath) {
            return null;
          }
          return {
            path: filePath,
            label: typeof value.label === "string" && value.label.trim() ? value.label : path.basename(filePath),
            mtimeMs: typeof value.mtimeMs === "number" && Number.isFinite(value.mtimeMs) ? value.mtimeMs : 0,
            size: typeof value.size === "number" && Number.isFinite(value.size) ? value.size : 0,
            lastSeenAt: typeof value.lastSeenAt === "string" && value.lastSeenAt.trim() ? value.lastSeenAt : fallback.lastCheckedAt || nowIso()
          };
        })
        .filter((item): item is SystemChangeDigestState["monitoredFiles"][number] => Boolean(item))
    : fallback.monitoredFiles.slice();
  const recentChanges = Array.isArray(record.recentChanges)
    ? record.recentChanges
        .map((item) => {
          if (!item || typeof item !== "object" || Array.isArray(item)) {
            return null;
          }
          const value = item as Record<string, unknown>;
          const filePath = typeof value.path === "string" && value.path.trim() ? value.path : "";
          if (!filePath) {
            return null;
          }
          return {
            path: filePath,
            label: typeof value.label === "string" && value.label.trim() ? value.label : path.basename(filePath),
            detectedAt: typeof value.detectedAt === "string" && value.detectedAt.trim() ? value.detectedAt : fallback.lastCheckedAt || nowIso(),
            mtimeMs: typeof value.mtimeMs === "number" && Number.isFinite(value.mtimeMs) ? value.mtimeMs : 0,
            size: typeof value.size === "number" && Number.isFinite(value.size) ? value.size : 0
          };
        })
        .filter((item): item is SystemChangeDigestState["recentChanges"][number] => Boolean(item))
    : fallback.recentChanges.slice();
  return {
    schemaVersion: typeof record.schemaVersion === "string" && record.schemaVersion.trim() ? record.schemaVersion : fallback.schemaVersion,
    summary: typeof record.summary === "string" && record.summary.trim() ? record.summary : fallback.summary,
    lastCheckedAt:
      typeof record.lastCheckedAt === "string" && record.lastCheckedAt.trim() ? record.lastCheckedAt : fallback.lastCheckedAt,
    lastChangedAt:
      typeof record.lastChangedAt === "string" && record.lastChangedAt.trim() ? record.lastChangedAt : fallback.lastChangedAt,
    monitoredFiles,
    recentChanges
  };
}

