const DEFAULT_OPENCLAW_CONFIG_PATH = path.join(os.homedir(), ".openclaw", "openclaw.json");

type MemoryCandidateProviderPreferenceDiagnostic = {
  configuredProvider: "workspace_files" | "openclaw_memory_search" | null;
  resolvedProvider: "workspace_files" | "openclaw_memory_search";
  source: "env" | "openclaw_config" | "default";
  configPath?: string;
};

let cachedMemoryCandidateProviderConfig:
  | {
      path: string;
      mtimeMs: number;
      provider: "workspace_files" | "openclaw_memory_search" | null;
    }
  | null = null;

function openclawConfigPath(): string {
  const explicitPath = process.env.AURORA_OPENCLAW_CONFIG_PATH?.trim();
  if (!explicitPath) {
    return DEFAULT_OPENCLAW_CONFIG_PATH;
  }
  return explicitPath.startsWith("~/") ? path.join(os.homedir(), explicitPath.slice(2)) : explicitPath;
}

function readMemoryCandidateProviderFromOpenClawConfig():
  | {
      provider: "workspace_files" | "openclaw_memory_search" | null;
      configPath: string;
    }
  | null {
  const configPath = openclawConfigPath();
  try {
    if (!existsSync(configPath)) {
      return null;
    }
    const stats = statSync(configPath);
    if (
      cachedMemoryCandidateProviderConfig &&
      cachedMemoryCandidateProviderConfig.path === configPath &&
      cachedMemoryCandidateProviderConfig.mtimeMs === stats.mtimeMs
    ) {
      return {
        provider: cachedMemoryCandidateProviderConfig.provider,
        configPath
      };
    }
    const parsed = JSON.parse(readFileSync(configPath, "utf8")) as {
      agents?: {
        defaults?: {
          memorySearch?: {
            provider?: unknown;
          };
        };
      };
    };
    const providerRaw =
      typeof parsed?.agents?.defaults?.memorySearch?.provider === "string"
        ? parsed.agents.defaults.memorySearch.provider.trim().toLowerCase()
        : "";
    const provider =
      providerRaw && providerRaw !== "none" && providerRaw !== "off" && providerRaw !== "disabled"
        ? "openclaw_memory_search"
        : null;
    cachedMemoryCandidateProviderConfig = {
      path: configPath,
      mtimeMs: stats.mtimeMs,
      provider
    };
    return {
      provider,
      configPath
    };
  } catch {
    return null;
  }
}

