async function loadTopicAffinityStore(filePath = topicAffinityStorePath()): Promise<TopicAffinityStore> {
  try {
    const info = await stat(filePath);
    if (cachedTopicAffinityStore && cachedTopicAffinityStore.path === filePath && cachedTopicAffinityStore.mtimeMs === info.mtimeMs) {
      return cachedTopicAffinityStore.store;
    }
    const raw = await readFile(filePath, "utf8");
    const store = coerceTopicAffinityStore(JSON.parse(raw) as unknown, nowIso());
    cachedTopicAffinityStore = {
      path: filePath,
      mtimeMs: info.mtimeMs,
      store
    };
    return store;
  } catch {
    return coerceTopicAffinityStore(null, nowIso());
  }
}

function loadTopicAffinityStoreSync(filePath = topicAffinityStorePath()): TopicAffinityStore {
  try {
    const info = statSync(filePath);
    if (cachedTopicAffinityStore && cachedTopicAffinityStore.path === filePath && cachedTopicAffinityStore.mtimeMs === info.mtimeMs) {
      return cachedTopicAffinityStore.store;
    }
    const raw = readFileSync(filePath, "utf8");
    const store = coerceTopicAffinityStore(JSON.parse(raw) as unknown, nowIso());
    cachedTopicAffinityStore = {
      path: filePath,
      mtimeMs: info.mtimeMs,
      store
    };
    return store;
  } catch {
    return coerceTopicAffinityStore(null, nowIso());
  }
}

async function saveTopicAffinityStore(store: TopicAffinityStore, filePath = topicAffinityStorePath()): Promise<void> {
  await ensureDirectory(filePath);
  await writeFile(filePath, `${JSON.stringify(store, null, 2)}\n`, "utf8");
  cachedTopicAffinityStore = null;
}

