function setSelectedTopicAffinityRuntime(
  state: CognitiveRuntimeState,
  store: TopicAffinityStore,
  query: string,
  linkedEntities: string[] = []
): TopicAffinitySelection[] {
  const runtime = ensureExtensions(state).topicAffinityRuntime;
  const selection = selectRelevantTopicAffinities(store, {
    query,
    linkedEntities
  });
  runtime.lastLoadedAt = nowIso();
  runtime.storeUpdatedAt = store.updatedAt;
  runtime.selected = selection.selected;
  runtime.bias = selection.bias;
  return selection.selected;
}

function clearSelectedTopicAffinityRuntime(state: CognitiveRuntimeState): void {
  ensureExtensions(state).topicAffinityRuntime = defaultTopicAffinityRuntimeState();
}

