function memoryCandidateProviderPreferenceDiagnostic(): MemoryCandidateProviderPreferenceDiagnostic {
  const raw = process.env.AURORA_MEMORY_CANDIDATE_PROVIDER?.trim().toLowerCase();
  if (raw === "openclaw_memory_search" || raw === "openclaw-search" || raw === "openclaw_search") {
    return {
      configuredProvider: "openclaw_memory_search",
      resolvedProvider: "openclaw_memory_search",
      source: "env"
    };
  }
  if (raw === "workspace_files" || raw === "workspace-files" || raw === "workspace") {
    return {
      configuredProvider: "workspace_files",
      resolvedProvider: "workspace_files",
      source: "env"
    };
  }
  const configProvider = readMemoryCandidateProviderFromOpenClawConfig();
  if (configProvider?.provider) {
    return {
      configuredProvider: configProvider.provider,
      resolvedProvider: configProvider.provider,
      source: "openclaw_config",
      configPath: configProvider.configPath
    };
  }
  return {
    configuredProvider: null,
    resolvedProvider: "workspace_files",
    source: "default",
    ...(configProvider?.configPath ? { configPath: configProvider.configPath } : {})
  };
}

