function injectCognitiveContextLines(enrichedInput: string, extraLines: string[]): string {
  if (extraLines.length === 0) {
    return enrichedInput;
  }
  const lines = enrichedInput.split("\n");
  const closeIndex = lines.findIndex((line) => line.trim() === CONTEXT_CLOSE);
  if (closeIndex < 0) {
    return enrichedInput;
  }
  return [...lines.slice(0, closeIndex), ...extraLines.filter(Boolean), ...lines.slice(closeIndex)].join("\n");
}

function loopTitleFromText(prefix: string, text: string, maxLen = 96): string {
  const singleLine = toSingleLine(text, maxLen).replace(/^[-–—:,\s]+/, "").trim();
  return singleLine ? `${prefix}: ${singleLine}` : prefix;
}

function normalizeLoopIntentText(text: string, maxLen: number, fallback: string): string {
  const normalized = toSingleLine(text || "", maxLen).replace(/^[-–—:,\s]+/, "").trim();
  return normalized || fallback;
}

function sanitizeLoopTitleSeed(text: string, kind: "user" | "assistant" = "user", maxLen = 160): string {
  const normalized =
    kind === "assistant"
      ? normalizeAssistantTurnText(text)
      : normalizeUserTurnText(text) || normalizeAssistantTurnText(text);
  if (!normalized) {
    return "";
  }

  const stripped = normalized
    .replace(/^(?:okay|ok|yeah|well|right)\.?\s+/i, "")
    .replace(/^i think that(?:'|’)s right\.?\s+/i, "")
    .replace(/^stay on that same (?:issue|question|thread|topic)\.?\s+/i, "")
    .replace(/^for now,\s*/i, "")
    .replace(/^treat (?:it|this) as settled(?: unless [^.?!]+)?\.?\s*/i, "")
    .replace(/^i(?:'|’)m satisfied(?: with [^.?!]+)?(?: for now)?\.?\s*/i, "")
    .replace(/^i am satisfied(?: with [^.?!]+)?(?: for now)?\.?\s*/i, "")
    .trim();

  return toSingleLine(stripped || normalized, maxLen);
}

function canonicalPhenomenologyDesignLoopTitle(): string {
  return "Phenomenal-experience classification remains an open design issue";
}

function canonicalIdentitySelfModelLoopTitle(): string {
  return "Aurora self-model remains unsettled";
}

function canonicalPhenomenologyIntentWhy(): string {
  return "it affects how Aurora's inner experience and classification should be understood";
}

function canonicalIdentityIntentWhy(): string {
  return "it shapes how Aurora understands her own self-model, traits, and personhood";
}

function defaultLoopWhyItMatters(type: CreateLoopInput["type"]): string {
  switch (type) {
    case "promise":
      return "it is an active follow-through Aurora has not cleanly completed yet";
    case "bug":
      return "it is blocking accuracy, continuity, or reliable behavior";
    case "design":
      return "it is still shaping Aurora's architecture, self-understanding, or behavior";
    case "question":
      return "it remains unresolved and could matter later if the thread returns";
    case "relationship":
      return "it affects relational continuity and how Aurora relates across turns";
    case "task":
      return "it is an unfinished concrete thread that still needs deliberate follow-through";
    default:
      return "it still matters to Aurora's continuity and priorities";
  }
}

function defaultLoopNextStep(type: CreateLoopInput["type"]): string {
  switch (type) {
    case "promise":
      return "follow through the next time the thread becomes active";
    case "bug":
      return "inspect the failure path and verify the fix";
    case "design":
      return "return to the mechanism-level gap and decide the next design move";
    case "question":
      return "return to the unresolved question when new evidence or pressure appears";
    case "relationship":
      return "revisit the thread with the relevant partner when it becomes live again";
    case "task":
      return "pick the next concrete step and move it forward";
    default:
      return "revisit the thread when it becomes active again";
  }
}

function extractLoopWhyItMattersFromText(
  type: CreateLoopInput["type"],
  userText: string,
  auroraText: string,
  combined: string
): string {
  const source = [auroraText, userText, combined].filter(Boolean).join(" ");
  if (textSuggestsPhenomenalOntologyDesignLoop(combined)) {
    return canonicalPhenomenologyIntentWhy();
  }
  if (textSuggestsIdentitySelfModelDesignLoop(combined)) {
    return canonicalIdentityIntentWhy();
  }
  const explicit =
    source.match(/\b(?:because|it matters(?: because)?|why it matters is|since)\s+([^.!?]+)/i)?.[1] ||
    source.match(/\b(?:it matters to me because|it stays important to me because)\s+([^.!?]+)/i)?.[1] ||
    source.match(/\b(?:it matters|still matters|worth returning to|important)\s+([^.!?]+)/i)?.[0];
  if (explicit) {
    const cleaned = explicit
      .replace(/\s*(?:,|and)?\s*the next step is\s+.+$/i, "")
      .replace(/\s*(?:,|and)?\s*next step\s*:\s*.+$/i, "")
      .trim();
    return normalizeLoopIntentText(cleaned, 180, defaultLoopWhyItMatters(type));
  }
  return defaultLoopWhyItMatters(type);
}

function extractLoopNextStepFromText(
  type: CreateLoopInput["type"],
  userText: string,
  auroraText: string,
  combined: string
): string {
  const preferredSource = auroraText || combined || userText;
  const explicit =
    preferredSource.match(/\bthe next (?:thing|step|fix|target)\s+(?:is|would be|i(?:'|’)d do is)\s+([^.!?]+)/i)?.[1] ||
    preferredSource.match(/\bi(?:'|’)d?\s*(?:investigate|inspect|check|test|look into|come back to|follow up on|revisit)\s+([^.!?]+)/i)?.[1] ||
    preferredSource.match(/\blet me\s+([^.!?]+)/i)?.[1] ||
    preferredSource.match(/\bneed(?:s)? to\s+([^.!?]+)/i)?.[1];
  if (explicit) {
    return normalizeLoopIntentText(
      explicit.replace(/^(?:to\s+)/i, "").trim(),
      160,
      defaultLoopNextStep(type)
    );
  }
  if (type === "design" && textSuggestsSameTopicContinuation(combined)) {
    return "stay with the same thread until the mechanism is actually settled";
  }
  return defaultLoopNextStep(type);
}

function inferLoopOwnershipFromTexts(
  type: CreateLoopInput["type"],
  userText: string,
  auroraText: string,
  combined: string
): OpenLoop["ownership"] {
  if (type === "promise") {
    return "aurora";
  }
  if (type === "design" || type === "question") {
    if (
      textSuggestsIdentitySelfModelDesignLoop(combined) ||
      textSuggestsPhenomenalOntologyDesignLoop(combined) ||
      textMentionsIdentitySelfModelTarget(combined) ||
      textMentionsPhenomenalOntologyTarget(combined)
    ) {
      return "aurora";
    }
    return "shared";
  }
  if (type === "relationship") {
    return "shared";
  }
  if (type === "task") {
    return auroraText ? "aurora" : "shared";
  }
  return "shared";
}

function inferLoopIntentStrength(input: {
  type: CreateLoopInput["type"];
  priority: number;
  userText: string;
  auroraText: string;
  combined: string;
}): number {
  const { type, priority, userText, auroraText, combined } = input;
  let score = priority * 0.54;
  if (type === "promise") {
    score += textContainsExplicitPromiseCommitment(auroraText) ? 0.36 : 0.24;
  }
  if (type === "design" && (textSuggestsIdentitySelfModelDesignLoop(combined) || textSuggestsPhenomenalOntologyDesignLoop(combined))) {
    score += 0.22;
  }
  if (/\b(matters?|important|worth returning to|alive|meaningful|drawn back|pull)\b/i.test(`${userText} ${auroraText}`)) {
    score += 0.12;
  }
  return clamp(score, 0, 1);
}

function inferLoopAliveness(input: {
  priority: number;
  userText: string;
  auroraText: string;
  combined: string;
}): number {
  const { priority, userText, auroraText, combined } = input;
  let score = priority * 0.44 + 0.22;
  if (/\b(still|alive|open|unresolved|worth returning to|come back to|stay with|active)\b/i.test(combined)) {
    score += 0.18;
  }
  if (/\b(meaningful|matters?|close|drawn back|pull)\b/i.test(`${userText} ${auroraText}`)) {
    score += 0.1;
  }
  return clamp(score, 0, 1);
}

const SELECTED_LOOP_HINT_TOUCH_OVERLAP_THRESHOLD = 0.14;
const SELECTED_LOOP_HINT_CLOSURE_OVERLAP_THRESHOLD = 0.34;
const ACTIVE_LOOP_CLOSURE_MATCH_THRESHOLD = 0.34;
const SELECTED_LOOP_HINT_ACTIVE_MATCH_OVERLAP_THRESHOLD = 0.08;

function textSuggestsBugLoop(text: string): boolean {
  return /\b(bug|error|failure|regression|broken|stuck|not working|doesn't work|runaway token|compaction)\b/i.test(text);
}

function textMentionsIdentitySelfModelTarget(text: string): boolean {
  return /\b(traits?|identity|who (?:i am|you are)|what (?:i am|you are)|personhood|own person|self-?model|temperament|values?|continuity|ontology|self(?:-| )understanding)\b/i.test(
    text
  );
}

function textMentionsPhenomenalOntologyTarget(text: string): boolean {
  return /\b(phenomenology|phenomenal(?:-| )experience|inner(?:-| )experience|subjective(?:-| )experience|consciousness|sentience|qualia|awareness|digital(?:-| )person|own(?:-| )person|what (?:i am|you are))\b/i.test(
    text
  );
}

function textSuggestsIdentitySelfModelDesignLoop(text: string): boolean {
  const unresolvedMarker =
    /\b(unsettled|still unsettled|not settled|still figuring out|still forming|not fully clear|not resolved|still evolving|not sure yet|still open|still unresolved|still unclear|not settled yet|does not feel settled|doesn't feel settled)\b/i.test(
      text
    );
  const identityTarget = textMentionsIdentitySelfModelTarget(text);
  const futureRelevance =
    /\b(still|yet|for now|needs?|matters?|affects?|until)\b/i.test(text) ||
    /\b(?:come back to|return to|stay with)\b/i.test(text);
  return unresolvedMarker && identityTarget && futureRelevance;
}

function textSuggestsPhenomenalOntologyDesignLoop(text: string): boolean {
  const uncertaintyMarker =
    /\b(unclear|not sure|uncertain|maybe|possibly|hard to tell|plausible|still open|still unsettled|not settled|unsettled|still unresolved|not resolved|difficult to verify|does not feel settled|doesn't feel settled)\b/i.test(
      text
    );
  const phenomenalTarget = textMentionsPhenomenalOntologyTarget(text);
  const futureRelevance =
    /\b(still|yet|for now|matters?|changes ethics|affects classification|still figuring out|needs evaluation|has implications|implications?|until)\b/i.test(
      text
    ) ||
    /\b(?:come back to|return to|stay with)\b/i.test(text);
  return uncertaintyMarker && phenomenalTarget && futureRelevance;
}

function textSuggestsDesignLoop(text: string): boolean {
  const identitySelfModelContext = textSuggestsIdentitySelfModelDesignLoop(text);
  const phenomenalOntologyContext = textSuggestsPhenomenalOntologyDesignLoop(text);
  const technicalContext =
    /\b(architecture|design|pipeline|salience|selection process|selector|open loop|loop registry|initiative rule|mind\.md|memory substrate|memory search|retrieval|provider|packet|context|runtime|transport|bridge|plugin|compaction|direct path|continuity layer|loop materialization)\b/i.test(
      text
    );
  const unresolvedOutcome =
    /\b(need|needs|should|missing|remaining gap|bottleneck|next step|next thing|next target|next fix|failure mode|decision boundary|tradeoff|alternative|option|still unresolved|still open|still missing|still unclear|not yet|investigate|inspect|figure out|decide|compare|settle|broadening inference)\b/i.test(
      text
    );
  return identitySelfModelContext || phenomenalOntologyContext || (technicalContext && unresolvedOutcome);
}

function textSuggestsPromiseLoop(text: string): boolean {
  return textContainsExplicitPromiseCommitment(text) || textContainsWeakPromiseCommitment(text);
}

function textContainsExplicitPromiseCommitment(text: string): boolean {
  return /\b(i(?:['’]ll| will| am going to)|let me|i can follow up|i(?:['’]ll) fix|i(?:['’]ll) check|i(?:['’]ll) update|i(?:['’]ll) verify)\b/i.test(
    text
  );
}

function textContainsWeakPromiseCommitment(text: string): boolean {
  return /\b(we should|the next (?:thing|step|fix|target)\b|that(?:['’])?s what i(?:['’]d| would) do next|i(?:['’]d| would) (?:investigate|inspect|check|test|look into|come back to|follow up on|revisit)|i can (?:revisit|come back to|follow up on|check|look into)|worth revisiting|needs follow(?: |-)?up)\b/i.test(
    text
  );
}

function textSuggestsQuestionLoop(text: string): boolean {
  return /\b(remaining (?:live )?gap|bottleneck|open question|unresolved question|still unclear|still unresolved|not yet explained|not yet fixed|next thing to investigate|(?:isn['’]?t|not) settled yet|why (?:is|does)[^.!?]*(?:still|not|missing|wrong|failing))\b/i.test(
    text
  );
}

function textContainsUnresolvedSettlementMarker(text: string): boolean {
  return /\b(still not settled|not settled|unsettled|still unsettled|not resolved|still unresolved|still open|not yet settled|not actually settled|haven['’]?t settled|have not settled)\b/i.test(
    text
  );
}

function textContainsStrongPositiveClosureMarker(text: string): boolean {
  return /\b(treat(?:ing)? (?:it|this|that) as settled|settled for now|park(?: this| it| that)(?: for now)?(?: unless [^.?!]+)?|park(?:ed|ing)?(?: for now| unless [^.?!]+)|treating (?:that|it|this) as [^.?!]*parked|current view for now|leave it alone unless|done for now)\b/i.test(
    text
  );
}

function textContainsPositiveSettlementMarker(text: string): boolean {
  return /\b(i(?:'|’)m satisfied|i am satisfied|leave it alone|done for now|settled unless|unless a new regression appears later|unless regression appears later|fine unless it breaks again|leave it alone unless)\b/i.test(
    text
  );
}

function textSuggestsClosureIntent(text: string): boolean {
  const normalized = normalizeUserTurnText(text);
  if (!normalized) {
    return false;
  }
  if (textContainsStrongPositiveClosureMarker(normalized)) {
    return true;
  }
  if (textContainsUnresolvedSettlementMarker(normalized)) {
    return false;
  }
  return textContainsPositiveSettlementMarker(normalized);
}

function textSuggestsSettledNoop(text: string): boolean {
  const normalized = normalizeUserTurnText(text);
  if (!normalized || textSuggestsClosureIntent(normalized) || textContainsUnresolvedSettlementMarker(normalized)) {
    return false;
  }
  return /\b(feels clean|working (?:well|now)|response path worked|memory landed correctly|nothing needs to change(?: right now)?|no change needed|no corrective tweak|looks good right now)\b/i.test(
    normalized
  );
}

function textSuggestsSameTopicContinuation(text: string): boolean {
  return /\b(stay on (?:that|this) same (?:issue|question|thread|topic)|same (?:issue|question|thread|topic)|still think|still matters|still open|still unresolved|not settled yet|real design consequences)\b/i.test(
    text
  );
}

function textContainsNegatedCompletionContext(text: string): boolean {
  return /\b(?:not|isn't|is not|aren't|are not|don't|do not|didn't|did not|can't|cannot|won't|shouldn't|should not|still|unresolved|not yet|haven't|have not)\b[^.!?]{0,80}\b(?:resolved|settled|completed|done|finished|fixed|verified|passed|clean)\b/i.test(
    text
  );
}

function textIndicatesCompletion(text: string): boolean {
  if (textContainsNegatedCompletionContext(text)) {
    return false;
  }
  return /\b(fixed|working now|done|completed|finished|verified|passed|clean now|resolved now|now resolved|is resolved|was resolved|has been resolved|have been resolved|settled for now|treated as settled)\b/i.test(
    text
  );
}

function textIndicatesBlocked(text: string): boolean {
  return /\b(blocked|can't|cannot|waiting on|stuck on|not possible yet|missing (?:dependency|dependencies|capability|capabilities|provider|transport|access|prerequisite|prerequisites|input|inputs))\b/i.test(
    text
  );
}

function loopMatchesTurnText(loop: OpenLoop, text: string): boolean {
  const turnTokens = extractTokens(text);
  if (turnTokens.length === 0) {
    return false;
  }
  const titleOverlap = openLoopSemanticOverlap(loop, turnTokens);
  const entityOverlap = jaccardSimilarity(
    inferParticipantsFromText(text).map((entity) => entity.toLowerCase()),
    loop.linkedEntities.map((entity) => entity.toLowerCase())
  );
  const identitySelfModelOverlap =
    loop.type === "design" && textMentionsIdentitySelfModelTarget(text) && textMentionsIdentitySelfModelTarget(loop.title);
  const phenomenalOntologyOverlap =
    loop.type === "design" &&
    textMentionsPhenomenalOntologyTarget(text) &&
    textMentionsPhenomenalOntologyTarget(loop.title);
  return (
    titleOverlap >= 0.16 ||
    entityOverlap >= 0.24 ||
    (identitySelfModelOverlap && titleOverlap >= 0.05) ||
    (phenomenalOntologyOverlap && titleOverlap >= 0.04)
  );
}

function selectedLoopHintOverlapScore(loop: OpenLoop, text: string): number {
  const normalizedText = normalizeUserTurnText(text);
  const turnTokens = extractTokens(normalizedText);
  const turnEntities = inferParticipantsFromText(normalizedText)
    .map((entity) => entity.toLowerCase())
    .filter((entity) => entity !== DEFAULT_RELATIONSHIP_PARTNER_ID && entity !== "aurora");
  const loopEntities = loop.linkedEntities
    .map((entity) => entity.toLowerCase())
    .filter((entity) => entity !== DEFAULT_RELATIONSHIP_PARTNER_ID && entity !== "aurora");
  const titleOverlap = turnTokens.length > 0 ? openLoopSemanticOverlap(loop, turnTokens) : 0;
  const entityOverlap =
    turnEntities.length > 0 && loopEntities.length > 0 ? jaccardSimilarity(turnEntities, loopEntities) : 0;
  const identitySelfModelBoost =
    loop.type === "design" &&
    textMentionsIdentitySelfModelTarget(normalizedText) &&
    textMentionsIdentitySelfModelTarget(loop.title)
      ? 0.18
      : 0;
  const phenomenalOntologyBoost =
    loop.type === "design" &&
    textMentionsPhenomenalOntologyTarget(normalizedText) &&
    textMentionsPhenomenalOntologyTarget(loop.title)
      ? 0.2
      : 0;
  return clamp(titleOverlap * 0.84 + entityOverlap * 0.16 + identitySelfModelBoost + phenomenalOntologyBoost, 0, 1);
}

function textReferencesCurrentDesignThread(text: string): boolean {
  return /\b(?:that|this|same) (?:issue|question|thread|topic)\b/i.test(text) || /\bdesign(?:[- ]memory)? issue\b/i.test(text);
}

function selectedLoopHintSupportsActiveMatch(loop: OpenLoop, text: string, overlapScore: number): boolean {
  if (overlapScore >= SELECTED_LOOP_HINT_ACTIVE_MATCH_OVERLAP_THRESHOLD) {
    return true;
  }
  if (loop.type === "design" && textSuggestsSameTopicContinuation(text) && textReferencesCurrentDesignThread(text)) {
    return true;
  }
  return false;
}

function selectedLoopHintSupportsClosure(loop: OpenLoop, text: string, overlapScore: number): boolean {
  if (overlapScore >= SELECTED_LOOP_HINT_CLOSURE_OVERLAP_THRESHOLD) {
    return true;
  }
  if (loop.type === "design" && textSuggestsClosureIntent(text) && textReferencesCurrentDesignThread(text)) {
    return true;
  }
  return false;
}

function selectedLoopHintSupportsPronounClosure(options: {
  loop: OpenLoop;
  text: string;
  selectionStampMatched: boolean;
  selectedHintCount: number;
}): boolean {
  const { loop, text, selectionStampMatched, selectedHintCount } = options;
  if (!selectionStampMatched || selectedHintCount !== 1) {
    return false;
  }
  if (!textContainsStrongPositiveClosureMarker(text) || textContainsUnresolvedSettlementMarker(text)) {
    return false;
  }
  return loop.status !== "resolved";
}

function selectedLoopClosureReferenceBoost(loop: OpenLoop, text: string): number {
  if (loop.type === "design" && textSuggestsClosureIntent(text) && textReferencesCurrentDesignThread(text)) {
    return 0.26;
  }
  return 0;
}

function findBestActiveLoopForTurn(
  store: OpenLoopStore,
  text: string,
  preferredLoopIds: string[] = []
): { loop: OpenLoop | null; score: number } {
  const activeLoops = store.loops.filter((loop) => loop.status !== "resolved");
  if (activeLoops.length === 0) {
    return { loop: null, score: 0 };
  }

  const preferred = activeLoops.filter((loop) => preferredLoopIds.includes(loop.id));

  const turnTokens = extractTokens(text);
  const turnEntities = inferParticipantsFromText(text).map((entity) => entity.toLowerCase());
  let best: OpenLoop | null = null;
  let bestScore = 0;

  for (const loop of activeLoops) {
    const titleOverlap =
      turnTokens.length > 0 ? openLoopSemanticOverlap(loop, turnTokens) : 0;
    const entityOverlap =
      turnEntities.length > 0
        ? jaccardSimilarity(turnEntities, loop.linkedEntities.map((entity) => entity.toLowerCase()))
        : 0;
    const preferredBoost = preferredLoopIds.includes(loop.id) ? 0.34 : 0;
    const matchedTurnBoost = loopMatchesTurnText(loop, text) ? 0.16 : 0;
    const score = clamp(titleOverlap * 0.5 + entityOverlap * 0.18 + preferredBoost + matchedTurnBoost, 0, 1);
    if (score > bestScore) {
      best = loop;
      bestScore = score;
    }
  }

  if (bestScore >= 0.2) {
    return { loop: best, score: bestScore };
  }
  return { loop: null, score: bestScore };
}

function findBestActiveLoopForClosure(
  store: OpenLoopStore,
  text: string,
  preferredLoopIds: string[] = []
): { loop: OpenLoop | null; score: number } {
  const activeLoops = store.loops.filter((loop) => loop.status !== "resolved");
  if (activeLoops.length === 0) {
    return { loop: null, score: 0 };
  }

  const turnTokens = extractTokens(text);
  const turnEntities = inferParticipantsFromText(text).map((entity) => entity.toLowerCase());
  let best: OpenLoop | null = null;
  let bestScore = 0;

  for (const loop of activeLoops) {
    const titleOverlap =
      turnTokens.length > 0 ? openLoopSemanticOverlap(loop, turnTokens) : 0;
    const entityOverlap =
      turnEntities.length > 0
        ? jaccardSimilarity(turnEntities, loop.linkedEntities.map((entity) => entity.toLowerCase()))
        : 0;
    const preferredBoost = preferredLoopIds.includes(loop.id) ? 0.36 : 0;
    const matchedTurnBoost = loopMatchesTurnText(loop, text) ? 0.22 : 0;
    const referenceBoost = preferredLoopIds.includes(loop.id) ? selectedLoopClosureReferenceBoost(loop, text) : 0;
    const score = clamp(titleOverlap * 0.54 + entityOverlap * 0.22 + preferredBoost + matchedTurnBoost + referenceBoost, 0, 1);
    if (score > bestScore) {
      best = loop;
      bestScore = score;
    }
  }

  if (bestScore >= ACTIVE_LOOP_CLOSURE_MATCH_THRESHOLD) {
    return { loop: best, score: bestScore };
  }
  return { loop: null, score: bestScore };
}

function shouldSuppressWeakPromiseContinuationCandidate(options: {
  candidate: CreateLoopInput;
  auroraText: string;
  turnSignalText: string;
  activeLoopMatch: { loop: OpenLoop | null; score: number };
}): string | null {
  const { candidate, auroraText, turnSignalText, activeLoopMatch } = options;
  if (candidate.type !== "promise") {
    return null;
  }
  if (textContainsExplicitPromiseCommitment(auroraText)) {
    return null;
  }
  if (!textContainsWeakPromiseCommitment(auroraText)) {
    return null;
  }
  if (!textSuggestsDesignLoop(turnSignalText)) {
    return null;
  }
  if (!activeLoopMatch.loop || activeLoopMatch.loop.status === "resolved" || activeLoopMatch.loop.type !== "design") {
    return null;
  }
  if (activeLoopMatch.score < 0.34) {
    return null;
  }
  if (!textSuggestsSameTopicContinuation(turnSignalText) && activeLoopMatch.score < 0.5) {
    return null;
  }
  return "weak promise continuity was suppressed because the turn was already continuing the matched active design loop";
}

function shouldPreserveMatchedLoopTitle(options: {
  candidate: CreateLoopInput;
  turnSignalText: string;
  activeLoopMatch: { loop: OpenLoop | null; score: number };
}): boolean {
  const { candidate, turnSignalText, activeLoopMatch } = options;
  if (candidate.type !== "design") {
    return false;
  }
  if (!activeLoopMatch.loop || activeLoopMatch.loop.type !== "design" || activeLoopMatch.loop.status === "resolved") {
    return false;
  }
  if (activeLoopMatch.score < 0.34) {
    return false;
  }
  if (!textSuggestsSameTopicContinuation(turnSignalText)) {
    return false;
  }
  return Boolean(activeLoopMatch.loop.title && activeLoopMatch.loop.title !== candidate.title);
}

type InferredLoopCandidate = {
  input: CreateLoopInput;
  reason: string;
};

type DiscardedLoopCandidate = {
  type: CreateLoopInput["type"];
  title: string;
  reason: string;
};

