function ensurePartnerLearnedUnifiedManifold32(
  state: CognitiveRuntimeState,
  rawPartnerId: string
): LearnedUnifiedManifold32State {
  const extensions = ensureExtensions(state);
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!extensions.partnerUnified32[partnerId]) {
    extensions.partnerUnified32[partnerId] = cloneUnifiedManifold32State(extensions.learnedUnifiedManifold32Global);
  }
  if (extensions.activeRelationshipPartnerId === partnerId) {
    extensions.learnedUnifiedManifold32 = extensions.partnerUnified32[partnerId];
  }
  return extensions.partnerUnified32[partnerId];
}

