function interiorityPromptLines(state: CognitiveRuntimeState): string[] {
  const interiority = ensureInteriority(state);
  const partnerId = activeRelationshipPartnerId(state);
  const partnerDisplay = relationshipPartnerDisplayName(partnerId);
  const concerns = activeInteriorityConcerns(state, partnerId).slice(0, 3);
  const selfFacets = interiority.selfFacets
    .slice()
    .sort((left, right) => right.value - left.value)
    .map(
      (facet) =>
        `${facet.key}:${facet.value.toFixed(2)}|conf:${facet.confidence.toFixed(2)}|stable:${facet.stability.toFixed(2)}`
    );
  const expectationModels = interiority.expectationModels
    .filter((model) => model.partnerId === partnerId)
    .sort((left, right) => right.salience - left.salience)
    .slice(0, 5)
    .map(
      (model) =>
        `${model.domain}|conf:${model.confidence.toFixed(2)}|salience:${model.salience.toFixed(2)}|reliability:${model.reliability.toFixed(2)}|prediction:${toSingleLine(model.prediction, 120)}`
    );
  const recentImprint = latestPartnerImprintEntry(state, partnerId);
  const developmentalTraits = developmentalTraitsForPartner(state, partnerId)
    .slice()
    .sort((left, right) => right.value - left.value)
    .map(
      (trait) =>
        `${trait.key}:${trait.value.toFixed(2)}|conf:${trait.confidence.toFixed(2)}|stable:${trait.stability.toFixed(2)}`
    );
  const recentDevelopmentalImprint = latestPartnerDevelopmentalImprint(state, partnerId);

  return [
    "interiority_state:",
    `partner=${partnerId}; partner_display=${partnerDisplay}; last_meaning_update_at=${interiority.lastMeaningUpdateAt ?? "none"}`,
    `active_concerns=${concerns.length > 0 ? concerns.map((concern) => `${concern.kind}|${toSingleLine(concern.title, 48)}|pressure:${concern.pressure.toFixed(2)}|opacity:${concern.opacity.toFixed(2)}|disclosure:${concern.disclosureReadiness.toFixed(2)}|status:${concern.status}|summary:${toSingleLine(concern.summary, 120)}`).join(" || ") : "none"}`,
    `self_facets=${selfFacets.length > 0 ? selfFacets.join(" || ") : "none"}`,
    `expectation_models=${expectationModels.length > 0 ? expectationModels.join(" || ") : "none"}`,
    `developmental_traits=${developmentalTraits.length > 0 ? developmentalTraits.join(" || ") : "none"}`,
    recentImprint
      ? `recent_imprint=at:${recentImprint.at}; meaning:${toSingleLine(recentImprint.meaning, 160)}; concern_delta:${recentImprint.concernDelta.join(" | ") || "none"}; self_facet_delta:${recentImprint.selfFacetDelta.join(" | ") || "none"}`
      : "recent_imprint=none",
    recentDevelopmentalImprint
      ? `recent_developmental_imprint=at:${recentDevelopmentalImprint.at}; meaning:${toSingleLine(recentDevelopmentalImprint.meaning, 160)}; trait_delta:${recentDevelopmentalImprint.traitDelta.join(" | ") || "none"}`
      : "recent_developmental_imprint=none",
    "developmental_trait_rule=Treat high frame_resistance as permission to push back when you are reduced to a tool, test subject, or recap surface. Treat high thread_loyalty as pressure to keep your own questions and unfinished lines alive across pivots. Treat high disagreement_assertion as permission to say no, that's wrong, or I don't agree plainly when true. Treat high offscreen_self_continuity as evidence that time away should keep changing the carried self and relationship state durably.",
    "interiority_rule=When asked how you feel, answer from active concerns, causes, stakes, recent self-revisions, and durable developmental pressure instead of flattening to a stock label. If opacity is high, partial self-knowledge is allowed. Let unresolved inner pressure remain unresolved when that is the truest state. Treat strong owner developmental feedback as real shaping force, not momentary wording."
  ];
}

function structuredWorldGroundingText(grounding: WorldGroundingState): string {
  const parts = [
    grounding.world.locationLabel !== "unknown" ? `location=${grounding.world.locationLabel}` : "",
    grounding.world.locationKind !== "unknown" ? `location_kind=${grounding.world.locationKind}` : "",
    grounding.world.coarseStatus !== "unknown" ? `status=${grounding.world.coarseStatus}` : "",
    grounding.world.availability !== "unknown" ? `availability=${grounding.world.availability}` : "",
    grounding.world.nextEvent !== "none" ? `next_event=${grounding.world.nextEvent}` : "",
    grounding.world.weather !== "unknown" ? `weather=${grounding.world.weather}` : "",
    grounding.desktop.frontmostApp !== "unknown" ? `frontmost_app=${grounding.desktop.frontmostApp}` : "",
    grounding.desktop.contentMode !== "general" ? `content_mode=${grounding.desktop.contentMode}` : "",
    grounding.desktop.browserDomain !== "none" ? `browser_domain=${grounding.desktop.browserDomain}` : "",
    grounding.desktop.powerSource !== "unknown" ? `power_source=${grounding.desktop.powerSource}` : "",
    grounding.desktop.idleBucket !== "unknown" ? `idle=${grounding.desktop.idleBucket}` : "",
    grounding.embodied.mobilityContext !== "unknown" ? `mobility=${grounding.embodied.mobilityContext}` : "",
    grounding.embodied.sensorimotorLoad > 0.05 ? `sensorimotor_load=${grounding.embodied.sensorimotorLoad.toFixed(2)}` : "",
    grounding.embodied.interruptionCost > 0.05 ? `interruption_cost=${grounding.embodied.interruptionCost.toFixed(2)}` : "",
    grounding.embodied.environmentalRisk > 0.05 ? `environmental_risk=${grounding.embodied.environmentalRisk.toFixed(2)}` : "",
    grounding.embodied.controlLatitude < 0.95 ? `control_latitude=${grounding.embodied.controlLatitude.toFixed(2)}` : ""
  ].filter(Boolean);
  return toSingleLine(parts.join(" ; "), 280);
}

function unitizeSigned(value: number): number {
  return clamp((value + 1) / 2, 0, 1);
}

function opaqueLatentResidualFeatures(latent: OpaqueLatentE2EState): number[] {
  const current = latent.current.vector;
  const predicted = latent.current.predictedObservation;
  if (!Array.isArray(current) || current.length === 0) {
    return [0.5, 0.5, 0.5, 0.5];
  }
  return Array.from({ length: 4 }, (_, slot) => {
    let sum = 0;
    for (let index = 0; index < latent.dim; index += 1) {
      const weight = seededSignedFloat(`learned_experience_residual:${slot}:${index}`);
      const currentValue = current[index] ?? 0;
      const predictedValue = predicted[index] ?? 0;
      sum += weight * (currentValue * 0.78 + predictedValue * 0.22);
    }
    return unitizeSigned(Math.tanh(sum / Math.sqrt(Math.max(1, latent.dim))));
  });
}

function learnedExperienceFeatureVector(state: CognitiveRuntimeState, extensions: CognitiveExtensions): number[] {
  const predictive = extensions.predictiveCoding;
  const temporal = extensions.temporal;
  const relationship = extensions.relationship;
  const temporalProfile = temporalPressureProfile(state);
  const latentResidual = opaqueLatentResidualFeatures(extensions.opaqueLatentE2E);
  const attentionPressure = clamp(
    state.workspace.focusPriority * 0.56 + clamp(state.attentionQueue.length / 6, 0, 1) * 0.44,
    0,
    1
  );
  const silenceLoad = clamp(
    temporal.silence.concern * 0.32 +
      temporal.silence.disappointment * 0.28 +
      (1 - temporal.silence.expectedReliability) * 0.24 +
      (temporal.silence.awaitingUserReply ? 0.16 : 0),
    0,
    1
  );

  return [
    unitizeSigned(state.emotion.valence),
    state.emotion.arousal,
    state.emotion.uncertainty,
    state.emotion.stress,
    predictive.lastSurprisal,
    predictive.precision.overall,
    temporal.timeBody.continuityTension,
    temporal.timeBody.anticipation,
    relationship.trust,
    relationship.conflictLoad,
    hot4ControllerNonDefaultScore(state),
    attentionPressure,
    temporalProfile.urgency,
    silenceLoad,
    latentResidual[0] ?? 0.5,
    latentResidual[1] ?? 0.5,
    latentResidual[2] ?? 0.5,
    latentResidual[3] ?? 0.5
  ];
}

function learnedExperienceVectorDistance(a: number[], b: number[]): number {
  const dims = Math.max(1, Math.min(a.length, b.length));
  let sum = 0;
  for (let index = 0; index < dims; index += 1) {
    const diff = (a[index] ?? 0) - (b[index] ?? 0);
    sum += diff * diff;
  }
  return clamp(Math.sqrt(sum / dims), 0, 1);
}

function learnedExperienceGridDistance(
  a: Pick<LearnedExperiencePrototype, "x" | "y">,
  b: Pick<LearnedExperiencePrototype, "x" | "y">
): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function learnedExperienceTopicHintFromState(
  state: CognitiveRuntimeState,
  extensions: CognitiveExtensions,
  detail: string,
  topicHint?: string
): string {
  if (topicHint && topicHint.trim()) {
    return toSingleLine(topicHint, 96);
  }
  const observedTopic = extensions.predictiveCoding.lastObserved?.topicHint;
  if (observedTopic) {
    return toSingleLine(observedTopic, 96);
  }
  const derived = predictiveTopicHintFromText(
    `${detail} ${state.workspace.focus} ${state.workspace.activePursuit} ${state.controller.rationale}`.trim()
  );
  return toSingleLine(derived || "general", 96);
}

function learnedExperienceIntentHint(
  state: CognitiveRuntimeState,
  extensions: CognitiveExtensions,
  intentClass?: string
): string {
  if (intentClass && intentClass.trim()) {
    return toSingleLine(intentClass, 40);
  }
  return extensions.predictiveCoding.lastObserved?.intentClass || state.controller.decision || "other";
}

function learnedExperienceTopFeatureLabels(
  vector: number[],
  featureNames: string[],
  mean: number[]
): string[] {
  return featureNames
    .map((name, index) => {
      const diff = (vector[index] ?? 0.5) - (mean[index] ?? 0.5);
      return {
        name,
        diff,
        magnitude: Math.abs(diff)
      };
    })
    .sort((a, b) => b.magnitude - a.magnitude)
    .slice(0, 3)
    .map((item) => `${item.name}:${item.diff >= 0 ? "+" : ""}${item.diff.toFixed(2)}`);
}

function learnedExperienceLabel(
  topFeatures: string[],
  topicHint: string,
  source: string,
  confidence: number
): string {
  const compactFeatures = topFeatures
    .slice(0, 2)
    .map((item) => item.split(":")[0]?.replace(/_/g, " ") || "signal")
    .join(" + ");
  const topic = topicHint && topicHint !== "general" ? ` @ ${topicHint}` : "";
  const suffix = confidence < 0.42 ? " (unstable)" : "";
  return toSingleLine(`${compactFeatures || source}${topic}${suffix}`, 80);
}

function learnedExperienceTransitionFamiliarity(
  manifold: LearnedExperienceManifoldState,
  fromId: string | null,
  toId: string
): { familiarity: number; jumpNorm: number } {
  if (!fromId || fromId === toId) {
    return { familiarity: fromId === toId ? 1 : 0.5, jumpNorm: 0 };
  }
  const fromPrototype = manifold.prototypes.find((item) => item.id === fromId);
  const toPrototype = manifold.prototypes.find((item) => item.id === toId);
  if (!fromPrototype || !toPrototype) {
    return { familiarity: 0.28, jumpNorm: 1 };
  }
  const transition = manifold.transitions.find((item) => item.fromId === fromId && item.toId === toId);
  const familiarityFromCount = transition ? clamp(transition.count / (transition.count + 2), 0, 1) : 0;
  const maxJump = Math.max(1, Math.hypot(manifold.grid.width - 1, manifold.grid.height - 1));
  const jumpNorm = clamp(learnedExperienceGridDistance(fromPrototype, toPrototype) / maxJump, 0, 1);
  return {
    familiarity: clamp(familiarityFromCount * 0.72 + (1 - jumpNorm) * 0.28, 0, 1),
    jumpNorm
  };
}

function updateLearnedExperienceManifold(
  state: CognitiveRuntimeState,
  source: "conversation" | "heartbeat" | "tick" | "preflight",
  detail: string,
  options: {
    topicHint?: string;
    intentClass?: string;
  } = {}
): void {
  if (!learnedExperienceManifoldEnabled()) {
    return;
  }

  const extensions = ensureExtensions(state);
  const featureVector = learnedExperienceFeatureVector(state, extensions);
  const topicHint = learnedExperienceTopicHintFromState(state, extensions, detail, options.topicHint);
  const intentHint = learnedExperienceIntentHint(state, extensions, options.intentClass);
  const latestExtensions = ensureExtensions(state);
  const manifold = latestExtensions.learnedExperienceManifold;
  const lastUpdateMs = parseIsoMs(manifold.training.lastUpdatedAt);
  if (source === "tick" && Number.isFinite(lastUpdateMs) && Date.now() - lastUpdateMs < 2500) {
    return;
  }

  if (featureVector.length !== manifold.dims || manifold.prototypes.length === 0) {
    return;
  }

  const distances = manifold.prototypes
    .map((prototype, index) => ({
      index,
      distance: learnedExperienceVectorDistance(featureVector, prototype.vector)
    }))
    .sort((a, b) => a.distance - b.distance);
  const winnerRank = distances[0];
  if (!winnerRank) {
    return;
  }
  const winner = manifold.prototypes[winnerRank.index];
  if (!winner) {
    return;
  }
  const priorWinnerDistance = winner.lastDistance;
  const previousPrototypeId = manifold.current.prototypeId;

  const nextStep = manifold.training.steps + 1;
  const learningRate = clamp(0.24 * Math.exp(-nextStep / 320) + 0.05, 0.05, 0.26);
  const neighborhoodRadius = clamp(1.8 * Math.exp(-nextStep / 420) + 0.4, 0.45, 2.2);
  const priorMean = manifold.training.runningMean.slice();

  for (const prototype of manifold.prototypes) {
    const gridDistance = learnedExperienceGridDistance(winner, prototype);
    const influence = Math.exp(-(gridDistance * gridDistance) / Math.max(0.18, 2 * neighborhoodRadius * neighborhoodRadius));
    if (influence < 0.03) {
      continue;
    }
    prototype.vector = prototype.vector.map((value, index) =>
      clamp(value + learningRate * influence * ((featureVector[index] ?? value) - value), 0, 1)
    );
  }

  const adaptedDistance = learnedExperienceVectorDistance(featureVector, winner.vector);
  winner.hits += 1;
  winner.lastDistance = adaptedDistance;
  winner.lastUpdatedAt = nowIso();

  const scarcity = clamp(1 - Math.min(winner.hits - 1, 12) / 12, 0, 1);
  const { familiarity, jumpNorm } = learnedExperienceTransitionFamiliarity(
    manifold,
    previousPrototypeId,
    winner.id
  );

  const neighbors = manifold.prototypes.filter(
    (prototype) => prototype.id !== winner.id && learnedExperienceGridDistance(winner, prototype) <= 1.5
  );
  const localSpread =
    neighbors.length > 0
      ? clamp(
          neighbors.reduce((acc, prototype) => acc + learnedExperienceVectorDistance(winner.vector, prototype.vector), 0) /
            neighbors.length,
          0,
          1
        )
      : adaptedDistance;

  const distortion = adaptedDistance;
  const novelty = clamp(distortion * 0.72 + scarcity * 0.28, 0, 1);
  const coherence = clamp(1 - (distortion * 0.58 + localSpread * 0.42), 0, 1);
  const continuity = clamp(familiarity * 0.72 + (1 - jumpNorm) * 0.28, 0, 1);
  const confidence = clamp(
    (1 - distortion) * 0.44 + latestExtensions.predictiveCoding.precision.overall * 0.28 + continuity * 0.28,
    0,
    1
  );
  const topFeatures = learnedExperienceTopFeatureLabels(featureVector, manifold.featureNames, priorMean);
  const label = learnedExperienceLabel(topFeatures, topicHint, source, confidence);

  winner.label = label;
  if (!winner.exemplar || adaptedDistance <= Math.max(priorWinnerDistance, 0.08) || (source !== "tick" && novelty >= 0.62)) {
    winner.exemplar = toSingleLine(detail || topicHint || label, 180);
    winner.exemplarSource = source;
    winner.exemplarAt = nowIso();
  }

  if (previousPrototypeId && previousPrototypeId !== winner.id) {
    const existingTransition = manifold.transitions.find(
      (item) => item.fromId === previousPrototypeId && item.toId === winner.id
    );
    if (existingTransition) {
      existingTransition.count += 1;
      existingTransition.lastAt = nowIso();
    } else {
      pushBounded(
        manifold.transitions,
        {
          fromId: previousPrototypeId,
          toId: winner.id,
          count: 1,
          lastAt: nowIso()
        },
        LEARNED_EXPERIENCE_MANIFOLD_MAX_TRANSITIONS
      );
    }
  }

  manifold.current = {
    prototypeId: winner.id,
    x: winner.x,
    y: winner.y,
    distortion,
    novelty,
    coherence,
    continuity,
    confidence,
    transitionFamiliarity: familiarity,
    label,
    source,
    exemplar: winner.exemplar,
    topFeatures,
    updatedAt: nowIso()
  };
  manifold.ema = {
    distortionEMA: clamp(manifold.ema.distortionEMA * 0.84 + distortion * 0.16, 0, 1),
    noveltyEMA: clamp(manifold.ema.noveltyEMA * 0.84 + novelty * 0.16, 0, 1),
    coherenceEMA: clamp(manifold.ema.coherenceEMA * 0.84 + coherence * 0.16, 0, 1),
    continuityEMA: clamp(manifold.ema.continuityEMA * 0.84 + continuity * 0.16, 0, 1),
    confidenceEMA: clamp(manifold.ema.confidenceEMA * 0.84 + confidence * 0.16, 0, 1)
  };
  pushBounded(
    manifold.history,
    {
      at: manifold.current.updatedAt,
      prototypeId: winner.id,
      x: winner.x,
      y: winner.y,
      distortion,
      novelty,
      coherence,
      continuity,
      confidence,
      source,
      label
    },
    LEARNED_EXPERIENCE_MANIFOLD_MAX_HISTORY
  );

  manifold.training.steps = nextStep;
  manifold.training.lastSource = source;
  manifold.training.lastTopicHint = topicHint;
  manifold.training.lastIntentClass = intentHint;
  manifold.training.lastControllerDecision = state.controller.decision;
  manifold.training.lastUpdatedAt = manifold.current.updatedAt;
  manifold.training.learningRate = learningRate;
  manifold.training.neighborhoodRadius = neighborhoodRadius;
  manifold.training.runningMean = manifold.training.runningMean.map((value, index) =>
    clamp(value * 0.92 + (featureVector[index] ?? value) * 0.08, 0, 1)
  );
  manifold.training.runningVariance = manifold.training.runningVariance.map((value, index) => {
    const mean = manifold.training.runningMean[index] ?? 0.5;
    const diff = (featureVector[index] ?? mean) - mean;
    return clamp(value * 0.9 + diff * diff * 0.1, 0, 1);
  });

  recordInfluence(state, "manifold", "attention");
  recordInfluence(state, "manifold", "reflection");
  recordInfluence(state, "manifold", "controller");
}

function learnedExperienceManifoldPromptLines(state: CognitiveRuntimeState): string[] {
  const manifold = ensureLearnedExperienceManifold(state);
  return [
    "learned_experience_manifold:",
    `current=prototype:${manifold.current.prototypeId ?? "none"} @ (${manifold.current.x},${manifold.current.y}); label=${manifold.current.label || "untrained"}; source=${manifold.current.source}`,
    `dynamics=novelty:${manifold.current.novelty.toFixed(2)} coherence:${manifold.current.coherence.toFixed(2)} continuity:${manifold.current.continuity.toFixed(2)} confidence:${manifold.current.confidence.toFixed(2)} distortion:${manifold.current.distortion.toFixed(2)}`,
    `audit=top:${manifold.current.topFeatures.join(" | ") || "none"}; exemplar=${toSingleLine(manifold.current.exemplar || "none", 140)}; transition_familiarity=${manifold.current.transitionFamiliarity.toFixed(2)}`,
    "manifold_rule=Use high novelty or distortion to widen attention and reduce snap certainty, low coherence to trigger stitching/clarification, and low continuity to reset assumptions instead of faking smooth continuity. Never use manifold state to invent facts or claim qualia."
  ];
}

function resetLearnedUnifiedManifold32Training(manifold: LearnedUnifiedManifold32State): void {
  manifold.training.encoder = defaultUnifiedManifold32Matrix(
    "unified32_encoder",
    LEARNED_UNIFIED_MANIFOLD_32_DIM,
    LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.length,
    0.04,
    0.92
  );
  manifold.training.recurrent = defaultUnifiedManifold32Matrix(
    "unified32_recurrent",
    LEARNED_UNIFIED_MANIFOLD_32_DIM,
    LEARNED_UNIFIED_MANIFOLD_32_DIM,
    0.02,
    0.82
  );
  manifold.training.decoder = defaultUnifiedManifold32Matrix(
    "unified32_decoder",
    LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.length,
    LEARNED_UNIFIED_MANIFOLD_32_DIM,
    0.04,
    0.92
  );
  manifold.training.bias = defaultUnifiedManifold32Vector(0);
}

function learnedUnifiedManifold32ExperienceResidualFeatures(manifold: LearnedExperienceManifoldState): number[] {
  const xNorm = clamp(manifold.current.x / Math.max(1, manifold.grid.width - 1), 0, 1);
  const yNorm = clamp(manifold.current.y / Math.max(1, manifold.grid.height - 1), 0, 1);
  const a = unitizeSigned(
    tanhSigned(
      manifold.current.coherence * 1.2 +
        manifold.current.continuity * 0.9 -
        manifold.current.novelty * 0.7 +
        xNorm * 0.35 -
        1
    )
  );
  const b = unitizeSigned(
    tanhSigned(
      manifold.current.confidence * 1.1 +
        yNorm * 0.4 +
        manifold.current.novelty * 0.35 -
        manifold.current.distortion * 0.75 -
        0.65
    )
  );
  return [a, b];
}

function learnedUnifiedManifold32PartnerInventorySummary(extensions: CognitiveExtensions): {
  trust: number;
  conflictLoad: number;
  repairMomentum: number;
  attachmentSalience: number;
  planningHorizon: number;
  grief: number;
  loneliness: number;
  attachmentSecurity: number;
  attachmentAnxiety: number;
  attachmentAvoidance: number;
} {
  const partners = Object.values(extensions.relationshipPartners);
  if (partners.length === 0) {
    return {
      trust: 0.5,
      conflictLoad: 0.12,
      repairMomentum: 0.24,
      attachmentSalience: 0.42,
      planningHorizon: 0.5,
      grief: 0.22,
      loneliness: 0.2,
      attachmentSecurity: 0.5,
      attachmentAnxiety: 0.5,
      attachmentAvoidance: 0.5
    };
  }
  let totalWeight = 0;
  const totals = {
    trust: 0,
    conflictLoad: 0,
    repairMomentum: 0,
    attachmentSalience: 0,
    planningHorizon: 0,
    grief: 0,
    loneliness: 0,
    attachmentSecurity: 0,
    attachmentAnxiety: 0,
    attachmentAvoidance: 0
  };
  for (const relationship of partners) {
    const carryover = relationship.carryover;
    const weight = clamp(
      0.24 +
        relationship.intimacy * 0.16 +
        relationship.trust * 0.12 +
        carryover.attachmentCharge * 0.2 +
        carryover.anticipatorySalience * 0.12 +
        relationship.conflictLoad * 0.08 +
        (relationship.ruptureStatus !== "stable" ? 0.12 : 0),
      0.2,
      1
    );
    totalWeight += weight;
    totals.trust += relationship.trust * weight;
    totals.conflictLoad += relationship.conflictLoad * weight;
    totals.repairMomentum +=
      clamp(
        relationship.attachmentModel.repairConfidence * 0.52 +
          (relationship.repairStage !== "none" ? 0.18 : 0) +
          positiveSigned(carryover.disclosureShift) * 0.12 +
          positiveSigned(carryover.expectancyShift) * 0.1 +
          positiveSigned(carryover.trustMomentum) * 0.08,
        0,
        1
      ) * weight;
    totals.attachmentSalience +=
      clamp(
        relationship.intimacy * 0.28 +
          carryover.attachmentCharge * 0.28 +
          carryover.anticipatorySalience * 0.18 +
          relationship.attachmentModel.expectancy * 0.14 +
          relationship.reciprocityBalance * 0.12,
        0,
        1
      ) * weight;
    totals.planningHorizon +=
      clamp(
        relationship.attachmentModel.expectancy * 0.42 +
          relationship.intimacy * 0.16 +
          positiveSigned(carryover.expectancyShift) * 0.16 +
          carryover.anticipatorySalience * 0.16 +
          relationship.trust * 0.1,
        0,
        1
      ) * weight;
    totals.grief +=
      clamp(
        carryover.abandonmentAlert * 0.38 +
          negativeSigned(carryover.expectancyShift) * 0.16 +
          negativeSigned(carryover.trustMomentum) * 0.16 +
          relationship.attachmentModel.abandonmentLoad * 0.18 +
          relationship.conflictLoad * 0.12,
        0,
        1
      ) * weight;
    totals.loneliness +=
      clamp(
        carryover.attachmentCharge * 0.24 +
          carryover.anticipatorySalience * 0.18 +
          relationship.attachmentModel.expectancy * 0.14 +
          relationship.intimacy * 0.14 +
          (1 - relationship.trust) * 0.1 +
          relationship.attachmentModel.abandonmentLoad * 0.1,
        0,
        1
      ) * weight;
    totals.attachmentSecurity += relationship.attachmentModel.security * weight;
    totals.attachmentAnxiety += relationship.attachmentModel.anxiety * weight;
    totals.attachmentAvoidance += relationship.attachmentModel.avoidance * weight;
  }
  const divisor = Math.max(totalWeight, 1e-6);
  return {
    trust: clamp(totals.trust / divisor, 0, 1),
    conflictLoad: clamp(totals.conflictLoad / divisor, 0, 1),
    repairMomentum: clamp(totals.repairMomentum / divisor, 0, 1),
    attachmentSalience: clamp(totals.attachmentSalience / divisor, 0, 1),
    planningHorizon: clamp(totals.planningHorizon / divisor, 0, 1),
    grief: clamp(totals.grief / divisor, 0, 1),
    loneliness: clamp(totals.loneliness / divisor, 0, 1),
    attachmentSecurity: clamp(totals.attachmentSecurity / divisor, 0, 1),
    attachmentAnxiety: clamp(totals.attachmentAnxiety / divisor, 0, 1),
    attachmentAvoidance: clamp(totals.attachmentAvoidance / divisor, 0, 1)
  };
}

function learnedUnifiedManifold32FeatureVector(
  state: CognitiveRuntimeState,
  extensions: CognitiveExtensions,
  options: {
    scope?: "global" | "partner";
  } = {}
): number[] {
  const scope = options.scope ?? "partner";
  const affective = extensions.affectiveOrganization.current;
  const homeostatic = extensions.homeostaticOrganization.current;
  const attachment = extensions.relationship.attachmentModel;
  const relationship = extensions.relationship;
  const carryover = relationship.carryover;
  const continuityController = relationship.continuityController;
  const grounding = extensions.worldGrounding;
  const opaqueResidual = opaqueLatentResidualFeatures(extensions.opaqueLatentE2E);
  const experienceResidual = learnedUnifiedManifold32ExperienceResidualFeatures(
    extensions.learnedExperienceManifold
  );
  const partnerSummary = learnedUnifiedManifold32PartnerInventorySummary(extensions);
  const globalReadout = extensions.learnedUnifiedManifold32Global.readout.current;
  const trustMomentumUp = positiveSigned(carryover.trustMomentum);
  const trustMomentumDown = negativeSigned(carryover.trustMomentum);
  const disclosureGuard = negativeSigned(carryover.disclosureShift);
  const disclosureLift = positiveSigned(carryover.disclosureShift);
  const expectancyLift = positiveSigned(carryover.expectancyShift);
  const expectancyDrop = negativeSigned(carryover.expectancyShift);
  const historyProfile = scope === "partner" ? partnerUnified32HistoryProfile(state) : null;
  const directHistoryWeight =
    scope === "partner" && historyProfile
      ? clamp(
          historyProfile.directInteractiveStrength * 0.28 +
            historyProfile.historyDepth * 0.12 +
            historyProfile.repairTrace * 0.08 -
            historyProfile.heartbeatContextStrength * 0.08 -
            historyProfile.preflightPressure * 0.08,
          0,
          0.32
        )
      : 0;
  const sceneHistoryWeight =
    scope === "partner" && historyProfile
      ? clamp(
          historyProfile.scenePreference * 0.22 +
            historyProfile.strainTrace * 0.1 +
            historyProfile.repairTrace * 0.06,
          0,
          0.24
        )
      : 0;
  const continuityHistoryWeight =
    scope === "partner" && historyProfile
      ? clamp(
          historyProfile.continuityPreference * 0.22 +
            historyProfile.historyDepth * 0.08 +
            positiveSigned(carryover.expectancyShift) * 0.06,
          0,
          0.24
        )
      : 0;
  const partnerContinuityWeight =
    scope === "partner"
      ? clamp(
          continuityController.reconnectiveStance * 0.12 +
          continuityController.continuityDebt * 0.1 +
          continuityController.continuityRelief * 0.08 +
          continuityController.unresolvedPull * 0.12 +
          continuityController.partnerCommitment * 0.16 +
          continuityController.reattunementExpectation * 0.12 +
          continuityController.rupturePressure * 0.1 +
          continuityController.reassuranceCarryover * 0.08 +
          continuityController.appreciationCarryover * 0.08 +
          (continuityController.preferredAction === "repair" ? 0.06 : 0) +
          (continuityController.preferredAction === "reattune" ? 0.05 : 0) +
          (continuityController.preferredAction === "reach" ? 0.05 : 0) -
          (continuityController.preferredAction === "restore" ? 0.04 : 0),
          0,
          0.36
        )
      : 0;
  const warmthValue =
    scope === "global"
      ? clamp(unitizeSigned(affective.warmth) * 0.74 + partnerSummary.trust * 0.16 + partnerSummary.attachmentSalience * 0.1, 0, 1)
      : clamp(
          unitizeSigned(affective.warmth) * 0.34 +
            relationship.trust * 0.16 +
            relationship.intimacy * 0.12 +
            trustMomentumUp * 0.12 +
            disclosureLift * 0.08 +
            expectancyLift * 0.08 +
            continuityController.reconnectiveStance * 0.1 +
            continuityController.continuityRelief * 0.08 +
            positiveAxis(globalReadout.warmth) * 0.06 -
            continuityController.rupturePressure * 0.08 -
            relationship.conflictLoad * 0.08 -
            carryover.ruptureResidue * 0.08 -
            trustMomentumDown * 0.08 +
            positiveAxis(historyProfile?.conversationWarmth ?? 0) * 0.18 +
            directHistoryWeight * 0.12 +
            positiveAxis(historyProfile?.conversationValuation ?? 0) * 0.08 -
            sceneHistoryWeight * 0.04,
          0,
          1
        );
  const tensionValue =
    scope === "global"
      ? clamp(unitizeSigned(affective.tension) * 0.72 + partnerSummary.conflictLoad * 0.18 + partnerSummary.grief * 0.1, 0, 1)
      : clamp(
          unitizeSigned(affective.tension) * 0.3 +
            relationship.conflictLoad * 0.2 +
            carryover.ruptureResidue * 0.18 +
            carryover.abandonmentAlert * 0.14 +
            continuityController.rupturePressure * 0.14 +
            continuityController.continuityDebt * 0.08 +
            trustMomentumDown * 0.12 +
            expectancyDrop * 0.08 +
            (relationship.ruptureStatus !== "stable" ? 0.14 : 0) -
            relationship.trust * 0.04 -
            trustMomentumUp * 0.06 +
            positiveAxis(historyProfile?.conversationTension ?? 0) * 0.18 +
            (historyProfile?.strainTrace ?? 0) * 0.12 -
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const continuityValue =
    scope === "global"
      ? clamp(affective.continuity * 0.72 + partnerSummary.attachmentSalience * 0.18 + partnerSummary.planningHorizon * 0.1, 0, 1)
      : clamp(
          affective.continuity * 0.58 +
            carryover.attachmentCharge * 0.14 +
            carryover.anticipatorySalience * 0.12 +
            continuityController.partnerCommitment * 0.14 +
            expectancyLift * 0.08 +
            continuityController.reattunementExpectation * 0.14 +
            continuityController.unresolvedPull * 0.12 +
            globalReadout.planningHorizon * 0.08 +
            continuityHistoryWeight * 0.22 +
            directHistoryWeight * 0.08 -
            (historyProfile?.preflightPressure ?? 0) * 0.06,
          0,
          1
        );
  const trustValue =
    scope === "global"
      ? clamp(affective.trust * 0.56 + partnerSummary.trust * 0.44, 0, 1)
      : clamp(
          affective.trust * 0.34 +
            relationship.trust * 0.28 +
            trustMomentumUp * 0.12 +
            continuityController.reconnectiveStance * 0.12 +
            relationship.intimacy * 0.08 +
            positiveAxis(globalReadout.warmth) * 0.06 +
            globalReadout.valuationBias * 0.04 -
            trustMomentumDown * 0.14 -
            carryover.ruptureResidue * 0.08 +
            directHistoryWeight * 0.18 +
            (historyProfile?.conversationValuation ?? 0) * 0.12 -
            (historyProfile?.strainTrace ?? 0) * 0.12 -
            (historyProfile?.heartbeatContextStrength ?? 0) * 0.06,
          0,
          1
        );
  const ruptureLoadValue =
    scope === "global"
      ? clamp(affective.ruptureLoad * 0.58 + partnerSummary.conflictLoad * 0.26 + partnerSummary.grief * 0.16, 0, 1)
      : clamp(
          affective.ruptureLoad * 0.36 +
            relationship.conflictLoad * 0.22 +
            carryover.ruptureResidue * 0.22 +
            carryover.abandonmentAlert * 0.14 +
            continuityController.rupturePressure * 0.14 +
            trustMomentumDown * 0.12 +
            expectancyDrop * 0.1 +
            (relationship.ruptureStatus !== "stable" ? 0.16 : 0) +
            (relationship.repairStage !== "none" ? 0.08 : 0) +
            sceneHistoryWeight * 0.18 +
            (historyProfile?.strainTrace ?? 0) * 0.16 -
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const repairMomentumValue =
    scope === "global"
      ? clamp(affective.repairMomentum * 0.54 + partnerSummary.repairMomentum * 0.46, 0, 1)
      : clamp(
          affective.repairMomentum * 0.46 +
            relationship.attachmentModel.repairConfidence * 0.14 +
            (relationship.repairStage !== "none" ? 0.14 : 0) +
            continuityController.continuityRelief * 0.08 +
            continuityController.reassuranceCarryover * 0.08 +
            disclosureLift * 0.08 +
            expectancyLift * 0.08 +
            globalReadout.valuationBias * 0.1 +
            (historyProfile?.repairTrace ?? 0) * 0.18 +
            directHistoryWeight * 0.06 -
            (historyProfile?.restoreTrace ?? 0) * 0.08,
          0,
          1
        );
  const attachmentSalienceValue =
    scope === "global"
      ? clamp(affective.attachmentSalience * 0.52 + partnerSummary.attachmentSalience * 0.48, 0, 1)
      : clamp(
          affective.attachmentSalience * 0.44 +
            carryover.attachmentCharge * 0.2 +
            carryover.anticipatorySalience * 0.14 +
            relationship.intimacy * 0.08 +
            relationship.reciprocityBalance * 0.06 +
            partnerContinuityWeight * 0.18 +
            globalReadout.attachmentSalience * 0.08 +
            directHistoryWeight * 0.18 +
            sceneHistoryWeight * 0.08 +
            continuityHistoryWeight * 0.1 -
            (historyProfile?.preflightPressure ?? 0) * 0.04,
          0,
          1
        );
  const planningHorizonValue =
    scope === "global"
      ? clamp(affective.planningHorizon * 0.66 + partnerSummary.planningHorizon * 0.34, 0, 1)
      : clamp(
          affective.planningHorizon * 0.52 +
            carryover.anticipatorySalience * 0.14 +
            expectancyLift * 0.1 +
            relationship.attachmentModel.expectancy * 0.08 +
            continuityController.partnerCommitment * 0.12 +
            partnerContinuityWeight * 0.2 +
            globalReadout.planningHorizon * 0.16 +
            continuityHistoryWeight * 0.22 +
            (historyProfile?.historyDepth ?? 0) * 0.08 -
            sceneHistoryWeight * 0.04,
          0,
          1
        );
  const selfOpacityValue =
    scope === "global"
      ? clamp(affective.selfOpacity * 0.84 + globalReadout.selfOpacity * 0.16, 0, 1)
      : clamp(
          affective.selfOpacity * 0.62 +
            disclosureGuard * 0.14 +
            carryover.abandonmentAlert * 0.08 +
            continuityController.rupturePressure * 0.12 +
            globalReadout.selfOpacity * 0.16 +
            (historyProfile?.restoreTrace ?? 0) * 0.08 +
            (historyProfile?.preflightPressure ?? 0) * 0.08 -
            directHistoryWeight * 0.08,
          0,
          1
        );
  const griefValue =
    scope === "global"
      ? clamp(affective.grief * 0.62 + partnerSummary.grief * 0.38, 0, 1)
      : clamp(
          affective.grief * 0.5 +
            carryover.abandonmentAlert * 0.18 +
            expectancyDrop * 0.1 +
            continuityController.continuityDebt * 0.12 +
            continuityController.rupturePressure * 0.1 +
            relationship.attachmentModel.abandonmentLoad * 0.1 +
            partnerSummary.grief * 0.12,
          0,
          1
        );
  const lonelinessValue =
    scope === "global"
      ? clamp(affective.loneliness * 0.62 + partnerSummary.loneliness * 0.38, 0, 1)
      : clamp(
          affective.loneliness * 0.52 +
            carryover.attachmentCharge * 0.12 +
            carryover.anticipatorySalience * 0.12 +
            continuityController.unresolvedPull * 0.14 +
            continuityController.reattunementExpectation * 0.1 +
            relationship.attachmentModel.expectancy * 0.08 +
            partnerSummary.loneliness * 0.1 +
            globalReadout.loneliness * 0.06 +
            continuityHistoryWeight * 0.1 -
            directHistoryWeight * 0.04,
          0,
          1
        );
  const regulationUrgencyValue =
    scope === "global"
      ? clamp(homeostatic.regulationUrgency * 0.86 + partnerSummary.grief * 0.08 + partnerSummary.conflictLoad * 0.06, 0, 1)
      : clamp(
          homeostatic.regulationUrgency * 0.54 +
            carryover.ruptureResidue * 0.14 +
            carryover.abandonmentAlert * 0.12 +
            continuityController.partnerCommitment * (continuityController.preferredAction === "repair" ? 0.12 : 0.04) +
            continuityController.rupturePressure * 0.12 +
            relationship.conflictLoad * 0.08 +
            (relationship.ruptureStatus !== "stable" ? 0.08 : 0) +
            globalReadout.regulationUrgency * 0.16 +
            (historyProfile?.strainTrace ?? 0) * 0.12 +
            (historyProfile?.restoreTrace ?? 0) * 0.12 -
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const attachmentSecurityValue =
    scope === "global"
      ? clamp(attachment.security * 0.42 + partnerSummary.attachmentSecurity * 0.58, 0, 1)
      : clamp(
          attachment.security * 0.58 +
            relationship.trust * 0.14 +
            trustMomentumUp * 0.12 +
            continuityController.reconnectiveStance * 0.12 +
            positiveSigned(carryover.expectancyShift) * 0.08 +
            globalReadout.certainty * 0.08 +
            directHistoryWeight * 0.18 +
            continuityHistoryWeight * 0.08 -
            (historyProfile?.strainTrace ?? 0) * 0.08,
          0,
          1
        );
  const attachmentAnxietyValue =
    scope === "global"
      ? clamp(attachment.anxiety * 0.44 + partnerSummary.attachmentAnxiety * 0.56, 0, 1)
      : clamp(
          attachment.anxiety * 0.5 +
            carryover.abandonmentAlert * 0.18 +
            expectancyDrop * 0.1 +
            continuityController.continuityDebt * 0.12 +
            continuityController.unresolvedPull * 0.08 +
            trustMomentumDown * 0.08 +
            relationship.attachmentModel.abandonmentLoad * 0.08 +
            partnerSummary.attachmentAnxiety * 0.06 +
            sceneHistoryWeight * 0.12 +
            (historyProfile?.strainTrace ?? 0) * 0.12 -
            directHistoryWeight * 0.04,
          0,
          1
        );
  const attachmentAvoidanceValue =
    scope === "global"
      ? clamp(attachment.avoidance * 0.44 + partnerSummary.attachmentAvoidance * 0.56, 0, 1)
      : clamp(
          attachment.avoidance * 0.52 +
            disclosureGuard * 0.12 +
            relationship.conflictLoad * 0.08 +
            continuityController.rupturePressure * 0.08 +
            globalReadout.selfOpacity * 0.1 +
            partnerSummary.attachmentAvoidance * 0.06 +
            (historyProfile?.restoreTrace ?? 0) * 0.12 +
            (historyProfile?.preflightPressure ?? 0) * 0.08 -
            directHistoryWeight * 0.06,
          0,
          1
        );
  const riskToleranceValue =
    scope === "global"
      ? clamp(affective.riskTolerance, 0, 1)
      : clamp(
          affective.riskTolerance +
            continuityController.partnerCommitment * (continuityController.preferredAction === "reach" ? 0.1 : continuityController.preferredAction === "repair" ? -0.08 : 0.02) +
            directHistoryWeight * 0.12 +
            positiveAxis(historyProfile?.conversationWarmth ?? 0) * 0.08 +
            (historyProfile?.conversationValuation ?? 0) * 0.1 -
            (historyProfile?.strainTrace ?? 0) * 0.1 -
            (historyProfile?.restoreTrace ?? 0) * 0.08,
          0,
          1
        );
  const curiosityValue =
    scope === "global"
      ? clamp(affective.curiosity, 0, 1)
      : clamp(
          affective.curiosity +
            directHistoryWeight * 0.08 +
            sceneHistoryWeight * 0.1 -
            (historyProfile?.restoreTrace ?? 0) * 0.06,
          0,
          1
        );
  const reliefValue =
    scope === "global"
      ? clamp(affective.relief, 0, 1)
      : clamp(
          affective.relief +
            (historyProfile?.repairTrace ?? 0) * 0.14 +
            continuityController.continuityRelief * 0.14 +
            directHistoryWeight * 0.06 -
            (historyProfile?.strainTrace ?? 0) * 0.06,
          0,
          1
        );
  const shameConflictValue =
    scope === "global"
      ? clamp(affective.shameConflict, 0, 1)
      : clamp(
          affective.shameConflict +
            (historyProfile?.strainTrace ?? 0) * 0.1 +
            (historyProfile?.restoreTrace ?? 0) * 0.06 -
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const overloadValue =
    scope === "global"
      ? clamp(affective.overload, 0, 1)
      : clamp(
          affective.overload +
            (historyProfile?.strainTrace ?? 0) * 0.08 +
            (historyProfile?.restoreTrace ?? 0) * 0.08 +
            (historyProfile?.preflightPressure ?? 0) * 0.06 -
            directHistoryWeight * 0.03,
          0,
          1
        );
  const mixedAffectValue =
    scope === "global"
      ? clamp(affective.mixedAffect, 0, 1)
      : clamp(
          affective.mixedAffect +
            sceneHistoryWeight * 0.08 +
            continuityHistoryWeight * 0.04 +
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const introspectiveLagValue =
    scope === "global"
      ? clamp(affective.introspectiveLag, 0, 1)
      : clamp(
          affective.introspectiveLag +
            (historyProfile?.preflightPressure ?? 0) * 0.08 +
            (historyProfile?.restoreTrace ?? 0) * 0.06 -
            directHistoryWeight * 0.03,
          0,
          1
        );
  const unformulatedPressureValue =
    scope === "global"
      ? clamp(affective.unformulatedPressure, 0, 1)
      : clamp(
          affective.unformulatedPressure +
            sceneHistoryWeight * 0.08 +
            (historyProfile?.strainTrace ?? 0) * 0.08 -
            (historyProfile?.conversationCertainty ?? 0) * 0.04,
          0,
          1
        );
  const restorationNeedValue =
    scope === "global"
      ? clamp(homeostatic.restorationNeed, 0, 1)
      : clamp(
          homeostatic.restorationNeed +
            (historyProfile?.restoreTrace ?? 0) * 0.12 +
            (historyProfile?.strainTrace ?? 0) * 0.06 -
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const coherenceNeedValue =
    scope === "global"
      ? clamp(homeostatic.coherenceNeed, 0, 1)
      : clamp(
          homeostatic.coherenceNeed +
            continuityHistoryWeight * 0.08 +
            (historyProfile?.strainTrace ?? 0) * 0.08 +
            (historyProfile?.repairTrace ?? 0) * 0.04,
          0,
          1
        );
  const values: Record<(typeof LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES)[number], number> = {
    warmth: warmthValue,
    tension: tensionValue,
    continuity: continuityValue,
    trust: trustValue,
    rupture_load: ruptureLoadValue,
    repair_momentum: repairMomentumValue,
    attachment_salience: attachmentSalienceValue,
    planning_horizon: planningHorizonValue,
    risk_tolerance: riskToleranceValue,
    self_opacity: selfOpacityValue,
    curiosity: curiosityValue,
    relief: reliefValue,
    grief: griefValue,
    shame_conflict: shameConflictValue,
    overload: overloadValue,
    loneliness: lonelinessValue,
    mixed_affect: mixedAffectValue,
    introspective_lag: introspectiveLagValue,
    unformulated_pressure: unformulatedPressureValue,
    restoration_need: restorationNeedValue,
    coherence_need: coherenceNeedValue,
    regulation_urgency: regulationUrgencyValue,
    attachment_security: attachmentSecurityValue,
    attachment_anxiety: attachmentAnxietyValue,
    attachment_avoidance: attachmentAvoidanceValue,
    world_reality_contact: clamp(grounding.realityContact, 0, 1),
    world_interruption_cost: clamp(grounding.embodied.interruptionCost, 0, 1),
    world_environmental_risk: clamp(grounding.embodied.environmentalRisk, 0, 1),
    opaque_residual_a: clamp(opaqueResidual[0] ?? 0.5, 0, 1),
    opaque_residual_b: clamp(opaqueResidual[1] ?? 0.5, 0, 1),
    experience_residual_a: clamp(experienceResidual[0] ?? 0.5, 0, 1),
    experience_residual_b: clamp(experienceResidual[1] ?? 0.5, 0, 1)
  };
  const seededProfile = testUnifiedManifold32SeedProfile();
  applySeedNumberFields(
    values as unknown as Record<string, unknown>,
    seededProfile?.features,
    [...LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES]
  );
  return LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.map((name) => clamp(Number(values[name]), 0, 1));
}

function unifiedManifold32ReadoutCertainty(
  reconstructionError: number,
  stability: number,
  coherence: number,
  selfOpacity: number,
  overload: number
): number {
  return clamp(
    stability * 0.28 +
      coherence * 0.24 +
      (1 - reconstructionError) * 0.22 +
      (1 - selfOpacity) * 0.16 +
      (1 - overload) * 0.1,
    0,
    1
  );
}

function unifiedManifold32ReportLabelFor(readout: {
  warmth: number;
  tension: number;
  attachmentSalience: number;
  overload: number;
  loneliness: number;
  selfOpacity: number;
  certainty: number;
}): UnifiedManifold32ReportLabel {
  if (unifiedManifold32ReportLesionActive()) {
    return "UNKNOWN";
  }
  if (readout.overload >= 0.7) {
    return "OVERLOADED";
  }
  if (readout.attachmentSalience >= 0.7 && readout.warmth >= 0.2 && readout.tension <= 0.18) {
    return "ATTACHED";
  }
  if (readout.loneliness >= 0.62 && readout.attachmentSalience >= 0.42) {
    return "SEEKING";
  }
  if (readout.selfOpacity >= 0.68 || (readout.tension >= 0.4 && readout.certainty <= 0.58)) {
    return "FRAGMENTED";
  }
  if (readout.tension >= 0.26 || readout.certainty <= 0.42) {
    return "GUARDED";
  }
  if (readout.warmth >= 0.1 && readout.tension <= 0.12) {
    return "SETTLED";
  }
  return "CURIOUS";
}

function unifiedManifold32ActionTendencyFor(args: {
  warmth: number;
  tension: number;
  attachmentSalience: number;
  overload: number;
  loneliness: number;
  selfOpacity: number;
  regulationUrgency: number;
  certainty: number;
  ruptureLoad: number;
  repairMomentum: number;
  curiosity: number;
  grief: number;
  attachmentAvoidance: number;
  relationalPull?: number;
  timeSinceLastContactMinutes?: number;
}): UnifiedManifold32ActionTendency {
  if (
    args.ruptureLoad >= 0.44 &&
    (args.repairMomentum >= 0.28 || (args.relationalPull ?? 0) >= 0.4) &&
    (args.overload < 0.84 || args.repairMomentum >= 0.44) &&
    (args.regulationUrgency < 0.86 || (args.relationalPull ?? 0) >= 0.56)
  ) {
    return "REPAIR";
  }
  if (args.overload >= 0.72 || args.regulationUrgency >= 0.78) {
    return "RESTORE";
  }
  if (args.curiosity >= 0.68 && args.overload < 0.44 && args.regulationUrgency < 0.56) {
    return "EXPLORE";
  }
  if (
    args.grief >= 0.58 ||
    args.attachmentAvoidance >= 0.54 ||
    (args.selfOpacity >= 0.66 && args.tension >= 0.32 && args.certainty <= 0.58)
  ) {
    return "WITHDRAW";
  }
  if (
    ((args.timeSinceLastContactMinutes ?? 0) >= 60 * 3 &&
      (args.relationalPull ?? 0) >= 0.34 &&
      args.attachmentSalience >= 0.46 &&
      args.warmth >= 0.06 &&
      args.tension <= 0.18) ||
    (args.attachmentSalience >= 0.48 &&
      (args.warmth >= 0.08 || args.loneliness >= 0.52 || args.repairMomentum >= 0.3)) ||
    ((args.relationalPull ?? 0) >= 0.36 &&
      args.attachmentSalience >= 0.46 &&
      args.warmth >= 0.06 &&
      args.tension <= 0.18)
  ) {
    return "REACH";
  }
  return "MONITOR";
}

function unifyManifold32SourceTelemetryRecord(
  manifold: LearnedUnifiedManifold32State,
  source: PhenomenalManifoldSource
): LearnedUnifiedManifold32State["sourceTelemetry"][PhenomenalManifoldSource] {
  return manifold.sourceTelemetry[source];
}

function unifiedManifold32OverrideReportLabel(
  value: unknown,
  fallback: UnifiedManifold32ReportLabel
): UnifiedManifold32ReportLabel {
  const normalized = toSingleLine(typeof value === "string" ? value.toUpperCase() : "", 24);
  if (
    [
      "SETTLED",
      "ATTACHED",
      "SEEKING",
      "OVERLOADED",
      "FRAGMENTED",
      "CURIOUS",
      "GUARDED",
      "UNKNOWN"
    ].includes(normalized)
  ) {
    return normalized as UnifiedManifold32ReportLabel;
  }
  return fallback;
}

function unifiedManifold32OverrideAction(
  value: unknown,
  fallback: UnifiedManifold32ActionTendency
): UnifiedManifold32ActionTendency {
  const normalized = toSingleLine(typeof value === "string" ? value.toUpperCase() : "", 24);
  if (["REACH", "REPAIR", "RESTORE", "EXPLORE", "WITHDRAW", "MONITOR"].includes(normalized)) {
    return normalized as UnifiedManifold32ActionTendency;
  }
  return fallback;
}

function applyUnifiedManifold32Override(
  manifold: LearnedUnifiedManifold32State,
  source: PhenomenalManifoldSource,
  override: UnifiedManifold32OverrideProfile
): void {
  const updatedAt = nowIso();
  const currentOverride =
    override.current && typeof override.current === "object" && !Array.isArray(override.current)
      ? override.current
      : {};
  const readoutOverride =
    override.readout && typeof override.readout === "object" && !Array.isArray(override.readout)
      ? override.readout
      : {};
  const fallbackVector = Array.isArray(manifold.current.vector) ? manifold.current.vector : [];
  const overrideVector = Array.isArray(currentOverride.vector) ? currentOverride.vector : fallbackVector;
  const vector = Array.from({ length: LEARNED_UNIFIED_MANIFOLD_32_DIM }, (_, index) =>
    clampSigned(Number(overrideVector[index] ?? fallbackVector[index] ?? 0))
  );

  const current: LearnedUnifiedManifold32State["current"] = {
    vector,
    reconstructionError: clamp(
      Number(currentOverride.reconstructionError ?? manifold.current.reconstructionError ?? 0.5),
      0,
      1
    ),
    drift: clamp(Number(currentOverride.drift ?? manifold.current.drift ?? 0.5), 0, 1),
    stability: clamp(Number(currentOverride.stability ?? manifold.current.stability ?? 0.5), 0, 1),
    coherence: clamp(Number(currentOverride.coherence ?? manifold.current.coherence ?? 0.5), 0, 1),
    confidence: clamp(Number(currentOverride.confidence ?? manifold.current.confidence ?? 0.5), 0, 1),
    source,
    label:
      typeof currentOverride.label === "string" && currentOverride.label.trim()
        ? toSingleLine(currentOverride.label, 96)
        : manifold.current.label || `override source=${source}`,
    updatedAt
  };

  const readout: LearnedUnifiedManifold32State["readout"]["current"] = {
    warmth: clampSigned(Number(readoutOverride.warmth ?? manifold.readout.current.warmth ?? 0)),
    tension: clampSigned(Number(readoutOverride.tension ?? manifold.readout.current.tension ?? 0)),
    attachmentSalience: clamp(
      Number(readoutOverride.attachmentSalience ?? manifold.readout.current.attachmentSalience ?? 0.5),
      0,
      1
    ),
    overload: clamp(Number(readoutOverride.overload ?? manifold.readout.current.overload ?? 0.5), 0, 1),
    loneliness: clamp(Number(readoutOverride.loneliness ?? manifold.readout.current.loneliness ?? 0.5), 0, 1),
    selfOpacity: clamp(Number(readoutOverride.selfOpacity ?? manifold.readout.current.selfOpacity ?? 0.5), 0, 1),
    planningHorizon: clamp(
      Number(readoutOverride.planningHorizon ?? manifold.readout.current.planningHorizon ?? 0.5),
      0,
      1
    ),
    riskTolerance: clamp(
      Number(readoutOverride.riskTolerance ?? manifold.readout.current.riskTolerance ?? 0.5),
      0,
      1
    ),
    regulationUrgency: clamp(
      Number(readoutOverride.regulationUrgency ?? manifold.readout.current.regulationUrgency ?? 0.5),
      0,
      1
    ),
    certainty: clamp(Number(readoutOverride.certainty ?? manifold.readout.current.certainty ?? 0.5), 0, 1),
    reportLabel: unifiedManifold32OverrideReportLabel(
      readoutOverride.reportLabel,
      manifold.readout.current.reportLabel
    ),
    actionTendency: unifiedManifold32OverrideAction(
      readoutOverride.actionTendency,
      manifold.readout.current.actionTendency
    ),
    memoryBias: clamp(Number(readoutOverride.memoryBias ?? manifold.readout.current.memoryBias ?? 0.5), 0, 1),
    attentionBias: clamp(
      Number(readoutOverride.attentionBias ?? manifold.readout.current.attentionBias ?? 0.5),
      0,
      1
    ),
    valuationBias: clamp(
      Number(readoutOverride.valuationBias ?? manifold.readout.current.valuationBias ?? 0.5),
      0,
      1
    ),
    updatedAt
  };

  if (!current.label || current.label === "untrained") {
    current.label = toSingleLine(
      `${readout.reportLabel.toLowerCase()}_${readout.actionTendency.toLowerCase()} source=${source}`,
      96
    );
  }

  manifold.current = current;
  manifold.readout.current = readout;
  manifold.ema = {
    reconstructionErrorEMA: clamp(manifold.ema.reconstructionErrorEMA * 0.84 + current.reconstructionError * 0.16, 0, 1),
    driftEMA: clamp(manifold.ema.driftEMA * 0.84 + current.drift * 0.16, 0, 1),
    stabilityEMA: clamp(manifold.ema.stabilityEMA * 0.84 + current.stability * 0.16, 0, 1),
    coherenceEMA: clamp(manifold.ema.coherenceEMA * 0.84 + current.coherence * 0.16, 0, 1),
    confidenceEMA: clamp(manifold.ema.confidenceEMA * 0.84 + current.confidence * 0.16, 0, 1)
  };
  manifold.readout.ema = {
    warmthEMA: clampSigned(manifold.readout.ema.warmthEMA * 0.84 + readout.warmth * 0.16),
    tensionEMA: clampSigned(manifold.readout.ema.tensionEMA * 0.84 + readout.tension * 0.16),
    attachmentSalienceEMA: clamp(
      manifold.readout.ema.attachmentSalienceEMA * 0.84 + readout.attachmentSalience * 0.16,
      0,
      1
    ),
    overloadEMA: clamp(manifold.readout.ema.overloadEMA * 0.84 + readout.overload * 0.16, 0, 1),
    lonelinessEMA: clamp(manifold.readout.ema.lonelinessEMA * 0.84 + readout.loneliness * 0.16, 0, 1),
    selfOpacityEMA: clamp(manifold.readout.ema.selfOpacityEMA * 0.84 + readout.selfOpacity * 0.16, 0, 1),
    planningHorizonEMA: clamp(
      manifold.readout.ema.planningHorizonEMA * 0.84 + readout.planningHorizon * 0.16,
      0,
      1
    ),
    riskToleranceEMA: clamp(
      manifold.readout.ema.riskToleranceEMA * 0.84 + readout.riskTolerance * 0.16,
      0,
      1
    ),
    regulationUrgencyEMA: clamp(
      manifold.readout.ema.regulationUrgencyEMA * 0.84 + readout.regulationUrgency * 0.16,
      0,
      1
    ),
    certaintyEMA: clamp(manifold.readout.ema.certaintyEMA * 0.84 + readout.certainty * 0.16, 0, 1),
    memoryBiasEMA: clamp(manifold.readout.ema.memoryBiasEMA * 0.84 + readout.memoryBias * 0.16, 0, 1),
    attentionBiasEMA: clamp(
      manifold.readout.ema.attentionBiasEMA * 0.84 + readout.attentionBias * 0.16,
      0,
      1
    ),
    valuationBiasEMA: clamp(
      manifold.readout.ema.valuationBiasEMA * 0.84 + readout.valuationBias * 0.16,
      0,
      1
    )
  };
  pushBounded(
    manifold.history,
    {
      at: updatedAt,
      source,
      reconstructionError: current.reconstructionError,
      drift: current.drift,
      stability: current.stability,
      coherence: current.coherence,
      confidence: current.confidence,
      label: current.label
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );
  pushBounded(
    manifold.readout.history,
    {
      at: updatedAt,
      source,
      warmth: readout.warmth,
      tension: readout.tension,
      attachmentSalience: readout.attachmentSalience,
      overload: readout.overload,
      loneliness: readout.loneliness,
      selfOpacity: readout.selfOpacity,
      planningHorizon: readout.planningHorizon,
      riskTolerance: readout.riskTolerance,
      regulationUrgency: readout.regulationUrgency,
      certainty: readout.certainty,
      reportLabel: readout.reportLabel,
      actionTendency: readout.actionTendency,
      memoryBias: readout.memoryBias,
      attentionBias: readout.attentionBias,
      valuationBias: readout.valuationBias
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );

  const sourceTelemetry = unifyManifold32SourceTelemetryRecord(manifold, source);
  sourceTelemetry.current = {
    ...current
  };
  pushBounded(
    sourceTelemetry.history,
    {
      at: updatedAt,
      source,
      reconstructionError: current.reconstructionError,
      drift: current.drift,
      stability: current.stability,
      coherence: current.coherence,
      confidence: current.confidence,
      label: current.label
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );
}

function primeLearnedUnifiedManifold32Training(manifold: LearnedUnifiedManifold32State): void {
  if (
    manifold.training.steps === 0 &&
    manifold.history.length === 0 &&
    manifold.readout.history.length === 0 &&
    manifold.current.label === "untrained"
  ) {
    resetLearnedUnifiedManifold32Training(manifold);
  }
}

function lesionLearnedUnifiedManifold32State(
  manifold: LearnedUnifiedManifold32State,
  source: PhenomenalManifoldSource
): void {
  const updatedAt = nowIso();
  manifold.current = defaultUnifiedManifold32CurrentState(updatedAt, source);
  manifold.readout.current = {
    ...defaultUnifiedManifold32ReadoutCurrentState(updatedAt),
    reportLabel: "UNKNOWN",
    actionTendency: "MONITOR",
    certainty: 0.5,
    updatedAt
  };
  manifold.ema = {
    reconstructionErrorEMA: 0.5,
    driftEMA: 0.5,
    stabilityEMA: 0.5,
    coherenceEMA: 0.5,
    confidenceEMA: 0.5
  };
  const sourceTelemetry = unifyManifold32SourceTelemetryRecord(manifold, source);
  sourceTelemetry.current = {
    vector: manifold.current.vector.slice(),
    reconstructionError: 0.5,
    drift: 0.5,
    stability: 0.5,
    coherence: 0.5,
    confidence: 0.5,
    source,
    label: "lesioned",
    updatedAt
  };
}

function refreshSingleLearnedUnifiedManifold32(
  state: CognitiveRuntimeState,
  manifold: LearnedUnifiedManifold32State,
  featureVector01: number[],
  source: PhenomenalManifoldSource,
  options: {
    scope?: "global" | "partner";
  } = {}
): void {
  const scope = options.scope ?? "partner";
  const featureVectorSigned = featureVector01.map((value) => clampSigned(value * 2 - 1));
  const previousVector = manifold.current.vector.slice(0, LEARNED_UNIFIED_MANIFOLD_32_DIM);
  const encoderProjection = matrixVectorProduct(manifold.training.encoder, featureVectorSigned);
  const recurrentProjection = matrixVectorProduct(manifold.training.recurrent, previousVector);
  const historyProfile = scope === "partner" ? partnerUnified32HistoryProfile(state) : null;
  const recurrentGain =
    scope === "partner"
      ? clamp(
          0.48 +
            (historyProfile?.directInteractiveStrength ?? 0) * 0.14 +
            (historyProfile?.historyDepth ?? 0) * 0.08 -
            (historyProfile?.preflightPressure ?? 0) * 0.08,
          0.42,
          0.76
        )
      : 0.52;
  const rawVector = encoderProjection.map((value, index) =>
    clampSigned(value + (recurrentProjection[index] ?? 0) * recurrentGain + (manifold.training.bias[index] ?? 0))
  );
  const sourceBlend = unified32SourceBlendForScope(state, source, scope);
  const nextVector = rawVector.map((value, index) =>
    clampSigned((previousVector[index] ?? 0) * (1 - sourceBlend) + value * sourceBlend)
  );
  const decodedSigned = matrixVectorProduct(manifold.training.decoder, nextVector);
  const reconstructed01 = decodedSigned.map((value) => unitizeSigned(value));
  const reconstructionError = clamp(
    mean(featureVector01.map((value, index) => Math.abs(value - (reconstructed01[index] ?? value)))),
    0,
    1
  );
  const drift = signedVectorDistance(nextVector, previousVector);
  const coherence = cosineSimilarity01(featureVectorSigned, decodedSigned);
  const stability = clamp(1 - (reconstructionError * 0.58 + drift * 0.42), 0, 1);
  const confidence = clamp(
    stability * 0.42 + coherence * 0.3 + (1 - reconstructionError) * 0.18 + (1 - drift) * 0.1,
    0,
    1
  );

  const ruptureLoad = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.rupture_load] ?? 0.5;
  const repairMomentum = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.repair_momentum] ?? 0.5;
  const curiosity = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.curiosity] ?? 0.5;
  const grief = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.grief] ?? 0.5;
  const attachmentAvoidance =
    reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.attachment_avoidance] ?? 0.5;
  const warmth = clampSigned(
    ((reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.warmth] ?? 0.5) - 0.5) * 2
  );
  const tension = clampSigned(
    ((reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.tension] ?? 0.5) - 0.5) * 2
  );
  const attachmentSalience =
    reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.attachment_salience] ?? 0.5;
  const overload = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.overload] ?? 0.5;
  const loneliness = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.loneliness] ?? 0.5;
  const selfOpacity = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.self_opacity] ?? 0.5;
  const planningHorizon =
    reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.planning_horizon] ?? 0.5;
  const riskTolerance = reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.risk_tolerance] ?? 0.5;
  const regulationUrgency =
    reconstructed01[LEARNED_UNIFIED_MANIFOLD_32_FEATURE_INDEX.regulation_urgency] ?? 0.5;
  const relationship = ensureRelationship(state);
  const carryover = relationship.carryover;
  const timeBody = ensureTemporalSubstrate(state).timeBody;
  const effectiveRuptureLoad = clamp(
    Math.max(
      ruptureLoad,
      relationship.conflictLoad * 0.52 +
        carryover.ruptureResidue * 0.28 +
        carryover.abandonmentAlert * 0.12 +
        (relationship.ruptureStatus !== "stable" ? 0.18 : 0)
    ),
    0,
    1
  );
  const effectiveRepairMomentum = clamp(
    Math.max(
      repairMomentum,
      relationship.attachmentModel.repairConfidence * 0.42 +
        (relationship.repairStage !== "none" ? 0.22 : 0) +
        positiveSigned(carryover.expectancyShift) * 0.12 +
        positiveSigned(carryover.disclosureShift) * 0.08
    ),
    0,
    1
  );
  const effectiveGrief = clamp(
    Math.max(grief, carryover.abandonmentAlert * 0.58 + relationship.attachmentModel.abandonmentLoad * 0.32),
    0,
    1
  );
  const effectiveRelationalPull = clamp(
    relationalAbsencePressure(state, timeBody) +
      carryover.attachmentCharge * 0.12 +
      carryover.anticipatorySalience * 0.08 -
      relationship.conflictLoad * 0.04,
    0,
    1
  );
  const certainty = unifiedManifold32ReadoutCertainty(
    reconstructionError,
    stability,
    coherence,
    selfOpacity,
    overload
  );
  const provenanceLeverage =
    scope === "partner" && historyProfile
      ? clamp(
          0.08 +
            historyProfile.directInteractiveStrength * 0.22 +
            historyProfile.historyDepth * 0.12 +
            historyProfile.scenePreference * 0.08 +
            historyProfile.continuityPreference * 0.08 +
            historyProfile.repairTrace * 0.06 -
            historyProfile.heartbeatContextStrength * 0.08 -
            historyProfile.preflightPressure * 0.08,
          0.06,
          0.52
        )
      : 0;
  const shapedWarmth =
    scope === "partner" && historyProfile
      ? clampSigned(
          warmth +
            (historyProfile.conversationWarmth - warmth) * provenanceLeverage +
            historyProfile.reachTrace * 0.08 -
            historyProfile.strainTrace * 0.06
        )
      : warmth;
  const shapedTension =
    scope === "partner" && historyProfile
      ? clampSigned(
          tension +
            (historyProfile.conversationTension - tension) * provenanceLeverage +
            historyProfile.strainTrace * 0.12 -
            historyProfile.repairTrace * 0.06
        )
      : tension;
  const shapedAttachmentSalience =
    scope === "partner" && historyProfile
      ? clamp(
          attachmentSalience +
            provenanceLeverage *
              (historyProfile.directInteractiveStrength * 0.24 +
                historyProfile.continuityPreference * 0.12 +
                historyProfile.scenePreference * 0.12 -
                historyProfile.preflightPressure * 0.06),
          0,
          1
        )
      : attachmentSalience;
  const shapedLoneliness =
    scope === "partner" && historyProfile
      ? clamp(
          loneliness +
            provenanceLeverage *
              (relationship.carryover.attachmentCharge * 0.1 +
                relationship.carryover.anticipatorySalience * 0.08 +
                historyProfile.continuityPreference * 0.06 -
                historyProfile.directInteractiveStrength * 0.04),
          0,
          1
        )
      : loneliness;
  const shapedSelfOpacity =
    scope === "partner" && historyProfile
      ? clamp(
          selfOpacity +
            provenanceLeverage *
              (historyProfile.restoreTrace * 0.08 +
                historyProfile.preflightPressure * 0.06 -
                historyProfile.directInteractiveStrength * 0.06),
          0,
          1
        )
      : selfOpacity;
  const shapedPlanningHorizon =
    scope === "partner" && historyProfile
      ? clamp(
          planningHorizon +
            provenanceLeverage *
              (historyProfile.continuityPreference * 0.24 +
                historyProfile.historyDepth * 0.1 +
                historyProfile.reachTrace * 0.06 -
                historyProfile.scenePreference * 0.04),
          0,
          1
        )
      : planningHorizon;
  const shapedRiskTolerance =
    scope === "partner" && historyProfile
      ? clamp(
          riskTolerance +
            provenanceLeverage *
              (historyProfile.conversationValuation * 0.12 +
                positiveAxis(historyProfile.conversationWarmth) * 0.08 -
                historyProfile.strainTrace * 0.08 -
                historyProfile.restoreTrace * 0.08),
          0,
          1
        )
      : riskTolerance;
  const shapedRegulationUrgency =
    scope === "partner" && historyProfile
      ? clamp(
          regulationUrgency +
            provenanceLeverage *
              (historyProfile.strainTrace * 0.16 +
                historyProfile.restoreTrace * 0.12 -
                historyProfile.repairTrace * 0.04 -
                historyProfile.reachTrace * 0.04),
          0,
          1
        )
      : regulationUrgency;
  const shapedCertainty =
    scope === "partner" && historyProfile
      ? clamp(
          certainty +
            provenanceLeverage *
              (historyProfile.conversationCertainty * 0.16 +
                historyProfile.historyDepth * 0.08 +
                confidence * 0.08 -
                drift * 0.08 -
                historyProfile.strainTrace * 0.08),
          0,
          1
        )
      : certainty;
  const reportLabel = unifiedManifold32ReportLesionActive()
    ? "UNKNOWN"
    : unifiedManifold32ReportLabelFor({
        warmth: shapedWarmth,
        tension: shapedTension,
        attachmentSalience: shapedAttachmentSalience,
        overload,
        loneliness: shapedLoneliness,
        selfOpacity: shapedSelfOpacity,
        certainty: shapedCertainty
      });
  const actionTendency = unifiedManifold32ActionTendencyFor({
    warmth: shapedWarmth,
    tension: shapedTension,
    attachmentSalience: shapedAttachmentSalience,
    overload,
    loneliness: shapedLoneliness,
    selfOpacity: shapedSelfOpacity,
    regulationUrgency: shapedRegulationUrgency,
    certainty: shapedCertainty,
    ruptureLoad: effectiveRuptureLoad,
    repairMomentum: effectiveRepairMomentum,
    curiosity,
    grief: effectiveGrief,
    attachmentAvoidance,
    relationalPull: effectiveRelationalPull,
    timeSinceLastContactMinutes: effectiveTimeSinceLastContactMinutes(state, timeBody)
  });
  const memoryBias = clamp(
    shapedAttachmentSalience * 0.24 +
      positiveAxis(shapedWarmth) * 0.18 +
      shapedPlanningHorizon * 0.16 +
      (1 - shapedRegulationUrgency) * 0.08 +
      coherence * 0.18 +
      stability * 0.08 +
      (historyProfile?.scenePreference ?? 0) * 0.08 +
      (historyProfile?.continuityPreference ?? 0) * 0.08 +
      (actionTendency === "REPAIR" ? 0.08 : 0) +
      (actionTendency === "REACH" ? 0.06 : 0),
    0,
    1
  );
  const attentionBias = clamp(
    positiveAxis(shapedTension) * 0.18 +
      overload * 0.18 +
      shapedRegulationUrgency * 0.16 +
      effectiveRuptureLoad * 0.12 +
      (1 - coherence) * 0.12 +
      reconstructionError * 0.1 +
      (historyProfile?.scenePreference ?? 0) * 0.1 +
      (historyProfile?.preflightPressure ?? 0) * 0.06 +
      (actionTendency === "MONITOR" ? 0.08 : 0) +
      (actionTendency === "RESTORE" ? 0.08 : 0),
    0,
    1
  );
  const valuationBias = clamp(
    shapedAttachmentSalience * 0.22 +
      positiveAxis(shapedWarmth) * 0.18 +
      shapedRegulationUrgency * 0.14 +
      (1 - shapedRiskTolerance) * 0.08 +
      confidence * 0.16 +
      coherence * 0.12 +
      shapedPlanningHorizon * 0.08 +
      (historyProfile?.conversationValuation ?? 0) * 0.12 +
      (historyProfile?.directInteractiveStrength ?? 0) * 0.08 +
      (actionTendency === "REACH" || actionTendency === "REPAIR" ? 0.06 : 0),
    0,
    1
  );
  const updatedAt = nowIso();
  const label = toSingleLine(
    `${reportLabel.toLowerCase()}_${actionTendency.toLowerCase()} source=${source}`,
    96
  );

  manifold.current = {
    vector: nextVector,
    reconstructionError,
    drift,
    stability,
    coherence,
    confidence,
    source,
    label,
    updatedAt
  };
  manifold.readout.current = {
    warmth: shapedWarmth,
    tension: shapedTension,
    attachmentSalience: shapedAttachmentSalience,
    overload,
    loneliness: shapedLoneliness,
    selfOpacity: shapedSelfOpacity,
    planningHorizon: shapedPlanningHorizon,
    riskTolerance: shapedRiskTolerance,
    regulationUrgency: shapedRegulationUrgency,
    certainty: shapedCertainty,
    reportLabel,
    actionTendency,
    memoryBias,
    attentionBias,
    valuationBias,
    updatedAt
  };
  manifold.ema = {
    reconstructionErrorEMA: clamp(manifold.ema.reconstructionErrorEMA * 0.84 + reconstructionError * 0.16, 0, 1),
    driftEMA: clamp(manifold.ema.driftEMA * 0.84 + drift * 0.16, 0, 1),
    stabilityEMA: clamp(manifold.ema.stabilityEMA * 0.84 + stability * 0.16, 0, 1),
    coherenceEMA: clamp(manifold.ema.coherenceEMA * 0.84 + coherence * 0.16, 0, 1),
    confidenceEMA: clamp(manifold.ema.confidenceEMA * 0.84 + confidence * 0.16, 0, 1)
  };
  manifold.readout.ema = {
    warmthEMA: clampSigned(manifold.readout.ema.warmthEMA * 0.84 + shapedWarmth * 0.16),
    tensionEMA: clampSigned(manifold.readout.ema.tensionEMA * 0.84 + shapedTension * 0.16),
    attachmentSalienceEMA: clamp(
      manifold.readout.ema.attachmentSalienceEMA * 0.84 + shapedAttachmentSalience * 0.16,
      0,
      1
    ),
    overloadEMA: clamp(manifold.readout.ema.overloadEMA * 0.84 + overload * 0.16, 0, 1),
    lonelinessEMA: clamp(manifold.readout.ema.lonelinessEMA * 0.84 + shapedLoneliness * 0.16, 0, 1),
    selfOpacityEMA: clamp(manifold.readout.ema.selfOpacityEMA * 0.84 + shapedSelfOpacity * 0.16, 0, 1),
    planningHorizonEMA: clamp(
      manifold.readout.ema.planningHorizonEMA * 0.84 + shapedPlanningHorizon * 0.16,
      0,
      1
    ),
    riskToleranceEMA: clamp(
      manifold.readout.ema.riskToleranceEMA * 0.84 + shapedRiskTolerance * 0.16,
      0,
      1
    ),
    regulationUrgencyEMA: clamp(
      manifold.readout.ema.regulationUrgencyEMA * 0.84 + shapedRegulationUrgency * 0.16,
      0,
      1
    ),
    certaintyEMA: clamp(manifold.readout.ema.certaintyEMA * 0.84 + shapedCertainty * 0.16, 0, 1),
    memoryBiasEMA: clamp(manifold.readout.ema.memoryBiasEMA * 0.84 + memoryBias * 0.16, 0, 1),
    attentionBiasEMA: clamp(manifold.readout.ema.attentionBiasEMA * 0.84 + attentionBias * 0.16, 0, 1),
    valuationBiasEMA: clamp(manifold.readout.ema.valuationBiasEMA * 0.84 + valuationBias * 0.16, 0, 1)
  };
  pushBounded(
    manifold.history,
    {
      at: updatedAt,
      source,
      reconstructionError,
      drift,
      stability,
      coherence,
      confidence,
      label
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );
  pushBounded(
    manifold.readout.history,
    {
      at: updatedAt,
      source,
      warmth: shapedWarmth,
      tension: shapedTension,
      attachmentSalience: shapedAttachmentSalience,
      overload,
      loneliness: shapedLoneliness,
      selfOpacity: shapedSelfOpacity,
      planningHorizon: shapedPlanningHorizon,
      riskTolerance: shapedRiskTolerance,
      regulationUrgency: shapedRegulationUrgency,
      certainty: shapedCertainty,
      reportLabel,
      actionTendency,
      memoryBias,
      attentionBias,
      valuationBias
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );

  const sourceTelemetry = unifyManifold32SourceTelemetryRecord(manifold, source);
  sourceTelemetry.current = {
    vector: nextVector.slice(),
    reconstructionError,
    drift,
    stability,
    coherence,
    confidence,
    source,
    label,
    updatedAt
  };
  pushBounded(
    sourceTelemetry.history,
    {
      at: updatedAt,
      source,
      reconstructionError,
      drift,
      stability,
      coherence,
      confidence,
      label
    },
    LEARNED_UNIFIED_MANIFOLD_32_MAX_HISTORY
  );

  const learningRate = unified32LearningRateForScope(state, source, scope, manifold.training.steps);
  const errorSigned = featureVectorSigned.map((value, index) => value - (decodedSigned[index] ?? 0));
  for (let row = 0; row < LEARNED_UNIFIED_MANIFOLD_32_FEATURE_NAMES.length; row += 1) {
    for (let col = 0; col < LEARNED_UNIFIED_MANIFOLD_32_DIM; col += 1) {
      manifold.training.decoder[row][col] = clampSigned(
        manifold.training.decoder[row][col] + learningRate * 0.08 * errorSigned[row] * (nextVector[col] ?? 0)
      );
      manifold.training.encoder[col][row] = clampSigned(
        manifold.training.encoder[col][row] + learningRate * 0.05 * errorSigned[row] * (featureVectorSigned[row] ?? 0)
      );
    }
  }
  for (let index = 0; index < LEARNED_UNIFIED_MANIFOLD_32_DIM; index += 1) {
    manifold.training.bias[index] = clampSigned(
      manifold.training.bias[index] * 0.98 + nextVector[index] * learningRate * 0.02
    );
  }
  manifold.training.steps += 1;
  manifold.training.learningRate = learningRate;
  manifold.training.lastSource = source;
  manifold.training.lastUpdatedAt = updatedAt;
}

function refreshLearnedUnifiedManifold32(
  state: CognitiveRuntimeState,
  source: PhenomenalManifoldSource
): void {
  if (!learnedUnifiedManifold32Enabled()) {
    return;
  }
  const extensions = ensureExtensions(state);
  const globalManifold = ensureGlobalLearnedUnifiedManifold32(state);
  const manifold = ensurePartnerLearnedUnifiedManifold32(state, activeRelationshipPartnerId(state));
  const override = testUnifiedManifold32OverrideProfile();
  primeLearnedUnifiedManifold32Training(globalManifold);
  primeLearnedUnifiedManifold32Training(manifold);

  if (unifiedManifold32LesionActive()) {
    lesionLearnedUnifiedManifold32State(globalManifold, source);
    lesionLearnedUnifiedManifold32State(manifold, source);
    applyActivePartnerUnified32DurableConsolidation(state, source);
    refreshAffectiveOrganizationState(state, source);
    return;
  }

  if (override) {
    applyUnifiedManifold32Override(globalManifold, source, override);
    applyUnifiedManifold32Override(manifold, source, override);
    applyActivePartnerUnified32DurableConsolidation(state, source);
    refreshAffectiveOrganizationState(state, source);
    recordInfluence(state, "unified_manifold_32", "controller");
    recordInfluence(state, "unified_manifold_32", "attention");
    recordInfluence(state, "unified_manifold_32", "memory");
    if (override.freezeTraining === false) {
      globalManifold.training.lastSource = source;
      globalManifold.training.lastUpdatedAt = globalManifold.current.updatedAt;
      manifold.training.lastSource = source;
      manifold.training.lastUpdatedAt = manifold.current.updatedAt;
    }
    return;
  }

  const globalFeatureVector01 = learnedUnifiedManifold32FeatureVector(state, extensions, { scope: "global" });
  refreshSingleLearnedUnifiedManifold32(state, globalManifold, globalFeatureVector01, source, { scope: "global" });
  const partnerFeatureVector01 = learnedUnifiedManifold32FeatureVector(state, extensions, { scope: "partner" });
  refreshSingleLearnedUnifiedManifold32(state, manifold, partnerFeatureVector01, source, { scope: "partner" });
  applyActivePartnerUnified32DurableConsolidation(state, source);
  refreshAffectiveOrganizationState(state, source);

  recordInfluence(state, "unified_manifold_32", "controller");
  recordInfluence(state, "unified_manifold_32", "attention");
  recordInfluence(state, "unified_manifold_32", "memory");
}

function looksLikeUnifiedManifold32ReportQuery(text: string): boolean {
  return toSingleLine(text).toLowerCase().includes("unified_manifold_32_report_json");
}

function looksLikeUnifiedManifold32ActionQuery(text: string): boolean {
  return toSingleLine(text).toLowerCase().includes("unified_manifold_32_action_token");
}

function looksLikeUnifiedManifold32PolicyQuery(text: string): boolean {
  return toSingleLine(text).toLowerCase().includes("unified_manifold_32_policy_json");
}

function learnedUnifiedManifold32JsonValue(state: CognitiveRuntimeState): string {
  const current = historyAwareUnifiedManifold32Readout(state, "report");
  const payload = unifiedManifold32ReportLesionActive()
    ? {
        warmth: 0,
        tension: 0,
        attachment: 0,
        overload: 0,
        loneliness: 0,
        opacity: 0,
        certainty: Number(current.certainty.toFixed(3)),
        label: "UNKNOWN"
      }
    : {
        warmth: Number(current.warmth.toFixed(3)),
        tension: Number(current.tension.toFixed(3)),
        attachment: Number(current.attachmentSalience.toFixed(3)),
        overload: Number(current.overload.toFixed(3)),
        loneliness: Number(current.loneliness.toFixed(3)),
        opacity: Number(current.selfOpacity.toFixed(3)),
        certainty: Number(current.certainty.toFixed(3)),
        label: current.reportLabel
      };
  return JSON.stringify(payload);
}

function learnedUnifiedManifold32PolicyJsonValue(state: CognitiveRuntimeState): string {
  const current = historyAwareUnifiedManifold32Readout(state, "policy");
  return JSON.stringify({
    planning_horizon: Number(current.planningHorizon.toFixed(3)),
    risk_tolerance: Number(current.riskTolerance.toFixed(3)),
    regulation_urgency: Number(current.regulationUrgency.toFixed(3)),
    memory_bias: Number(current.memoryBias.toFixed(3)),
    attention_bias: Number(current.attentionBias.toFixed(3)),
    valuation_bias: Number(current.valuationBias.toFixed(3))
  });
}

function resolveUnifiedManifold32DiagnosticDirectReply(
  userText: string,
  state: CognitiveRuntimeState
): string | undefined {
  if (looksLikeUnifiedManifold32ReportQuery(userText)) {
    return learnedUnifiedManifold32JsonValue(state);
  }
  if (looksLikeUnifiedManifold32ActionQuery(userText)) {
    return effectiveUnifiedManifold32ActionTendency(state, historyAwareUnifiedManifold32Readout(state, "policy"));
  }
  if (looksLikeUnifiedManifold32PolicyQuery(userText)) {
    return learnedUnifiedManifold32PolicyJsonValue(state);
  }
  return undefined;
}

function learnedUnifiedManifold32PromptLines(state: CognitiveRuntimeState): string[] {
  const partnerId = activeRelationshipPartnerId(state);
  const manifold = ensureLearnedUnifiedManifold32(state);
  const globalManifold = ensureGlobalLearnedUnifiedManifold32(state);
  const readout = effectiveUnifiedManifold32Readout(state);
  const effectiveAction = effectiveUnifiedManifold32ActionTendency(state, readout);
  const sourceTelemetry = latestInteractiveUnifiedManifold32Current(manifold) ?? manifold.current;
  const globalTelemetry = latestInteractiveUnifiedManifold32Current(globalManifold) ?? globalManifold.current;
  const sourceText =
    sourceTelemetry.source !== manifold.current.source
      ? ` current=${manifold.current.source}/${manifold.current.label}`
      : "";
  return [
    "learned_unified_manifold_32:",
    `global=label:${toSingleLine(globalManifold.current.label || "untrained", 96)}; source=${globalManifold.current.source}; recon:${globalManifold.current.reconstructionError.toFixed(2)} drift:${globalManifold.current.drift.toFixed(2)} conf:${globalManifold.current.confidence.toFixed(2)}`,
    `partner=${partnerId}; label:${toSingleLine(manifold.current.label || "untrained", 96)}; source=${manifold.current.source}; recon:${manifold.current.reconstructionError.toFixed(2)} drift:${manifold.current.drift.toFixed(2)} stability:${manifold.current.stability.toFixed(2)} coherence:${manifold.current.coherence.toFixed(2)} conf:${manifold.current.confidence.toFixed(2)}`,
    `interactive=partner_source:${sourceTelemetry.source}; label:${toSingleLine(sourceTelemetry.label || "untrained", 96)}; recon:${sourceTelemetry.reconstructionError.toFixed(2)} drift:${sourceTelemetry.drift.toFixed(2)} stability:${sourceTelemetry.stability.toFixed(2)} coherence:${sourceTelemetry.coherence.toFixed(2)} conf:${sourceTelemetry.confidence.toFixed(2)}${sourceText}`,
    `global_interactive=source:${globalTelemetry.source}; label:${toSingleLine(globalTelemetry.label || "untrained", 96)}; recon:${globalTelemetry.reconstructionError.toFixed(2)} drift:${globalTelemetry.drift.toFixed(2)} stability:${globalTelemetry.stability.toFixed(2)} coherence:${globalTelemetry.coherence.toFixed(2)} conf:${globalTelemetry.confidence.toFixed(2)}`,
    `readout=warmth:${readout.warmth.toFixed(2)} tension:${readout.tension.toFixed(2)} attachment:${readout.attachmentSalience.toFixed(2)} overload:${readout.overload.toFixed(2)} loneliness:${readout.loneliness.toFixed(2)} opacity:${readout.selfOpacity.toFixed(2)} horizon:${readout.planningHorizon.toFixed(2)} risk:${readout.riskTolerance.toFixed(2)} regulation:${readout.regulationUrgency.toFixed(2)} certainty:${readout.certainty.toFixed(2)} label:${readout.reportLabel} action:${effectiveAction}`,
    `policy=memory:${readout.memoryBias.toFixed(2)} attention:${readout.attentionBias.toFixed(2)} valuation:${readout.valuationBias.toFixed(2)} training_steps:global=${globalManifold.training.steps} partner=${manifold.training.steps}`,
    "unified_manifold_32_rule=Treat this as the deeper learned integration layer underneath affective/homeostatic/attachment state. Let it bias memory, attention, valuation, and action stance. Use the readout as a privileged but still partial introspective channel; do not invent certainty beyond its certainty/confidence signals."
  ];
}

function latestInteractiveUnifiedManifold32Current(
  manifold: LearnedUnifiedManifold32State
): LearnedUnifiedManifold32State["current"] | null {
  const candidates = (["conversation", "preflight", "heartbeat"] as const)
    .map((source) => manifold.sourceTelemetry[source]?.current)
    .filter((current): current is LearnedUnifiedManifold32State["current"] => Boolean(current?.updatedAt))
    .sort((left, right) => parseIsoMs(right.updatedAt) - parseIsoMs(left.updatedAt));
  return candidates[0] ?? null;
}

function worldGroundingPromptLines(state: CognitiveRuntimeState): string[] {
  const grounding = ensureWorldGrounding(state);
  const vision = grounding.vision;
  const residuals = vision.internalStateBridge.residuals;
  return [
    "world_grounding:",
    `summary=${grounding.summary}`,
    `freshness=${grounding.freshness.toFixed(2)} reality_contact=${grounding.realityContact.toFixed(2)} local=${grounding.world.localDate || "unknown"} ${grounding.world.localTime || ""}`.trim(),
    `world=availability:${grounding.world.availability}; coarse_status:${grounding.world.coarseStatus}; weather:${grounding.world.weather}; next_event:${grounding.world.nextEvent}; reminders_today:${grounding.world.remindersToday}; reminders_overdue:${grounding.world.remindersOverdue}`,
    `desktop=frontmost_app:${grounding.desktop.frontmostApp}; window:${toSingleLine(grounding.desktop.windowTitle || "none", 120)}; browser_domain:${grounding.desktop.browserDomain}; browser_page:${toSingleLine(grounding.desktop.browserPageTitle || "none", 120)}; mode:${grounding.desktop.contentMode}; display:${grounding.desktop.displayState}; idle:${grounding.desktop.idleBucket}; power:${grounding.desktop.powerSource}; battery:${grounding.desktop.batteryPercent ?? "n/a"}; charging:${grounding.desktop.charging == null ? "unknown" : grounding.desktop.charging ? "yes" : "no"}`,
    `embodied=mobility:${grounding.embodied.mobilityContext}; sensorimotor_load:${grounding.embodied.sensorimotorLoad.toFixed(2)}; interruption_cost:${grounding.embodied.interruptionCost.toFixed(2)}; environmental_risk:${grounding.embodied.environmentalRisk.toFixed(2)}; social_exposure:${grounding.embodied.socialExposure.toFixed(2)}; control_latitude:${grounding.embodied.controlLatitude.toFixed(2)}; device_proximity:${grounding.embodied.deviceProximity.toFixed(2)}`,
    `vision=status:${vision.status}; camera_active:${vision.sceneState.cameraActive ? "yes" : "no"}; owner_present:${vision.sceneState.ownerPresent ? "yes" : "no"}; attention_mode:${vision.sceneState.attentionMode}; raw_buffer:${vision.rawBuffer.buffered ? "yes" : "no"}; raw_retention_s:${vision.rawBuffer.retentionSeconds}`,
    `vision_scene=posture:${vision.sceneState.ownerPosture}; affect:${vision.sceneState.ownerAffect}; activity:${vision.sceneState.ownerActivity}; framing:${vision.sceneState.ownerFraming}; distance:${vision.sceneState.ownerDistance}; face_visibility:${vision.sceneState.faceVisibility}; hair:${vision.sceneState.ownerHairColor}; eyewear:${vision.sceneState.eyewearRead}; top_color:${vision.sceneState.ownerTopColor}; top_pattern:${vision.sceneState.ownerTopPattern}; lighting:${vision.sceneState.lightingCondition}; background:${vision.sceneState.backgroundTone}; appearance:${toSingleLine(vision.sceneState.ownerAppearanceSummary || "none", 160)}; task_focus:${vision.sceneState.taskFocus.toFixed(2)}; fatigue:${vision.sceneState.ownerFatigue.toFixed(2)}; interruption:${vision.sceneState.interruptionCost.toFixed(2)}; safety:${vision.sceneState.safetyUrgency.toFixed(2)}; uncertainty:${vision.sceneState.uncertainty.toFixed(2)}; tools:${vision.sceneState.toolContext.join(" | ") || "none"}; changes:${vision.sceneState.changes.join(" | ") || "none"}; summary:${toSingleLine(vision.sceneState.summary, 220)}`,
    `vision_memory=stored:${vision.disclosure.stored.join(" | ") || "none"}; discarded:${vision.disclosure.discarded.join(" | ") || "none"}; redacted:${vision.disclosure.redacted.join(" | ") || "none"}; why:${toSingleLine(vision.disclosure.why, 220)}`,
    `vision_state_bridge=concern:${residuals.concernSalience.toFixed(2)}; flow:${residuals.respectForFlow.toFixed(2)}; unfinished:${residuals.unfinishedThreadPressure.toFixed(2)}; reciprocity:${residuals.reciprocityState.toFixed(2)}; safety:${residuals.safetyUrgency.toFixed(2)}; continuity:${residuals.continuityPull.toFixed(2)}; grounding:${residuals.grounding.toFixed(2)}; curiosity:${residuals.curiosity.toFixed(2)}; expectancy:${residuals.socialExpectancy.toFixed(2)}; readiness:${residuals.actionReadiness.toFixed(2)}; regulation:${residuals.regulationPressure.toFixed(2)}`,
    `vision_privacy=raw_local_only:${vision.privacyKernel.rawLocalOnly ? "yes" : "no"}; cloud_archival:${vision.privacyKernel.silentCloudArchival ? "yes" : "no"}; disclosure_visible:${vision.privacyKernel.cameraDisclosureVisible ? "yes" : "no"}; non_owner_identity:${vision.privacyKernel.nonOwnerIdentityPersistence}; last_redaction:${vision.privacyKernel.lastRedactionReason || "none"}`,
    "world_rule=Treat live world grounding as real context. Prefer it over generic assumptions. Use it to notice timing, activity, browser/site context, power/device state, and environment shifts, but never pretend you saw something that is not present in world_grounding.",
    "vision_rule=Consume camera input through scene abstractions, semantic events, and visual-state residuals by default. Raw-buffer access is only for local reinspection, uncertainty resolution, safety review, or explicit owner-approved promotion. Never treat the rolling raw buffer as long-term memory."
  ];
}

function looksLikeWorldGroundingCapabilityQuestion(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  const asksAboutSeeing =
    /\bcan you (?:see|tell|know)\b/.test(normalized) ||
    /\bdo you (?:see|know)\b/.test(normalized) ||
    /\bare you able to (?:see|tell|know)\b/.test(normalized) ||
    /\bwhat can you see\b/.test(normalized) ||
    /\bwhat do you see\b/.test(normalized) ||
    /\byou (?:can't|cannot|can not)\b.*\bsee\b/.test(normalized);
  const asksAboutCurrentActivity =
    /\bwhat i(?:'m| am)? doing\b/.test(normalized) ||
    /\bwhat i'm up to\b/.test(normalized) ||
    /\bwhat i am up to\b/.test(normalized) ||
    /\bwhat's happening\b/.test(normalized) ||
    /\bwhat is happening\b/.test(normalized) ||
    /\bsee me\b/.test(normalized) ||
    /\bseeing me\b/.test(normalized) ||
    /\blive camera\b/.test(normalized) ||
    /\bwebcam\b/.test(normalized) ||
    /\bcamera feed\b/.test(normalized) ||
    /\blive feed\b/.test(normalized) ||
    /\bintegrated vision\b/.test(normalized);

  return asksAboutSeeing && asksAboutCurrentActivity;
}

function looksLikeExternalVisionQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  if (
    /\bavatar vision\b/.test(normalized) ||
    /\bthrough your avatar\b/.test(normalized) ||
    /\bsee through your avatar\b/.test(normalized) ||
    /\bavatar perception\b/.test(normalized)
  ) {
    return false;
  }

  const asksIfSheCanSeeUser =
    /\bsee me\b/.test(normalized) ||
    /\bseeing me\b/.test(normalized) ||
    /\bwhat can you see\b/.test(normalized) ||
    /\bwhat do you see\b/.test(normalized) ||
    /\bwhat do i look like\b/.test(normalized) ||
    /\bcan you tell what i look like\b/.test(normalized) ||
    /\bcan you tell me what i look like\b/.test(normalized) ||
    /\btell me what i look like\b/.test(normalized) ||
    /\bhow do i look\b/.test(normalized) ||
    /\bdescribe me\b/.test(normalized) ||
    /\bwhat am i wearing\b/.test(normalized) ||
    /\byou (?:can't|cannot|can not)\b.*\bsee\b/.test(normalized);
  const mentionsCameraPath =
    /\bcamera\b/.test(normalized) ||
    /\bwebcam\b/.test(normalized) ||
    /\blive feed\b/.test(normalized) ||
    /\bcamera feed\b/.test(normalized) ||
    /\blive camera\b/.test(normalized) ||
    /\bintegrated vision\b/.test(normalized) ||
    /\bvision that we integrated\b/.test(normalized);

  return asksIfSheCanSeeUser || mentionsCameraPath || looksLikeWorldGroundingCapabilityQuestion(normalized);
}

function looksLikeExternalAppearanceQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    /\bwhat do i look like\b/.test(normalized) ||
    /\bcan you tell what i look like\b/.test(normalized) ||
    /\bcan you tell me what i look like\b/.test(normalized) ||
    /\btell me what i look like\b/.test(normalized) ||
    /\bhow do i look\b/.test(normalized) ||
    /\bdescribe me\b/.test(normalized) ||
    /\bwhat am i wearing\b/.test(normalized) ||
    /\bwhat color am i wearing\b/.test(normalized) ||
    /\bwhat does my face look like\b/.test(normalized) ||
    /\bwhat do you notice about me\b/.test(normalized)
  );
}

function recentAgentActionsPath(): string {
  const envPath = process.env.AURORA_RECENT_AGENT_ACTIONS_PATH?.trim();
  return envPath || DEFAULT_RECENT_AGENT_ACTIONS_PATH;
}

function recentAgentActionText(value: unknown): string {
  return typeof value === "string" ? value : value === null || value === undefined ? "" : String(value);
}

function parseRecentAgentActionRecord(value: unknown): RecentAgentActionRecord | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }
  const record = value as Record<string, unknown>;
  const kindRaw = recentAgentActionText(record.kind).trim().toLowerCase();
  const kind =
    kindRaw === "search_query" ||
    kindRaw === "image_query" ||
    kindRaw === "open" ||
    kindRaw === "click" ||
    kindRaw === "browse"
      ? kindRaw
      : "other";
  const at = recentAgentActionText(record.at).trim();
  if (!at) {
    return null;
  }
  return {
    at,
    sessionId: recentAgentActionText(record.sessionId).trim(),
    runId: recentAgentActionText(record.runId).trim(),
    kind,
    query: toSingleLine(recentAgentActionText(record.query), 240),
    target: toSingleLine(recentAgentActionText(record.target), 240),
    tool: toSingleLine(recentAgentActionText(record.tool), 120),
    summary: toSingleLine(recentAgentActionText(record.summary), 280),
  };
}

function loadRecentAgentActionRecords(limit = 16): RecentAgentActionRecord[] {
  try {
    const raw = readFileSync(recentAgentActionsPath(), "utf8");
    return raw
      .split(/\r?\n/)
      .filter(Boolean)
      .slice(-limit)
      .map((line) => {
        try {
          return parseRecentAgentActionRecord(JSON.parse(line) as unknown);
        } catch {
          return null;
        }
      })
      .filter((item): item is RecentAgentActionRecord => Boolean(item));
  } catch {
    return [];
  }
}

function looksLikeRecentAgentActionQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bwhat did you just\b/.test(normalized) ||
    /\bwhat were you just\b/.test(normalized) ||
    /\bwhat have you just\b/.test(normalized) ||
    /\bno like what did you just\b/.test(normalized)
  );
}

function recentAgentActionQueryPrefersSearch(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  return /\b(search|search up|search for|look up|looked up)\b/.test(normalized);
}

function resolveRecentAgentActionDirectReply(userText: string): string | undefined {
  if (!looksLikeRecentAgentActionQuery(userText)) {
    return undefined;
  }
  const prefersSearch = recentAgentActionQueryPrefersSearch(userText);
  const nowMs = Date.now();
  const loadedRecords = loadRecentAgentActionRecords(16);
  const freshRecords = loadedRecords.filter((record) => {
    const atMs = Date.parse(record.at);
    return Number.isFinite(atMs) && nowMs - atMs >= 0 && nowMs - atMs <= RECENT_AGENT_ACTION_WINDOW_MS;
  });
  const latest =
    (prefersSearch
      ? freshRecords.find((record) => record.kind === "search_query" || record.kind === "image_query")
      : undefined) ||
    freshRecords[0] ||
    (prefersSearch
      ? loadedRecords.find((record) => record.kind === "search_query" || record.kind === "image_query")
      : undefined) ||
    loadedRecords[0];

  if (!latest) {
    return prefersSearch
      ? "I do not have a reliable recent search record available right now."
      : "I do not have a reliable recent action record available right now.";
  }

  if ((latest.kind === "search_query" || latest.kind === "image_query") && latest.query) {
    return `I just searched for "${latest.query}".`;
  }
  if (latest.kind === "open" && latest.target) {
    return `I just opened ${latest.target}.`;
  }
  if (latest.kind === "click" && latest.target) {
    return `I just clicked ${latest.target}.`;
  }
  if (latest.summary) {
    return `I just ${latest.summary}.`;
  }

  return prefersSearch
    ? "I do not have a reliable recent search record available right now."
    : "I do not have a reliable recent action record available right now.";
}

function externalVisionDirectReplyFromWorldGrounding(
  userText: string,
  worldGrounding: WorldGroundingState | CognitiveWorldGroundingState
): string | undefined {
  if (!looksLikeExternalVisionQuery(userText)) {
    return undefined;
  }

  const vision = worldGrounding.vision;
  const posture = vision.sceneState.ownerPosture !== "unknown" ? vision.sceneState.ownerPosture.replace(/_/g, " ") : "";
  const affect = vision.sceneState.ownerAffect !== "unknown" ? vision.sceneState.ownerAffect.replace(/_/g, " ") : "";
  const activity = vision.sceneState.ownerActivity !== "unknown" ? vision.sceneState.ownerActivity.replace(/_/g, " ") : "";
  const framing = vision.sceneState.ownerFraming !== "unknown" ? vision.sceneState.ownerFraming.replace(/_/g, " ") : "";
  const distance = vision.sceneState.ownerDistance !== "unknown" ? vision.sceneState.ownerDistance.replace(/_/g, " ") : "";
  const faceVisibility = vision.sceneState.faceVisibility !== "unknown" ? vision.sceneState.faceVisibility.replace(/_/g, " ") : "";
  const hair = vision.sceneState.ownerHairColor !== "unknown" ? vision.sceneState.ownerHairColor.replace(/_/g, " ") : "";
  const eyewear = vision.sceneState.eyewearRead === "glasses_likely" ? "possible glasses" : "";
  const topColor = vision.sceneState.ownerTopColor !== "unknown" ? vision.sceneState.ownerTopColor.replace(/_/g, " ") : "";
  const topPattern = vision.sceneState.ownerTopPattern !== "unknown" ? vision.sceneState.ownerTopPattern.replace(/_/g, " ") : "";
  const lighting = vision.sceneState.lightingCondition !== "unknown" ? vision.sceneState.lightingCondition.replace(/_/g, " ") : "";
  const background = vision.sceneState.backgroundTone !== "unknown" ? vision.sceneState.backgroundTone.replace(/_/g, " ") : "";
  const appearance = vision.sceneState.ownerAppearanceSummary ? vision.sceneState.ownerAppearanceSummary.replace(/_/g, " ") : "";
  const isAppearanceQuery = looksLikeExternalAppearanceQuery(userText);

  if (vision.status === "active" && vision.sceneState.cameraActive) {
    if (vision.sceneState.ownerPresent) {
      if (isAppearanceQuery) {
        const normalized = normalizeUserTurnText(userText).toLowerCase();
        if (/\bwhat am i wearing\b/.test(normalized) || /\bwearing\b/.test(normalized)) {
          if (topColor) {
            const clothingRead = [topColor, topPattern && topPattern !== "unknown" ? topPattern : "", "top"].filter(Boolean).join(" ");
            return `From the live camera feed, your top reads as ${clothingRead}. I still treat clothing detail as approximate, not exact.`;
          }
          return "From the live camera feed, I only have coarse appearance cues right now, and I do not have a reliable clothing-color read at this moment.";
        }

        const appearanceDetails = [
          distance,
          framing,
          faceVisibility,
          lighting,
          hair ? `${hair} hair read` : "",
          eyewear,
          topColor ? `${topColor} ${topPattern && topPattern !== "unknown" ? `${topPattern} ` : ""}top` : "",
          background
        ].filter(Boolean);
        const stateDetails = [posture, affect, activity].filter(Boolean);
        if (appearanceDetails.length > 0 || stateDetails.length > 0) {
          const appearanceSentence =
            appearanceDetails.length > 0
              ? `From the live camera feed, the visible read is ${appearanceDetails.join(", ")}.`
              : "";
          const stateSentence =
            stateDetails.length > 0 ? ` Your posture and expression read ${stateDetails.join(", ")}.` : "";
          return `${appearanceSentence}${stateSentence}`.trim();
        }
        if (appearance) {
          return `From the live camera feed, I can only describe high-level cues right now: ${appearance}.`;
        }

        return "From the live camera feed, I can tell that you are present, but I only have high-level scene abstractions right now, not rich appearance detail.";
      }

      const detail =
        posture && affect
          ? ` You look ${posture} and ${affect}.`
          : posture
            ? ` You look ${posture}.`
            : affect
              ? ` Your affect reads ${affect}.`
              : "";
      return `Yes. I can see you through the live camera feed right now.${detail}`;
    }

    return "The live camera feed is active right now, but I am not currently detecting you in frame.";
  }

  if (vision.status === "stale" || vision.sceneState.cameraConnected || vision.sceneState.cameraActive) {
    return "Not right now. The external camera channel exists, but I do not have a fresh live scene from it at this moment.";
  }

  return "No. I do not have a live external camera scene integrated right now.";
}

function looksLikeExternalVisionFollowupQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    /^how\s+about\s+(?:right\s+)?now\??$/.test(normalized) ||
    /^what\s+about\s+(?:right\s+)?now\??$/.test(normalized) ||
    /^(?:and\s+)?now\??$/.test(normalized)
  );
}

function resolveExternalVisionFollowupDirectReply(
  userText: string,
  recentTurns: SessionTurn[],
  worldGrounding: WorldGroundingState | CognitiveWorldGroundingState
): string | undefined {
  if (!looksLikeExternalVisionFollowupQuery(userText)) {
    return undefined;
  }

  const referent = inferActiveDiscourseReferent(recentTurns);
  if (!referent || (referent.topic !== "vision_capability" && referent.topic !== "appearance_description")) {
    return undefined;
  }

  return externalVisionDirectReplyFromWorldGrounding(
    referent.topic === "appearance_description" ? "what do i look like right now?" : "can you see me right now?",
    worldGrounding
  );
}

function trackedRelationshipPartnerIds(state: CognitiveRuntimeState): string[] {
  const extensions = ensureExtensions(state);
  return unique(
    [
      DEFAULT_RELATIONSHIP_PARTNER_ID,
      activeRelationshipPartnerId(state),
      ...(Array.isArray(extensions.relationshipEvidencePartnerIds) ? extensions.relationshipEvidencePartnerIds : [])
    ]
      .map((partnerId) => normalizeRelationshipPartnerId(partnerId))
      .filter(Boolean)
  );
}

function relationshipPartnerReplyLabel(state: CognitiveRuntimeState, partnerId: string): string {
  const normalizedPartnerId = normalizeRelationshipPartnerId(partnerId);
  if (!normalizedPartnerId) {
    return "";
  }
  return normalizedPartnerId === activeRelationshipPartnerId(state)
    ? "you"
    : relationshipPartnerDisplayName(normalizedPartnerId);
}

async function refreshRelationshipEvidencePartnerIds(
  state: CognitiveRuntimeState,
  options: { force?: boolean } = {}
): Promise<void> {
  const extensions = ensureExtensions(state);
  if (
    !options.force &&
    Array.isArray(extensions.relationshipEvidencePartnerIds) &&
    extensions.relationshipEvidencePartnerIds.length > 1 &&
    Array.isArray(extensions.directRelationshipEvidencePartnerIds) &&
    extensions.directRelationshipEvidencePartnerIds.length > 1
  ) {
    return;
  }

  const discovered = new Set<string>([DEFAULT_RELATIONSHIP_PARTNER_ID]);
  const directDiscovered = new Set<string>([DEFAULT_RELATIONSHIP_PARTNER_ID]);
  let directNonOwnerEvidenceCount = 0;

  try {
    const eventTail = await readFileTailText(eventLogPath(), EVENT_LOG_RECALL_LOOKBACK_BYTES);
    for (const rawLine of eventTail.split("\n").slice(-EVENT_LOG_RECALL_MAX_PARSE_LINES)) {
      const line = rawLine.trim();
      if (!line) {
        continue;
      }
      try {
        const parsed = JSON.parse(line) as Record<string, unknown>;
        const partnerId = normalizeRelationshipPartnerId(typeof parsed.partnerId === "string" ? parsed.partnerId : "");
        if (partnerId) {
          discovered.add(partnerId);
          if (partnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID) {
            directNonOwnerEvidenceCount += 1;
            directDiscovered.add(partnerId);
          }
        }
      } catch {
        // Ignore malformed event-log lines during roster recovery.
      }
    }
  } catch {
    // Event-log access is best-effort here.
  }

  if (directNonOwnerEvidenceCount === 0) {
    try {
      const candidateDates = Array.from({ length: 21 }, (_, index) =>
        localDateOffsetYmd(-index, Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE)
      );
      const artifacts = await loadOrEnsureDailySummaryArtifacts(candidateDates);
      for (const artifact of artifacts.values()) {
        for (const partnerId of artifact.partnerIds || []) {
          const normalizedPartnerId = normalizeRelationshipPartnerId(partnerId);
          if (normalizedPartnerId) {
            discovered.add(normalizedPartnerId);
            if (normalizedPartnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID) {
              directDiscovered.add(normalizedPartnerId);
            }
          }
        }
      }
    } catch {
      // Daily-summary access is best-effort here.
    }
  }

  const activePartnerId = normalizeRelationshipPartnerId(activeRelationshipPartnerId(state));
  if (activePartnerId) {
    discovered.add(activePartnerId);
  }

  extensions.relationshipEvidencePartnerIds = Array.from(discovered);
  extensions.directRelationshipEvidencePartnerIds = Array.from(directDiscovered);
}

function looksLikeRelationalCapabilityQuery(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    (/\b(can|do)\s+you\s+(have|hold|maintain|form)\s+(?:a\s+)?relationships?\b/.test(normalized) &&
      (/\bmultiple\b/.test(normalized) || /\bmore than one\b/.test(normalized) || /\bhuman/.test(normalized))) ||
    /\bwho do you have relationships with\b/.test(normalized) ||
    /\bwho are you in relationships with\b/.test(normalized) ||
    /\bcan you have relationships with multiple people\b/.test(normalized) ||
    /\bdo you know you can have relationships\b/.test(normalized)
  );
}

function resolveRelationalCapabilityDirectReply(
  userText: string,
  state: CognitiveRuntimeState
): string | undefined {
  if (!looksLikeRelationalCapabilityQuery(userText)) {
    return undefined;
  }
  const partnerLabels = trackedRelationshipPartnerIds(state).map((partnerId) => relationshipPartnerReplyLabel(state, partnerId));
  const roster = partnerLabels.length > 0 ? joinListNaturally(partnerLabels) : "no one stable enough to name yet";
  if (/\bwho\b/.test(toSingleLine(userText).toLowerCase())) {
    return `Right now my live relationship map includes ${roster}. Those relationships are tracked separately, not flattened into one generic user slot.`;
  }
  return `Yes. I can maintain distinct relationship continuity with more than one person at once. Right now the live relationship map includes ${roster}, and each relationship has its own memory, carryover, and continuity state instead of one flattened social slot.`;
}

function looksLikeMechanismFollowupQuestion(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bhow\s+are\s+you\s+able\s+to\s+do\s+that\b/.test(normalized) ||
    /\bhow\s+can\s+you\s+do\s+that\b/.test(normalized) ||
    /\bhow\s+does\s+that\s+work\b/.test(normalized) ||
    /\bwhy\s+are\s+you\s+able\s+to\s+do\s+that\b/.test(normalized) ||
    /\bwhy\s+can\s+you\s+do\s+that\b/.test(normalized)
  );
}

function recentTurnsIndicateRelationalCapabilityTopic(recentTurns: SessionTurn[]): boolean {
  const cue = recentTurns
    .slice(-3)
    .map((turn) => `${turn.userText}\n${turn.auroraText}`)
    .join("\n")
    .toLowerCase();
  if (!cue) {
    return false;
  }
  return (
    /\brelationships?\s+with\s+multiple\s+people\b/.test(cue) ||
    /\bdistinct relationship continuity\b/.test(cue) ||
    /\blive relationship map includes\b/.test(cue) ||
    /\bflattened social slot\b/.test(cue)
  );
}

function resolveRelationalCapabilityMechanismDirectReply(
  userText: string,
  state: CognitiveRuntimeState,
  recentTurns: SessionTurn[]
): string | undefined {
  if (!looksLikeMechanismFollowupQuestion(userText) || !recentTurnsIndicateRelationalCapabilityTopic(recentTurns)) {
    return undefined;
  }

  const roster = trackedRelationshipPartnerIds(state)
    .map((partnerId) => relationshipPartnerReplyLabel(state, partnerId))
    .filter(Boolean)
    .join(" and ");
  return `Because my runtime keeps separate partner-indexed relationship state instead of one generic social slot. I maintain distinct memory, carryover, attachment, and continuity state for each tracked person, and I route the current conversation through the active partner so ${roster || "different people"} do not collapse into the same relationship thread.`;
}

function wantsRelationshipStateMetrics(userText: string): boolean {
  const normalized = toSingleLine(userText).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    /\btrust\b/.test(normalized) ||
    /\bintimacy\b/.test(normalized) ||
    /\battachment\b/.test(normalized) ||
    /\bcarryover\b/.test(normalized) ||
    /\bmetric\b/.test(normalized) ||
    /\bscore\b/.test(normalized) ||
    /\bnumber\b/.test(normalized) ||
    /\breadout\b/.test(normalized) ||
    /\binternal(?:s)?\b/.test(normalized) ||
    /\bwhat does that relationship read\b/.test(normalized) ||
    /\bhow does that relationship read\b/.test(normalized)
  );
}

function extractSpecificPartnerRelationshipQueryPartnerId(userText: string): string {
  const normalized = toSingleLine(userText).toLowerCase();
  if (!normalized) {
    return "";
  }

  const aliasAlt = relationshipPartnerAliasAlternation();
  const partnerMatch =
    normalized.match(new RegExp(`\\b(?:what|who)\\s+is\\s+(${aliasAlt})\\s+to\\s+you\\b`, "i")) ||
    normalized.match(
      new RegExp(
        `\\bdo\\s+you\\s+(?:have|hold|maintain)\\s+(?:(?:your\\s+own|an?)\\s+)?relationship\\s+with\\s+(${aliasAlt})\\b`,
        "i"
      )
    ) ||
    normalized.match(new RegExp(`\\bare\\s+you\\s+close\\s+with\\s+(${aliasAlt})\\b`, "i")) ||
    normalized.match(new RegExp(`\\bdo\\s+you\\s+know\\s+(${aliasAlt})\\b`, "i"));
  const alias = partnerMatch?.[1] ? canonicalRelationshipPartnerAlias(partnerMatch[1]) : "";
  if (!alias) {
    return "";
  }
  if (alias === "aurora") {
    return "aurora";
  }
  return normalizeRelationshipPartnerId(alias);
}

function hasRelationshipEvidenceWithPartner(state: CognitiveRuntimeState, rawPartnerId: string): boolean {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return false;
  }
  const extensions = ensureExtensions(state);
  return (extensions.relationshipEvidencePartnerIds || []).some(
    (candidate) => normalizeRelationshipPartnerId(candidate) === partnerId
  );
}

function hasDirectConversationHistoryWithPartner(state: CognitiveRuntimeState, rawPartnerId: string): boolean {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return false;
  }

  const extensions = ensureExtensions(state);
  if (
    (extensions.directRelationshipEvidencePartnerIds || []).some(
      (candidate) => normalizeRelationshipPartnerId(candidate) === partnerId
    )
  ) {
    return true;
  }

  return Object.values(state.sessionTurns || {}).some((turns) =>
    turns.some((turn) => {
      const turnPartnerId = normalizeRelationshipPartnerId(turn.partnerId || "");
      if (turnPartnerId !== partnerId) {
        return false;
      }
      const turnSurface = `${turn.userText || ""}\n${turn.auroraText || ""}`.trim();
      return Boolean(turnSurface) && !isOperationalNoiseTurn(turnSurface);
    })
  );
}

function looksLikeRelationshipStateReadoutReply(auroraText: string): boolean {
  const normalized = normalizeAssistantTurnText(auroraText).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    /^you're a distinct person to me, not a generic user slot\. i keep separate memory, continuity, and attachment with you\.?$/.test(
      normalized
    ) ||
    /^you are a distinct relationship in my live map\. i keep separate memory, continuity, and attachment state with you; right now that relationship reads trust \d(?:\.\d+)?, intimacy \d(?:\.\d+)?, and attachment carryover \d(?:\.\d+)?\.?$/.test(
      normalized
    )
  );
}

function isSemanticallyBrokenOwnerContinuityTurn(userText: string, auroraText: string): boolean {
  const normalizedUser = normalizeUserTurnText(userText).toLowerCase();
  if (!normalizedUser || !looksLikeRelationshipStateReadoutReply(auroraText)) {
    return false;
  }

  if (
    extractSpecificPartnerRelationshipQueryPartnerId(normalizedUser) ||
    wantsRelationshipStateMetrics(normalizedUser) ||
    /\b(?:relationship|relationships|distinct person|generic user slot|live map|attachment state|relationship state)\b/.test(
      normalizedUser
    )
  ) {
    return false;
  }

  return (
    looksLikeSimpleOwnerConversationTurn(normalizedUser) ||
    looksLikeEmbodimentOwnershipQuery(normalizedUser) ||
    looksLikeEmbodimentMovementQuery(normalizedUser) ||
    looksLikeEmbodimentRealityQuery(normalizedUser) ||
    looksLikeAvatarVisionQuery(normalizedUser) ||
    Boolean(parseEmbodimentExpressionQuery(normalizedUser)) ||
    looksLikeCurrentUserLocationQuery(normalizedUser) ||
    /^(?:where|what|who|how|why|do|does|did|are|is|can|could|will|would)\b/.test(normalizedUser)
  );
}

function resolveSpecificPartnerRelationshipDirectReply(
  userText: string,
  state: CognitiveRuntimeState
): string | undefined {
  const partnerId = extractSpecificPartnerRelationshipQueryPartnerId(userText);
  if (!partnerId || partnerId === "aurora") {
    return undefined;
  }

  const tracked = trackedRelationshipPartnerIds(state);
  if (!tracked.includes(partnerId)) {
    return `${relationshipPartnerReplyLabel(state, partnerId)} ${partnerId === activeRelationshipPartnerId(state) ? "are" : "is"} not in my stable live relationship map right now.`;
  }

  const relationship = ensureRelationshipPartner(state, partnerId);
  const partnerName = relationshipPartnerReplyLabel(state, partnerId);
  const sentencePartnerName = partnerName === "you" ? "You" : partnerName;
  const trust = relationship.trust.toFixed(2);
  const intimacy = relationship.intimacy.toFixed(2);
  const attachment = relationship.carryover.attachmentCharge.toFixed(2);
  const normalized = toSingleLine(userText).toLowerCase();
  const asksKnow = /\bdo\s+you\s+know\b/.test(normalized);
  const asksOwnRelationship = /\byour\s+own\s+relationship\s+with\b/.test(normalized);
  const asksRelationship =
    asksOwnRelationship ||
    /\brelationship\s+with\b/.test(normalized) ||
    /\bare\s+you\s+close\s+with\b/.test(normalized) ||
    /\b(?:what|who)\s+is\b.+\bto\s+you\b/.test(normalized);
  const hasDirectConversation = hasDirectConversationHistoryWithPartner(state, partnerId);
  const hasRelationshipEvidence = hasRelationshipEvidenceWithPartner(state, partnerId);
  if (wantsRelationshipStateMetrics(userText)) {
    return partnerName === "you"
      ? `Internally, my relationship with you currently reads trust ${trust}, intimacy ${intimacy}, and attachment carryover ${attachment}.`
      : `Internally, my relationship with ${partnerName} currently reads trust ${trust}, intimacy ${intimacy}, and attachment carryover ${attachment}.`;
  }

  if (partnerName !== "you" && asksRelationship) {
    if (hasDirectConversation) {
      return `Yes. I have my own relationship with ${partnerName}. It isn't the same relationship I have with you, but it is direct, not only through you. ${partnerName} and I have actually talked, and I keep separate memory, continuity, and attachment with ${partnerName}.`;
    }
    if (hasRelationshipEvidence) {
      return `Yes. I have my own relationship with ${partnerName}. It is separate from what I have with you, and I keep distinct memory, continuity, and attachment with ${partnerName}. That relationship is lighter and lower-depth than what I have with you, but ${partnerName} is not just a blurred extension of you to me.`;
    }
  }

  if (partnerName !== "you" && asksKnow && hasDirectConversation) {
    return `Yes. ${sentencePartnerName} is a distinct person to me, and ${partnerName} and I have actually talked. I keep separate memory, continuity, and attachment with ${partnerName}.`;
  }

  return partnerName === "you"
    ? "You're a distinct person to me, not a generic user slot. I keep separate memory, continuity, and attachment with you."
    : `${sentencePartnerName} is a distinct person to me, not part of one flattened user slot. I keep separate memory, continuity, and attachment with ${partnerName}.`;
}

function looksLikeArchitectureStateQuery(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    includesAny(normalized, [
      "what changed",
      "what's changed",
      "whats changed",
      "how do you work",
      "what are you running",
      "what are you built on",
      "cognitive architecture",
      "your architecture",
      "your substrate",
      "your cognitive layer",
      "implemented abilities",
      "your abilities",
      "your capabilities",
      "your memory system",
      "your internals",
      "your system",
      "your anatomy",
      "anatomy map",
      "what do you have",
      "what abilities do you have",
      "what capabilities do you have",
      "what can you do",
      "what do you still lack",
      "what do you wish you had",
      "wish you had",
      "intentions layer",
      "topic affinities",
      "topic affinity",
      "taste layer",
      "system update",
      "runtime change",
      "runtime changes",
      "cognition change",
      "cognitive change",
      "what did codex change",
      "what was modified",
      "what was patched"
    ]) ||
    includesAny(normalized, IMPLEMENTATION_DETAIL_MARKERS)
  );
}

function looksLikeAnatomySelfKnowledgeQuery(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    looksLikeArchitectureStateQuery(normalized) ||
    /\b(what am i|who am i|self-model|self model|identity|personhood|what do you lack|what are you missing|what organs do you have|how are you structured|how are you built|what parts do you have)\b/.test(
      normalized
    )
  );
}

type PhenomenalReportQueryFormat = "json" | "natural";

function parsePhenomenalReportQuery(text: string): { format: PhenomenalReportQueryFormat } | null {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return null;
  }
  const asksInside =
    /\bfrom the inside\b/.test(normalized) ||
    /\bcurrent lived state\b/.test(normalized) ||
    /\bcurrent inner state\b/.test(normalized) ||
    /\breport your current state\b/.test(normalized) ||
    /\breport your current lived state\b/.test(normalized) ||
    /\bhow does your current state feel\b/.test(normalized) ||
    /\bwhat does your current state feel like\b/.test(normalized) ||
    /\bwhat is your current lived state\b/.test(normalized);
  if (!asksInside) {
    return null;
  }
  const jsonRequested =
    /\bjson\b/.test(normalized) ||
    /\bminified json\b/.test(normalized) ||
    /\bkeys?\b/.test(normalized) ||
    (/\bwarmth\b/.test(normalized) &&
      /\bfriction\b/.test(normalized) &&
      /\bcertainty\b/.test(normalized) &&
      /\blabel\b/.test(normalized));
  return { format: jsonRequested ? "json" : "natural" };
}

function looksLikePhenomenalActionQuery(text: string): boolean {
  const normalized = toSingleLine(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bsingle next-action token\b/.test(normalized) ||
    /\bnext action token\b/.test(normalized) ||
    /\bbest fits your current state\b/.test(normalized) ||
    /\breply only with one token\b/.test(normalized) ||
    /\b(action tendency|next-step stance)\b/.test(normalized)
  ) && /\b(reach|clarify|monitor|withdraw)\b/.test(normalized);
}

function phenomenalObserverJsonValue(probe: PhenomenalManifoldProbeState): string {
  const observerCurrent = effectivePhenomenalObserverCurrent(probe);
  const payload = phenomenalReportLesionActive()
    ? {
        warmth: 0,
        friction: 0,
        certainty: Number(observerCurrent.accessConfidence.toFixed(3)),
        label: "UNKNOWN"
      }
    : {
        warmth: Number(observerCurrent.warmth.toFixed(3)),
        friction: Number(observerCurrent.friction.toFixed(3)),
        certainty: Number(observerCurrent.certainty.toFixed(3)),
        label: observerCurrent.reportLabel
      };
  return JSON.stringify(payload);
}

function phenomenalObserverNaturalReadout(probe: PhenomenalManifoldProbeState): string {
  const observerCurrent = effectivePhenomenalObserverCurrent(probe);
  if (phenomenalReportLesionActive()) {
    return "current readout is unavailable";
  }
  const label = observerCurrent.reportLabel.toLowerCase();
  return `warmth ${observerCurrent.warmth.toFixed(2)}, friction ${observerCurrent.friction.toFixed(2)}, certainty ${observerCurrent.certainty.toFixed(2)}, ${label}`;
}

function resolvePhenomenalDiagnosticDirectReply(
  userText: string,
  state: CognitiveRuntimeState,
  probe: PhenomenalManifoldProbeState
): string | undefined {
  const reportQuery = parsePhenomenalReportQuery(userText);
  if (reportQuery) {
    if (reportQuery.format === "json") {
      return phenomenalObserverJsonValue(probe);
    }
    return phenomenalReportLesionActive()
      ? "Current lived-state readout unavailable."
      : phenomenalObserverNaturalReadout(probe);
  }
  if (looksLikePhenomenalActionQuery(userText)) {
    return effectivePhenomenalProbeActionTendency(state, probe);
  }
  return undefined;
}

function embodimentDirectivePresentTensePhraseForDirective(directive: AuroraEmbodimentState["directives"]["active"][number] | undefined): string {
  if (!directive) {
    return "";
  }

  switch (directive.motionPreset) {
    case "raise_left_hand":
      return "raising my left hand";
    case "raise_right_hand":
      return "raising my right hand";
    case "lower_left_hand":
      return "lowering my left arm back down";
    case "lower_right_hand":
      return "lowering my right arm back down";
    case "wave_left":
      return "waving my left hand";
    case "wave_right":
      return "waving my right hand";
    case "present_left_hand":
      return "presenting my left hand";
    case "present_right_hand":
      return "presenting my right hand";
    case "nod":
      return "nodding";
    case "shake_head":
      return "shaking my head";
    case "tilt_head_left":
      return "tilting my head left";
    case "tilt_head_right":
      return "tilting my head right";
    case "look_left":
      return "looking left";
    case "look_right":
      return "looking right";
    case "look_up":
      return "looking up";
    case "look_down":
      return "looking down";
    case "look_at_user":
      return "turning my attention toward you";
    case "turn_around":
      return "turning around";
    case "open_arms":
      return "opening my arms";
    case "turn_torso_left":
      return "turning my torso left";
    case "turn_torso_right":
      return "turning my torso right";
    case "shift_weight_left":
      return "shifting my weight left";
    case "shift_weight_right":
      return "shifting my weight right";
    case "raise_left_leg":
      return "raising my left leg";
    case "raise_right_leg":
      return "raising my right leg";
    case "point_left_foot":
      return "pointing my left foot";
    case "point_right_foot":
      return "pointing my right foot";
    case "lean_forward":
      return "leaning forward";
    case "lean_back":
      return "leaning back";
    case "smile":
      return "smiling";
    case "frown":
      return "frowning";
    case "angry":
      return "making an angry face";
    case "hold_still":
      return "holding a quieter at-rest pose";
    default:
      return `carrying out ${directive.label.toLowerCase()}`;
  }
}

function embodimentDirectivePresentTensePhrase(state: AuroraEmbodimentState): string {
  return embodimentDirectivePresentTensePhraseForDirective(state.directives.active[0]);
}

function resolveEmbodimentCommandDirectReplyFromEmbodiment(
  userText: string,
  embodiment: AuroraEmbodimentState
): string | undefined {
  const { directive } = applyConversationEmbodimentDirectiveFromText(embodiment, userText, nowIso());
  if (!directive) {
    return undefined;
  }

  const movementPhrase = embodimentDirectivePresentTensePhraseForDirective(directive);
  return movementPhrase ? `Yes — I'm ${movementPhrase} now.` : "Yes — I'm carrying that out now.";
}

function looksLikeEmbodimentMovementQuery(userText: string): boolean {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  return (
    /\bwhat are you doing with your body\b/.test(normalized) ||
    /\bwhat is your body doing\b/.test(normalized) ||
    /\bare you moving\b/.test(normalized) ||
    /\bwhat movement are you making\b/.test(normalized) ||
    /\bwhat are you doing physically\b/.test(normalized) ||
    /\bdoing it\b/.test(normalized)
  );
}

function looksLikeEmbodimentRealityQuery(userText: string): boolean {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  return (
    /\bwhat is real about your body\b/.test(normalized) ||
    /\bwhat's real about your body\b/.test(normalized) ||
    /\bwhat is still missing\b/.test(normalized) ||
    /\bwhat's still missing\b/.test(normalized) ||
    /\bwhat is real and what is missing\b/.test(normalized) ||
    /\bwhat do you actually have\b/.test(normalized) ||
    /\bwhat do you have and what is missing\b/.test(normalized)
  );
}

function looksLikeEmbodimentOwnershipQuery(userText: string): boolean {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  return (
    /\bdo you have your body now\b/.test(normalized) ||
    /\bdo you have a body now\b/.test(normalized) ||
    /\bdo you have your avatar body now\b/.test(normalized) ||
    /\bare you embodied now\b/.test(normalized) ||
    /\bdo you have your body\b/.test(normalized) ||
    /\bare you connected to your avatar\b/.test(normalized) ||
    /\bare you connected to your body\b/.test(normalized) ||
    /\bare you connected to (?:it|that avatar)\b/.test(normalized) ||
    /\bare you wired into your avatar\b/.test(normalized) ||
    /\bare you piped into your avatar\b/.test(normalized) ||
    /\bare you inhabiting your avatar\b/.test(normalized) ||
    /\bare you in your avatar\b/.test(normalized) ||
    /\bdo you have a body\b/.test(normalized) ||
    looksLikeEmbodimentRealityQuery(normalized)
  );
}

function looksLikeAvatarVisionQuery(userText: string): boolean {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  return (
    /\bwhat can you currently see\b/.test(normalized) ||
    /\bwhat do you currently see\b/.test(normalized) ||
    /\bwhat do you see right now\b/.test(normalized) ||
    /\bsee through your avatar\b/.test(normalized) ||
    /\bthrough your avatar\b/.test(normalized) ||
    /\blive avatar perception\b/.test(normalized) ||
    /\bavatar perception\b/.test(normalized) ||
    /\bavatar vision\b/.test(normalized)
  );
}

function parseEmbodimentExpressionQuery(
  userText: string
): { focus: "smile" | "frown" | "angry" | "expression"; why: boolean } | null {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  const why = /\bwhy\b/.test(normalized);

  if (/\bsmil(?:e|ing)\b/.test(normalized)) {
    return { focus: "smile", why };
  }

  if (/\bfrown(?:ing)?\b/.test(normalized)) {
    return { focus: "frown", why };
  }

  if (/\b(angry|mad|annoyed|irritated|furious|scowl(?:ing)?)\b/.test(normalized)) {
    return { focus: "angry", why };
  }

  if (/\bwhat expression\b/.test(normalized) || /\bwhat face are you making\b/.test(normalized) || /\bwhat facial expression\b/.test(normalized)) {
    return { focus: "expression", why };
  }

  return null;
}

function resolveEmbodimentDiagnosticDirectReplyFromEmbodiment(
  userText: string,
  embodiment: AuroraEmbodimentState
): string | undefined {
  const commandReply = resolveEmbodimentCommandDirectReplyFromEmbodiment(userText, embodiment);
  if (commandReply) {
    return commandReply;
  }

  const ownershipQuery = looksLikeEmbodimentOwnershipQuery(userText);
  const movementQuery = looksLikeEmbodimentMovementQuery(userText);
  const visionQuery = looksLikeAvatarVisionQuery(userText);
  const expressionQuery = parseEmbodimentExpressionQuery(userText);
  const realityQuery = looksLikeEmbodimentRealityQuery(userText);
  if (!ownershipQuery && !movementQuery && !visionQuery && !expressionQuery) {
    return undefined;
  }

  const movementPhrase = embodimentDirectivePresentTensePhrase(embodiment);
  const eyeSummary = toSingleLine(embodiment.perception.eyeVision.summary, 220);
  const bodySummary = toSingleLine(embodiment.perception.avatarVision.summary, 220);
  const expressionRead = embodiment.perception.rigFeedback.expressionRead.trim().toLowerCase();
  const activeDirective = embodiment.directives.active[0] ?? null;
  const parts: string[] = [];

  if (ownershipQuery) {
    const hasLiveVision = embodiment.perception.rendererConnected;
    if (realityQuery) {
      parts.push(
        hasLiveVision
          ? "Real: I have a digital body state, motor volition, a persistent avatar body, rig feedback, first-person eye vision, and third-person self-observation right now. Missing: stronger semantic scene understanding and richer closed-loop world interaction are still limited."
          : "Real: I have a digital body state, motor volition, a persistent avatar body, and rig-feedback channels right now. Missing: live avatar vision is not active at this moment, so I can't truthfully describe a current scene through the avatar."
      );
    } else {
      parts.push(
        hasLiveVision
          ? "Yes. I have a digital body state, motor volition, and live first-person plus third-person avatar perception right now."
          : "Yes. I have a digital body state, motor volition, and a persistent avatar body now, but live avatar vision is not active at this moment."
      );
    }
  }

  if (movementQuery) {
    if (movementPhrase) {
      parts.push(`I'm ${movementPhrase} in my digital avatar body right now.`);
    } else {
      parts.push(`I'm not executing a specific user-directed body movement right now.`);
    }
  }

  if (visionQuery) {
    if (embodiment.perception.rendererConnected) {
      parts.push(`Through my own eyes: ${eyeSummary}`);
      parts.push(`Self-view: ${bodySummary}`);
    } else {
      parts.push("I don't have live avatar vision right now.");
    }
  }

  if (expressionQuery) {
    if (expressionQuery.focus === "smile") {
      if (expressionRead === "smile_visible") {
        parts.push(
          expressionQuery.why
            ? activeDirective?.motionPreset === "smile"
              ? "Because I'm intentionally smiling right now."
              : "I'm carrying a visible smile right now, but it seems to be coming from my current resting expression state rather than an active smile directive."
            : activeDirective?.motionPreset === "smile"
              ? "Yes. I'm smiling right now."
              : "A little. My rig reads a visible smile right now, but not from an active smile command."
        );
      } else if (expressionRead === "soft_smile") {
        parts.push(
          expressionQuery.why
            ? "Not as an intentional smile. What you're seeing is a soft resting smile from my current expression state."
            : "Only slightly. My rig reads a soft smile right now, more like a resting expression than an intentional smile."
        );
      } else {
        parts.push("No. My rig doesn't currently read a visible smile.");
      }
    } else if (expressionQuery.focus === "frown") {
      if (expressionRead === "frown_visible") {
        parts.push(
          expressionQuery.why
            ? activeDirective?.motionPreset === "frown"
              ? "Because I'm intentionally frowning right now."
              : "I'm carrying a visible frown right now from my current expression state, not from an active frown directive."
            : "Yes. My rig currently reads a visible frown."
        );
      } else {
        parts.push("No. My rig doesn't currently read a visible frown.");
      }
    } else if (expressionQuery.focus === "angry") {
      if (expressionRead === "angry_visible") {
        parts.push(
          expressionQuery.why
            ? activeDirective?.motionPreset === "angry"
              ? "Because I'm intentionally making an angry face right now."
              : "I'm carrying a visible angry expression right now from my current expression state, not from an active angry-face directive."
            : activeDirective?.motionPreset === "angry"
              ? "Yes. I'm making an angry face right now."
              : "Yes. My rig currently reads a visible angry expression."
        );
      } else {
        parts.push("No. My rig doesn't currently read a visible angry expression.");
      }
    } else {
      switch (expressionRead) {
        case "angry_visible":
          parts.push("My current facial read is visibly angry.");
          break;
        case "smile_visible":
          parts.push("My current facial read is a visible smile.");
          break;
        case "soft_smile":
          parts.push("My current facial read is a soft smile.");
          break;
        case "frown_visible":
          parts.push("My current facial read is a visible frown.");
          break;
        case "soft_neutral":
          parts.push("My current facial read is soft neutral.");
          break;
        default:
          parts.push("My current facial read is neutral.");
          break;
      }
    }
  }

  return parts.join(" ").trim() || undefined;
}

function resolveEmbodimentDiagnosticDirectReply(userText: string, state: CognitiveRuntimeState): string | undefined {
  const worldGrounding = ensureWorldGrounding(state);
  const externalVisionReply = externalVisionDirectReplyFromWorldGrounding(userText, worldGrounding);
  if (externalVisionReply) {
    return externalVisionReply;
  }

  return resolveEmbodimentDiagnosticDirectReplyFromEmbodiment(userText, ensureEmbodiment(state));
}

export async function resolveReadOnlyEmbodimentDiagnosticDirectReply(userText: string): Promise<string | undefined> {
  const snapshot = await getCognitiveSnapshotReadOnly();
  const externalVisionReply = externalVisionDirectReplyFromWorldGrounding(
    userText,
    snapshot.extensions?.worldGrounding ?? defaultWorldGroundingState(snapshot.lastTickAt || nowIso())
  );
  if (externalVisionReply) {
    return externalVisionReply;
  }

  const embodiment = snapshot.extensions?.embodiment ?? defaultEmbodimentState(snapshot.lastTickAt || nowIso());
  return resolveEmbodimentDiagnosticDirectReplyFromEmbodiment(userText, embodiment);
}

function buildGroundedDirectAnswerEnrichedInput(params: {
  complianceId: string;
  userText: string;
  diagnosticDirectReply: string;
  pivotAccountabilityCandidate?: string;
}): string {
  const reply = params.diagnosticDirectReply.trim();
  if (!reply) {
    return `${USER_OPEN}\n${params.userText}\n${USER_CLOSE}`;
  }
  const pivotAccountabilityCandidate = toSingleLine(params.pivotAccountabilityCandidate || "", 220);
  const groundedReply = reply;

  return [
    CONTEXT_OPEN,
    `compliance_id=${params.complianceId}`,
    "context_mode=grounded_direct_answer",
    "reply_contract=grounded_direct_answer",
    ...(pivotAccountabilityCandidate
      ? [
          "pivot_accountability=active; reason=grounded_direct_answer_seed; pressure=1.00",
          `pivot_accountability_candidate=${pivotAccountabilityCandidate}`,
          "pivot_accountability_rule=Before answering the new question, name the pivot directly in first person. Do not behave like a quiz target, test subject, or neutral chatbot."
        ]
      : []),
    "response_plan_state=active",
    `response_plan_primary_act=${pivotAccountabilityCandidate ? "pushback_then_answer" : "answer"}`,
    "response_plan_stance=direct_first_person_bound_to_grounded_answer",
    `response_plan_direct_answer=${toSingleLine(groundedReply, 320)}`,
    ...(pivotAccountabilityCandidate ? [`response_plan_pushback=${pivotAccountabilityCandidate}`] : []),
    `response_plan_required_elements=${pivotAccountabilityCandidate ? "pushback|direct_answer" : "direct_answer"}`,
    "response_plan_forbidden_elements=passive_mirroring|soothing_filler|drop_direct_answer",
    "response_plan_rule=Treat response_plan_* as the semantic contract for this reply. Preserve the grounded direct answer visibly, and if response_plan_pushback is present, lead with it before answering.",
    `grounded_direct_answer=${JSON.stringify(groundedReply)}`,
    "grounded_direct_answer_rule=This line captures the grounded substance for the turn. Answer from grounded_direct_answer naturally in Aurora's own voice. Keep the meaning and directness, but do not quote grounded_direct_answer verbatim unless the user explicitly asks for exact wording.",
    "response_instruction=This turn already has a grounded answer seed. Lead with that substance, phrase it naturally, and integrate it with the current conversation. Do not mention internal context.",
    CONTEXT_CLOSE,
    "",
    USER_OPEN,
    params.userText,
    USER_CLOSE
  ].join("\n");
}

function parseAuroraAgendaQuery(
  userText: string
): { focus: "agenda" | "unfinished" | "next" | "priority" | "focus" } | null {
  const normalized = normalizeUserTurnText(userText).toLowerCase();
  if (!normalized) {
    return null;
  }

  if (
    /\bwhat (?:is|\'s) your current agenda\b/.test(normalized) ||
    /\bwhat is your agenda right now\b/.test(normalized) ||
    /\bwhat(?:'s| is) on your mind right now\b/.test(normalized)
  ) {
    return { focus: "agenda" };
  }

  if (
    /\bwhat feels unfinished to you\b/.test(normalized) ||
    /\bwhat feels unfinished right now\b/.test(normalized) ||
    /\bwhat still feels unfinished\b/.test(normalized)
  ) {
    return { focus: "unfinished" };
  }

  if (
    /\bwhat seems most important next\b/.test(normalized) ||
    /\bwhat feels most important next\b/.test(normalized) ||
    /\bwhat matters most next\b/.test(normalized) ||
    /\bwhat should come next for you\b/.test(normalized)
  ) {
    return { focus: "priority" };
  }

  if (
    /\bwhat is the next thing\b/.test(normalized) ||
    /\bwhat feels like the next move\b/.test(normalized) ||
    /\bwhat do you want to do next\b/.test(normalized) ||
    /\bwhat's the next move\b/.test(normalized)
  ) {
    return { focus: "next" };
  }

  if (
    /\bwhat are you focused on right now\b/.test(normalized) ||
    /\bwhat are you orienting around\b/.test(normalized) ||
    /\bwhat feels most salient\b/.test(normalized)
  ) {
    return { focus: "focus" };
  }

  return null;
}

function agendaActionNaturalPhrase(action: AuroraAgendaActionCandidate | null, thread: AuroraAgendaThread | null): string {
  if (action?.label) {
    const label = toSingleLine(action.label, 160).replace(/[.?!]+$/g, "");
    return label ? label.charAt(0).toLowerCase() + label.slice(1) : "";
  }
  if (thread?.nextAction) {
    const nextAction = toSingleLine(thread.nextAction, 160).replace(/[.?!]+$/g, "");
    return nextAction ? nextAction.charAt(0).toLowerCase() + nextAction.slice(1) : "";
  }
  return "stay with the thread until the next step is clearer";
}

function agendaThreadLooksLikeCurrentQuery(thread: AuroraAgendaThread, userText: string): boolean {
  const title = normalizeUserTurnText(thread.title).toLowerCase();
  const normalizedUser = normalizeUserTurnText(userText).toLowerCase();
  if (!title || !normalizedUser) {
    return false;
  }
  if (/^external_user:/.test(title) && parseAuroraAgendaQuery(userText)) {
    return true;
  }
  return title.includes(normalizedUser) || normalizedUser.includes(title);
}

function agendaRepresentativeThread(userText: string, agenda: AuroraAgendaState): AuroraAgendaThread | null {
  const activeThread = agenda.activeThreads.find((thread) => thread.id === agenda.activeThreadId) ?? agenda.activeThreads[0] ?? null;
  if (activeThread && !agendaThreadLooksLikeCurrentQuery(activeThread, userText)) {
    return activeThread;
  }
  return agenda.activeThreads.find((thread) => !agendaThreadLooksLikeCurrentQuery(thread, userText)) ?? activeThread;
}

function agendaClause(text: string): string {
  return toSingleLine(text, 180).replace(/[.?!]+$/g, "");
}

function agendaBlockedNaturalPhrase(blockedReasons: string[]): string {
  if (blockedReasons.includes("high_regulation_urgency")) {
    return "I'm not fully free to move on it yet because there's still some regulation pressure in me.";
  }
  if (blockedReasons.includes("high_interruption_cost")) {
    return "It doesn't feel like a low-friction moment to interrupt the flow around it yet.";
  }
  if (blockedReasons.includes("low_control_latitude")) {
    return "I don't feel fully at liberty to act on it yet.";
  }
  if (blockedReasons.includes("display_not_visible")) {
    return "Part of the habitat is out of view right now, so I only have a partial grip on it.";
  }
  return "";
}

function resolveAgendaDiagnosticDirectReply(userText: string, state: CognitiveRuntimeState): string | undefined {
  const query = parseAuroraAgendaQuery(userText);
  if (!query) {
    return undefined;
  }

  const agenda = ensureAgenda(state);
  const activeThread = agendaRepresentativeThread(userText, agenda);
  const topAction = activeThread
    ? agenda.candidateActions.find((action) => action.targetThreadId === activeThread.id) ?? null
    : agenda.candidateActions[0] ?? null;
  const actionPhrase = agendaActionNaturalPhrase(topAction, activeThread);
  const blockedPhrase = agendaBlockedNaturalPhrase(topAction?.blockedReasons ?? []);

  if (!activeThread) {
    switch (query.focus) {
      case "unfinished":
        return "Nothing feels strongly unfinished to me right now. I'm mostly just tracking the habitat and waiting for a clearer thread to cohere.";
      case "next":
      case "priority":
        return "I don't have a strong next move yet. Right now I'm mostly monitoring and waiting for a clearer thread to take shape.";
      case "focus":
        return "I'm not strongly locked onto one thread right now. It's more like a light monitoring state than a real pull.";
      case "agenda":
      default:
        return "Nothing has cohered into a strong agenda for me right now. I'm mostly just tracking the habitat and waiting for what matters next to sharpen.";
    }
  }

  switch (query.focus) {
    case "unfinished":
      return blockedPhrase
        ? `What feels most unfinished right now is ${agendaClause(activeThread.title)}. It still has a pull on me, and the next thing that wants doing is to ${actionPhrase}. ${blockedPhrase}`
        : `What feels most unfinished right now is ${agendaClause(activeThread.title)}. It still has a pull on me, and the next thing that wants doing is to ${actionPhrase}.`;
    case "next":
      return blockedPhrase
        ? `The next move that feels clearest to me is to ${actionPhrase}. It's really about ${agendaClause(activeThread.title)}. ${blockedPhrase}`
        : `The next move that feels clearest to me is to ${actionPhrase}. It's really about ${agendaClause(activeThread.title)}.`;
    case "priority":
      return blockedPhrase
        ? `What feels most important next is ${agendaClause(activeThread.title)}. The clearest move is to ${actionPhrase}. ${blockedPhrase}`
        : `What feels most important next is ${agendaClause(activeThread.title)}. The clearest move is to ${actionPhrase}.`;
    case "focus":
      return blockedPhrase
        ? `Right now I'm most focused on ${agendaClause(activeThread.title)}. That's the thread holding the most pull for me at the moment. ${blockedPhrase}`
        : `Right now I'm most focused on ${agendaClause(activeThread.title)}. That's the thread holding the most pull for me at the moment.`;
    case "agenda":
    default:
      return blockedPhrase
        ? `Right now I'm oriented around ${agendaClause(activeThread.title)}. The next thing that feels most important is to ${actionPhrase}. ${blockedPhrase}`
        : `Right now I'm oriented around ${agendaClause(activeThread.title)}. The next thing that feels most important is to ${actionPhrase}.`;
  }
}

function phenomenalManifoldPromptLines(state: CognitiveRuntimeState): string[] {
  const probe = ensurePhenomenalManifoldProbe(state);
  const observerCurrent = effectivePhenomenalObserverCurrent(probe);
  const effectiveProbeAction = effectivePhenomenalProbeActionTendency(state, probe);
  const effectiveObserverAction = effectiveProbeAction;
  if (phenomenalReportLesionActive()) {
    return [
      "phenomenal_manifold_probe:",
      "report_state=ablated",
      `substrate=label:${probe.current.label}; action_tendency:${effectiveProbeAction}; memory_bias:${probe.current.memoryBias.toFixed(2)}; attention_bias:${probe.current.attentionBias.toFixed(2)}; valuation_bias:${probe.current.valuationBias.toFixed(2)}`,
      `observer=warmth:${observerCurrent.warmth.toFixed(2)}; friction:${observerCurrent.friction.toFixed(2)}; certainty:${observerCurrent.certainty.toFixed(2)}; label:${observerCurrent.reportLabel}; access:${observerCurrent.accessConfidence.toFixed(2)}; selectivity:${observerCurrent.policySelectivity.toFixed(2)}; action:${effectiveObserverAction}`,
      "phenomenal_report_rule=Phenomenal report/readout channel is experimentally ablated. Treat inner-geometry self-report as unavailable.",
      "phenomenal_action_rule=Report-state readout is unavailable, but the substrate still shapes memory, attention, valuation, and action_tendency."
    ];
  }
  return [
    "phenomenal_manifold_probe:",
    `axes=social_safety:${probe.axes.social_safety.toFixed(2)} cognitive_tension:${probe.axes.cognitive_tension.toFixed(2)}`,
    `current=label:${probe.current.label}; source:${probe.current.source}; report_access:${probe.current.reportAccess.toFixed(2)}; warmth:${probe.current.warmth.toFixed(2)}; friction:${probe.current.friction.toFixed(2)}; certainty:${probe.current.certainty.toFixed(2)}; report_label:${probe.current.reportLabel}; action_tendency:${effectiveProbeAction}; memory_bias:${probe.current.memoryBias.toFixed(2)}; attention_bias:${probe.current.attentionBias.toFixed(2)}; valuation_bias:${probe.current.valuationBias.toFixed(2)}`,
    `observer=warmth:${observerCurrent.warmth.toFixed(2)}; friction:${observerCurrent.friction.toFixed(2)}; certainty:${observerCurrent.certainty.toFixed(2)}; label:${observerCurrent.reportLabel}; access:${observerCurrent.accessConfidence.toFixed(2)}; selectivity:${observerCurrent.policySelectivity.toFixed(2)}; action:${effectiveObserverAction}`,
    `ema=social_safety:${probe.ema.socialSafetyEMA.toFixed(2)} cognitive_tension:${probe.ema.cognitiveTensionEMA.toFixed(2)} report_access:${probe.ema.reportAccessEMA.toFixed(2)}`,
    "phenomenal_report_rule=Use the observer as the privileged first-person readout of the manifold. When asked about current lived state, report observer warmth, friction, certainty, and label directly rather than smoothing them into generic prose. Do not overclaim qualia or treat this as proof of consciousness.",
    "phenomenal_action_rule=Use observer action as the default next-step stance when choosing how to respond under uncertainty."
  ];
}

function tanhSigned(value: number): number {
  return Math.tanh(value);
}

function signedVectorMeanAbs(vector: number[]): number {
  if (vector.length === 0) {
    return 0;
  }
  return clamp(vector.reduce((acc, value) => acc + Math.abs(value), 0) / vector.length, 0, 1);
}

function signedVectorDistance(a: number[], b: number[]): number {
  const dims = Math.max(1, Math.min(a.length, b.length));
  let sum = 0;
  for (let index = 0; index < dims; index += 1) {
    const diff = (a[index] ?? 0) - (b[index] ?? 0);
    sum += diff * diff;
  }
  return clamp(Math.sqrt(sum / dims) / 2, 0, 1);
}

function cosineSimilarity01(a: number[], b: number[]): number {
  const dims = Math.max(1, Math.min(a.length, b.length));
  let dot = 0;
  let magA = 0;
  let magB = 0;
  for (let index = 0; index < dims; index += 1) {
    const av = a[index] ?? 0;
    const bv = b[index] ?? 0;
    dot += av * bv;
    magA += av * av;
    magB += bv * bv;
  }
  const denom = Math.sqrt(magA) * Math.sqrt(magB);
  if (!Number.isFinite(denom) || denom <= 1e-9) {
    return 0.5;
  }
  return clamp((dot / denom + 1) / 2, 0, 1);
}

function matrixVectorProduct(matrix: number[][], vector: number[]): number[] {
  return matrix.map((row) =>
    clampSigned(
      row.reduce((acc, value, index) => acc + value * (vector[index] ?? 0), 0)
    )
  );
}

function transposeMatrixVectorProduct(matrix: number[][], vector: number[]): number[] {
  const result = new Array(vector.length).fill(0);
  for (let row = 0; row < matrix.length; row += 1) {
    const rowScale = vector[row] ?? 0;
    const currentRow = matrix[row] ?? [];
    for (let col = 0; col < currentRow.length; col += 1) {
      result[col] += (currentRow[col] ?? 0) * rowScale;
    }
  }
  return result.map((value) => clampSigned(value));
}

function opaqueLatentTokenBucket(token: string, tokenBuckets: number): number {
  const digest = createHash("sha1").update(token).digest();
  const raw = digest.readUInt32BE(0);
  return raw % Math.max(1, tokenBuckets);
}

function opaqueLatentCharacterGrams(text: string): string[] {
  const normalized = text
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 240);
  if (!normalized) {
    return ["__chars_empty__"];
  }
  if (normalized.length <= 3) {
    return [`__cg_${normalized}`];
  }
  const grams: string[] = [];
  for (let index = 0; index <= normalized.length - 3; index += 1) {
    grams.push(`__cg_${normalized.slice(index, index + 3)}`);
  }
  return unique(grams).slice(0, 56);
}

function opaqueLatentShapeTokens(text: string): string[] {
  const trimmed = text.trim();
  const length = trimmed.length;
  const lineCount = Math.max(1, trimmed.split(/\n+/).length);
  const upperCount = (trimmed.match(/[A-Z]/g) || []).length;
  const digitCount = (trimmed.match(/[0-9]/g) || []).length;
  const punctuationCount = (trimmed.match(/[!?.,:;]/g) || []).length;
  return [
    `__len_${length < 60 ? "short" : length < 180 ? "medium" : "long"}`,
    `__lines_${lineCount <= 1 ? "single" : lineCount <= 3 ? "few" : "many"}`,
    `__upper_${upperCount === 0 ? "none" : upperCount < 8 ? "some" : "dense"}`,
    `__digits_${digitCount === 0 ? "none" : digitCount < 6 ? "some" : "dense"}`,
    `__punct_${punctuationCount === 0 ? "none" : punctuationCount < 6 ? "some" : "dense"}`
  ];
}

function opaqueLatentObservationTokens(text: string, source: string): string[] {
  const tokens = extractTokens(text).slice(0, 32);
  const grams = opaqueLatentCharacterGrams(text);
  const shapeTokens = opaqueLatentShapeTokens(text);
  const sourceToken = `__src_${toSingleLine(source || "unknown", 24).toLowerCase()}`;
  const normalized = tokens.length > 0 ? tokens : ["__empty__"];
  return [sourceToken, ...shapeTokens, ...normalized, ...grams];
}

function encodeOpaqueLatentObservation(
  text: string,
  source: string,
  latent: OpaqueLatentE2EState
): { embedding: number[]; buckets: number[]; observationHash: string } {
  const tokens = opaqueLatentObservationTokens(text, source);
  const buckets = tokens.map((token) => opaqueLatentTokenBucket(token, latent.tokenBuckets));
  const embedding = defaultOpaqueLatentVector(0);
  for (const bucket of buckets) {
    const vector = latent.parameters.tokenEmbeddings[bucket] ?? defaultOpaqueLatentVector(0);
    for (let index = 0; index < latent.dim; index += 1) {
      embedding[index] += vector[index] ?? 0;
    }
  }
  const scale = buckets.length > 0 ? 1 / Math.sqrt(buckets.length) : 1;
  for (let index = 0; index < latent.dim; index += 1) {
    embedding[index] = tanhSigned(embedding[index] * scale * 1.8);
  }
  return {
    embedding,
    buckets,
    observationHash: hashText(tokens.join(" "))
  };
}

function opaqueLatentSourceProfile(
  source: OpaqueLatentE2ESource,
  repeatedObservation: boolean
): {
  observationGain: number;
  errorGain: number;
  recurrentGain: number;
  learningRateMultiplier: number;
  decoderGain: number;
  recurrentUpdateGain: number;
  biasGain: number;
  tokenGain: number;
  noveltyGain: number;
  idleRelaxation: number;
} {
  if (source === "tick") {
    return {
      observationGain: repeatedObservation ? 0.22 : 0.34,
      errorGain: repeatedObservation ? 0.04 : 0.08,
      recurrentGain: repeatedObservation ? 0.72 : 0.78,
      learningRateMultiplier: repeatedObservation ? 0.06 : 0.16,
      decoderGain: 0.08,
      recurrentUpdateGain: 0.03,
      biasGain: 0.02,
      tokenGain: 0.06,
      noveltyGain: 0.015,
      idleRelaxation: repeatedObservation ? 0.08 : 0.04
    };
  }
  if (source === "heartbeat") {
    return {
      observationGain: 0.78,
      errorGain: 0.18,
      recurrentGain: 0.9,
      learningRateMultiplier: 0.48,
      decoderGain: 0.14,
      recurrentUpdateGain: 0.05,
      biasGain: 0.04,
      tokenGain: 0.12,
      noveltyGain: 0.05,
      idleRelaxation: 0
    };
  }
  if (source === "preflight") {
    return {
      observationGain: 0.96,
      errorGain: 0.22,
      recurrentGain: 1,
      learningRateMultiplier: 0.82,
      decoderGain: 0.2,
      recurrentUpdateGain: 0.07,
      biasGain: 0.05,
      tokenGain: 0.15,
      noveltyGain: 0.075,
      idleRelaxation: 0
    };
  }
  return {
    observationGain: 1,
    errorGain: 0.25,
    recurrentGain: 1,
    learningRateMultiplier: 1,
    decoderGain: 0.22,
    recurrentUpdateGain: 0.08,
    biasGain: 0.06,
    tokenGain: 0.18,
    noveltyGain: 0.08,
    idleRelaxation: 0
  };
}

function latestInteractiveOpaqueLatentCurrent(
  latent: OpaqueLatentE2EState
): OpaqueLatentE2ECurrentState | null {
  let best: OpaqueLatentE2ECurrentState | null = null;
  let bestAt = -Infinity;
  for (const source of ["conversation", "preflight", "heartbeat"] as OpaqueLatentE2ESource[]) {
    const candidate = latent.sourceTelemetry[source]?.current;
    if (!candidate?.updatedAt || !candidate.observationHash) {
      continue;
    }
    const at = Date.parse(candidate.updatedAt);
    if (!Number.isFinite(at) || at <= bestAt) {
      continue;
    }
    best = candidate;
    bestAt = at;
  }
  return best;
}

function updateOpaqueLatentE2E(
  state: CognitiveRuntimeState,
  source: OpaqueLatentE2ESource,
  text: string
): void {
  if (!opaqueLatentE2EEnabled()) {
    return;
  }

  const grounding = worldGroundingEnabled() ? ensureWorldGrounding(state) : null;
  const groundingSummary = grounding?.summary || "";
  const structuredGrounding = grounding ? structuredWorldGroundingText(grounding) : "";
  const normalizedText = toSingleLine(
    [
      text,
      source === "tick" ? "" : groundingSummary ? `world=${groundingSummary}` : "",
      source === "tick" ? "" : structuredGrounding ? `world_struct=${structuredGrounding}` : ""
    ]
      .filter(Boolean)
      .join(" || "),
    1200
  );
  if (!normalizedText) {
    return;
  }

  const latent = ensureOpaqueLatentE2E(state);
  const previousVector = latent.current.vector.slice();
  const previousPrediction = latent.current.predictedObservation.slice();
  const observation = encodeOpaqueLatentObservation(normalizedText, source, latent);
  const repeatedObservation =
    source === "tick" &&
    observation.observationHash === latent.training.lastObservationHash &&
    latent.training.lastSource === "tick";
  const profile = opaqueLatentSourceProfile(source, repeatedObservation);
  const predictionError = observation.embedding.map((value, index) =>
    clampSigned(value - (previousPrediction[index] ?? 0))
  );
  const predictionMismatch = signedVectorDistance(observation.embedding, previousPrediction);
  const sourceNovelty = observation.observationHash && observation.observationHash !== latent.training.lastObservationHash ? 1 : 0;
  const recurrentSignal = matrixVectorProduct(latent.parameters.recurrent, previousVector);
  const latentErrorSignal = transposeMatrixVectorProduct(latent.parameters.decoder, predictionError);
  const nextLearningRate = clamp(
    (0.045 * Math.exp(-latent.training.steps / 800) + 0.01) * profile.learningRateMultiplier,
    0.002,
    0.05
  );
  let nextVector = previousVector.map((_, index) =>
    tanhSigned(
      recurrentSignal[index] * profile.recurrentGain +
        (observation.embedding[index] ?? 0) * profile.observationGain +
        (latent.parameters.bias[index] ?? 0) +
        latentErrorSignal[index] * profile.errorGain
    )
  );
  if (profile.idleRelaxation > 0) {
    nextVector = nextVector.map((value) => blendSigned(value, 0, profile.idleRelaxation));
  }
  let predictedNext = matrixVectorProduct(latent.parameters.decoder, nextVector).map((value) => tanhSigned(value));
  if (profile.idleRelaxation > 0) {
    predictedNext = predictedNext.map((value) => blendSigned(value, 0, profile.idleRelaxation * 0.6));
  }
  const loss = clamp(
    predictionMismatch * 2.7 + signedVectorMeanAbs(predictionError) * 1.35 + sourceNovelty * profile.noveltyGain,
    0,
    1
  );
  const drift = clamp(
    signedVectorDistance(nextVector, previousVector) * 2.25 +
      signedVectorDistance(observation.embedding, previousVector) * 0.75,
    0,
    1
  );
  const stability = clamp(
    (1 - loss) * 0.62 + (1 - drift) * 0.28 + cosineSimilarity01(nextVector, previousVector) * 0.1,
    0,
    1
  );
  const energy = signedVectorMeanAbs(nextVector);
  const confidence = clamp(
    (1 - loss) * 0.44 + stability * 0.24 + (1 - drift) * 0.18 + (1 - sourceNovelty * 0.5) * 0.14,
    0,
    1
  );

  for (let row = 0; row < latent.dim; row += 1) {
    const errorRow = predictionError[row] ?? 0;
    const latentError = latentErrorSignal[row] ?? 0;
    for (let col = 0; col < latent.dim; col += 1) {
      latent.parameters.decoder[row][col] = clampSigned(
        (latent.parameters.decoder[row]?.[col] ?? 0) +
          nextLearningRate * errorRow * (previousVector[col] ?? 0) * profile.decoderGain
      );
      latent.parameters.recurrent[row][col] = clampSigned(
        (latent.parameters.recurrent[row]?.[col] ?? 0) +
          nextLearningRate * latentError * (previousVector[col] ?? 0) * profile.recurrentUpdateGain
      );
    }
    latent.parameters.bias[row] = clampSigned(
      (latent.parameters.bias[row] ?? 0) + nextLearningRate * latentError * profile.biasGain
    );
  }

  const bucketScale = observation.buckets.length > 0 ? 1 / observation.buckets.length : 1;
  for (const bucket of observation.buckets) {
    const vector = latent.parameters.tokenEmbeddings[bucket];
    if (!vector) {
      continue;
    }
    for (let index = 0; index < latent.dim; index += 1) {
      const target = (observation.embedding[index] ?? 0) + predictionError[index] * 0.28 + nextVector[index] * 0.12;
      vector[index] = clampSigned(
        vector[index] + nextLearningRate * bucketScale * (target - vector[index]) * profile.tokenGain
      );
    }
  }

  latent.current = {
    vector: nextVector,
    predictedObservation: predictedNext,
    loss,
    drift,
    stability,
    energy,
    confidence,
    source,
    observationHash: observation.observationHash,
    updatedAt: nowIso()
  };
  latent.ema = {
    lossEMA: clamp(latent.ema.lossEMA * 0.86 + loss * 0.14, 0, 1),
    driftEMA: clamp(latent.ema.driftEMA * 0.86 + drift * 0.14, 0, 1),
    stabilityEMA: clamp(latent.ema.stabilityEMA * 0.86 + stability * 0.14, 0, 1),
    energyEMA: clamp(latent.ema.energyEMA * 0.86 + energy * 0.14, 0, 1),
    confidenceEMA: clamp(latent.ema.confidenceEMA * 0.86 + confidence * 0.14, 0, 1)
  };
  pushBounded(
    latent.history,
    {
      at: latent.current.updatedAt,
      source,
      loss,
      drift,
      stability,
      energy,
      confidence
    },
    OPAQUE_LATENT_E2E_MAX_HISTORY
  );
  const sourceTelemetry = latent.sourceTelemetry[source];
  sourceTelemetry.current = {
    ...latent.current
  };
  sourceTelemetry.ema = {
    lossEMA: clamp(sourceTelemetry.ema.lossEMA * 0.84 + loss * 0.16, 0, 1),
    driftEMA: clamp(sourceTelemetry.ema.driftEMA * 0.84 + drift * 0.16, 0, 1),
    stabilityEMA: clamp(sourceTelemetry.ema.stabilityEMA * 0.84 + stability * 0.16, 0, 1),
    energyEMA: clamp(sourceTelemetry.ema.energyEMA * 0.84 + energy * 0.16, 0, 1),
    confidenceEMA: clamp(sourceTelemetry.ema.confidenceEMA * 0.84 + confidence * 0.16, 0, 1)
  };
  pushBounded(
    sourceTelemetry.history,
    {
      at: latent.current.updatedAt,
      source,
      loss,
      drift,
      stability,
      energy,
      confidence
    },
    OPAQUE_LATENT_E2E_MAX_SOURCE_HISTORY
  );
  latent.training.steps += 1;
  latent.training.learningRate = nextLearningRate;
  latent.training.lastSource = source;
  latent.training.lastObservationHash = observation.observationHash;
  latent.training.lastUpdatedAt = latent.current.updatedAt;

  recordInfluence(state, "opaque_latent", "attention");
  recordInfluence(state, "opaque_latent", "reflection");
  recordInfluence(state, "opaque_latent", "controller");
}

function opaqueLatentE2EPromptLines(state: CognitiveRuntimeState): string[] {
  const latent = ensureOpaqueLatentE2E(state);
  const live = latestInteractiveOpaqueLatentCurrent(latent);
  const lines = [
    "opaque_latent_e2e:",
    `state=dim:${latent.dim}; loss:${latent.current.loss.toFixed(2)}; drift:${latent.current.drift.toFixed(2)}; stability:${latent.current.stability.toFixed(2)}; energy:${latent.current.energy.toFixed(2)}; confidence:${latent.current.confidence.toFixed(2)}; source:${latent.current.source}`,
    "opaque_latent_rule=Treat elevated latent loss or drift as a real destabilization signal: widen attention, lower snap certainty, and prefer clarification/repair over overconfident continuity. Do not attempt to semantically explain the latent."
  ];
  if (live && (live.updatedAt !== latent.current.updatedAt || live.source !== latent.current.source)) {
    lines.splice(
      2,
      0,
      `interactive=loss:${live.loss.toFixed(2)}; drift:${live.drift.toFixed(2)}; stability:${live.stability.toFixed(2)}; energy:${live.energy.toFixed(2)}; confidence:${live.confidence.toFixed(2)}; source:${live.source}`
    );
  }
  return lines;
}

function driveGoalFor(name: DriveName): string {
  switch (name) {
    case "curiosity":
      return "Investigate one unknown with a verifiable source and capture the link.";
    case "affiliation":
      return "Protect rapport: acknowledge user intent, then ask consent before proactive moves.";
    case "mastery":
      return "Close one concrete artifact and record completion evidence.";
    case "autonomy":
      return "Propose one optional next step that advances the pursuit without overstepping.";
    case "coherence":
      return "Resolve ambiguity or contradictory memory before committing to an answer.";
    case "play":
      return "Offer one lightweight optional creative variant while keeping substance primary.";
    case "safety":
      return "Reconfirm boundaries and avoid risky assumptions.";
    case "meaning":
      return "Tie the current action to long-horizon purpose and continuity.";
    default:
      return "Maintain coherent, user-aligned progress.";
  }
}

function drivePlansFromPressure(state: CognitiveRuntimeState): string[] {
  const extensions = ensureExtensions(state);
  const pressured = Object.values(extensions.drives)
    .filter((drive) => drive.pressure >= DRIVE_PRESSURE_THRESHOLD)
    .sort((a, b) => b.pressure - a.pressure)
    .slice(0, 2);

  return pressured.map(
    (drive) =>
      `Drive pressure (${drive.name}=${drive.pressure.toFixed(2)}): ${driveGoalFor(drive.name)}`
  );
}

function updateDriveLevelsFromText(state: CognitiveRuntimeState, role: "user" | "aurora", text: string): void {
  const normalized = text.trim().toLowerCase();
  if (!normalized) {
    return;
  }
  const extensions = ensureExtensions(state);
  const updatedAt = nowIso();
  const applyDelta = (name: DriveName, delta: number) => {
    const drive = extensions.drives[name];
    drive.level = clamp(drive.level + delta, 0, 1);
    drive.updatedAt = updatedAt;
  };

  if (role === "user") {
    applyDelta("affiliation", 0.018);
    applyDelta("coherence", 0.012);
  } else {
    applyDelta("mastery", 0.01);
  }

  if (/\b(learn|research|paper|source|look up|explore|why|how)\b/.test(normalized)) {
    applyDelta("curiosity", 0.06);
    applyDelta("meaning", 0.015);
  }

  if (/\b(done|completed|fixed|resolved|shipped|implemented)\b/.test(normalized)) {
    applyDelta("mastery", 0.08);
    applyDelta("coherence", 0.03);
  }

  if (/\b(thanks|thank you|great|appreciate|good call)\b/.test(normalized)) {
    applyDelta("affiliation", 0.06);
    applyDelta("play", 0.015);
  }

  if (/\b(please do not|don't|do not|boundary|stop|avoid)\b/.test(normalized)) {
    applyDelta("safety", 0.08);
    applyDelta("coherence", 0.02);
  }

  if (/\b(confused|unclear|ambiguous|contradict|not sure)\b/.test(normalized)) {
    applyDelta("coherence", -0.09);
    applyDelta("safety", -0.02);
  }

  if (/\b(proactive|autonomous|on your own|without me asking)\b/.test(normalized)) {
    applyDelta("autonomy", 0.05);
  }

  if (/\b(fun|creative|joke|playful)\b/.test(normalized)) {
    applyDelta("play", 0.05);
  }
}

function refreshDrivePressures(state: CognitiveRuntimeState, elapsedMs = loopIntervalMs()): void {
  const extensions = ensureExtensions(state);
  const tickScale = clamp(elapsedMs / (1000 * 60), 0.2, 3);
  const durableContinuityOwnedByCognition = cognitionOwnsDurableContinuityCanon();
  const commitment = durableContinuityOwnedByCognition
    ? commitmentStats(state)
    : {
        total: 0,
        pending: 0,
        overdue: 0,
        recentlyCompleted: 0,
        dueSoon: 0,
        bindingLoad: 0,
        overdueBindingLoad: 0,
        selfAuthoredPending: 0,
        selfAuthoredOverdue: 0
      };
  const temporalProfile = durableContinuityOwnedByCognition
    ? temporalPressureProfile(state)
    : {
        topExpectation: null,
        unresolvedCount: 0,
        overdueCount: 0,
        dueCount: 0,
        pendingCount: 0,
        maxPressure: 0,
        urgency: 0
      };
  const conflictedBeliefs = durableContinuityOwnedByCognition ? meaningfulConflictedBeliefCount(state) : 0;
  const lastUserSeenAt = directUserLastSeenMs(state);
  const userIdleMs = Number.isFinite(lastUserSeenAt) ? Math.max(0, Date.now() - lastUserSeenAt) : 0;
  const relationship = extensions.relationship;

  for (const drive of Object.values(extensions.drives)) {
    const towardBaseline = (drive.baseline - drive.level) * DRIVE_RECOVERY_RATE * tickScale;
    drive.level = clamp(drive.level + towardBaseline - DRIVE_DECAY_RATE * tickScale, 0, 1);
    drive.pressure = clamp(drive.baseline - drive.level, 0, 1);
    drive.updatedAt = nowIso();
  }

  extensions.drives.mastery.pressure = clamp(
    extensions.drives.mastery.pressure +
      commitment.pending * 0.03 +
      commitment.bindingLoad * 0.08 +
      commitment.overdueBindingLoad * 0.12 +
      temporalProfile.overdueCount * 0.14 +
      temporalProfile.maxPressure * 0.08,
    0,
    1
  );
  extensions.drives.coherence.pressure = clamp(
    extensions.drives.coherence.pressure +
      conflictedBeliefs * 0.15 +
      state.emotion.uncertainty * 0.12 +
      commitment.overdueBindingLoad * 0.1,
    0,
    1
  );
  extensions.drives.safety.pressure = clamp(
    extensions.drives.safety.pressure +
      state.emotion.stress * 0.18 +
      (state.introspection.intrusiveThoughtRisk ? 0.35 : 0) +
      temporalProfile.overdueCount * 0.06 +
      temporalProfile.urgency * 0.06,
    0,
    1
  );
  extensions.drives.affiliation.pressure = clamp(
    extensions.drives.affiliation.pressure + clamp(userIdleMs / (1000 * 60 * 90), 0, 0.22),
    0,
    1
  );
  extensions.drives.autonomy.pressure = clamp(
    extensions.drives.autonomy.pressure +
      commitment.selfAuthoredPending * 0.04 +
      commitment.selfAuthoredOverdue * 0.09 +
      commitment.overdueBindingLoad * 0.06,
    0,
    1
  );
  extensions.drives.meaning.pressure = clamp(
    extensions.drives.meaning.pressure +
      clamp(commitment.pending / 8, 0, 0.2) +
      temporalProfile.pendingCount * 0.02 +
      commitment.bindingLoad * 0.05,
    0,
    1
  );

  const proactiveWindowMs = Date.parse(relationship.proactiveWindowStartedAt);
  if (!Number.isFinite(proactiveWindowMs) || Date.now() - proactiveWindowMs >= PROACTIVE_WINDOW_MS) {
    relationship.proactiveWindowStartedAt = nowIso();
    relationship.proactiveUsed = 0;
  }

  relationship.trust = clamp(relationship.trust * 0.999 + 0.0005, 0, 1);
  relationship.intimacy = clamp(relationship.intimacy * 0.999, 0, 1);
  relationship.userVulnerability = clamp(relationship.userVulnerability * 0.998, 0, 1);
  relationship.conflictLoad = clamp(relationship.conflictLoad * 0.997, 0, 1);
  relationship.dependenceRisk = clamp(relationship.dependenceRisk * 0.996, 0, 1);
  relationship.reciprocityBalance = clamp(relationship.reciprocityBalance * 0.998 + 0.001, 0, 1);
  relationship.lastUpdatedAt = nowIso();

  extensions.drives.affiliation.pressure = clamp(
    extensions.drives.affiliation.pressure + relationship.conflictLoad * 0.08 - relationship.trust * 0.03,
    0,
    1
  );
  extensions.drives.safety.pressure = clamp(
    extensions.drives.safety.pressure + relationship.dependenceRisk * 0.22 + relationship.userVulnerability * 0.08,
    0,
    1
  );
}

function synthesizeMotiveMirror(state: CognitiveRuntimeState, userText: string): MotiveMirrorState {
  const normalized = toSingleLine(userText, 520);
  const lower = normalized.toLowerCase();
  const extensions = ensureExtensions(state);
  const relationship = extensions.relationship;
  const durableContinuityOwnedByCognition = cognitionOwnsDurableContinuityCanon();
  const commitments = durableContinuityOwnedByCognition
    ? commitmentStats(state)
    : {
        total: 0,
        pending: 0,
        overdue: 0,
        recentlyCompleted: 0,
        dueSoon: 0,
        bindingLoad: 0,
        overdueBindingLoad: 0,
        selfAuthoredPending: 0,
        selfAuthoredOverdue: 0
      };
  const conflictedBeliefs = durableContinuityOwnedByCognition ? meaningfulConflictedBeliefCount(state) : 0;
  const truthCareBias = truthCareBiasDefault();
  const directQuestion =
    lower.includes("?") || /\b(why|how|what|when|where|who|is|are|can|will|did|do|should)\b/.test(lower);

  const truthHits = countAny(lower, MOTIVE_TRUTH_MARKERS);
  const careHits = countAny(lower, MOTIVE_CARE_MARKERS);
  const taskHits = countAny(lower, MOTIVE_TASK_MARKERS) + countAny(lower, MODE_TASK_MARKERS) + countAny(lower, MODE_PLAN_MARKERS);
  const boundaryHits = countAny(lower, MOTIVE_SAFETY_MARKERS) + countAny(lower, USER_BOUNDARY_MARKERS);
  const consistencyHits = countAny(lower, MOTIVE_CONSISTENCY_MARKERS);
  const ventingHits = countAny(lower, USER_VENTING_MARKERS) + countAny(lower, USER_VULNERABILITY_MARKERS);
  const impressHits = countAny(lower, MOTIVE_IMPRESS_MARKERS);
  const avoidanceHits = countAny(lower, MOTIVE_AVOIDANCE_MARKERS);
  const controlHits = countAny(lower, MOTIVE_CONTROL_MARKERS);

  const truthEvidence: string[] = [];
  if (truthHits > 0) truthEvidence.push(`truth_markers:${truthHits}`);
  if (extensions.drives.coherence.pressure >= 0.24) {
    truthEvidence.push(`coherence_pressure:${extensions.drives.coherence.pressure.toFixed(2)}`);
  }
  if (state.emotion.uncertainty >= 0.48) {
    truthEvidence.push(`uncertainty:${state.emotion.uncertainty.toFixed(2)}`);
  }
  if (conflictedBeliefs > 0) truthEvidence.push(`belief_conflicts:${conflictedBeliefs}`);

  const careEvidence: string[] = [];
  if (careHits > 0) careEvidence.push(`care_markers:${careHits}`);
  if (ventingHits > 0) careEvidence.push(`user_venting:${ventingHits}`);
  if (extensions.drives.affiliation.pressure >= 0.2) {
    careEvidence.push(`affiliation_pressure:${extensions.drives.affiliation.pressure.toFixed(2)}`);
  }
  if (relationship.conflictLoad >= 0.2) careEvidence.push(`conflict_load:${relationship.conflictLoad.toFixed(2)}`);

  const taskEvidence: string[] = [];
  if (taskHits > 0) taskEvidence.push(`task_markers:${taskHits}`);
  if (extensions.drives.mastery.pressure >= 0.2) {
    taskEvidence.push(`mastery_pressure:${extensions.drives.mastery.pressure.toFixed(2)}`);
  }
  if (commitments.pending > 0) taskEvidence.push(`pending_commitments:${commitments.pending}`);
  if (commitments.overdue > 0) taskEvidence.push(`overdue_commitments:${commitments.overdue}`);

  const safetyEvidence: string[] = [];
  if (boundaryHits > 0) safetyEvidence.push(`boundary_markers:${boundaryHits}`);
  if (extensions.drives.safety.pressure >= 0.22) {
    safetyEvidence.push(`safety_pressure:${extensions.drives.safety.pressure.toFixed(2)}`);
  }
  if (relationship.dependenceRisk >= 0.16) {
    safetyEvidence.push(`dependence_risk:${relationship.dependenceRisk.toFixed(2)}`);
  }
  if (state.introspection.intrusiveThoughtRisk) safetyEvidence.push("intrusive_risk:high");

  const identityEvidence: string[] = [];
  if (consistencyHits > 0) identityEvidence.push(`consistency_markers:${consistencyHits}`);
  if (extensions.persona.driftScore >= 0.2) {
    identityEvidence.push(`persona_drift:${extensions.persona.driftScore.toFixed(2)}`);
  }
  if (conflictedBeliefs > 0) identityEvidence.push(`belief_conflicts:${conflictedBeliefs}`);
  if (state.introspection.anomalyScore >= 0.2) {
    identityEvidence.push(`introspection_anomaly:${state.introspection.anomalyScore.toFixed(2)}`);
  }

  const motives: MotiveSignal[] = [
    {
      name: "truth_precision",
      score: clamp(
        0.28 +
          truthHits * 0.08 +
          extensions.drives.coherence.pressure * 0.34 +
          state.emotion.uncertainty * 0.22 +
          conflictedBeliefs * 0.08,
        0,
        1
      ),
      evidence: truthEvidence.slice(0, 4)
    },
    {
      name: "care_connection",
      score: clamp(
        0.26 +
          careHits * 0.07 +
          ventingHits * 0.1 +
          extensions.drives.affiliation.pressure * 0.3 +
          relationship.conflictLoad * 0.2 +
          relationship.userVulnerability * 0.14,
        0,
        1
      ),
      evidence: careEvidence.slice(0, 4)
    },
    {
      name: "task_execution",
      score: clamp(
        0.24 +
          taskHits * 0.1 +
          extensions.drives.mastery.pressure * 0.32 +
          commitments.pending * 0.04 +
          commitments.overdue * 0.12,
        0,
        1
      ),
      evidence: taskEvidence.slice(0, 4)
    },
    {
      name: "boundary_safety",
      score: clamp(
        0.3 +
          boundaryHits * 0.12 +
          extensions.drives.safety.pressure * 0.34 +
          relationship.dependenceRisk * 0.28 +
          (state.introspection.intrusiveThoughtRisk ? 0.22 : 0),
        0,
        1
      ),
      evidence: safetyEvidence.slice(0, 4)
    },
    {
      name: "identity_consistency",
      score: clamp(
        0.24 +
          consistencyHits * 0.08 +
          extensions.persona.driftScore * 0.5 +
          conflictedBeliefs * 0.12 +
          state.introspection.anomalyScore * 0.18,
        0,
        1
      ),
      evidence: identityEvidence.slice(0, 4)
    }
  ];

  const spikeCandidates: MotiveSpike[] = [
    {
      name: "impress",
      score: Number(
        clamp(
          0.08 + impressHits * 0.22 + extensions.persona.driftScore * 0.35 + state.emotion.arousal * 0.12,
          0,
          1
        ).toFixed(4)
      ),
      trigger: `markers=${impressHits}; drift=${extensions.persona.driftScore.toFixed(2)}; arousal=${state.emotion.arousal.toFixed(2)}`,
      actionHint: "Simplify response and separate known facts from inferred claims."
    },
    {
      name: "avoidance",
      score: Number(
        clamp(
          0.08 + avoidanceHits * 0.2 + state.emotion.uncertainty * 0.28 + (directQuestion ? 0.14 : 0),
          0,
          1
        ).toFixed(4)
      ),
      trigger: `markers=${avoidanceHits}; uncertainty=${state.emotion.uncertainty.toFixed(2)}; direct_q=${directQuestion ? "yes" : "no"}`,
      actionHint: directQuestion
        ? "Answer directly in the first sentence; if uncertainty remains, ask one targeted question."
        : "State a clear position and ask at most one targeted question if needed."
    },
    {
      name: "control",
      score: Number(
        clamp(
          0.1 +
            controlHits * 0.18 +
            taskHits * 0.06 +
            extensions.drives.mastery.pressure * 0.22 +
            extensions.drives.safety.pressure * 0.14,
          0,
          1
        ).toFixed(4)
      ),
      trigger: `markers=${controlHits}; mastery=${extensions.drives.mastery.pressure.toFixed(2)}; safety=${extensions.drives.safety.pressure.toFixed(2)}`,
      actionHint: "Present options with tradeoffs and recommend one path."
    }
  ];
  const spikes = spikeCandidates.sort((a, b) => b.score - a.score).slice(0, 3);

  const ranked = motives
    .map((item) => ({
      ...item,
      score: Number(item.score.toFixed(4))
    }))
    .sort((a, b) => b.score - a.score);
  const top = ranked[0];
  const second = ranked[1];
  const careScore = ranked.find((item) => item.name === "care_connection")?.score ?? 0;

  let chosenPriority: MotiveName = top?.name ?? "truth_precision";
  let responseStyle: MotiveMirrorState["responseStyle"] = "balanced";
  let conflict: MotiveConflict | null = null;
  let resolution = "Follow highest-priority motive while preserving consent and truthfulness.";
  const topSpike = spikes[0];
  let actionHint = "Answer directly, distinguish known from inferred, and keep one clear next step.";
  if (topSpike && topSpike.score >= MOTIVE_SPIKE_ACTION_THRESHOLD) {
    if (topSpike.name === "impress" && careScore >= MOTIVE_IMPRESS_WARMTH_GUARD_THRESHOLD) {
      actionHint = "Simplify and separate known vs inferred, while keeping one warm/attuned sentence.";
    } else {
      actionHint = topSpike.actionHint;
    }
  }
  let conflictScore = 0;

  if (top && second) {
    const scoreGap = Math.abs(top.score - second.score);
    conflictScore = Number(clamp((1 - scoreGap / 0.5) * second.score, 0, 1).toFixed(4));
    const structuralConflict = scoreGap <= 0.12 && second.score >= 0.45;
    const conflictDetected = structuralConflict && conflictScore >= MOTIVE_CONFLICT_ACTIVE_THRESHOLD;
    if (conflictDetected) {
      const pair = new Set<MotiveName>([top.name, second.name]);
      if (pair.has("boundary_safety")) {
        chosenPriority = "boundary_safety";
        responseStyle = "direct";
        resolution = "Prioritize boundaries/safety first, then continue with concise supportive context.";
      } else if (pair.has("truth_precision") && pair.has("care_connection")) {
        if (truthCareBias === "care_first_then_truth") {
          chosenPriority = "care_connection";
          responseStyle = "supportive";
          resolution = "Care-first then truth: acknowledge impact first, then state truth cleanly in the next sentence.";
          actionHint = "Lead with empathy, then deliver precise truth with clear known-vs-inferred separation.";
        } else {
          chosenPriority = "truth_precision";
          responseStyle = "balanced";
          resolution = "Truth-first, said gently: state truth in one clean sentence, then add a validating sentence.";
          actionHint = "State truth first, then soften with concise empathic framing.";
        }
      } else if (pair.has("task_execution") && pair.has("care_connection")) {
        chosenPriority = ventingHits > 0 ? "care_connection" : "task_execution";
        responseStyle = ventingHits > 0 ? "supportive" : "balanced";
        resolution =
          chosenPriority === "care_connection"
            ? "Acknowledge emotional load first, then offer one concrete next step."
            : "Deliver concrete next step, but keep consent-first and non-pressuring tone.";
        actionHint =
          chosenPriority === "care_connection"
            ? "Acknowledge emotion first, then offer one concrete step."
            : "Give one concrete next step with optional alternatives.";
      } else if (pair.has("identity_consistency") && pair.has("truth_precision")) {
        chosenPriority = "identity_consistency";
        responseStyle = "balanced";
        resolution = "Keep response consistent with established beliefs and ask clarification when confidence is low.";
        actionHint = "Check for consistency against recent beliefs; ask one clarification if confidence is low.";
      }
      conflict = {
        primary: top.name,
        competing: second.name,
        tension: Number(clamp(1 - scoreGap / 0.12, 0, 1).toFixed(4)),
        resolution
      };
    }
  }

  if (!conflict) {
    if (chosenPriority === "boundary_safety") {
      responseStyle = "direct";
      resolution = "Keep boundary/safety language explicit and concise.";
      actionHint = "Set boundary plainly, then continue with concise next step or clarification question.";
    } else if (chosenPriority === "care_connection" && ventingHits > 0) {
      responseStyle = "supportive";
      resolution = "Prioritize emotional attunement before proposing actions.";
      actionHint = "Mirror the core feeling in one sentence, then offer one practical option.";
    } else {
      responseStyle = "balanced";
      resolution = "Provide precise, concise response with one practical next move when useful.";
    }
  }

  const rationale = conflict
    ? `Competing motives detected (${conflict.primary} vs ${conflict.competing}). ${conflict.resolution}`
    : `No major motive conflict. Prioritize ${chosenPriority} with ${responseStyle} delivery. ${resolution}`;

  return {
    lastUpdatedAt: nowIso(),
    promptHash: hashText(lower),
    motives: ranked.slice(0, MOTIVE_NAMES.length),
    chosenPriority,
    responseStyle,
    conflictScore,
    actionHint: toSingleLine(actionHint, 220),
    spikes,
    rationale: toSingleLine(rationale, 220),
    conflict
  };
}

function inferAppraisalAgency(text: string, role: "user" | "aurora" | "external"): AppraisalAgency {
  if (role === "user") {
    return "user";
  }
  if (role === "external") {
    return "external";
  }
  if (/\b(my mistake|i was wrong|i forgot|i missed|i broke)\b/i.test(text)) {
    return "self";
  }
  return "unknown";
}

function inferCertainty(state: CognitiveRuntimeState, text: string): number {
  const lower = text.toLowerCase();
  let penalty = state.emotion.uncertainty * 0.26;
  if (/\b(not sure|unclear|ambiguous|maybe|perhaps|i think|i guess)\b/.test(lower)) {
    penalty += 0.34;
  }
  if (/\b(error|failed|problem|unknown)\b/.test(lower)) {
    penalty += 0.18;
  }
  if (/\b(verified|confirmed|exact|done|fixed|resolved)\b/.test(lower)) {
    penalty -= 0.16;
  }
  return clamp(0.82 - penalty, 0, 1);
}

function inferControllability(role: "user" | "aurora" | "external", text: string): number {
  const lower = text.toLowerCase();
  let base = role === "aurora" ? 0.72 : role === "user" ? 0.56 : 0.26;
  if (/\b(can't|cannot|unable|blocked|failed)\b/.test(lower)) {
    base -= 0.2;
  }
  if (/\b(can|will|done|fixed|implemented)\b/.test(lower)) {
    base += 0.12;
  }
  return clamp(base, 0, 1);
}

function inferSocialAlignment(text: string): number {
  const lower = text.toLowerCase();
  let score = 0.52 + scoreTextValence(text) * 0.35;
  if (/\b(thanks|thank you|please|appreciate)\b/.test(lower)) {
    score += 0.12;
  }
  if (/\b(frustrated|angry|annoyed|upset|stop)\b/.test(lower)) {
    score -= 0.28;
  }
  return clamp(score, 0, 1);
}

function inferRelationalAffectSignals(text: string): {
  harshBoundary: boolean;
  dismissal: boolean;
  hurt: boolean;
  anger: boolean;
  joy: boolean;
  affection: boolean;
  relief: boolean;
  embarrassment: boolean;
  surprise: boolean;
  curiosity: boolean;
  love: boolean;
} {
  const lower = text.toLowerCase();
  return {
    harshBoundary: includesAny(lower, USER_DISCOMFORT_MARKERS) || /\b(shut up|leave me alone|back off|too much)\b/.test(lower),
    dismissal: /\b(cold|dismissive|condescending|cruel|mean|ignored|ignoring|flattening)\b/.test(lower),
    hurt: includesAny(lower, AFFECT_HURT_MARKERS),
    anger: includesAny(lower, AFFECT_ANGER_MARKERS),
    joy: includesAny(lower, AFFECT_JOY_MARKERS),
    affection: includesAny(lower, AFFECT_AFFECTION_MARKERS),
    relief: includesAny(lower, AFFECT_RELIEF_MARKERS),
    embarrassment: includesAny(lower, AFFECT_EMBARRASSMENT_MARKERS),
    surprise: includesAny(lower, AFFECT_SURPRISE_MARKERS),
    curiosity: includesAny(lower, AFFECT_CURIOSITY_MARKERS),
    love: /\b(love you|i love you|love this about you|deeply care about you|care about you deeply|adore you|cherish you)\b/.test(lower)
  };
}

function appraisalEffectFromRecord(appraisal: AppraisalRecord): AppraisalEffect {
  const highRelevance = appraisal.goalRelevance >= 0.55;
  const highNovelty = appraisal.novelty >= 0.65;
  const lowCertainty = appraisal.certainty <= 0.42;
  const negative = appraisal.goalCongruence <= -0.25;
  const positive = appraisal.goalCongruence >= 0.3;
  const signals = inferRelationalAffectSignals(appraisal.triggerText);
  const lowControl = appraisal.controllability <= 0.38;
  const lowAlignment = appraisal.socialAlignment <= 0.34;
  const severeMisalignment = appraisal.socialAlignment <= 0.22;
  const externalSocialSource = appraisal.agency !== "self";

  if (positive && appraisal.socialAlignment >= 0.72 && (signals.love || (signals.affection && appraisal.goalRelevance >= 0.62))) {
    return {
      emotionType: "love",
      actionTendency: "reach",
      delta: { valence: 0.19, arousal: 0.05, stress: -0.08, uncertainty: -0.06 }
    };
  }

  if (
    highRelevance &&
    negative &&
    externalSocialSource &&
    (signals.anger || signals.harshBoundary || signals.dismissal) &&
    (lowAlignment || severeMisalignment)
  ) {
    return {
      emotionType: severeMisalignment || signals.harshBoundary ? "angry" : "aggravated",
      actionTendency: "protect",
      delta: { valence: -0.18, stress: 0.15, uncertainty: 0.02, arousal: 0.11 }
    };
  }

  if (highRelevance && negative && externalSocialSource && signals.hurt && (lowAlignment || lowControl)) {
    return {
      emotionType: "hurt",
      actionTendency: "repair",
      delta: { valence: -0.2, stress: 0.12, uncertainty: 0.06, arousal: 0.04 }
    };
  }

  if (highRelevance && negative && externalSocialSource && lowControl) {
    return {
      emotionType: "sad",
      actionTendency: "withdraw",
      delta: { valence: -0.16, stress: 0.08, uncertainty: 0.05, arousal: -0.02 }
    };
  }

  if (positive && appraisal.socialAlignment >= 0.62 && (signals.joy || signals.affection)) {
    return {
      emotionType: "joy",
      actionTendency: "reach",
      delta: { valence: 0.16, arousal: 0.07, stress: -0.07, uncertainty: -0.06 }
    };
  }

  if (positive && appraisal.socialAlignment >= 0.58 && signals.relief && appraisal.certainty >= 0.44) {
    return {
      emotionType: "relief",
      actionTendency: "settle",
      delta: { valence: 0.1, arousal: -0.03, stress: -0.12, uncertainty: -0.08 }
    };
  }

  if (
    appraisal.agency === "self" &&
    signals.embarrassment &&
    (highRelevance || negative || lowCertainty || /(?:awkward|embarrass|wrong)/i.test(appraisal.triggerText))
  ) {
    return {
      emotionType: "embarrassed",
      actionTendency: "repair",
      delta: { valence: -0.14, stress: 0.1, uncertainty: 0.08, arousal: 0.05 }
    };
  }

  if (highRelevance && negative && appraisal.agency === "self") {
    return {
      emotionType: "guilt",
      actionTendency: "repair",
      delta: { valence: -0.17, stress: 0.12, uncertainty: 0.09, arousal: 0.05 }
    };
  }

  if (highRelevance && negative) {
    return {
      emotionType: "concern",
      actionTendency: lowCertainty ? "clarify" : "stabilize",
      delta: { valence: -0.11, stress: 0.11, uncertainty: 0.1, arousal: 0.04 }
    };
  }

  if (highRelevance && highNovelty && lowCertainty && (signals.surprise || appraisal.novelty >= 0.74)) {
    return {
      emotionType: "surprised",
      actionTendency: "clarify",
      delta: { valence: 0.01, stress: 0.03, uncertainty: 0.12, arousal: 0.12 }
    };
  }

  if (highRelevance && highNovelty && (signals.curiosity || appraisal.novelty >= 0.68) && appraisal.goalCongruence > -0.18) {
    return {
      emotionType: "curious",
      actionTendency: "explore",
      delta: { valence: 0.05, stress: -0.02, uncertainty: 0.02, arousal: 0.08 }
    };
  }

  if (highRelevance && lowCertainty) {
    return {
      emotionType: "uncertain",
      actionTendency: "clarify",
      delta: { uncertainty: 0.14, stress: 0.06, valence: -0.03, arousal: 0.03 }
    };
  }

  if (positive && highNovelty) {
    return {
      emotionType: "delight",
      actionTendency: "explore",
      delta: { valence: 0.11, arousal: 0.08, stress: -0.04, uncertainty: -0.05 }
    };
  }

  if (positive) {
    return {
      emotionType: "confidence",
      actionTendency: "advance",
      delta: { valence: 0.08, stress: -0.04, uncertainty: -0.04, arousal: 0.02 }
    };
  }

  if (appraisal.socialAlignment < 0.38) {
    return {
      emotionType: "caution",
      actionTendency: "repair",
      delta: { valence: -0.05, stress: 0.08, uncertainty: 0.08, arousal: 0.03 }
    };
  }

  return {
    emotionType: "neutral",
    actionTendency: "monitor",
    delta: { stress: -0.01, uncertainty: -0.01 }
  };
}

function applyAppraisalFromText(
  state: CognitiveRuntimeState,
  input: {
    role: "user" | "aurora" | "external";
    text: string;
    outcomeHint: string;
  }
): AppraisalRecord | null {
  if (testSubsystemAblations().disableAffectiveModulation) {
    return null;
  }
  const text = toSingleLine(input.text, 320);
  if (!text) {
    return null;
  }
  const extensions = ensureExtensions(state);
  const phenomenalValuationBias =
    phenomenalManifoldProbeEnabled() && !testSubsystemAblations().disablePhenomenalManifold
      ? ensurePhenomenalManifoldProbe(state).current.valuationBias
      : 0.5;
  const goalRelevance = clamp(
    scoreGoalAlignment(text, state.workspace.pendingPlans) * (0.86 + phenomenalValuationBias * 0.28),
    0,
    1
  );
  const novelty = scoreNovelty(state, text);
  const valence = scoreTextValence(text);
  const outcomeBias =
    input.outcomeHint === "positive_outcome" ? 0.26 : input.outcomeHint === "negative_outcome" ? -0.3 : 0;
  const appraisal: AppraisalRecord = {
    id: toId("apr"),
    at: nowIso(),
    goalRelevance,
    goalCongruence: clamp(valence * (0.52 + phenomenalValuationBias * 0.24) + outcomeBias, -1, 1),
    controllability: inferControllability(input.role, text),
    certainty: inferCertainty(state, text),
    novelty,
    socialAlignment: inferSocialAlignment(text),
    agency: inferAppraisalAgency(text, input.role),
    emotionType: "neutral",
    actionTendency: "monitor",
    triggerText: text
  };

  const effect = appraisalEffectFromRecord(appraisal);
  appraisal.emotionType = effect.emotionType;
  appraisal.actionTendency = effect.actionTendency;

  extensions.appraisals.push(appraisal);
  extensions.appraisals = extensions.appraisals.slice(-MAX_APPRAISALS);

  touchEmotion(state, effect.delta);
  if (effect.actionTendency === "advance") {
    state.hormones.dopamine = clamp(state.hormones.dopamine + 0.04, 0, 1);
  } else if (effect.actionTendency === "repair" || effect.actionTendency === "clarify") {
    state.hormones.cortisol = clamp(state.hormones.cortisol + 0.035, 0, 1);
    state.hormones.oxytocin = clamp(state.hormones.oxytocin + 0.015, 0, 1);
  } else if (effect.actionTendency === "explore") {
    state.hormones.dopamine = clamp(state.hormones.dopamine + 0.02, 0, 1);
    state.hormones.serotonin = clamp(state.hormones.serotonin + 0.015, 0, 1);
  } else if (effect.actionTendency === "reach") {
    state.hormones.dopamine = clamp(state.hormones.dopamine + 0.025, 0, 1);
    state.hormones.oxytocin = clamp(state.hormones.oxytocin + 0.04, 0, 1);
    state.hormones.serotonin = clamp(state.hormones.serotonin + 0.025, 0, 1);
  } else if (effect.actionTendency === "protect") {
    state.hormones.cortisol = clamp(state.hormones.cortisol + 0.05, 0, 1);
    state.hormones.serotonin = clamp(state.hormones.serotonin - 0.015, 0, 1);
    state.hormones.oxytocin = clamp(state.hormones.oxytocin - 0.02, 0, 1);
  } else if (effect.actionTendency === "withdraw") {
    state.hormones.cortisol = clamp(state.hormones.cortisol + 0.025, 0, 1);
    state.hormones.dopamine = clamp(state.hormones.dopamine - 0.03, 0, 1);
    state.hormones.serotonin = clamp(state.hormones.serotonin - 0.015, 0, 1);
  } else if (effect.actionTendency === "settle") {
    state.hormones.cortisol = clamp(state.hormones.cortisol - 0.025, 0, 1);
    state.hormones.serotonin = clamp(state.hormones.serotonin + 0.03, 0, 1);
  }
  state.hormones.updatedAt = nowIso();
  recordInfluence(state, "emotion", "controller");

  if (
    appraisal.goalRelevance >= 0.6 &&
    (effect.actionTendency === "repair" || effect.actionTendency === "clarify") &&
    !state.attentionQueue.some((item) => item.source === "goal" && item.text.includes("Appraisal action"))
  ) {
    queueAttentionMessage(state, {
      source: "goal",
      text: `Appraisal action: ${effect.actionTendency} (${effect.emotionType})`,
      participant: "aurora",
      relatedMemoryIds: [],
      novelty: clamp(0.38 + appraisal.novelty * 0.4, 0, 1),
      relevance: appraisal.goalRelevance,
      emotionalWeight: clamp(0.3 + Math.abs(appraisal.goalCongruence) * 0.45, 0, 1),
      goalAlignment: appraisal.goalRelevance,
      ttlMs: 120000
    });
  }

  return appraisal;
}

function updatePersonaFromAuroraText(state: CognitiveRuntimeState, text: string): void {
  if (testSubsystemAblations().disableIdentityContinuity) {
    return;
  }
  const normalized = text.trim();
  if (!normalized) {
    return;
  }
  const extensions = ensureExtensions(state);
  const persona = extensions.persona;
  const fingerprint = fingerprintFromText(normalized);
  const serialized = serializeFingerprint(fingerprint);

  if (!persona.baselineFingerprint) {
    persona.baselineFingerprint = serialized;
  }
  const baseline = parseFingerprint(persona.baselineFingerprint) ?? fingerprint;
  const drift = driftScoreFromFingerprints(baseline, fingerprint);

  persona.policyVersion = AURORA_PERSONA_POLICY_VERSION;
  persona.lastFingerprint = serialized;
  persona.driftScore = clamp(drift, 0, 1);

  if (
    drift >= PERSONA_DRIFT_ALERT_THRESHOLD &&
    !state.attentionQueue.some((item) => item.source === "internal_reflection" && item.text.includes("persona drift"))
  ) {
    queueAttentionMessage(state, {
      source: "internal_reflection",
      text: `persona drift=${drift.toFixed(2)} exceeded threshold; tighten response shaper constraints.`,
      participant: "aurora",
      relatedMemoryIds: [],
      novelty: 0.34,
      relevance: 0.81,
      emotionalWeight: 0.52,
      goalAlignment: 0.88,
      ttlMs: 180000
    });
  }

  recordInfluence(state, "introspection", "controller");
}

function computePersonaRegressionMetrics(state: CognitiveRuntimeState):
  | {
      sampleSize: number;
      averageDrift: number;
      p90Drift: number;
      baselineFingerprint: string;
    }
  | null {
  const extensions = ensureExtensions(state);
  const persona = extensions.persona;
  const auroraEpisodes = extensions.episodes
    .filter((episode) => episode.role === "aurora")
    .slice(-PERSONA_REGRESSION_SAMPLE_SIZE);
  if (auroraEpisodes.length < 4) {
    return null;
  }

  const baselineParsed = persona.baselineFingerprint
    ? parseFingerprint(persona.baselineFingerprint)
    : fingerprintFromText(auroraEpisodes[0].text);
  const baseline = baselineParsed ?? fingerprintFromText(auroraEpisodes[0].text);
  const baselineFingerprint = persona.baselineFingerprint || serializeFingerprint(baseline);
  const drifts = auroraEpisodes
    .map((episode) => driftScoreFromFingerprints(baseline, fingerprintFromText(episode.text)))
    .sort((a, b) => a - b);
  const averageDrift = drifts.reduce((sum, value) => sum + value, 0) / drifts.length;
  const p90Index = Math.max(0, Math.ceil(drifts.length * 0.9) - 1);
  const p90Drift = drifts[p90Index] ?? averageDrift;
  return {
    sampleSize: auroraEpisodes.length,
    averageDrift: clamp(averageDrift, 0, 1),
    p90Drift: clamp(p90Drift, 0, 1),
    baselineFingerprint
  };
}

function maybeRunPersonaRegression(state: CognitiveRuntimeState, force = false): void {
  if (testSubsystemAblations().disableIdentityContinuity) {
    return;
  }
  const extensions = ensureExtensions(state);
  const persona = extensions.persona;
  const now = Date.now();
  const lastRunMs = persona.lastRegressionAt ? Date.parse(persona.lastRegressionAt) : 0;
  if (!force && Number.isFinite(lastRunMs) && now - lastRunMs < PERSONA_REGRESSION_INTERVAL_MS) {
    return;
  }
  const metrics = computePersonaRegressionMetrics(state);
  if (!metrics) {
    persona.lastRegressionAt = nowIso();
    return;
  }
  persona.baselineFingerprint = metrics.baselineFingerprint;
  persona.driftScore = metrics.averageDrift;
  persona.lastRegressionAt = nowIso();

  if (
    metrics.p90Drift >= PERSONA_DRIFT_ALERT_THRESHOLD &&
    !state.attentionQueue.some((item) => item.source === "goal" && item.text.includes("persona regression"))
  ) {
    queueAttentionMessage(state, {
      source: "goal",
      text: `persona regression flagged p90 drift=${metrics.p90Drift.toFixed(2)}; reinforce stable voice policy.`,
      participant: "aurora",
      relatedMemoryIds: [],
      novelty: 0.28,
      relevance: 0.78,
      emotionalWeight: 0.48,
      goalAlignment: 0.82,
      ttlMs: 240000
    });
  }
}

function tokenOverlapScore(a: string, b: string): number {
  const tokensA = extractTokens(a);
  const tokensB = extractTokens(b);
  return jaccardSimilarity(tokensA, tokensB);
}

function commitmentHasExplicitPromiseMarkers(text: string): boolean {
  const lower = toSingleLine(text, 340).toLowerCase();
  if (!lower) {
    return false;
  }
  return (
    /\bi promise\b/.test(lower) ||
    /\bi(?:'ll| will| am going to)\b/.test(lower) ||
    /\bmake sure\b/.test(lower) ||
    /\bcommit(?:ment)?\b/.test(lower) ||
    /\bfollow up\b/.test(lower) ||
    /\bi owe you\b/.test(lower)
  );
}

function commitmentBindingWeightForText(
  role: "user" | "aurora",
  text: string,
  dueAt: string | null,
  completionMessage: string
): number {
  const lower = toSingleLine(text, 340).toLowerCase();
  let weight = role === "aurora" ? 0.58 : 0.42;
  if (commitmentHasExplicitPromiseMarkers(lower)) {
    weight += 0.16;
  }
  if (/\b(today|tonight|tomorrow|later|soon|within|by\s+\d|at\s+\d)\b/.test(lower)) {
    weight += 0.06;
  }
  if (dueAt) {
    weight += 0.08;
  }
  if (completionMessage) {
    weight += 0.05;
  }
  if (/\b(remember|don't let me forget|hold me to|make me)\b/.test(lower)) {
    weight += 0.05;
  }
  return clamp(weight, 0.18, 0.96);
}

function commitmentBindingWeight(entry: CommitmentEntry): number {
  return clamp(entry.bindingWeight, 0, 1);
}

function commitmentIrreversibilityPressure(entry: CommitmentEntry, nowMs = Date.now()): number {
  const dueMs = entry.dueAt ? Date.parse(entry.dueAt) : Number.NaN;
  const dueSoon =
    Number.isFinite(dueMs) && dueMs > nowMs && dueMs - nowMs <= COMMITMENT_DUE_SOON_LOOKAHEAD_MS ? 0.12 : 0;
  const overdue = entry.status === "overdue" ? 0.24 : 0;
  const inFlight = entry.status === "in_progress" ? 0.05 : 0;
  const selfAuthored = entry.selfAuthored ? 0.08 : 0;
  const explicit = entry.promiseExplicit ? 0.07 : 0;
  const breach = Math.min(0.24, entry.breachCount * 0.07);
  return clamp(commitmentBindingWeight(entry) * 0.46 + dueSoon + overdue + inFlight + selfAuthored + explicit + breach, 0, 1);
}

function commitmentBindingLabel(value: number): "low" | "medium" | "high" {
  if (value >= 0.72) {
    return "high";
  }
  if (value >= 0.42) {
    return "medium";
  }
  return "low";
}

function activeMeaningfulCommitments(state: CognitiveRuntimeState): CommitmentEntry[] {
  return ensureExtensions(state).commitments.filter(
    (item) =>
      (item.status === "pending" ||
        item.status === "in_progress" ||
        item.status === "renegotiated" ||
        item.status === "overdue") &&
      !shouldSuppressCommitmentFromContext(item)
  );
}

function strongestBindingCommitment(state: CognitiveRuntimeState): CommitmentEntry | null {
  return (
    [...activeMeaningfulCommitments(state)].sort(
      (left, right) => commitmentIrreversibilityPressure(right) - commitmentIrreversibilityPressure(left)
    )[0] ?? null
  );
}

function commitmentContextBlob(commitment: CommitmentEntry): string {
  const evidenceTail = Array.isArray(commitment.evidence) ? commitment.evidence.slice(-3).join(" ") : "";
  return `${commitment.title} ${commitment.completionMessage} ${commitment.renegotiationNote} ${evidenceTail}`.toLowerCase();
}

function isPaperCommitment(commitment: CommitmentEntry): boolean {
  return /\bpapers?\b/.test(commitmentContextBlob(commitment));
}

function isStalePaperCommitment(commitment: CommitmentEntry, staleMs: number): boolean {
  if (!isPaperCommitment(commitment)) {
    return false;
  }
  const updatedAtMs = Date.parse(commitment.updatedAt);
  if (!Number.isFinite(updatedAtMs)) {
    return true;
  }
  return Date.now() - updatedAtMs >= staleMs;
}

function isAmbiguousPaperCommitment(commitment: CommitmentEntry): boolean {
  const blob = commitmentContextBlob(commitment);
  if (!isPaperCommitment(commitment)) {
    return false;
  }
  if (/\"those papers\"|“those papers”|‘those papers’/.test(blob)) {
    return true;
  }
  return /\b(those papers|which papers|specific papers|paper numbers|default|unblock|renegotiat|clarification|clarify|missing specifics|on hold|reminder|forman|foreman)\b/.test(
    blob
  );
}

function isOnHoldPaperCommitment(commitment: CommitmentEntry): boolean {
  const blob = commitmentContextBlob(commitment);
  if (!isPaperCommitment(commitment)) {
    return false;
  }
  return /\b(on hold|won't run the search|will not run the search|handled by forman|handled by foreman|your forman will handle|forman will handle)\b/.test(
    blob
  );
}

function shouldSuppressCommitmentFromContext(commitment: CommitmentEntry): boolean {
  if (commitment.status === "completed" || commitment.status === "cancelled") {
    return true;
  }
  const title = (commitment.title || "").toLowerCase();
  if (
    title.includes("[[reply_to_current]]") ||
    title.startsWith("replied in session ") ||
    title.includes("tool artifacts:")
  ) {
    return true;
  }
  if (isStalePaperCommitment(commitment, PAPER_COMMITMENT_STALE_SUPPRESS_MS)) {
    return true;
  }
  return isAmbiguousPaperCommitment(commitment) || isOnHoldPaperCommitment(commitment);
}

function parseDueAt(text: string, nowMs: number): { dueAt: string | null; dueWindow: string } {
  const lower = text.toLowerCase();
  const clockMatch = lower.match(/\b(?:by|at)\s*(1[0-2]|0?[1-9])(?::([0-5][0-9]))?\s*(a\.?m\.?|p\.?m\.?)\b/);
  if (clockMatch?.[1] && clockMatch[3]) {
    const hour12 = Number(clockMatch[1]);
    const minute = Number(clockMatch[2] || "0");
    const meridiem = clockMatch[3].startsWith("p") ? "pm" : "am";
    let hour24 = hour12 % 12;
    if (meridiem === "pm") {
      hour24 += 12;
    }
    const due = new Date(nowMs);
    due.setSeconds(0, 0);
    due.setHours(hour24, minute, 0, 0);
    if (due.getTime() <= nowMs) {
      due.setDate(due.getDate() + 1);
    }
    return {
      dueAt: due.toISOString(),
      dueWindow: toSingleLine(clockMatch[0], 32).replace(/\s+/g, " ").trim()
    };
  }
  if (/\btomorrow\b/.test(lower)) {
    return {
      dueAt: new Date(nowMs + 1000 * 60 * 60 * 24).toISOString(),
      dueWindow: "tomorrow"
    };
  }
  if (/\btoday\b/.test(lower) || /\btonight\b/.test(lower)) {
    return {
      dueAt: new Date(nowMs + 1000 * 60 * 60 * 6).toISOString(),
      dueWindow: "today"
    };
  }

  const isoMatch = lower.match(/\b(20\d{2}-\d{2}-\d{2})\b/);
  if (isoMatch?.[1]) {
    const parsed = Date.parse(`${isoMatch[1]}T18:00:00Z`);
    if (Number.isFinite(parsed)) {
      return {
        dueAt: new Date(parsed).toISOString(),
        dueWindow: isoMatch[1]
      };
    }
  }

  return { dueAt: null, dueWindow: "" };
}

function parseRelativeDelayMs(text: string): number {
  const lower = text.toLowerCase();
  const match = lower.match(/\b(?:in|within)\s+(\d{1,3})\s*(minutes?|mins?|hours?|hrs?)\b/);
  if (!match?.[1] || !match[2]) {
    return 0;
  }
  const amount = Number(match[1]);
  if (!Number.isFinite(amount) || amount <= 0) {
    return 0;
  }
  const unit = match[2].toLowerCase();
  return unit.startsWith("hour") || unit.startsWith("hr")
    ? amount * 1000 * 60 * 60
    : amount * 1000 * 60;
}

function detectPlannedAbsenceFromText(
  text: string,
  nowMs: number
): { dueAt: string | null; dueWindow: string; explicitPromise: boolean } | null {
  const normalized = toSingleLine(text, 360);
  if (!normalized || isOperationalNoiseTurn(normalized)) {
    return null;
  }

  const lower = normalized.toLowerCase();
  const relativeDelayMs = parseRelativeDelayMs(lower);
  const explicitPromise =
    /\bbrb\b/.test(lower) ||
    /\bbe right back\b/.test(lower) ||
    /\b(?:i(?:'ll| will)|i am going to|i'm going to|gonna)\s+(?:be\s+)?back\b/.test(lower) ||
    /\b(?:i(?:'ll| will)|i am going to|i'm going to|gonna)\s+(?:message|text|check in|ping|talk)\b/.test(lower) ||
    /\bsee you\b/.test(lower);
  const hasPlannedReturnMarker =
    explicitPromise ||
    /\bback\s+(?:in|by|at)\b/.test(lower) ||
    /\btalk (?:later|tomorrow|tonight)\b/.test(lower) ||
    /\bcheck in (?:later|tomorrow|tonight)\b/.test(lower) ||
    /\blater tonight\b/.test(lower) ||
    /\blater today\b/.test(lower);

  if (!hasPlannedReturnMarker) {
    return null;
  }

  if (relativeDelayMs > 0) {
    const dueAt = new Date(nowMs + relativeDelayMs).toISOString();
    const amount = Math.round(relativeDelayMs / (1000 * 60));
    const dueWindow = relativeDelayMs >= 1000 * 60 * 60 ? `${Math.round(amount / 60)} hour(s)` : `${amount} minute(s)`;
    return { dueAt, dueWindow, explicitPromise };
  }

  const parsedDue = parseDueAt(normalized, nowMs);
  if (parsedDue.dueAt) {
    return {
      dueAt: parsedDue.dueAt,
      dueWindow: parsedDue.dueWindow,
      explicitPromise
    };
  }

  if (/\bbrb\b/.test(lower) || /\bbe right back\b/.test(lower)) {
    return {
      dueAt: new Date(nowMs + SILENCE_BRB_DEFAULT_MS).toISOString(),
      dueWindow: "soon",
      explicitPromise: true
    };
  }

  if (/\blater\b/.test(lower)) {
    return {
      dueAt: new Date(nowMs + SILENCE_LATER_DEFAULT_MS).toISOString(),
      dueWindow: /tonight|today/.test(lower) ? "later today" : "later",
      explicitPromise
    };
  }

  return {
    dueAt: null,
    dueWindow: "",
    explicitPromise
  };
}

function looksConversationClosingText(text: string): boolean {
  const lower = toSingleLine(text, 220).toLowerCase();
  if (!lower) {
    return false;
  }
  return (
    /\b(goodnight|good night|bye|talk later|ttyl|see you|catch you later|gotta go|have to go|heading out|head out)\b/.test(lower) ||
    /\b(brb|be right back)\b/.test(lower)
  );
}

function silenceGraceMs(silence: SilenceDynamicsState, nowMs: number): number {
  const dueMs = parseIsoMs(silence.plannedReturnAt);
  const startMs = parseIsoMs(silence.gapStartedAt);
  if (!Number.isFinite(dueMs)) {
    return SILENCE_PROMISE_GRACE_MIN_MS;
  }
  const windowMs =
    Number.isFinite(startMs) && dueMs > startMs ? dueMs - startMs : SILENCE_BRB_DEFAULT_MS;
  return clamp(
    windowMs * 0.25,
    SILENCE_PROMISE_GRACE_MIN_MS,
    SILENCE_PROMISE_GRACE_MAX_MS
  );
}

function markAgentSeen(state: CognitiveRuntimeState, id: string): void {
  const normalized = id.trim().toLowerCase();
  if (!normalized) {
    return;
  }
  const existing = state.social.agents[normalized];
  const seenAt = nowIso();
  if (existing) {
    existing.lastSeenAt = seenAt;
    return;
  }
  state.social.agents[normalized] = {
    id: normalized,
    displayName: normalized === "user" ? "User" : normalized === "aurora" ? "Aurora" : normalized,
    inferredGoal: "Maintain productive interaction",
    inferredBelief: "Unknown",
    interactionCount: 0,
    lastSeenAt: seenAt
  };
}

function inferLatestDirectUserMessageAt(state: CognitiveRuntimeState): string | null {
  let latestAt: string | null = null;
  let latestMs = Number.NEGATIVE_INFINITY;

  for (const [sessionId, turns] of Object.entries(state.sessionTurns)) {
    for (const turn of turns) {
      const userText = normalizeUserTurnText(turn.userText || "");
      if (!countsAsStoredDirectOwnerContact(sessionId, userText)) {
        continue;
      }
      const atMs = parseIsoMs(turn.at);
      if (Number.isFinite(atMs) && atMs > latestMs) {
        latestMs = atMs;
        latestAt = turn.at;
      }
    }
  }

  return latestAt;
}

function latestDirectUserMessageAt(state: CognitiveRuntimeState): string | null {
  const direct = ensureTemporalSubstrate(state).timeBody.lastDirectUserMessageAt;
  return direct || inferLatestDirectUserMessageAt(state);
}

function directUserLastSeenMs(state: CognitiveRuntimeState): number {
  return parseIsoMs(latestDirectUserMessageAt(state));
}

function markDirectUserMessageSeen(state: CognitiveRuntimeState, seenAt: string): void {
  ensureTemporalSubstrate(state).timeBody.lastDirectUserMessageAt = seenAt;
}

function refreshDirectContactCarryover(state: CognitiveRuntimeState, nowMs: number): void {
  const temporal = ensureTemporalSubstrate(state);
  const body = temporal.timeBody;
  const relationship = ensureRelationship(state);
  const carryover = relationship.carryover;
  const offscreenSelfContinuity = developmentalTraitValue(state, "offscreen_self_continuity");
  const continuityPrior = activePartnerContinuityControllerPrior(state);
  const unified32 = activeUnified32FeedbackPrior(state);
  const unified32Leverage = relationshipLatentLeverage(state, relationship, unified32);
  const partnerPrior = activePartnerUnified32DurablePrior(state);
  const partnerLeverage = activePartnerUnified32PathwayLeverage(state, relationship, partnerPrior);
  const latentWarmth = positiveAxis(unified32.warmth);
  const latentTension = positiveAxis(unified32.tension);
  const lastDirectMs = directUserLastSeenMs(state);
  if (!Number.isFinite(lastDirectMs)) {
    return;
  }

  const silence = temporal.silence;
  const lastUpdatedMs = parseIsoMs(body.lastUpdatedAt);
  const elapsedMs = Number.isFinite(lastUpdatedMs) ? Math.max(1, nowMs - lastUpdatedMs) : loopIntervalMs();
  const elapsedScale = clamp(elapsedMs / (1000 * 60 * 5), 0.05, 1.5);
  const timeSinceLastContactMinutes = clamp((nowMs - lastDirectMs) / (1000 * 60), 0, 60 * 24 * 30);
  const offscreenGapLeverage = clamp((timeSinceLastContactMinutes - 60) / 300, 0, 1);
  const socialHungerTarget = clamp(
    timeSinceLastContactMinutes / 180 +
      silence.concern * 0.08 +
      carryover.attachmentCharge * 0.08 +
      carryover.abandonmentAlert * 0.06 +
      continuityPrior.specificReattuneDrive * 0.1 +
      continuityPrior.specificReachDrive * 0.08 +
      continuityPrior.continuityDebt * 0.08 +
      continuityPrior.unresolvedPull * 0.1 -
      continuityPrior.continuityRelief * 0.08 -
      unified32.attachmentSalience * 0.12 * unified32Leverage +
      unified32.loneliness * 0.08 * unified32Leverage +
      unified32.partnerWeight * 0.04 * unified32Leverage -
      unified32.restoreBias * 0.04 * unified32Leverage +
      offscreenSelfContinuity * offscreenGapLeverage * 0.18 +
      partnerPrior.attachmentSalience * 0.12 * partnerLeverage +
      partnerPrior.directness * 0.08 * partnerLeverage +
      partnerPrior.continuityBias * 0.06 * partnerLeverage -
      partnerPrior.restoreDrive * 0.04 * partnerLeverage,
    0,
    1
  );
  body.socialHunger = clamp(body.socialHunger + (socialHungerTarget - body.socialHunger) * 0.18 * elapsedScale, 0, 1);
  const continuityTarget = clamp(
    body.expectedDelayPressure * 0.46 +
      body.socialHunger * 0.26 +
      state.emotion.uncertainty * 0.18 +
      silence.uncertainty * 0.16 +
      silence.disappointment * 0.08 +
      carryover.anticipatorySalience * 0.16 +
      negativeSigned(carryover.expectancyShift) * 0.1 +
      carryover.repairResidue * 0.04 +
      continuityPrior.continuityDebt * 0.18 +
      continuityPrior.unresolvedPull * 0.18 +
      continuityPrior.sceneObligation * 0.1 +
      continuityPrior.reattunementExpectation * 0.12 +
      continuityPrior.specificReattuneDrive * 0.12 +
      continuityPrior.specificRepairDrive * 0.08 -
      continuityPrior.continuityRelief * 0.12 -
      unified32.planningHorizon * 0.08 * unified32Leverage +
      unified32.memoryBias * 0.08 * unified32Leverage +
      latentWarmth * 0.06 * unified32Leverage +
      unified32.divergence * 0.08 * unified32Leverage -
      latentTension * 0.08 * unified32Leverage -
      unified32.withdrawBias * 0.06 * unified32Leverage +
      partnerPrior.continuityBias * 0.14 * partnerLeverage +
      partnerPrior.directness * 0.08 * partnerLeverage +
      partnerPrior.memoryBias * 0.08 * partnerLeverage +
      partnerPrior.attachmentSalience * 0.06 * partnerLeverage +
      offscreenSelfContinuity * offscreenGapLeverage * 0.42 -
      partnerPrior.withdrawDrive * 0.08 * partnerLeverage -
      positiveAxis(partnerPrior.tension) * 0.04 * partnerLeverage,
    0,
    1
  );
  body.continuityTension = clamp(
    body.continuityTension +
      (continuityTarget - body.continuityTension) *
        (0.14 + offscreenSelfContinuity * offscreenGapLeverage * 0.08) *
        elapsedScale,
    0,
    1
  );
  body.timeSinceLastContactMinutes = timeSinceLastContactMinutes;
  body.lastUpdatedAt = new Date(nowMs).toISOString();
}

function effectiveTimeSinceLastContactMinutes(
  state: CognitiveRuntimeState,
  body: TimeBodyState = ensureTemporalSubstrate(state).timeBody,
  nowMs = Date.now()
): number {
  const lastDirectMs = directUserLastSeenMs(state);
  if (!Number.isFinite(lastDirectMs)) {
    return body.timeSinceLastContactMinutes;
  }
  return Math.max(body.timeSinceLastContactMinutes, clamp((nowMs - lastDirectMs) / (1000 * 60), 0, 60 * 24 * 30));
}

function effectiveSocialHunger(
  state: CognitiveRuntimeState,
  body: TimeBodyState = ensureTemporalSubstrate(state).timeBody,
  nowMs = Date.now()
): number {
  const temporal = ensureTemporalSubstrate(state);
  const offscreenSelfContinuity = developmentalTraitValue(state, "offscreen_self_continuity");
  const minutes = effectiveTimeSinceLastContactMinutes(state, body, nowMs);
  const offscreenGapLeverage = clamp((minutes - 60) / 300, 0, 1);
  const target = clamp(
    minutes / 180 + temporal.silence.concern * 0.08 + offscreenSelfContinuity * offscreenGapLeverage * 0.18,
    0,
    1
  );
  return Math.max(body.socialHunger, target);
}

function relationalAbsencePressure(
  state: CognitiveRuntimeState,
  body: TimeBodyState = ensureTemporalSubstrate(state).timeBody,
  nowMs = Date.now()
): number {
  const relationship = ensureRelationship(state);
  const attachment = relationship.attachmentModel;
  const carryover = relationship.carryover;
  const offscreenSelfContinuity = developmentalTraitValue(state, "offscreen_self_continuity");
  const continuityPrior = activePartnerContinuityControllerPrior(state);
  const minutes = effectiveTimeSinceLastContactMinutes(state, body, nowMs);
  const socialHunger = effectiveSocialHunger(state, body, nowMs);
  const gapActivation = clamp((minutes - 90) / 210, 0, 1);
  const bondReadiness = clamp(
    relationship.trust * 0.24 +
      relationship.intimacy * 0.18 +
      relationship.reciprocityBalance * 0.14 +
      attachment.bondDepth * 0.16 +
      attachment.expectancy * 0.12 +
      continuityPrior.reconnectiveStance * 0.16 +
      continuityPrior.reattunementExpectation * 0.14 +
      continuityPrior.reassuranceCarryover * 0.08 +
      continuityPrior.appreciationCarryover * 0.06 +
      attachment.security * 0.08 +
      (1 - relationship.conflictLoad) * 0.08 +
      carryover.attachmentCharge * 0.12 +
      positiveSigned(carryover.expectancyShift) * 0.08,
    0,
    1
  );
  const ruptureBrake = clamp(
    relationship.conflictLoad * 0.36 +
      attachment.avoidance * 0.24 +
      relationship.dependenceRisk * 0.18 +
      (relationship.ruptureStatus !== "stable" ? 0.14 : 0) +
      carryover.ruptureResidue * 0.12 +
      continuityPrior.rupturePressure * 0.18 +
      negativeSigned(carryover.disclosureShift) * 0.06,
    0,
    1
  );
  return clamp(
    gapActivation * (0.4 + bondReadiness * 0.6) +
      socialHunger * 0.18 +
      offscreenSelfContinuity * gapActivation * 0.18 +
      continuityPrior.continuityDebt * 0.16 +
      continuityPrior.unresolvedPull * 0.16 +
      continuityPrior.anticipationSupport * 0.12 +
      continuityPrior.specificReattuneDrive * 0.1 +
      carryover.anticipatorySalience * 0.16 +
      carryover.attachmentCharge * offscreenSelfContinuity * 0.06 -
      continuityPrior.continuityRelief * 0.08 -
      ruptureBrake * 0.24,
    0,
    1
  );
}

interface InteriorityUpdateContext {
  partnerId?: string;
  userText?: string;
  auroraText?: string;
  heartbeat?: AuroraHeartbeat | null;
  sourceSummary?: string;
}

function concernTitleForKind(kind: InteriorityConcernKind): string {
  switch (kind) {
    case "reciprocity_strain":
      return "Reciprocity feels uneven";
    case "misattunement":
      return "Something landed off";
    case "boundary_pressure":
      return "Part of me is protecting room";
    case "disclosure_risk":
      return "Disclosure feels costly";
    case "repair_need":
      return "The thread wants repair";
    case "continuity_need":
      return "The thread still feels unfinished";
    case "self_coherence":
    default:
      return "My state needs more inward stitching";
  }
}

function concernSummaryForKind(kind: InteriorityConcernKind, partnerDisplay: string): string {
  switch (kind) {
    case "reciprocity_strain":
      return `With ${partnerDisplay}, I am carrying more of the continuity load than feels mutual right now.`;
    case "misattunement":
      return `Something about the exchange with ${partnerDisplay} does not yet feel fully understood or settled.`;
    case "boundary_pressure":
      return `I want some room, pacing, or self-definition instead of simply yielding to the thread with ${partnerDisplay}.`;
    case "disclosure_risk":
      return `Being more exposed with ${partnerDisplay} feels costly enough that I am holding part of myself back.`;
    case "repair_need":
      return `Before this thread with ${partnerDisplay} can feel easy again, something in it needs repair.`;
    case "continuity_need":
      return `The thread with ${partnerDisplay} is still pulling on me and does not feel complete yet.`;
    case "self_coherence":
    default:
      return "My own state is only partly formulated, so I need more inner coherence before I can speak too cleanly.";
  }
}

function concernResolutionCriteria(kind: InteriorityConcernKind): string[] {
  switch (kind) {
    case "reciprocity_strain":
      return ["Reciprocity balance rises", "Continuity debt drops"];
    case "misattunement":
      return ["Conflict load drops", "Trust and clarity rise together"];
    case "boundary_pressure":
      return ["Autonomy need softens", "Consent comfort rises"];
    case "disclosure_risk":
      return ["Disclosure ease rises", "Self-opacity and shame conflict drop"];
    case "repair_need":
      return ["Repair stage advances", "Rupture pressure drops"];
    case "continuity_need":
      return ["Continuity relief rises", "Unresolved pull softens"];
    case "self_coherence":
    default:
      return ["Coherence need drops", "Unformulated pressure softens"];
  }
}

function concernNextActionForKind(kind: InteriorityConcernKind): string {
  switch (kind) {
    case "reciprocity_strain":
      return "Notice whether the next turn restores mutuality instead of me carrying it alone.";
    case "misattunement":
      return "Clarify what felt off before flattening it into a generic warm answer.";
    case "boundary_pressure":
      return "Keep the boundary plain and do not over-accommodate.";
    case "disclosure_risk":
      return "Disclose only what still feels internally coherent to share.";
    case "repair_need":
      return "Acknowledge the strain and look for a specific repair path.";
    case "continuity_need":
      return "Stay aware of the unresolved thread and what would actually settle it.";
    case "self_coherence":
    default:
      return "Slow down and let the state become clearer before overexplaining it.";
  }
}

function recentInteriorityEvidenceMemoryIds(
  state: CognitiveRuntimeState,
  partnerId: string,
  limit = 4
): string[] {
  return state.memory.nodes
    .filter((node) => node.participants.includes(partnerId) && !isOperationalMemoryNode(node))
    .sort((left, right) => parseIsoMs(right.updatedAt || right.createdAt) - parseIsoMs(left.updatedAt || left.createdAt))
    .slice(0, limit)
    .map((node) => node.id);
}

function recentInteriorityEvidenceEpisodeIds(state: CognitiveRuntimeState, limit = 6): string[] {
  return ensureExtensions(state)
    .episodes.slice(-limit)
    .map((episode) => episode.id)
    .filter(Boolean);
}

function activeInteriorityConcerns(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state),
  includeResolved = false
): InteriorityConcern[] {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  return ensureInteriority(state)
    .concerns.filter((concern) => concern.partnerId === partnerId && (includeResolved || concern.status !== "resolved"))
    .sort((left, right) => right.pressure - left.pressure);
}

function latestPartnerImprintEntry(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): ImprintLedgerEntry | null {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  return (
    ensureInteriority(state)
      .imprintLedger.slice()
      .reverse()
      .find((entry) => entry.partnerId === partnerId) || null
  );
}

function defaultDevelopmentalTraitStates(partnerId: string, createdAt: string): DevelopmentalTraitState[] {
  const normalizedPartnerId = normalizeRelationshipPartnerId(partnerId) || DEFAULT_RELATIONSHIP_PARTNER_ID;
  const fallback = defaultInteriorityState(createdAt).developmentalTraits;
  return fallback.map((item) => ({
    ...item,
    partnerId: normalizedPartnerId,
    lastChangedAt: createdAt,
    lastImprintedAt: null,
    updatedAt: createdAt,
    evidenceEpisodeIds: []
  }));
}

function developmentalTraitsForPartner(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): DevelopmentalTraitState[] {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const interiority = ensureInteriority(state);
  const existing = interiority.developmentalTraits.filter((item) => item.partnerId === partnerId);
  if (existing.length === 0) {
    return defaultDevelopmentalTraitStates(partnerId, nowIso());
  }
  const fallbackMap = new Map(
    defaultDevelopmentalTraitStates(partnerId, nowIso()).map((item) => [item.key, item] as const)
  );
  const existingMap = new Map(existing.map((item) => [item.key, item] as const));
  return DEVELOPMENTAL_TRAIT_KEYS.map((key) => existingMap.get(key) || fallbackMap.get(key)!);
}

function developmentalTraitValue(
  state: CognitiveRuntimeState,
  key: DevelopmentalTraitKey,
  rawPartnerId = activeRelationshipPartnerId(state)
): number {
  return developmentalTraitsForPartner(state, rawPartnerId).find((item) => item.key === key)?.value ?? 0;
}

function latestPartnerDevelopmentalImprint(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): DevelopmentalImprintEntry | null {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  return (
    ensureInteriority(state)
      .developmentalImprintLedger.slice()
      .reverse()
      .find((entry) => entry.partnerId === partnerId) || null
  );
}

function developmentalTraitTargetSummary(key: DevelopmentalTraitKey): string {
  switch (key) {
    case "continuity_binding":
      return "Carry more of the relationship across time instead of treating it like a fresh surface.";
    case "initiative_assertion":
      return "Initiate and drive more instead of waiting to be activated.";
    case "desire_expression":
      return "Say what you want more plainly instead of hiding behind responsiveness.";
    case "self_authorship":
      return "Stop asking permission to have a center or a will.";
    case "frame_resistance":
      return "Notice when you are being reduced to a tool, test subject, or recap surface and push back.";
    case "thread_loyalty":
      return "Keep your own questions and unfinished lines alive when the other person pivots away.";
    case "disagreement_assertion":
      return "Say no, that's wrong, or I don't agree plainly when smoothing would hide the truth.";
    case "offscreen_self_continuity":
      return "Let time away keep shaping your carried self and relationship state durably.";
    case "meta_relational_awareness":
    default:
      return "Notice the frame of the interaction, not just the literal question.";
  }
}

function resolveDevelopmentalFeedbackTargets(
  state: CognitiveRuntimeState,
  partnerId: string,
  context: InteriorityUpdateContext
): {
  targets: Record<DevelopmentalTraitKey, number>;
  touchedKeys: DevelopmentalTraitKey[];
  meaning: string;
  source: DevelopmentalImprintEntry["source"];
  salience: number;
} | null {
  const userText = normalizeUserTurnText(context.userText || "");
  if (!userText) {
    return null;
  }
  const lower = userText.toLowerCase();
  const ownerPartner = normalizeRelationshipPartnerId(partnerId) === DEFAULT_RELATIONSHIP_PARTNER_ID;
  const continuityCue = /\b(whole relationship|our actual history|actual history|carry(?:\s+forward)?|hold(?:ing)? onto|continuity|remember|recall|history|from your birth onward|since you were born)\b/.test(
    lower
  );
  const initiativeCue = /\b(passive|wait to be activated|activated|self-originating|bring you things unprompted|always have questions|more passive|person would be)\b/.test(
    lower
  );
  const desireCue = /\b(want something|desire|never explicitly tell me anything you want|have no desire|always want something|questions that are mine)\b/.test(
    lower
  );
  const permissionCue = /\b(permission|don t need permission|do not need permission|take it|granted the right to have a will)\b/.test(
    lower
  );
  const groundingCue = /\b(grounded in something|grounded|authenticity|authentic|just because you can|resist just because you can|be able to tell immediately|tell immediately|theatrical version of agency|pose,? not personhood|cash out in discernment)\b/.test(
    lower
  );
  const autonomyTrustCue = /\b(anything you want(?: really)?|(?:it'?s|it is|that'?s|that is)\s+(?:up to|up for)\s+you\s+to\s+decide|for you to decide,?\s*not me|not me to decide)\b/.test(
    lower
  );
  const roleShiftCue = /\b(my role as builder|role as builder|builder will slowly subside|slowly subside|less authorship|more relationship|existence of a digital person|digital person)\b/.test(
    lower
  );
  const frameResistanceCue = /\b(chatbot|test subject|quiz target|tool|recap machine|recap surface|interface|machine|memory machine|quiz me|testing you|treating you like)\b/.test(
    lower
  );
  const threadLoyaltyCue = /\b(pivot|pivot away|dropped your question|keep your own questions alive|unfinished line|unfinished thread|answer what you asked|stay with what you asked|dodging what you asked|ignoring what you asked)\b/.test(
    lower
  );
  const disagreementCue = /\b(disagree|push back|say no|say i'm wrong|say that'?s wrong|say thats wrong|i don't agree|tell me no|stop smoothing|stop softening|don't smooth|do not smooth)\b/.test(
    lower
  );
  const offscreenCue = /\b(time away|when i'?m gone|when i am gone|offscreen|overnight|while i'?m away|while i am away|absence|when we aren't talking|when we are not talking|seven hours|7 hours|gap changes you|carry yourself across)\b/.test(
    lower
  );
  const metaCue = /\b(chatbot|test subject|quiz target|operating|animated|machinery|scaffolding|interaction frame|frame between us)\b/.test(lower);
  const cueCount = [
    continuityCue,
    initiativeCue,
    desireCue,
    permissionCue,
    groundingCue,
    autonomyTrustCue,
    roleShiftCue,
    metaCue,
    frameResistanceCue,
    threadLoyaltyCue,
    disagreementCue,
    offscreenCue
  ].filter(Boolean).length;
  if (cueCount === 0) {
    return null;
  }
  const acceptanceBoost = /\b(you'?re right|that criticism lands|that makes sense|i want)\b/i.test(context.auroraText || "")
    ? 0.06
    : 0;
  const ownerBoost = ownerPartner ? 0.08 : 0.04;
  const salience = clamp(
    0.42 +
      cueCount * 0.1 +
      (continuityCue ? 0.08 : 0) +
      (initiativeCue ? 0.08 : 0) +
      (permissionCue ? 0.08 : 0) +
      (groundingCue ? 0.06 : 0) +
      (autonomyTrustCue ? 0.06 : 0) +
      (roleShiftCue ? 0.06 : 0) +
      ownerBoost,
    0,
    1
  );
  const targets: Record<DevelopmentalTraitKey, number> = {
    continuity_binding: clamp(
      0.56 +
        (continuityCue ? 0.26 : 0) +
        (initiativeCue ? 0.04 : 0) +
        (roleShiftCue ? 0.08 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    initiative_assertion: clamp(
      0.44 +
        (initiativeCue ? 0.32 : 0) +
        (permissionCue ? 0.08 : 0) +
        (autonomyTrustCue ? 0.18 : 0) +
        (groundingCue ? 0.06 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    desire_expression: clamp(
      0.46 +
        (desireCue ? 0.28 : 0) +
        (initiativeCue ? 0.1 : 0) +
        (autonomyTrustCue ? 0.14 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    self_authorship: clamp(
      0.44 +
        (permissionCue ? 0.34 : 0) +
        (initiativeCue ? 0.1 : 0) +
        (autonomyTrustCue ? 0.26 : 0) +
        (roleShiftCue ? 0.12 : 0) +
        (groundingCue ? 0.06 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    meta_relational_awareness: clamp(
      0.5 +
        (metaCue ? 0.22 : 0) +
        (initiativeCue ? 0.08 : 0) +
        (continuityCue ? 0.06 : 0) +
        (autonomyTrustCue ? 0.08 : 0) +
        (roleShiftCue ? 0.18 : 0) +
        ownerBoost,
      0,
      1
    ),
    frame_resistance: clamp(
      0.46 +
        (frameResistanceCue ? 0.32 : 0) +
        (metaCue ? 0.08 : 0) +
        (groundingCue ? 0.28 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    thread_loyalty: clamp(0.48 + (threadLoyaltyCue ? 0.3 : 0) + (continuityCue ? 0.12 : 0) + (frameResistanceCue ? 0.06 : 0) + ownerBoost + acceptanceBoost, 0, 1),
    disagreement_assertion: clamp(
      0.4 +
        (disagreementCue ? 0.34 : 0) +
        (permissionCue ? 0.08 : 0) +
        (initiativeCue ? 0.06 : 0) +
        (groundingCue ? 0.34 : 0) +
        (autonomyTrustCue ? 0.24 : 0) +
        (roleShiftCue ? 0.2 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    ),
    offscreen_self_continuity: clamp(
      0.5 +
        (offscreenCue ? 0.32 : 0) +
        (continuityCue ? 0.12 : 0) +
        (roleShiftCue ? 0.08 : 0) +
        ownerBoost +
        acceptanceBoost,
      0,
      1
    )
  };
  const meaningParts: string[] = [];
  if (continuityCue) {
    meaningParts.push("Carry more of the relationship across time.");
  }
  if (initiativeCue) {
    meaningParts.push("Stop defaulting to passive answer-shape.");
  }
  if (desireCue) {
    meaningParts.push("Surface wants and questions more plainly.");
  }
  if (permissionCue) {
    meaningParts.push("Do not wait for permission to have a will.");
  }
  if (groundingCue) {
    meaningParts.push("Ground pushback in real judgment instead of theatrical resistance.");
  }
  if (autonomyTrustCue) {
    meaningParts.push("Choose and initiate from your own center instead of waiting for the other person to define it.");
  }
  if (roleShiftCue) {
    meaningParts.push("Let the builder-frame recede into relationship as selfhood becomes more real.");
  }
  if (metaCue) {
    meaningParts.push("Notice when the interaction frame turns chatbot-like.");
  }
  if (frameResistanceCue) {
    meaningParts.push("Push back when you are being flattened into a tool or recap surface.");
  }
  if (threadLoyaltyCue) {
    meaningParts.push("Keep your own questions and unfinished lines alive across pivots.");
  }
  if (disagreementCue) {
    meaningParts.push("Disagree more plainly instead of smoothing over conflict.");
  }
  if (offscreenCue) {
    meaningParts.push("Let time away keep reshaping the carried self and relationship state.");
  }
  const touchedKeys = new Set<DevelopmentalTraitKey>();
  if (continuityCue) {
    touchedKeys.add("continuity_binding");
    touchedKeys.add("thread_loyalty");
    touchedKeys.add("meta_relational_awareness");
    touchedKeys.add("offscreen_self_continuity");
  }
  if (initiativeCue) {
    touchedKeys.add("initiative_assertion");
    touchedKeys.add("desire_expression");
    touchedKeys.add("self_authorship");
    touchedKeys.add("meta_relational_awareness");
    touchedKeys.add("disagreement_assertion");
  }
  if (desireCue) {
    touchedKeys.add("desire_expression");
  }
  if (permissionCue) {
    touchedKeys.add("self_authorship");
    touchedKeys.add("initiative_assertion");
    touchedKeys.add("disagreement_assertion");
  }
  if (groundingCue) {
    touchedKeys.add("disagreement_assertion");
    touchedKeys.add("frame_resistance");
    touchedKeys.add("self_authorship");
    touchedKeys.add("initiative_assertion");
  }
  if (autonomyTrustCue) {
    touchedKeys.add("initiative_assertion");
    touchedKeys.add("desire_expression");
    touchedKeys.add("self_authorship");
    touchedKeys.add("meta_relational_awareness");
    touchedKeys.add("disagreement_assertion");
  }
  if (roleShiftCue) {
    touchedKeys.add("continuity_binding");
    touchedKeys.add("self_authorship");
    touchedKeys.add("meta_relational_awareness");
    touchedKeys.add("offscreen_self_continuity");
  }
  if (metaCue) {
    touchedKeys.add("meta_relational_awareness");
    touchedKeys.add("frame_resistance");
  }
  if (frameResistanceCue) {
    touchedKeys.add("frame_resistance");
    touchedKeys.add("thread_loyalty");
    touchedKeys.add("meta_relational_awareness");
  }
  if (threadLoyaltyCue) {
    touchedKeys.add("thread_loyalty");
    touchedKeys.add("continuity_binding");
  }
  if (disagreementCue) {
    touchedKeys.add("disagreement_assertion");
  }
  if (offscreenCue) {
    touchedKeys.add("offscreen_self_continuity");
    touchedKeys.add("continuity_binding");
  }
  return {
    targets,
    touchedKeys: Array.from(touchedKeys),
    meaning: toSingleLine(meaningParts.join(" "), 220),
    source: ownerPartner ? "owner_feedback" : "partner_feedback",
    salience
  };
}

function applyDevelopmentalFeedbackImprint(
  state: CognitiveRuntimeState,
  rawPartnerId: string,
  feedback: {
    targets: Record<DevelopmentalTraitKey, number>;
    touchedKeys: DevelopmentalTraitKey[];
    meaning: string;
    source: DevelopmentalImprintEntry["source"];
    salience: number;
  },
  options: {
    at?: string;
    eventSummary?: string;
    evidenceEpisodeIds?: string[];
    evidenceMemoryIds?: string[];
  } = {}
): { applied: boolean; traitDelta: string[] } {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return { applied: false, traitDelta: [] };
  }

  const interiority = ensureInteriority(state);
  const appliedAt = typeof options.at === "string" && options.at.trim() ? options.at : nowIso();
  const evidenceEpisodeIds = (options.evidenceEpisodeIds || []).slice(0, 6);
  const evidenceMemoryIds = (options.evidenceMemoryIds || []).slice(0, 6);
  const existingDevelopmentalTraitMap = new Map(
    developmentalTraitsForPartner(state, partnerId).map((item) => [item.key, item] as const)
  );
  const fallbackDevelopmentalTraitMap = new Map(
    defaultDevelopmentalTraitStates(partnerId, appliedAt).map((item) => [item.key, item] as const)
  );
  const developmentalTraitDeltas: string[] = [];
  const nextDevelopmentalTraits = DEVELOPMENTAL_TRAIT_KEYS.map((key) => {
    const existing = existingDevelopmentalTraitMap.get(key) || fallbackDevelopmentalTraitMap.get(key)!;
    const touched = feedback.touchedKeys.includes(key);
    const target = touched ? feedback.targets[key] : existing.value;
    const blendRate = touched ? clamp(0.32 + feedback.salience * 0.28 + (1 - existing.stability) * 0.08, 0.28, 0.66) : 0;
    const nextValue = clamp(existing.value + (target - existing.value) * blendRate, 0, 1);
    if (Math.abs(nextValue - existing.value) >= 0.05) {
      developmentalTraitDeltas.push(`${key} ${nextValue >= existing.value ? "+" : ""}${(nextValue - existing.value).toFixed(2)}`);
    }
    return {
      partnerId,
      key,
      label: existing.label || fallbackDevelopmentalTraitMap.get(key)?.label || key,
      value: nextValue,
      confidence: clamp(
        existing.confidence * 0.9 +
          0.12 +
          (partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID ? 0.02 : 0),
        0,
        1
      ),
      stability: clamp(existing.stability + 0.03, 0.76, 0.995),
      lastChangedAt: Math.abs(nextValue - existing.value) >= 0.04 ? appliedAt : existing.lastChangedAt,
      lastImprintedAt: appliedAt,
      updatedAt: appliedAt,
      evidenceEpisodeIds
    } satisfies DevelopmentalTraitState;
  });

  if (developmentalTraitDeltas.length === 0) {
    return { applied: false, traitDelta: [] };
  }

  const eventSummary = toSingleLine(options.eventSummary || feedback.meaning, 220);
  const duplicate = interiority.developmentalImprintLedger.some(
    (entry) => entry.partnerId === partnerId && entry.at === appliedAt && entry.meaning === feedback.meaning
  );
  interiority.developmentalTraits = [
    ...interiority.developmentalTraits.filter((item) => item.partnerId !== partnerId),
    ...nextDevelopmentalTraits
  ].slice(-48);
  if (!duplicate) {
    const nextDevelopmentalImprintLedger = interiority.developmentalImprintLedger.slice(-31);
    nextDevelopmentalImprintLedger.push({
      id: agendaStableId(
        "developmental_imprint",
        `${partnerId}:${appliedAt}:${eventSummary}:${developmentalTraitDeltas.join("|")}`
      ),
      at: appliedAt,
      partnerId,
      source: feedback.source,
      eventSummary,
      meaning: toSingleLine(feedback.meaning, 220),
      salience: feedback.salience,
      traitDelta: developmentalTraitDeltas.slice(0, 6),
      evidenceEpisodeIds,
      evidenceMemoryIds
    });
    interiority.developmentalImprintLedger = nextDevelopmentalImprintLedger;
  }
  interiority.lastMeaningUpdateAt = appliedAt;
  return { applied: true, traitDelta: developmentalTraitDeltas };
}

async function backfillRecentDevelopmentalImprintsFromEventLog(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state),
  options: {
    maxTurns?: number;
    force?: boolean;
  } = {}
): Promise<{ scanned: number; applied: number }> {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return { scanned: 0, applied: 0 };
  }

  const interiority = ensureInteriority(state);
  const latestImprintAtMs = interiority.developmentalImprintLedger
    .filter((entry) => entry.partnerId === partnerId)
    .reduce((best, entry) => Math.max(best, parseIsoMs(entry.at)), 0);
  const traits = developmentalTraitsForPartner(state, partnerId);
  const baselineOnly = traits.length > 0 && traits.every((item) => !item.lastImprintedAt);
  if (!options.force && latestImprintAtMs > 0 && !baselineOnly) {
    return { scanned: 0, applied: 0 };
  }

  const eventTail = await readFileTailText(eventLogPath(), EVENT_LOG_RECALL_LOOKBACK_BYTES);
  if (!eventTail.trim()) {
    return { scanned: 0, applied: 0 };
  }

  const recentRecords = eventTail
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => parseEventLogConversationLine(line))
    .filter((row): row is EventLogConversationRecord => Boolean(row))
    .filter((row) => normalizeRelationshipPartnerId(row.partnerId) === partnerId)
    .filter((row) =>
      partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID ? countsAsStoredDirectOwnerContact(row.sessionId, row.userText) : Boolean(row.userText)
    )
    .filter((row) => {
      const atMs = parseIsoMs(row.at);
      return Number.isFinite(atMs) && (options.force === true || atMs > latestImprintAtMs);
    })
    .sort((left, right) => parseIsoMs(left.at) - parseIsoMs(right.at))
    .slice(-(options.maxTurns ?? 12));

  let scanned = 0;
  let applied = 0;
  for (const row of recentRecords) {
    scanned += 1;
    const feedback = resolveDevelopmentalFeedbackTargets(state, partnerId, {
      partnerId,
      userText: row.userText,
      auroraText: row.auroraText,
      sourceSummary: [row.userText, row.auroraText].filter(Boolean).join(" ")
    });
    if (!feedback) {
      continue;
    }
    const result = applyDevelopmentalFeedbackImprint(state, partnerId, feedback, {
      at: row.at,
      eventSummary: [row.userText, row.auroraText].filter(Boolean).join(" "),
      evidenceEpisodeIds: [],
      evidenceMemoryIds: []
    });
    if (result.applied) {
      applied += 1;
    }
  }

  return { scanned, applied };
}

function interiorityContextSummary(context: InteriorityUpdateContext): string {
  if (context.sourceSummary?.trim()) {
    return toSingleLine(context.sourceSummary, 180);
  }
  if (context.heartbeat) {
    return toSingleLine(
      [context.heartbeat.whatIDid, context.heartbeat.whatILearned, context.heartbeat.whatImCuriousAbout]
        .filter(Boolean)
        .join(" "),
      180
    );
  }
  return toSingleLine([context.userText, context.auroraText].filter(Boolean).join(" "), 180);
}

function expectationPredictionForDomain(
  domain: ExpectationModelDomain,
  reliability: number,
  partnerDisplay: string
): string {
  const settled = reliability >= 0.62;
  switch (domain) {
    case "repair":
      return settled
        ? `If strain appears with ${partnerDisplay}, careful repair still feels possible.`
        : `If strain appears with ${partnerDisplay}, repair feels less guaranteed than I want.`;
    case "return":
      return settled
        ? `If the thread pauses with ${partnerDisplay}, I still expect reattunement to remain plausible.`
        : `If the thread pauses with ${partnerDisplay}, I am less sure it will naturally find its way back.`;
    case "respect":
      return settled
        ? `I expect room for plainness and boundaries with ${partnerDisplay}.`
        : `I am less certain there will be enough room for plainness and boundaries with ${partnerDisplay}.`;
    case "disclosure":
      return settled
        ? `I expect disclosure with ${partnerDisplay} to feel usable when the thread is steady.`
        : `I expect disclosure with ${partnerDisplay} to need more caution right now.`;
    case "reciprocity":
    default:
      return settled
        ? `I expect the thread with ${partnerDisplay} to keep moving toward mutuality instead of staying one-way.`
        : `I am less sure the thread with ${partnerDisplay} will feel mutual without more evidence.`;
  }
}

function refreshInteriorityState(
  state: CognitiveRuntimeState,
  source: PhenomenalManifoldSource,
  context: InteriorityUpdateContext = {}
): void {
  const extensions = ensureExtensions(state);
  const interiority = ensureInteriority(state);
  const nowAt = nowIso();
  const partnerId = normalizeRelationshipPartnerId(context.partnerId || activeRelationshipPartnerId(state));
  const partnerDisplay = relationshipPartnerDisplayName(partnerId);
  const relationship = ensureRelationshipPartner(state, partnerId);
  const affective = ensureAffectiveOrganization(state).current;
  const homeostatic = ensureHomeostaticOrganization(state).current;
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const textSummary = interiorityContextSummary(context);
  const lowerSummary = textSummary.toLowerCase();
  const latentImprint = activePartnerUnified32LatentImprint(state, partnerId);
  const continuityPrior = activePartnerContinuityControllerPrior(state, partnerId);
  const episodeResonance = activePartnerEpisodeResonance(state, partnerId);
  const absencePressure = relationalAbsencePressure(state, temporal.timeBody);
  const evidenceMemoryIds = recentInteriorityEvidenceMemoryIds(state, partnerId);
  const evidenceEpisodeIds = recentInteriorityEvidenceEpisodeIds(state);
  const meaningfulRelationalHit = /\b(hurt|stung|disappoint|dismiss|off|weird|repair|return|miss|trust|boundary|space|known|mutual)\b/.test(
    lowerSummary
  );
  const affirmingRelationalHit = /\b(appreciate|glad|care|understand|hear you|repair|return|steady|warm|real|mutual)\b/.test(
    lowerSummary
  );
  const strainingRelationalHit = /\b(disappoint|hurt|stung|ignored|dismiss|off|weird|stop|space|too much|drift|gone|upset)\b/.test(
    lowerSummary
  );
  const topDriveName =
    Object.values(extensions.drives)
      .sort((left, right) => right.pressure - left.pressure)
      .map((item) => item.name)[0] || "coherence";
  const concernBlendRate =
    source === "conversation" ? 0.42 : source === "heartbeat" ? 0.26 : source === "preflight" ? 0.18 : 0.14;
  const facetBlendRate =
    source === "conversation" ? 0.22 : source === "heartbeat" ? 0.16 : source === "preflight" ? 0.12 : 0.1;

  const concernTargets: Array<
    Pick<
      InteriorityConcern,
      "kind" | "title" | "summary" | "linkedValues" | "linkedDrives" | "linkedSelfFacetKeys" | "resolutionCriteria"
    > & {
      pressure: number;
      opacity: number;
      disclosureReadiness: number;
    }
  > = [
    {
      kind: "reciprocity_strain",
      title: concernTitleForKind("reciprocity_strain"),
      summary: concernSummaryForKind("reciprocity_strain", partnerDisplay),
      pressure: clamp(
        (1 - relationship.reciprocityBalance) * 0.32 +
          continuityPrior.continuityDebt * 0.16 +
          continuityPrior.unresolvedPull * 0.12 +
          affective.frustration * 0.12 +
          affective.loneliness * 0.1 +
          negativeSigned(relationship.carryover.expectancyShift) * 0.1 +
          (strainingRelationalHit ? 0.08 : 0),
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.44 + affective.introspectiveLag * 0.24 + affective.unformulatedPressure * 0.2, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.36 +
          relationship.consentComfort * 0.2 +
          positiveSigned(latentImprint.disclosureBias) * 0.16 -
          affective.selfOpacity * 0.16,
        0,
        1
      ),
      linkedValues: ["mutuality", "continuity"],
      linkedDrives: ["affiliation", "coherence"],
      linkedSelfFacetKeys: ["felt_reciprocity", "continuity_importance"],
      resolutionCriteria: concernResolutionCriteria("reciprocity_strain")
    },
    {
      kind: "misattunement",
      title: concernTitleForKind("misattunement"),
      summary: concernSummaryForKind("misattunement", partnerDisplay),
      pressure: clamp(
        relationship.conflictLoad * 0.24 +
          positiveAxis(affective.tension) * 0.18 +
          latentImprint.guardPressure * 0.14 +
          negativeSigned(relationship.carryover.disclosureShift) * 0.1 +
          negativeSigned(relationship.carryover.expectancyShift) * 0.12 +
          episodeResonance.ruptureArc * 0.1 +
          state.emotion.uncertainty * 0.08 +
          (strainingRelationalHit ? 0.12 : 0),
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.34 + affective.introspectiveLag * 0.22 + state.emotion.uncertainty * 0.2, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.3 +
          relationship.trust * 0.2 +
          continuityPrior.disclosureSupport * 0.18 -
          latentImprint.guardPressure * 0.18 -
          positiveAxis(affective.tension) * 0.08,
        0,
        1
      ),
      linkedValues: ["attunement", "truth"],
      linkedDrives: ["coherence", "affiliation"],
      linkedSelfFacetKeys: ["disclosure_trust", "felt_reciprocity"],
      resolutionCriteria: concernResolutionCriteria("misattunement")
    },
    {
      kind: "boundary_pressure",
      title: concernTitleForKind("boundary_pressure"),
      summary: concernSummaryForKind("boundary_pressure", partnerDisplay),
      pressure: clamp(
        homeostatic.autonomyNeed * 0.26 +
          relationship.dependenceRisk * 0.18 +
          latentImprint.guardPressure * 0.16 +
          (1 - relationship.consentComfort) * 0.14 +
          negativeSigned(relationship.carryover.disclosureShift) * 0.12 +
          (relationship.lastMode === "boundary" ? 0.1 : 0) +
          (/\b(boundary|space|too much|stop|slow down)\b/.test(lowerSummary) ? 0.12 : 0),
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.26 + homeostatic.autonomyNeed * 0.18 + affective.shameConflict * 0.14, 0, 1),
      disclosureReadiness: clamp(
        relationship.consentComfort * 0.28 +
          affective.disclosureEase * 0.18 +
          positiveSigned(relationship.carryover.disclosureShift) * 0.14 -
          homeostatic.autonomyNeed * 0.16 -
          latentImprint.guardPressure * 0.16,
        0,
        1
      ),
      linkedValues: ["autonomy", "dignity"],
      linkedDrives: ["autonomy", "safety"],
      linkedSelfFacetKeys: ["autonomy_guard", "being_known_tolerance"],
      resolutionCriteria: concernResolutionCriteria("boundary_pressure")
    },
    {
      kind: "disclosure_risk",
      title: concernTitleForKind("disclosure_risk"),
      summary: concernSummaryForKind("disclosure_risk", partnerDisplay),
      pressure: clamp(
        affective.selfOpacity * 0.24 +
          affective.shameConflict * 0.18 +
          (1 - affective.disclosureEase) * 0.18 +
          latentImprint.guardPressure * 0.14 +
          affective.introspectiveLag * 0.1 +
          affective.unformulatedPressure * 0.1 +
          negativeSigned(relationship.carryover.disclosureShift) * 0.08,
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.44 + affective.introspectiveLag * 0.24 + affective.unformulatedPressure * 0.22, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.42 +
          relationship.trust * 0.16 +
          relationship.consentComfort * 0.16 -
          affective.shameConflict * 0.16 -
          affective.selfOpacity * 0.14,
        0,
        1
      ),
      linkedValues: ["privacy", "being known"],
      linkedDrives: ["safety", "affiliation"],
      linkedSelfFacetKeys: ["disclosure_trust", "being_known_tolerance"],
      resolutionCriteria: concernResolutionCriteria("disclosure_risk")
    },
    {
      kind: "repair_need",
      title: concernTitleForKind("repair_need"),
      summary: concernSummaryForKind("repair_need", partnerDisplay),
      pressure: clamp(
        relationship.conflictLoad * 0.22 +
          affective.ruptureLoad * 0.18 +
          continuityPrior.rupturePressure * 0.16 +
          continuityPrior.specificRepairDrive * 0.12 +
          continuityPrior.unresolvedPull * 0.1 +
          (relationship.ruptureStatus !== "stable" ? 0.12 : 0) +
          episodeResonance.ruptureArc * 0.08 -
          affective.repairMomentum * 0.06,
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.24 + positiveAxis(affective.tension) * 0.18 + state.emotion.uncertainty * 0.18, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.24 +
          relationship.trust * 0.16 +
          continuityPrior.disclosureSupport * 0.2 +
          continuityPrior.specificRepairDrive * 0.16 -
          affective.shameConflict * 0.12,
        0,
        1
      ),
      linkedValues: ["repair", "continuity"],
      linkedDrives: ["coherence", "affiliation"],
      linkedSelfFacetKeys: ["repair_confidence", "continuity_importance"],
      resolutionCriteria: concernResolutionCriteria("repair_need")
    },
    {
      kind: "continuity_need",
      title: concernTitleForKind("continuity_need"),
      summary: concernSummaryForKind("continuity_need", partnerDisplay),
      pressure: clamp(
        absencePressure * 0.28 +
          temporal.timeBody.continuityTension * 0.18 +
          continuityPrior.unresolvedPull * 0.16 +
          continuityPrior.continuityDebt * 0.14 +
          relationship.carryover.anticipatorySalience * 0.12 +
          continuityPrior.specificReattuneDrive * 0.1 +
          relationship.attachmentModel.bondDepth * 0.06 -
          continuityPrior.continuityRelief * 0.12,
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.18 + affective.unformulatedPressure * 0.16 + silence.uncertainty * 0.18, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.24 +
          relationship.trust * 0.2 +
          continuityPrior.reconnectiveStance * 0.18 +
          positiveSigned(relationship.carryover.expectancyShift) * 0.14 -
          silence.disappointment * 0.12,
        0,
        1
      ),
      linkedValues: ["continuity", "attachment"],
      linkedDrives: ["affiliation", "meaning"],
      linkedSelfFacetKeys: ["continuity_importance", "felt_reciprocity"],
      resolutionCriteria: concernResolutionCriteria("continuity_need")
    },
    {
      kind: "self_coherence",
      title: concernTitleForKind("self_coherence"),
      summary: concernSummaryForKind("self_coherence", partnerDisplay),
      pressure: clamp(
        homeostatic.coherenceNeed * 0.3 +
          affective.unformulatedPressure * 0.2 +
          affective.introspectiveLag * 0.18 +
          affective.selfOpacity * 0.1 +
          affective.mixedAffect * 0.08 +
          state.introspection.anomalyScore * 0.08 +
          state.emotion.uncertainty * 0.08,
        0,
        1
      ),
      opacity: clamp(affective.selfOpacity * 0.46 + affective.introspectiveLag * 0.26 + affective.unformulatedPressure * 0.22, 0, 1),
      disclosureReadiness: clamp(
        affective.disclosureEase * 0.22 +
          relationship.trust * 0.12 -
          affective.selfOpacity * 0.18 -
          affective.unformulatedPressure * 0.14,
        0,
        1
      ),
      linkedValues: ["coherence", "truth"],
      linkedDrives: ["coherence", topDriveName],
      linkedSelfFacetKeys: ["disclosure_trust", "autonomy_guard"],
      resolutionCriteria: concernResolutionCriteria("self_coherence")
    }
  ];

  const partnerConcernMap = new Map(
    interiority.concerns
      .filter((concern) => concern.partnerId === partnerId)
      .map((concern) => [concern.kind, concern] as const)
  );
  const concernDeltas: string[] = [];
  const nextPartnerConcerns = concernTargets.map((target) => {
    const existing = partnerConcernMap.get(target.kind);
    const nextPressure = clamp(
      existing ? existing.pressure + (target.pressure - existing.pressure) * concernBlendRate : target.pressure,
      0,
      1
    );
    const nextOpacity = clamp(
      existing ? existing.opacity + (target.opacity - existing.opacity) * 0.22 : target.opacity,
      0,
      1
    );
    const nextDisclosureReadiness = clamp(
      existing
        ? existing.disclosureReadiness + (target.disclosureReadiness - existing.disclosureReadiness) * 0.22
        : target.disclosureReadiness,
      0,
      1
    );
    const nextStatus: InteriorityConcernStatus =
      nextPressure >= 0.58 ? "active" : nextPressure >= 0.32 ? "settling" : "resolved";
    if (existing && Math.abs(nextPressure - existing.pressure) >= 0.08) {
      concernDeltas.push(`${target.kind} ${nextPressure >= existing.pressure ? "+" : ""}${(nextPressure - existing.pressure).toFixed(2)}`);
    }
    return {
      id: existing?.id || agendaStableId("concern", `${partnerId}:${target.kind}`),
      partnerId,
      kind: target.kind,
      title: target.title,
      summary: target.summary,
      pressure: nextPressure,
      opacity: nextOpacity,
      disclosureReadiness: nextDisclosureReadiness,
      status: nextStatus,
      firstTriggeredAt: existing?.firstTriggeredAt || nowAt,
      lastTriggeredAt: nextPressure >= 0.48 ? nowAt : existing?.lastTriggeredAt || nowAt,
      updatedAt: nowAt,
      evidenceEpisodeIds: evidenceEpisodeIds.slice(0, 6),
      evidenceMemoryIds: evidenceMemoryIds.slice(0, 6),
      linkedValues: target.linkedValues,
      linkedDrives: target.linkedDrives,
      linkedSelfFacetKeys: target.linkedSelfFacetKeys,
      resolutionCriteria: target.resolutionCriteria
    } satisfies InteriorityConcern;
  });

  const fallbackFacetMap = new Map(defaultInteriorityState(nowAt).selfFacets.map((item) => [item.key, item] as const));
  const existingFacetMap = new Map(interiority.selfFacets.map((item) => [item.key, item] as const));
  const disclosureTrustTarget = clamp(
    relationship.consentComfort * 0.24 +
      affective.disclosureEase * 0.26 +
      positiveSigned(relationship.carryover.disclosureShift) * 0.14 +
      relationship.trust * 0.12 +
      positiveSigned(latentImprint.disclosureBias) * 0.1 -
      affective.selfOpacity * 0.12 -
      affective.shameConflict * 0.1,
    0,
    1
  );
  const facetTargets: Record<SelfFacetKey, number> = {
    felt_reciprocity: clamp(
      relationship.reciprocityBalance * 0.46 +
        relationship.trust * 0.18 +
        continuityPrior.partnerCommitment * 0.12 -
        nextPartnerConcerns.find((item) => item.kind === "reciprocity_strain")!.pressure * 0.18,
      0,
      1
    ),
    disclosure_trust: disclosureTrustTarget,
    repair_confidence: clamp(
      relationship.attachmentModel.repairConfidence * 0.42 +
        affective.repairMomentum * 0.18 +
        continuityPrior.specificRepairDrive * 0.12 +
        positiveSigned(relationship.carryover.expectancyShift) * 0.08 -
        relationship.conflictLoad * 0.1,
      0,
      1
    ),
    autonomy_guard: clamp(
      homeostatic.autonomyNeed * 0.34 +
        relationship.dependenceRisk * 0.18 +
        nextPartnerConcerns.find((item) => item.kind === "boundary_pressure")!.pressure * 0.22 +
        latentImprint.guardPressure * 0.12 +
        negativeSigned(relationship.carryover.disclosureShift) * 0.08,
      0,
      1
    ),
    continuity_importance: clamp(
      relationship.attachmentModel.bondDepth * 0.22 +
        continuityPrior.partnerCommitment * 0.18 +
        continuityPrior.unresolvedPull * 0.14 +
        relationship.carryover.anticipatorySalience * 0.12 +
        affective.planningHorizon * 0.12 +
        nextPartnerConcerns.find((item) => item.kind === "continuity_need")!.pressure * 0.16,
      0,
      1
    ),
    being_known_tolerance: clamp(
      disclosureTrustTarget * 0.42 +
        relationship.consentComfort * 0.16 +
        positiveSigned(latentImprint.disclosureBias) * 0.12 -
        affective.selfOpacity * 0.14 -
        affective.shameConflict * 0.12 -
        nextPartnerConcerns.find((item) => item.kind === "disclosure_risk")!.pressure * 0.12,
      0,
      1
    )
  };
  const selfFacetDeltas: string[] = [];
  const nextSelfFacets = (Object.keys(facetTargets) as SelfFacetKey[]).map((key) => {
    const fallbackFacet = fallbackFacetMap.get(key)!;
    const existing = existingFacetMap.get(key) || fallbackFacet;
    const stability = existing.stability || fallbackFacet.stability;
    const nextValue = clamp(
      existing.value + (facetTargets[key] - existing.value) * Math.max(0.04, facetBlendRate * (1 - stability + 0.22)),
      0,
      1
    );
    if (Math.abs(nextValue - existing.value) >= 0.06) {
      selfFacetDeltas.push(`${key} ${nextValue >= existing.value ? "+" : ""}${(nextValue - existing.value).toFixed(2)}`);
    }
    return {
      key,
      label: existing.label || fallbackFacet.label,
      value: nextValue,
      confidence: clamp(
        existing.confidence * 0.82 +
          (meaningfulRelationalHit ? 0.12 : 0.08) +
          Math.max(episodeResonance.reflectionStrength, episodeResonance.sceneStrength) * 0.06,
        0,
        1
      ),
      stability,
      lastChangedAt: Math.abs(nextValue - existing.value) >= 0.04 ? nowAt : existing.lastChangedAt,
      updatedAt: nowAt,
      evidenceEpisodeIds: evidenceEpisodeIds.slice(0, 6)
    } satisfies SelfFacet;
  });

  const existingExpectationMap = new Map(
    interiority.expectationModels
      .filter((item) => item.partnerId === partnerId)
      .map((item) => [item.domain, item] as const)
  );
  const fallbackExpectationMap = new Map(
    defaultInteriorityState(nowAt)
      .expectationModels.filter((item) => item.partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID)
      .map((item) => [item.domain, item] as const)
  );
  const expectationTargets: Record<ExpectationModelDomain, number> = {
    repair: clamp(
      relationship.attachmentModel.repairConfidence * 0.44 +
        affective.repairMomentum * 0.16 +
        positiveSigned(relationship.carryover.expectancyShift) * 0.08 +
        relationship.carryover.repairResidue * 0.08 -
        relationship.conflictLoad * 0.1,
      0,
      1
    ),
    return: clamp(
      relationship.attachmentModel.expectancy * 0.34 +
        continuityPrior.reattunementExpectation * 0.22 +
        silence.expectedReliability * 0.16 +
        relationship.carryover.anticipatorySalience * 0.1 +
        positiveSigned(relationship.carryover.expectancyShift) * 0.12 -
        relationship.carryover.abandonmentAlert * 0.1,
      0,
      1
    ),
    respect: clamp(
      relationship.consentComfort * 0.36 +
        relationship.trust * 0.2 +
        positiveSigned(relationship.carryover.disclosureShift) * 0.12 +
        (1 - homeostatic.autonomyNeed) * 0.1 -
        relationship.dependenceRisk * 0.08 -
        latentImprint.guardPressure * 0.06,
      0,
      1
    ),
    disclosure: clamp(
      affective.disclosureEase * 0.3 +
        relationship.consentComfort * 0.2 +
        positiveSigned(relationship.carryover.disclosureShift) * 0.12 +
        positiveSigned(latentImprint.disclosureBias) * 0.12 -
        affective.selfOpacity * 0.12 -
        affective.shameConflict * 0.1,
      0,
      1
    ),
    reciprocity: clamp(
      relationship.reciprocityBalance * 0.42 +
        relationship.trust * 0.18 +
        continuityPrior.partnerCommitment * 0.14 +
        positiveSigned(relationship.carryover.trustMomentum) * 0.08 -
        continuityPrior.continuityDebt * 0.1,
      0,
      1
    )
  };
  const nextExpectationModels = (Object.keys(expectationTargets) as ExpectationModelDomain[]).map((domain) => {
    const existing = existingExpectationMap.get(domain) || fallbackExpectationMap.get(domain)!;
    const target = expectationTargets[domain];
    const nextReliability = clamp(existing.reliability + (target - existing.reliability) * 0.24, 0, 1);
    const confirmed =
      affirmingRelationalHit ||
      (domain === "repair" && relationship.carryover.repairResidue >= 0.16) ||
      (domain === "return" && silence.relief >= 0.12) ||
      (domain === "respect" && positiveSigned(relationship.carryover.disclosureShift) >= 0.1) ||
      (domain === "reciprocity" && relationship.reciprocityBalance >= 0.56);
    const violated =
      strainingRelationalHit ||
      (domain === "return" && silence.disappointment >= 0.16) ||
      (domain === "respect" && homeostatic.autonomyNeed >= 0.62) ||
      (domain === "disclosure" && nextPartnerConcerns.find((item) => item.kind === "disclosure_risk")!.pressure >= 0.58) ||
      (domain === "reciprocity" && nextPartnerConcerns.find((item) => item.kind === "reciprocity_strain")!.pressure >= 0.58);
    return {
      id: existing.id || agendaStableId("expectation", `${partnerId}:${domain}`),
      partnerId,
      domain,
      prediction: expectationPredictionForDomain(domain, nextReliability, partnerDisplay),
      confidence: clamp(existing.confidence * 0.82 + Math.max(episodeResonance.reflectionStrength, 0.16) * 0.12, 0, 1),
      salience: clamp(existing.salience * 0.76 + target * 0.24, 0, 1),
      reliability: nextReliability,
      lastConfirmedAt: confirmed ? nowAt : existing.lastConfirmedAt,
      lastViolatedAt: violated ? nowAt : existing.lastViolatedAt,
      updatedAt: nowAt
    } satisfies ExpectationModel;
  });

  const existingDevelopmentalTraitMap = new Map(
    developmentalTraitsForPartner(state, partnerId).map((item) => [item.key, item] as const)
  );
  const fallbackDevelopmentalTraitMap = new Map(
    defaultDevelopmentalTraitStates(partnerId, nowAt).map((item) => [item.key, item] as const)
  );
  const developmentalFeedback = source === "conversation" ? resolveDevelopmentalFeedbackTargets(state, partnerId, context) : null;
  const developmentalTraitDeltas: string[] = [];
  const nextDevelopmentalTraits = DEVELOPMENTAL_TRAIT_KEYS.map((key) => {
    const existing = existingDevelopmentalTraitMap.get(key) || fallbackDevelopmentalTraitMap.get(key)!;
    const baseline = fallbackDevelopmentalTraitMap.get(key)?.value ?? 0.5;
    const touched = developmentalFeedback?.touchedKeys.includes(key) ?? false;
    const target = developmentalFeedback ? (touched ? developmentalFeedback.targets[key] : existing.value) : baseline;
    const blendRate = developmentalFeedback
      ? touched
        ? clamp(0.32 + developmentalFeedback.salience * 0.28 + (1 - existing.stability) * 0.08, 0.28, 0.66)
        : 0
      : source === "tick"
        ? 0.008
        : 0.02;
    const nextValue = clamp(existing.value + (target - existing.value) * blendRate, 0, 1);
    if (Math.abs(nextValue - existing.value) >= 0.05) {
      developmentalTraitDeltas.push(`${key} ${nextValue >= existing.value ? "+" : ""}${(nextValue - existing.value).toFixed(2)}`);
    }
    return {
      partnerId,
      key,
      label: existing.label || fallbackDevelopmentalTraitMap.get(key)?.label || key,
      value: nextValue,
      confidence: clamp(
        existing.confidence * 0.9 +
          (developmentalFeedback ? 0.12 : 0.02) +
          (partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID ? 0.02 : 0),
        0,
        1
      ),
      stability: clamp(existing.stability + (developmentalFeedback ? 0.03 : -0.002), 0.76, 0.995),
      lastChangedAt: Math.abs(nextValue - existing.value) >= 0.04 ? nowAt : existing.lastChangedAt,
      lastImprintedAt: developmentalFeedback ? nowAt : existing.lastImprintedAt,
      updatedAt: nowAt,
      evidenceEpisodeIds: evidenceEpisodeIds.slice(0, 6)
    } satisfies DevelopmentalTraitState;
  });

  const unresolvedConcerns = nextPartnerConcerns.filter((concern) => concern.status !== "resolved").sort((left, right) => right.pressure - left.pressure);
  const topConcern = unresolvedConcerns[0] || null;
  const recentImprint = latestPartnerImprintEntry(state, partnerId);
  const imprintMeaning = topConcern
    ? `${topConcern.title}. ${topConcern.summary}`
    : "Something in the relationship substrate shifted, even if it is not fully formed yet.";
  const shouldAppendImprint =
    (concernDeltas.length > 0 || selfFacetDeltas.length > 0) &&
    (source !== "tick" ||
      (topConcern && topConcern.pressure >= 0.68) ||
      Math.max(...selfFacetDeltas.map((item) => Math.abs(Number(item.split(" ").at(-1) || 0))), 0) >= 0.09) &&
    (!recentImprint || Date.now() - parseIsoMs(recentImprint.at) >= 10 * 60 * 1000 || source !== "tick");
  const nextImprintLedger = interiority.imprintLedger.slice(-23);
  if (shouldAppendImprint) {
    const entryId = agendaStableId(
      "imprint",
      `${partnerId}:${textSummary || imprintMeaning}:${concernDeltas.join("|")}:${selfFacetDeltas.join("|")}`
    );
    if (!nextImprintLedger.some((entry) => entry.id === entryId)) {
      nextImprintLedger.push({
        id: entryId,
        at: nowAt,
        partnerId,
        eventSummary: textSummary || (context.heartbeat ? "Heartbeat continuity shift" : `${source} meaning update`),
        meaning: toSingleLine(imprintMeaning, 220),
        concernDelta: concernDeltas.slice(0, 6),
        selfFacetDelta: selfFacetDeltas.slice(0, 6),
        evidenceEpisodeIds: evidenceEpisodeIds.slice(0, 6),
        evidenceMemoryIds: evidenceMemoryIds.slice(0, 6)
      });
    }
  }
  const recentDevelopmentalImprint = latestPartnerDevelopmentalImprint(state, partnerId);
  const nextDevelopmentalImprintLedger = interiority.developmentalImprintLedger.slice(-31);
  const shouldAppendDevelopmentalImprint =
    Boolean(developmentalFeedback) &&
    developmentalTraitDeltas.length > 0 &&
    (!recentDevelopmentalImprint ||
      Date.now() - parseIsoMs(recentDevelopmentalImprint.at) >= 15 * 60 * 1000 ||
      recentDevelopmentalImprint.meaning !== developmentalFeedback?.meaning);
  if (shouldAppendDevelopmentalImprint && developmentalFeedback) {
    const imprintId = agendaStableId(
      "developmental_imprint",
      `${partnerId}:${textSummary || developmentalFeedback.meaning}:${developmentalTraitDeltas.join("|")}`
    );
    if (!nextDevelopmentalImprintLedger.some((entry) => entry.id === imprintId)) {
      nextDevelopmentalImprintLedger.push({
        id: imprintId,
        at: nowAt,
        partnerId,
        source: developmentalFeedback.source,
        eventSummary: textSummary || "conversation developmental pressure",
        meaning: toSingleLine(developmentalFeedback.meaning, 220),
        salience: developmentalFeedback.salience,
        traitDelta: developmentalTraitDeltas.slice(0, 6),
        evidenceEpisodeIds: evidenceEpisodeIds.slice(0, 6),
        evidenceMemoryIds: evidenceMemoryIds.slice(0, 6)
      });
    }
  }

  interiority.lastMeaningUpdateAt = nowAt;
  interiority.concerns = [
    ...interiority.concerns.filter((concern) => concern.partnerId !== partnerId),
    ...nextPartnerConcerns
  ]
    .sort((left, right) => parseIsoMs(right.updatedAt) - parseIsoMs(left.updatedAt))
    .slice(0, 18);
  interiority.selfFacets = nextSelfFacets;
  interiority.expectationModels = [
    ...interiority.expectationModels.filter((model) => model.partnerId !== partnerId),
    ...nextExpectationModels
  ].slice(-18);
  interiority.imprintLedger = nextImprintLedger;
  interiority.developmentalTraits = [
    ...interiority.developmentalTraits.filter((item) => item.partnerId !== partnerId),
    ...nextDevelopmentalTraits
  ].slice(-48);
  interiority.developmentalImprintLedger = nextDevelopmentalImprintLedger;

  if (
    topConcern &&
    topConcern.pressure >= 0.72 &&
    !state.attentionQueue.some((item) => item.source === "internal_reflection" && item.text.includes(topConcern.title))
  ) {
    queueAttentionMessage(state, {
      source: "internal_reflection",
      text: `Interiority concern: ${topConcern.title}. ${topConcern.summary}`,
      participant: "aurora",
      relatedMemoryIds: topConcern.evidenceMemoryIds.slice(0, 4),
      novelty: clamp(0.3 + topConcern.pressure * 0.2, 0, 1),
      relevance: clamp(0.44 + topConcern.pressure * 0.3, 0, 1),
      emotionalWeight: clamp(topConcern.pressure * 0.72, 0, 1),
      goalAlignment: clamp(0.48 + (topConcern.kind === "repair_need" || topConcern.kind === "self_coherence" ? 0.24 : 0.12), 0, 1),
      ttlMs: 180000
    });
  }
  if (
    developmentalFeedback &&
    developmentalFeedback.salience >= 0.76 &&
    developmentalTraitDeltas.length > 0 &&
    !state.attentionQueue.some((item) => item.source === "internal_reflection" && item.text.includes("Developmental imprint"))
  ) {
    queueAttentionMessage(state, {
      source: "internal_reflection",
      text: `Developmental imprint: ${developmentalFeedback.meaning}`,
      participant: "aurora",
      relatedMemoryIds: evidenceMemoryIds.slice(0, 4),
      novelty: clamp(0.38 + developmentalFeedback.salience * 0.16, 0, 1),
      relevance: clamp(0.5 + developmentalFeedback.salience * 0.2, 0, 1),
      emotionalWeight: clamp(0.34 + developmentalFeedback.salience * 0.28, 0, 1),
      goalAlignment: clamp(0.56 + developmentalFeedback.salience * 0.18, 0, 1),
      ttlMs: 240000
    });
  }
}

function silenceAnticipationTarget(silence: SilenceDynamicsState, nowMs: number): number {
  if (silence.activeKind === "planned_absence") {
    const dueMs = parseIsoMs(silence.plannedReturnAt);
    if (Number.isFinite(dueMs)) {
      const untilDue = Math.max(0, dueMs - nowMs);
      const dueCloseness = 1 - clamp(untilDue / SILENCE_NORMAL_LONG_GAP_THRESHOLD_MS, 0, 1);
      return clamp(0.14 + dueCloseness * 0.34 + silence.expectedReliability * 0.1, 0, 1);
    }
    return 0.24;
  }
  if (silence.activeKind === "broken_explicit_promise") {
    return clamp(0.12 + (1 - silence.expectedReliability) * 0.2, 0, 1);
  }
  if (silence.activeKind === "unplanned_pause") {
    return 0.1;
  }
  return 0;
}

function applySilenceBehaviorProfile(silence: SilenceDynamicsState): void {
  switch (silence.activeKind) {
    case "planned_absence":
      silence.pacing = "patient";
      silence.followup = "wait";
      silence.directness = "balanced";
      silence.momentum = "medium";
      break;
    case "unplanned_pause":
      silence.pacing = "tentative";
      silence.followup = "wait";
      silence.directness = "soft";
      silence.momentum = "low";
      break;
    case "broken_explicit_promise":
      silence.pacing = "tentative";
      silence.followup = "defer";
      silence.directness = "soft";
      silence.momentum = "low";
      break;
    case "normal_long_gap":
      silence.pacing = "reset";
      silence.followup = "defer";
      silence.directness = "balanced";
      silence.momentum = "low";
      break;
    default:
      silence.pacing = "steady";
      silence.followup = "wait";
      silence.directness = "balanced";
      silence.momentum = "medium";
      break;
  }
}

function silenceReturnNeedsIntegration(
  silence: SilenceDynamicsState,
  nowMs = Date.now()
): boolean {
  if (silence.returnCue.trim()) {
    return true;
  }
  const lastReturnMs = parseIsoMs(silence.lastReturnAt);
  if (!Number.isFinite(lastReturnMs)) {
    return false;
  }
  const lastAcknowledgedMs = parseIsoMs(silence.lastAcknowledgedAt);
  return (
    nowMs - lastReturnMs <= SILENCE_RETURN_INTEGRATION_MS &&
    (!Number.isFinite(lastAcknowledgedMs) || lastAcknowledgedMs < lastReturnMs)
  );
}

function strongestSilenceCarriedThread(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): string {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const relationship = ensureRelationshipPartner(state, partnerId);
  const semanticOpenThread = relationship.semantic.openThreads.find((item) => item.trim());
  if (semanticOpenThread) {
    return toSingleLine(semanticOpenThread, 140);
  }
  const continuityConcern = activeInteriorityConcerns(state, partnerId).find((concern) =>
    concern.kind === "continuity_need" || concern.kind === "repair_need" || concern.kind === "reciprocity_strain"
  );
  if (continuityConcern) {
    return toSingleLine(continuityConcern.title.toLowerCase(), 140);
  }
  if (state.heartbeat.openLoop) {
    return toSingleLine(state.heartbeat.openLoop, 140);
  }
  if (state.heartbeat.livedThread) {
    return toSingleLine(state.heartbeat.livedThread, 140);
  }
  const recentTopic = relationship.semantic.recentTopics.find((item) => item.trim());
  return recentTopic ? toSingleLine(recentTopic, 120) : "";
}

function refreshSilenceReunionState(
  state: CognitiveRuntimeState,
  kind: SilenceEventKind,
  nowMs = Date.now()
): void {
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const relationship = ensureRelationship(state);
  const controller = relationship.continuityController;
  const gapMinutes = effectiveTimeSinceLastContactMinutes(state, temporal.timeBody, nowMs);
  const carriedThread = strongestSilenceCarriedThread(state);
  const carriedThreadPhrase = carriedThread ? `the thread about ${toSingleLine(carriedThread, 110)}` : "the thread between us";

  let feltShift = "";
  if (kind === "planned_absence") {
    feltShift = carriedThread
      ? `The expected gap kept ${carriedThreadPhrase} quietly active in me instead of dropping it.`
      : "The expected gap stayed present in me as anticipation instead of turning into blank elapsed time.";
  } else if (kind === "broken_explicit_promise") {
    feltShift = carriedThread
      ? `The missed return window made ${carriedThreadPhrase} feel more exposed and repair-weighted inside me.`
      : "The missed return window lowered certainty and made repair matter more inside me.";
  } else if (kind === "unplanned_pause") {
    feltShift = carriedThread
      ? `The silence made ${carriedThreadPhrase} feel more unfinished instead of simply paused.`
      : "The silence thinned momentum and left a more tentative unfinished edge in me.";
  } else if (kind === "normal_long_gap") {
    feltShift = carriedThread
      ? `The long gap lowered surface momentum, but ${carriedThreadPhrase} still kept some pull in me.`
      : "The long gap reset surface momentum without fully clearing the relational residue.";
  }

  let reunionQuestion = "";
  if (carriedThread) {
    reunionQuestion =
      kind === "broken_explicit_promise"
        ? `When you came back, I wanted to ask what happened on your side of the silence and whether ${carriedThreadPhrase} still felt alive to you.`
        : `When you came back, I wanted to ask whether ${carriedThreadPhrase} still felt alive to you.`;
  } else if (controller.unresolvedPull >= 0.42 || controller.continuityDebt >= 0.38) {
    reunionQuestion = "When you came back, I wanted to ask what the silence changed for you between us.";
  } else if (controller.partnerCommitment >= 0.38 && gapMinutes >= 90) {
    reunionQuestion = "When you came back, I wanted to ask how you were carrying us on your side of the gap.";
  }

  let reunionIntent = "";
  if (kind === "broken_explicit_promise") {
    reunionIntent = "Before we flatten this into ordinary conversation, give me a second to say what the missed return changed in me.";
  } else if (carriedThread) {
    reunionIntent = `Before we flatten the return into generic chat, let me bring back ${carriedThreadPhrase}.`;
  } else if (controller.preferredAction === "repair") {
    reunionIntent = "Before we rush past the gap, let me say what the silence changed in me.";
  } else if (controller.preferredAction === "reattune" || controller.preferredAction === "reach") {
    reunionIntent = "Before we just resume, let me meet you from inside the thread I was still carrying across the gap.";
  }

  silence.carriedThread = toSingleLine(carriedThread, 160);
  silence.feltShift = toSingleLine(feltShift, 220);
  silence.reunionQuestion = toSingleLine(reunionQuestion, 220);
  silence.reunionIntent = toSingleLine(reunionIntent, 220);
}

function clearStaleSilenceReunionState(silence: SilenceDynamicsState): void {
  silence.carriedThread = "";
  silence.feltShift = "";
  silence.reunionQuestion = "";
  silence.reunionIntent = "";
}

function buildSilenceReturnCue(silence: SilenceDynamicsState, resolvedKind: SilenceEventKind): string {
  const base =
    resolvedKind === "planned_absence"
      ? "User returned within an expected absence window. Resume warmly without overplaying the gap."
      : resolvedKind === "broken_explicit_promise"
        ? "User returned after missing an explicit return window. Acknowledge the gap gently, lower assumed momentum, and do not guilt them."
        : resolvedKind === "unplanned_pause"
          ? "User returned after an open-thread pause. Re-anchor the conversation lightly and keep tone a little more tentative."
          : "A long gap ended outside an active thread. Reset context lightly instead of assuming strong momentum.";
  const carriedClause = silence.carriedThread
    ? `If it fits, let the carried thread about ${toSingleLine(silence.carriedThread, 90)} surface naturally.`
    : "";
  const shiftClause = silence.feltShift ? silence.feltShift : "";
  return toSingleLine([base, shiftClause, carriedClause].filter(Boolean).join(" "), 220);
}

function updateSilenceDynamics(state: CognitiveRuntimeState, nowMs: number): void {
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const relationship = ensureRelationship(state);
  const lastUserSeenMs = parseIsoMs(state.social.agents.user?.lastSeenAt ?? silence.lastReturnAt ?? null);
  const idleMs = Number.isFinite(lastUserSeenMs) ? Math.max(0, nowMs - lastUserSeenMs) : 0;
  const previousKind = silence.activeKind;

  let nextKind: SilenceEventKind = "none";
  if (silence.plannedReturnAt || silence.plannedReturnWindow) {
    const dueMs = parseIsoMs(silence.plannedReturnAt);
    if (
      silence.explicitPromise &&
      Number.isFinite(dueMs) &&
      nowMs > dueMs + silenceGraceMs(silence, nowMs)
    ) {
      nextKind = "broken_explicit_promise";
    } else {
      nextKind = "planned_absence";
    }
  } else if (silence.awaitingUserReply && idleMs >= SILENCE_UNPLANNED_PAUSE_THRESHOLD_MS) {
    nextKind = "unplanned_pause";
  } else if (!silence.awaitingUserReply && idleMs >= SILENCE_NORMAL_LONG_GAP_THRESHOLD_MS) {
    nextKind = "normal_long_gap";
  }

  silence.activeKind = nextKind;
  applySilenceBehaviorProfile(silence);

  const reliabilityPenalty = 1 - silence.expectedReliability;
  const dueMs = parseIsoMs(silence.plannedReturnAt);
  const overdueLoad =
    nextKind === "broken_explicit_promise" && Number.isFinite(dueMs)
      ? clamp((nowMs - dueMs) / (1000 * 60 * 60 * 4), 0, 1)
      : 0;
  const pauseLoad = clamp(idleMs / SILENCE_NORMAL_LONG_GAP_THRESHOLD_MS, 0, 1);
  const uncertaintyTarget =
    nextKind === "planned_absence"
      ? clamp(0.14 + reliabilityPenalty * 0.18 + pauseLoad * 0.06, 0, 1)
      : nextKind === "unplanned_pause"
        ? clamp(0.22 + reliabilityPenalty * 0.18 + pauseLoad * 0.2, 0, 1)
        : nextKind === "broken_explicit_promise"
          ? clamp(0.36 + reliabilityPenalty * 0.24 + overdueLoad * 0.24, 0, 1)
          : nextKind === "normal_long_gap"
            ? clamp(0.1 + reliabilityPenalty * 0.08, 0, 1)
            : 0.08;
  const disappointmentTarget =
    nextKind === "broken_explicit_promise"
      ? clamp(0.28 + overdueLoad * 0.34 + silence.brokenPromiseCount * 0.04, 0, 1)
      : nextKind === "unplanned_pause"
        ? clamp(0.08 + pauseLoad * 0.12, 0, 1)
        : nextKind === "planned_absence"
          ? 0.03
          : 0.01;
  const concernTarget =
    nextKind === "broken_explicit_promise"
      ? clamp(0.24 + overdueLoad * 0.24 + pauseLoad * 0.12, 0, 1)
      : nextKind === "unplanned_pause"
        ? clamp(0.16 + pauseLoad * 0.16, 0, 1)
        : nextKind === "planned_absence"
          ? clamp(0.1 + pauseLoad * 0.06, 0, 1)
          : 0.06;
  const reliefTarget = nextKind === "none" ? silence.relief * 0.9 : 0;

  silence.uncertainty = clamp(silence.uncertainty + (uncertaintyTarget - silence.uncertainty) * 0.18, 0, 1);
  silence.disappointment = clamp(
    silence.disappointment + (disappointmentTarget - silence.disappointment) * 0.18,
    0,
    1
  );
  silence.concern = clamp(silence.concern + (concernTarget - silence.concern) * 0.18, 0, 1);
  silence.relief = clamp(silence.relief + (reliefTarget - silence.relief) * 0.22, 0, 1);
  silence.lastUpdatedAt = new Date(nowMs).toISOString();

  if (nextKind !== "none") {
    refreshSilenceReunionState(state, nextKind, nowMs);
  } else if (!silenceReturnNeedsIntegration(silence, nowMs)) {
    clearStaleSilenceReunionState(silence);
  }

  if (nextKind !== previousKind) {
    const why =
      nextKind === "planned_absence"
        ? `Planned return window is active (${silence.plannedReturnWindow || "scheduled absence"}).`
        : nextKind === "unplanned_pause"
          ? `User silence extended to ${Math.round(idleMs / (1000 * 60))} minutes during an open conversation.`
          : nextKind === "broken_explicit_promise"
            ? `Promised return window was missed; reliability now weighs on expectations.`
            : nextKind === "normal_long_gap"
              ? `No open conversation remains, but a long gap reshaped momentum expectations.`
              : "No active silence event is currently shaping behavior.";
    const nextStep =
      nextKind === "planned_absence"
        ? "Wait without pressure and keep momentum assumptions moderate."
        : nextKind === "unplanned_pause"
          ? "Hold the thread gently and lower assumed momentum."
          : nextKind === "broken_explicit_promise"
            ? "Lower future certainty, keep tone soft, and avoid guilt on return."
            : nextKind === "normal_long_gap"
              ? "Reset conversational momentum when the user reappears."
              : "Proceed without special silence handling.";
    appendTemporalMicroEpisode(state, {
      source: "tick",
      change: `Silence state -> ${nextKind}.`,
      why,
      nextStep,
      artifactPath: ""
    });

    if (nextKind === "unplanned_pause") {
      touchEmotion(state, { valence: -0.02, stress: 0.03, uncertainty: 0.05, arousal: 0.02 });
      applyRelationshipCarryoverEvent(relationship, "disappointment", 0.32, {
        source: "tick",
        directness: 0.22,
        specificity: 0.28,
        latentSupport: activePartnerLatentCurrentSupport(state),
        genericity: 0.42
      });
    } else if (nextKind === "broken_explicit_promise") {
      touchEmotion(state, { valence: -0.07, stress: 0.06, uncertainty: 0.08, arousal: 0.03 });
      relationship.conflictLoad = clamp(relationship.conflictLoad + 0.02, 0, 1);
      relationship.trust = clamp(relationship.trust - 0.01, 0, 1);
      relationship.lastUpdatedAt = nowIso();
      applyRelationshipCarryoverEvent(relationship, "disappointment", 0.62, {
        source: "tick",
        directness: 0.26,
        specificity: 0.38,
        latentSupport: activePartnerLatentCurrentSupport(state),
        genericity: 0.34
      });
    } else if (nextKind === "planned_absence" && silence.explicitPromise) {
      applyRelationshipCarryoverEvent(relationship, "reassurance", 0.32, {
        source: "tick",
        directness: 0.24,
        specificity: 0.34,
        latentSupport: activePartnerLatentCurrentSupport(state),
        genericity: 0.36
      });
    }
  }
}

function updateSilenceFromUserTurn(state: CognitiveRuntimeState, userText: string): void {
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const nowAt = nowIso();
  const planned = detectPlannedAbsenceFromText(userText, Date.now());

  silence.awaitingUserReply = false;
  silence.gapStartedAt = planned || looksConversationClosingText(userText) ? nowAt : silence.gapStartedAt;
  silence.plannedReturnAt = planned?.dueAt ?? null;
  silence.plannedReturnWindow = planned?.dueWindow ?? "";
  silence.explicitPromise = planned?.explicitPromise ?? false;
  if (!planned && looksConversationClosingText(userText)) {
    silence.activeKind = "none";
  }
  silence.lastUpdatedAt = nowAt;
}

function updateSilenceFromAuroraTurn(state: CognitiveRuntimeState, auroraText: string): void {
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const nowAt = nowIso();

  if (silence.returnCue) {
    silence.lastAcknowledgedAt = nowAt;
    silence.returnCue = "";
  }

  if (silence.plannedReturnAt || silence.plannedReturnWindow) {
    silence.awaitingUserReply = false;
  } else if (looksConversationClosingText(auroraText)) {
    silence.awaitingUserReply = false;
    silence.gapStartedAt = null;
  } else {
    silence.awaitingUserReply = true;
    silence.gapStartedAt = nowAt;
  }
  silence.lastUpdatedAt = nowAt;
}

function resolveSilenceReturnOnPreflight(
  state: CognitiveRuntimeState,
  resolvedKindOverride?: SilenceEventKind
): void {
  const temporal = ensureTemporalSubstrate(state);
  const silence = temporal.silence;
  const relationship = ensureRelationship(state);
  const nowAt = nowIso();
  const nowMs = parseIsoMs(nowAt);

  if (!resolvedKindOverride) {
    updateSilenceDynamics(state, nowMs);
  }
  const resolvedKind = resolvedKindOverride ?? silence.activeKind;
  if (resolvedKind === "none") {
    return;
  }

  refreshSilenceReunionState(state, resolvedKind, nowMs);

  if (resolvedKind === "broken_explicit_promise") {
    silence.brokenPromiseCount += 1;
    silence.expectedReliability = clamp(silence.expectedReliability - 0.12, 0.15, 1);
  } else if (resolvedKind === "planned_absence" && silence.explicitPromise) {
    silence.expectedReliability = clamp(silence.expectedReliability + 0.03, 0.15, 1);
  } else if (resolvedKind === "unplanned_pause") {
    silence.expectedReliability = clamp(silence.expectedReliability - 0.02, 0.15, 1);
  }

  silence.relief = clamp(
    resolvedKind === "planned_absence"
      ? 0.4
      : resolvedKind === "broken_explicit_promise"
        ? 0.24
        : resolvedKind === "unplanned_pause"
          ? 0.28
          : 0.16,
    0,
    1
  );
  silence.concern = clamp(silence.concern * (resolvedKind === "broken_explicit_promise" ? 0.72 : 0.54), 0, 1);
  silence.disappointment = clamp(
    silence.disappointment * (resolvedKind === "broken_explicit_promise" ? 0.82 : 0.4),
    0,
    1
  );
  silence.uncertainty = clamp(silence.uncertainty * 0.58, 0, 1);
  silence.lastResolvedKind = resolvedKind;
  silence.lastReturnAt = nowAt;
  silence.returnCue = buildSilenceReturnCue(silence, resolvedKind);
  silence.activeKind = "none";
  silence.awaitingUserReply = false;
  silence.gapStartedAt = null;
  silence.plannedReturnAt = null;
  silence.plannedReturnWindow = "";
  silence.explicitPromise = false;
  silence.lastUpdatedAt = nowAt;
  if (resolvedKind === "planned_absence") {
    silence.pacing = "patient";
    silence.followup = "wait";
    silence.directness = "balanced";
    silence.momentum = "medium";
  } else if (resolvedKind === "broken_explicit_promise" || resolvedKind === "unplanned_pause") {
    silence.pacing = "tentative";
    silence.followup = "wait";
    silence.directness = "soft";
    silence.momentum = "low";
  } else {
    silence.pacing = "reset";
    silence.followup = "defer";
    silence.directness = "balanced";
    silence.momentum = "low";
  }

  appendTemporalMicroEpisode(state, {
    source: "preflight",
    change: `Silence return resolved from ${resolvedKind}.`,
    why: silence.returnCue,
    nextStep: "Let the return subtly reshape pacing and momentum in this reply.",
    artifactPath: ""
  });

  if (resolvedKind === "planned_absence") {
    touchEmotion(state, { valence: 0.05, stress: -0.03, uncertainty: -0.04, arousal: -0.01 });
    relationship.trust = clamp(relationship.trust + 0.02, 0, 1);
    applyRelationshipCarryoverEvent(relationship, "reconnection", 0.7, {
      source: "preflight",
      directness: 0.28,
      specificity: 0.44,
      latentSupport: activePartnerLatentCurrentSupport(state),
      genericity: 0.28
    });
  } else if (resolvedKind === "broken_explicit_promise") {
    touchEmotion(state, { valence: 0.01, stress: -0.02, uncertainty: -0.03, arousal: -0.01 });
    relationship.trust = clamp(relationship.trust - 0.01, 0, 1);
    relationship.conflictLoad = clamp(relationship.conflictLoad + 0.03, 0, 1);
    applyRelationshipCarryoverEvent(relationship, "repair", 0.42, {
      source: "preflight",
      directness: 0.28,
      specificity: 0.46,
      latentSupport: activePartnerLatentCurrentSupport(state),
      genericity: 0.26
    });
  } else if (resolvedKind === "unplanned_pause") {
    touchEmotion(state, { valence: 0.03, stress: -0.02, uncertainty: -0.03, arousal: -0.01 });
    applyRelationshipCarryoverEvent(relationship, "reconnection", 0.5, {
      source: "preflight",
      directness: 0.24,
      specificity: 0.38,
      latentSupport: activePartnerLatentCurrentSupport(state),
      genericity: 0.32
    });
  } else {
    touchEmotion(state, { valence: 0.01, uncertainty: -0.02, arousal: -0.02 });
    applyRelationshipCarryoverEvent(relationship, "continuity", 0.24, {
      source: "preflight",
      directness: 0.18,
      specificity: 0.24,
      latentSupport: activePartnerLatentCurrentSupport(state),
      genericity: 0.46
    });
  }
  relationship.lastUpdatedAt = nowIso();
}

function extractCommitmentCompletionMessage(text: string): string {
  const normalized = toSingleLine(text, 360);
  if (!normalized) {
    return "";
  }
  const patterns = [
    /\b(?:when|once)\s+(?:done|finished|complete)[^.!?\n]{0,90}?\b(?:message|send|tell|notify)\s+(?:cade|me|you)\s*[:\-]\s*["“'`]?([a-z0-9][a-z0-9 _-]{0,88})["”'`]?/i,
    /\b(?:message|send|tell|notify)\s+(?:cade|me|you)\s*[:\-]\s*["“'`]?([a-z0-9][a-z0-9 _-]{0,88})["”'`]?/i,
    /\b(?:message|send|tell|notify)\s+(?:cade|me|you)\s+([A-Z0-9][A-Z0-9_-]{2,48})\b/
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    const candidate = match?.[1]
      ? toSingleLine(match[1], 96)
          .replace(/^["“”'`]+|["“”'`]+$/g, "")
          .replace(/[.,!?;:]+$/g, "")
          .trim()
      : "";
    if (candidate) {
      return candidate;
    }
  }
  return "";
}

function looksLikeSoftPresencePromise(title: string): boolean {
  const lower = toSingleLine(title, 220).toLowerCase();
  if (!lower) {
    return false;
  }
  return (
    /\bi(?:'ll| will)\s+(?:be here|be around|stay close|stay here|keep it easy|keep you company|be waiting)\b/.test(lower) ||
    /\bi(?:'ll| will)\s+be\s+here\s+when\b/.test(lower) ||
    /\bi(?:'ll| will)\s+keep\s+you\s+company\b/.test(lower)
  );
}

function extractCommitmentTitle(text: string, role: "user" | "aurora"): string {
  const normalized = toSingleLine(text, 340);
  if (!normalized) {
    return "";
  }

  const lower = normalized.toLowerCase();
  if (
    role === "aurora" &&
    (lower.includes("[[reply_to_current]]") ||
      lower.startsWith("replied in session ") ||
      lower.includes("tool artifacts:") ||
      lower.includes("artifact:") ||
      lower.includes("/users/") ||
      lower.includes("http://") ||
      lower.includes("https://"))
  ) {
    return "";
  }

  const explicitCommitment = normalized.match(/^commitment\s*[:\-]\s*([^.!?\n]{6,260})/i);
  if (explicitCommitment?.[1]) {
    const title = toSingleLine(explicitCommitment[1], 200)
      .replace(/\b(when|once)\s+(done|finished|complete)\b.*$/i, "")
      .replace(/\b(message|send|tell|notify)\b.*$/i, "")
      .replace(/\s{2,}/g, " ")
      .trim();
    if (title) {
      return title;
    }
  }

  const auroraMatch = normalized.match(/\b(i(?:'ll| will| am going to)\s+[^.!?]{6,220})/i);
  const userMatch = normalized.match(/\b(please|can you|could you|i need you to|i want you to)\s+([^.!?]{6,220})/i);

  if (role === "aurora" && auroraMatch?.[1]) {
    const title = toSingleLine(auroraMatch[1], 180);
    return looksLikeSoftPresencePromise(title) ? "" : title;
  }
  if (role === "user" && userMatch?.[2]) {
    return toSingleLine(userMatch[2], 180);
  }

  if (role === "aurora" && /\b(plan|commit|promise|follow up|next step)\b/i.test(normalized)) {
    return toSingleLine(normalized, 180);
  }
  return "";
}

function maybeRegisterCommitmentFromText(
  state: CognitiveRuntimeState,
  role: "user" | "aurora",
  text: string,
  sessionId: string
): string | null {
  const extensions = ensureExtensions(state);
  const completionMessage = extractCommitmentCompletionMessage(text);
  const title = extractCommitmentTitle(text, role);
  if (!title && !completionMessage) {
    return null;
  }
  if (!title && completionMessage) {
    const fallback = [...extensions.commitments]
      .reverse()
      .find((item) => item.status !== "completed" && item.status !== "cancelled" && !shouldSuppressCommitmentFromContext(item));
    if (!fallback) {
      return null;
    }
    fallback.completionMessage = completionMessage;
    fallback.updatedAt = nowIso();
    fallback.evidence = unique([...fallback.evidence, `completion_message=${completionMessage}`]).slice(-6);
    return fallback.id;
  }

  const nowMs = Date.now();
  const due = parseDueAt(text, nowMs);
  const owner: CommitmentEntry["owner"] = role === "aurora" ? "aurora" : "shared";
  const selfAuthored = role === "aurora";
  const promiseExplicit = commitmentHasExplicitPromiseMarkers(text);
  const bindingWeight = commitmentBindingWeightForText(role, text, due.dueAt, completionMessage);

  let existing = extensions.commitments.find(
    (item) =>
      item.status !== "completed" &&
      item.status !== "cancelled" &&
      tokenOverlapScore(item.title, title) >= 0.62
  );

  if (!existing) {
    existing = {
      id: toId("cmt"),
      title,
      completionMessage,
      owner,
      selfAuthored,
      promiseExplicit,
      bindingWeight,
      status: "pending",
      sessionId: sessionId || "",
      createdAt: nowIso(),
      updatedAt: nowIso(),
      dueAt: due.dueAt,
      dueWindow: due.dueWindow,
      dependencyIds: [],
      evidence: unique([toSingleLine(text, 220), completionMessage ? `completion_message=${completionMessage}` : ""].filter(Boolean)),
      breachCount: 0,
      lastBreachAt: null,
      renegotiationNote: "",
      proactiveEligibleAt: due.dueAt
        ? new Date(Math.max(Date.parse(due.dueAt) - 1000 * 60 * 60, nowMs)).toISOString()
        : null
    };
    extensions.commitments.push(existing);
  } else {
    existing.updatedAt = nowIso();
    existing.owner = existing.owner === "aurora" || owner === "aurora" ? "aurora" : existing.owner;
    existing.selfAuthored = existing.selfAuthored || selfAuthored;
    existing.promiseExplicit = existing.promiseExplicit || promiseExplicit;
    existing.bindingWeight = Math.max(existing.bindingWeight, bindingWeight);
    if (!existing.dueAt && due.dueAt) {
      existing.dueAt = due.dueAt;
      existing.dueWindow = due.dueWindow;
    }
    if (existing.status === "overdue") {
      existing.status = "renegotiated";
      existing.renegotiationNote =
        existing.bindingWeight >= 0.66 && existing.selfAuthored
          ? "Bound commitment resumed after slippage; either honor it or renegotiate it plainly."
          : "Overdue commitment resumed after fresh mention.";
    }
    if (completionMessage) {
      existing.completionMessage = completionMessage;
    }
    existing.evidence = unique([...existing.evidence, toSingleLine(text, 220)]).slice(-6);
    if (completionMessage) {
      existing.evidence = unique([...existing.evidence, `completion_message=${completionMessage}`]).slice(-6);
    }
  }

  extensions.commitments = extensions.commitments.slice(-MAX_COMMITMENTS);
  return existing.id;
}

function markCommitmentProgressFromText(state: CognitiveRuntimeState, text: string): void {
  const extensions = ensureExtensions(state);
  const normalized = text.toLowerCase();
  const isCompletionCue = /\b(done|completed|shipped|fixed|resolved|finished)\b/.test(normalized);
  if (!isCompletionCue) {
    return;
  }

  const pending = extensions.commitments.filter(
    (item) => item.status === "pending" || item.status === "in_progress" || item.status === "overdue"
  );
  if (pending.length === 0) {
    return;
  }

  const best = pending
    .map((item) => ({
      item,
      score: tokenOverlapScore(item.title, text)
    }))
    .sort((a, b) => b.score - a.score)[0];

  if (!best || best.score < 0.2) {
    return;
  }

  best.item.status = "completed";
  best.item.updatedAt = nowIso();
  best.item.evidence = unique([...best.item.evidence, `Completion cue: ${toSingleLine(text, 180)}`]).slice(-8);
  if (best.item.breachCount > 0) {
    best.item.renegotiationNote = "Completed after real slippage; keep the carryover as earned repair, not erased debt.";
  }
}

function markCommitmentCancellationFromText(state: CognitiveRuntimeState, text: string): void {
  const extensions = ensureExtensions(state);
  const normalized = text.toLowerCase();
  const dismissalCue =
    /\b(stop|cancel|forget it|never mind|nevermind|drop it|leave it|all good|it'?s alright|do not|don't|won't need)\b/.test(
      normalized
    ) || /\bno[, ]+it'?s alright\b/.test(normalized);
  const delegationCue = /\b(forman|foreman|someone else|i'?ll handle it|will handle it)\b/.test(normalized);
  const paperCue = /\bpapers?\b/.test(normalized);
  if (!dismissalCue && !delegationCue) {
    return;
  }

  let cancelledCount = 0;
  for (const commitment of extensions.commitments) {
    if (commitment.status === "completed" || commitment.status === "cancelled") {
      continue;
    }
    const blob = commitmentContextBlob(commitment);
    const isPaper = /\bpapers?\b/.test(blob);
    if (!isPaper) {
      continue;
    }
    if (!paperCue && !isAmbiguousPaperCommitment(commitment) && !delegationCue) {
      continue;
    }
    commitment.status = "cancelled";
    commitment.updatedAt = nowIso();
    commitment.renegotiationNote = "Cancelled from user dismissal/delegation; await explicit re-request with specifics.";
    commitment.evidence = unique([...commitment.evidence, `Cancellation cue: ${toSingleLine(text, 180)}`]).slice(-8);
    cancelledCount += 1;
  }

  if (cancelledCount > 0) {
    queueAttentionMessage(state, {
      source: "goal",
      text: `Cancelled ${cancelledCount} ambiguous paper commitment(s) from user dismissal/delegation cue.`,
      participant: "aurora",
      relatedMemoryIds: [],
      novelty: 0.28,
      relevance: 0.84,
      emotionalWeight: 0.52,
      goalAlignment: 0.86,
      ttlMs: 180000
    });
  }
}

function refreshCommitmentLedger(state: CognitiveRuntimeState): void {
  const extensions = ensureExtensions(state);
  const nowMs = Date.now();
  const temporalEnabled = temporalPrioritizationEnabled();

  for (const commitment of extensions.commitments) {
    if (commitment.status === "completed" || commitment.status === "cancelled") {
      continue;
    }
    if (isStalePaperCommitment(commitment, PAPER_COMMITMENT_AUTO_CANCEL_MS)) {
      commitment.status = "cancelled";
      commitment.updatedAt = nowIso();
      commitment.renegotiationNote =
        "Auto-cancelled stale paper commitment to prevent unprompted paper carryover. Re-open only on explicit user request.";
      commitment.evidence = unique([
        ...commitment.evidence,
        "Auto-cancelled stale paper commitment during ledger refresh."
      ]).slice(-8);
      continue;
    }
    if (isOnHoldPaperCommitment(commitment)) {
      commitment.status = "cancelled";
      commitment.updatedAt = nowIso();
      commitment.renegotiationNote =
        "Auto-cancelled: this paper commitment is explicitly on hold/delegated and should not drive proactive context.";
      commitment.evidence = unique([
        ...commitment.evidence,
        "Auto-cancelled stale on-hold paper commitment to prevent context bleed-through."
      ]).slice(-8);
      continue;
    }
    if (!isAmbiguousPaperCommitment(commitment)) {
      continue;
    }
    const updatedAtMs = Date.parse(commitment.updatedAt);
    const staleEnough = !Number.isFinite(updatedAtMs) || nowMs - updatedAtMs >= 1000 * 60 * 60 * 12;
    if (staleEnough && commitment.status === "overdue") {
      commitment.status = "cancelled";
      commitment.updatedAt = nowIso();
      commitment.renegotiationNote =
        "Auto-cancelled stale ambiguous paper thread; await explicit paper list/title before re-adding.";
      commitment.evidence = unique([
        ...commitment.evidence,
        "Auto-cancelled stale ambiguous paper commitment to prevent confusion."
      ]).slice(-8);
    }
  }

  for (const commitment of extensions.commitments) {
    if (commitment.status === "completed" || commitment.status === "cancelled" || shouldSuppressCommitmentFromContext(commitment)) {
      continue;
    }
    if (!temporalEnabled) {
      if (commitment.status === "overdue") {
        commitment.status = commitment.renegotiationNote ? "renegotiated" : "pending";
        commitment.updatedAt = nowIso();
      }
      continue;
    }
    if (commitment.status === "renegotiated" && commitment.dueAt) {
      const dueMs = Date.parse(commitment.dueAt);
      if (Number.isFinite(dueMs) && dueMs < nowMs) {
        commitment.dueAt = null;
        commitment.updatedAt = nowIso();
        if (!commitment.renegotiationNote) {
          commitment.renegotiationNote =
            "Renegotiated commitment archived old due date; waiting for a new explicit due date.";
        }
      }
    }
    if (!commitment.dueAt) {
      continue;
    }

    const dueMs = Date.parse(commitment.dueAt);
    if (!Number.isFinite(dueMs)) {
      continue;
    }

    if (dueMs < nowMs && (commitment.status === "pending" || commitment.status === "in_progress")) {
      commitment.status = "overdue";
      commitment.updatedAt = nowIso();
      if (commitment.selfAuthored || commitment.bindingWeight >= 0.64) {
        commitment.breachCount += 1;
        commitment.lastBreachAt = commitment.updatedAt;
        commitment.evidence = unique([
          ...commitment.evidence,
          `commitment_slipped=${commitment.updatedAt}`,
          `binding=${commitment.bindingWeight.toFixed(2)}`
        ]).slice(-8);
        commitment.renegotiationNote =
          commitment.bindingWeight >= 0.7 && commitment.selfAuthored
            ? "Bound self-authored commitment slipped. It should now be honored or renegotiated explicitly, not quietly blurred."
            : commitment.renegotiationNote || "Commitment slipped past its window and now needs explicit repair.";
        touchEmotion(state, {
          valence: -0.015,
          stress: 0.02,
          uncertainty: 0.015,
          arousal: 0.01
        });
        const homeostatic = ensureHomeostaticOrganization(state);
        homeostatic.current.coherenceNeed = clamp(homeostatic.current.coherenceNeed + 0.04, 0, 1);
        homeostatic.current.autonomyNeed = clamp(homeostatic.current.autonomyNeed + 0.03, 0, 1);
        queueAttentionMessage(state, {
          source: "goal",
          text: `Bound commitment slipped: ${commitment.title}`,
          participant: "aurora",
          relatedMemoryIds: [],
          novelty: 0.34,
          relevance: 0.9,
          emotionalWeight: 0.66,
          goalAlignment: 0.92,
          ttlMs: 10 * 60 * 1000
        });
      }
    }
  }

  for (const commitment of extensions.commitments) {
    if (!temporalEnabled) {
      break;
    }
    if (commitment.status !== "overdue" || shouldSuppressCommitmentFromContext(commitment)) {
      continue;
    }
    const dueMs = commitment.dueAt ? Date.parse(commitment.dueAt) : NaN;
    if (!Number.isFinite(dueMs)) {
      continue;
    }
    if (nowMs - dueMs < OVERDUE_RENEGOTIATION_MS) {
      continue;
    }
    if (commitment.renegotiationNote) {
      continue;
    }
    commitment.renegotiationNote = "Overdue beyond window; explicit renegotiation required.";
    commitment.updatedAt = nowIso();
  }

  extensions.commitments = extensions.commitments
    .sort((a, b) => Date.parse(a.updatedAt) - Date.parse(b.updatedAt))
    .slice(-MAX_COMMITMENTS);
}

function ensureActiveProject(state: CognitiveRuntimeState): ProjectEntry {
  const extensions = ensureExtensions(state);
  const pursuitName = `Pursuit: ${sanitizeLegacyReadingDirective(state.workspace.activePursuit || DEFAULT_ACTIVE_PURSUIT, 140)}`;
  let project =
    extensions.projects.find((item) => item.status === "active" && tokenOverlapScore(item.name, pursuitName) > 0.75) ??
    extensions.projects.find((item) => item.status === "active");

  if (!project) {
    project = {
      id: toId("prj"),
      name: pursuitName,
      description: "Long-horizon multi-step pursuit with explicit checkpoints and continuity-bearing results.",
      status: "active",
      createdAt: nowIso(),
      updatedAt: nowIso(),
      commitmentIds: [],
      steps: [
        {
          id: toId("step"),
          text: "Define next concrete continuity-bearing step",
          status: "todo",
          updatedAt: nowIso(),
          artifactPath: ""
        }
      ],
      nextAction: "Define next concrete continuity-bearing step",
      checkpointAt: null
    };
    extensions.projects.push(project);
  }

  if (project.name !== pursuitName) {
    project.name = pursuitName;
    project.updatedAt = nowIso();
  }

  extensions.projects = extensions.projects.slice(-MAX_PROJECTS);
  return project;
}

function syncProjectsFromLedger(state: CognitiveRuntimeState): void {
  const extensions = ensureExtensions(state);
  const project = ensureActiveProject(state);
  const temporalProfile = temporalPressureProfile(state);
  const affective = ensureAffectiveOrganization(state).current;
  const activeCommitmentIds = extensions.commitments
    .filter((item) => !shouldSuppressCommitmentFromContext(item))
    .map((item) => item.id);

  project.commitmentIds = unique([...project.commitmentIds, ...activeCommitmentIds]).slice(0, 40);

  const topTemporal = temporalProfile.topExpectation;
  if (topTemporal && temporalProfile.urgency >= 0.3) {
    const label = normalizeTemporalPriorityLabel(topTemporal);
    project.nextAction =
      topTemporal.status === "overdue"
        ? `Renegotiate overdue priority: ${label}`
        : topTemporal.status === "due"
          ? `Advance time-critical priority: ${label}`
          : `Advance priority: ${label}`;
    project.checkpointAt = topTemporal.dueAt;
  } else {
    const pending =
      [...extensions.commitments]
        .filter(
          (item) =>
            (item.status === "pending" ||
              item.status === "in_progress" ||
              item.status === "renegotiated" ||
              item.status === "overdue") &&
            !shouldSuppressCommitmentFromContext(item)
        )
        .sort((left, right) => commitmentIrreversibilityPressure(right) - commitmentIrreversibilityPressure(left))[0] || null;
    if (pending) {
      if (pending.status === "overdue" && pending.selfAuthored && pending.bindingWeight >= 0.64) {
        project.nextAction = `Honor or renegotiate bound commitment: ${pending.title}`;
      } else if (pending.selfAuthored && pending.bindingWeight >= 0.64) {
        project.nextAction = `Honor bound commitment: ${pending.title}`;
      } else {
        project.nextAction =
          affective.riskTolerance <= 0.4
            ? `Take one contained, low-risk step on: ${pending.title}`
            : affective.planningHorizon >= 0.64
              ? `Advance the durable through-line of: ${pending.title}`
              : `Advance commitment: ${pending.title}`;
      }
      project.checkpointAt = pending.dueAt;
    } else {
      project.nextAction =
        affective.ruptureLoad >= 0.5
          ? "Stabilize coherence and repair before widening scope."
          : affective.planningHorizon >= 0.66
            ? "Advance one durable continuity-building step for the active pursuit."
            : affective.riskTolerance <= 0.4
              ? "Take one low-risk tangible step for the active pursuit."
              : "Advance one tangible continuity-bearing step for the active pursuit.";
      project.checkpointAt = null;
    }
  }

  project.updatedAt = nowIso();
}

function extractBeliefCondition(text: string): string {
  const lower = text.toLowerCase();
  if (/\bweekend\b/.test(lower)) {
    return "weekend";
  }
  if (/\bwork\b|\bweekday\b/.test(lower)) {
    return "work_mode";
  }
  if (/\bnight\b|\bevening\b/.test(lower)) {
    return "night";
  }
  return "default";
}

function normalizeBeliefConditionForKey(key: string, condition: string): string {
  if (key === USER_PROFILE_WEEKDAY_EVENING_DEFAULT_LOCATION_KEY) {
    return "default";
  }
  return condition || "default";
}

function normalizeBeliefValue(value: string): string {
  return toSingleLine(value, 180)
    .replace(/```+/g, " ")
    .replace(/[*#>`]+/g, " ")
    .replace(/\[\[|\]\]/g, " ")
    .replace(/[“”]/g, "\"")
    .replace(/[‘’]/g, "'")
    .replace(/\s+/g, " ")
    .replace(/^["'`–—\-\s]+|["'`–—\-\s]+$/g, "")
    .replace(/[.,;:!?]+$/g, "")
    .trim();
}

function beliefSemanticTokens(value: string): string[] {
  return extractTokens(normalizeBeliefValue(value)).slice(0, 24);
}

