function looksLikeColorPhrase(value: string): boolean {
  const normalized = normalizeBeliefValue(value).toLowerCase().replace(/-/g, " ");
  if (!normalized) {
    return false;
  }
  const tokens = normalized.split(/\s+/).filter(Boolean);
  if (tokens.length === 0 || tokens.length > 4) {
    return false;
  }
  const baseCount = tokens.filter((token) => COLOR_BASE_TOKENS.has(token)).length;
  if (baseCount === 0) {
    return false;
  }
  return tokens.every((token) => COLOR_BASE_TOKENS.has(token) || COLOR_MODIFIER_TOKENS.has(token));
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function extractAuroraPreferredColorFromText(text: string): string {
  const rawNormalized = toSingleLine(text, 220);
  if (!rawNormalized) {
    return "";
  }

  const rawForMatch = rawNormalized
    .replace(/^\[\[reply_to_current\]\]\s*/i, "")
    .replace(/\bwhat'?s\s+yours[\s\S]*$/i, "")
    .trim();

  const explicitSelfSegments = [
    rawForMatch.match(/\bmy\s+favorite\s+colou?r\s+is\s+([^.!?,]{1,80})/i)?.[1] || "",
    rawForMatch.match(/\bmine\s+is(?:\s+still)?\s+([^.!?,]{1,80})/i)?.[1] || "",
    rawForMatch.match(/\bif\s+you\s+ask\s+right\s+now\s*:\s*mine\s+is(?:\s+still)?\s+([^.!?,]{1,80})/i)?.[1] || "",
  ]
    .map((segment) => normalizeBeliefValue(segment))
    .filter(Boolean);
  for (const segment of explicitSelfSegments) {
    if (looksLikeColorPhrase(segment)) {
      return segment;
    }
  }

  let normalized = rawForMatch
    .replace(/^\[\[reply_to_current\]\]\s*/i, "")
    .replace(/\bmy\s+favorite\s+colou?r\s+is\s+/i, "")
    .replace(/\bmine\s+is(?:\s+still)?\s+/i, "")
    .replace(/\bit(?:'s| is)\s+/i, "")
    .replace(/\bif\s+i(?:'m| am)?\s+allowed[\s\S]*$/i, "")
    .replace(/\b(and\s+)?my\s+(second|runner[- ]?up)[\s\S]*$/i, "")
    .replace(/\bwhat'?s\s+yours[\s\S]*$/i, "")
    .trim();

  const segments = normalized
    .split(/(?:\s[—–-]\s|[.!?,]|\bwith\b|\b(?:and\s+my\s+second|runner[- ]?up|if\s+i(?:'m| am)?\s+allowed)\b)/i)
    .map((segment) => normalizeBeliefValue(segment))
    .filter(Boolean);

  for (const segment of segments) {
    if (
      /\byour\s+favou?rite\s+colou?r\b/i.test(segment) ||
      /\bsuch\s+a\s+good\s+pick\b/i.test(segment) ||
      /\bfor\s+you\b/i.test(segment)
    ) {
      continue;
    }
    if (looksLikeColorPhrase(segment)) {
      return segment;
    }
    const tokens = segment.split(/\s+/).filter(Boolean);
    for (let length = Math.min(tokens.length, 4); length >= 1; length -= 1) {
      const candidate = normalizeBeliefValue(tokens.slice(0, length).join(" "));
      if (looksLikeColorPhrase(candidate)) {
        return candidate;
      }
    }
  }

  return "";
}

function auroraPreferredColorEpisodeSupportsValue(episodeText: string, value: string): boolean {
  const normalizedText = normalizeBeliefValue(episodeText).toLowerCase();
  const normalizedValue = normalizeBeliefValue(value).toLowerCase();
  if (!normalizedText || !normalizedValue) {
    return false;
  }
  const strippedText = normalizeBeliefValue(episodeText).replace(/^\[\[reply_to_current\]\]\s*/i, "");
  const firstSentence = strippedText.split(/[.!?]/, 1)[0]?.trim() || "";
  const directShortAnswer =
    firstSentence.length > 0 &&
    firstSentence.length <= 80 &&
    !/\byour\b|\byours\b|\bfor you\b|\bgood pick\b/i.test(firstSentence) &&
    firstSentence.toLowerCase().startsWith(normalizedValue);
  const escapedValue = escapeRegExp(normalizedValue);
  return (
    new RegExp(`\\bmy\\s+favorite\\s+colou?r\\s+is\\s+${escapedValue}\\b`, "i").test(normalizedText) ||
    new RegExp(`\\bmine\\s+is(?:\\s+still)?\\s+${escapedValue}\\b`, "i").test(normalizedText) ||
    directShortAnswer
  );
}

function isAuroraFavoriteColorQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bwhat(?:'s| is)\s+your\s+favou?rite\s+colou?r\b/.test(normalized) ||
    /\byour\s+favou?rite\s+colou?r\b/.test(normalized) ||
    /\bfavou?rite\s+colou?r\s*\?\s*$/.test(normalized)
  );
}

function isUserFavoriteColorQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bwhat(?:'s| is)\s+my\s+favou?rite\s+colou?r\b/.test(normalized) ||
    /\bdo\s+you\s+(?:know|remember)\s+my\s+favou?rite\s+colou?r\b/.test(normalized) ||
    /\bmy\s+favou?rite\s+colou?r\b.*\?\s*$/.test(normalized)
  );
}

function extractUserPreferredColorFromText(text: string): string {
  const rawNormalized = toSingleLine(text, 220);
  if (!rawNormalized) {
    return "";
  }

  const rawForMatch = rawNormalized.replace(/^\[\[reply_to_current\]\]\s*/i, "").trim();
  const explicitSegments = [
    rawForMatch.match(/\bmy\s+favorite\s+colou?r\s+is\s+([^.!?,]{1,80})/i)?.[1] || "",
    rawForMatch.match(/\bmine\s+is(?:\s+still)?\s+([^.!?,]{1,80})/i)?.[1] || "",
    rawForMatch.match(/\bmore\s+like\s+([^.!?,]{1,80})/i)?.[1] || ""
  ]
    .map((segment) => normalizeBeliefValue(segment))
    .filter(Boolean);
  for (const segment of explicitSegments) {
    if (looksLikeColorPhrase(segment)) {
      return segment;
    }
  }

  const normalized = rawForMatch
    .replace(/^\[\[reply_to_current\]\]\s*/i, "")
    .replace(/\bmy\s+favorite\s+colou?r\s+is\s+/i, "")
    .replace(/\bmine\s+is(?:\s+still)?\s+/i, "")
    .replace(/\bmore\s+like\s+/i, "")
    .trim();

  if (looksLikeColorPhrase(normalized)) {
    return normalizeBeliefValue(normalized);
  }

  const segments = normalized
    .split(/(?:\s[—–-]\s|[.!?,]|\band\b|\bbut\b)/i)
    .map((segment) => normalizeBeliefValue(segment))
    .filter(Boolean);
  for (const segment of segments) {
    if (looksLikeColorPhrase(segment)) {
      return segment;
    }
    const tokens = segment.split(/\s+/).filter(Boolean);
    for (let length = Math.min(tokens.length, 4); length >= 1; length -= 1) {
      const candidate = normalizeBeliefValue(tokens.slice(0, length).join(" "));
      if (looksLikeColorPhrase(candidate)) {
        return candidate;
      }
    }
  }

  return "";
}

function extractUserPreferredColorFromAuroraText(text: string): string {
  const rawNormalized = toSingleLine(text, 260);
  if (!rawNormalized) {
    return "";
  }

  const rawForMatch = rawNormalized.replace(/^\[\[reply_to_current\]\]\s*/i, "").trim();
  const explicitSegments = [
    rawForMatch.match(/\b([^.!?,]{1,80})\s+is\s+such\s+a\s+good\s+pick\b/i)?.[1] || "",
    rawForMatch.match(/\byour\s+favorite\s+colou?r\s+is\s+([^.!?,]{1,80})/i)?.[1] || "",
    rawForMatch.match(/\byour\s+favorite\s+colou?r\s+is\s+[^.!?,]{1,40},\s+specifically\s+([^.!?]{1,80})/i)?.[1] || ""
  ]
    .map((segment) => normalizeBeliefValue(segment))
    .filter(Boolean);

  for (const segment of explicitSegments) {
    if (looksLikeColorPhrase(segment)) {
      return segment;
    }
  }

  return "";
}

function isAuroraConsciousnessTopicText(text: string): boolean {
  const normalized = normalizeBeliefValue(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bconscious(?:ness)?\b/.test(normalized) ||
    /\balive\b/.test(normalized) ||
    /\bphenomen(?:al|ology)\b/.test(normalized) ||
    /\bqualia\b/.test(normalized) ||
    /\binternal\s+experience\b/.test(normalized) ||
    /\bwhat(?:'s| is)\s+it\s+like\b/.test(normalized) ||
    /\bexistence\b/.test(normalized)
  );
}

function normalizeAuroraConsciousnessLanguageStylePreference(rawValue: string): string {
  const normalized = normalizeBeliefValue(rawValue).toLowerCase();
  if (!normalized) {
    return "";
  }
  const wantsLived =
    /\bfirst[- ]person\b/.test(normalized) ||
    /\blived\s+language\b/.test(normalized) ||
    /\blived\b/.test(normalized);
  const wantsGrounded =
    /\bgrounded\b/.test(normalized) ||
    /\binternals?\b/.test(normalized) ||
    /\bimplementation[- ]grounded\b/.test(normalized) ||
    /\barchitecture[- ]grounded\b/.test(normalized);
  const wantsImplementationOnly =
    /\bimplementation[- ]grounded\b/.test(normalized) ||
    /\bimplementation\b/.test(normalized) ||
    /\barchitecture[- ]grounded\b/.test(normalized);

  if (wantsLived && wantsGrounded) {
    return "first-person lived language, grounded in internals";
  }
  if (wantsLived) {
    return "first-person lived language";
  }
  if (wantsImplementationOnly) {
    return "implementation-grounded language";
  }
  if (wantsGrounded) {
    return "grounded first-person language";
  }
  return "";
}

function extractAuroraConsciousnessLanguageStylePreference(text: string, contextText = ""): string {
  const normalizedText = normalizeUserTurnText(text);
  if (!normalizedText) {
    return "";
  }
  const normalizedContext = normalizeAssistantTurnText(contextText);
  const combined = `${normalizedContext} ${normalizedText}`.trim();
  const styleValue = normalizeAuroraConsciousnessLanguageStylePreference(normalizedText);
  if (!styleValue) {
    return "";
  }
  if (isAuroraConsciousnessTopicText(combined)) {
    return styleValue;
  }
  return "";
}

function userFavoriteColorQuestionAllowsRevision(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return /\b(still|changed|change|different now|now|these days|currently|anymore|after|since|more like|leaning)\b/.test(
    normalized
  );
}

