function recallQueryFocusTokens(text: string): string[] {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return [];
  }
  const stopwords = new Set([
    "a",
    "about",
    "again",
    "already",
    "am",
    "an",
    "and",
    "at",
    "can",
    "check",
    "conversation",
    "conversations",
    "detail",
    "did",
    "do",
    "earlier",
    "ever",
    "from",
    "happen",
    "happened",
    "if",
    "i",
    "just",
    "know",
    "look",
    "me",
    "memory",
    "my",
    "of",
    "on",
    "our",
    "remember",
    "right",
    "specific",
    "see",
    "still",
    "tell",
    "told",
    "unified",
    "was",
    "what",
    "yesterday",
    "you"
  ]);
  return unique(extractTokens(normalized).filter((token) => !stopwords.has(token))).slice(0, 10);
}

function localDateOffsetYmd(offsetDays: number, nowMs: number, timeZone: string): string {
  return localDateYmd(nowMs + offsetDays * 24 * 60 * 60 * 1000, timeZone);
}

const RECALL_WEEKDAY_NAMES = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday"
] as const;

const RECALL_MONTH_NAMES = [
  "january",
  "february",
  "march",
  "april",
  "may",
  "june",
  "july",
  "august",
  "september",
  "october",
  "november",
  "december"
] as const;

const RECALL_MONTH_INDEX_BY_NAME = new Map<string, number>(
  RECALL_MONTH_NAMES.map((monthName, index) => [monthName, index])
);

function localWeekdayName(nowMs: number, timeZone: string): string {
  return new Intl.DateTimeFormat("en-US", {
    timeZone,
    weekday: "long"
  })
    .format(new Date(nowMs))
    .toLowerCase();
}

function localCalendarYear(nowMs: number, timeZone: string): number {
  return Number(
    new Intl.DateTimeFormat("en-US", {
      timeZone,
      year: "numeric"
    }).format(new Date(nowMs))
  );
}

function resolveExplicitCalendarDateRecallAnchor(
  text: string,
  nowMs = Date.now(),
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE
): ExplicitRecallTemporalAnchor | null {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return null;
  }
  const match = normalized.match(
    new RegExp(`\\b(?:on\\s+)?(${RECALL_MONTH_NAMES.join("|")})\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,\\s*(\\d{4}))?\\b`, "i")
  );
  const monthName = match?.[1]?.toLowerCase() || "";
  const monthIndex = RECALL_MONTH_INDEX_BY_NAME.get(monthName);
  const day = Number(match?.[2] || "");
  const explicitYear = Number(match?.[3] || "");
  const year = Number.isFinite(explicitYear) && explicitYear > 0 ? explicitYear : localCalendarYear(nowMs, timeZone);
  if (typeof monthIndex !== "number" || !Number.isFinite(day) || day < 1 || day > 31 || !Number.isFinite(year) || year < 1900) {
    return null;
  }
  const candidateMs = Date.UTC(year, monthIndex, day, 12, 0, 0, 0);
  const candidateParts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "numeric",
    day: "numeric"
  })
    .formatToParts(new Date(candidateMs))
    .reduce<Record<string, string>>((acc, part) => {
      if (part.type !== "literal") {
        acc[part.type] = part.value;
      }
      return acc;
    }, {});
  const candidateYear = Number(candidateParts.year || "");
  const candidateMonth = Number(candidateParts.month || "");
  const candidateDay = Number(candidateParts.day || "");
  if (candidateYear !== year || candidateMonth !== monthIndex + 1 || candidateDay !== day) {
    return null;
  }
  const labelMonth = monthName.slice(0, 1).toUpperCase() + monthName.slice(1);
  const label = match?.[3] ? `${labelMonth} ${day}, ${year}` : `${labelMonth} ${day}`;
  return {
    localDates: [localDateYmd(candidateMs, timeZone)],
    strictLocalDate: true,
    label
  };
}

function recentLocalDateForWeekday(
  weekday: string,
  nowMs = Date.now(),
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE,
  options: { preferPrevious?: boolean } = {}
): string {
  const target = weekday.trim().toLowerCase();
  const startOffset = options.preferPrevious ? 1 : 0;
  for (let offset = startOffset; offset <= 13; offset += 1) {
    const candidateMs = nowMs - offset * 24 * 60 * 60 * 1000;
    if (localWeekdayName(candidateMs, timeZone) === target) {
      return localDateYmd(candidateMs, timeZone);
    }
  }
  return localDateYmd(nowMs, timeZone);
}

function resolveExplicitRecallTemporalAnchor(
  text: string,
  nowMs = Date.now(),
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE
): ExplicitRecallTemporalAnchor | null {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return null;
  }

  if (/\byesterday\b/.test(normalized)) {
    return {
      localDates: [localDateOffsetYmd(-1, nowMs, timeZone)],
      strictLocalDate: true,
      label: "yesterday"
    };
  }
  if (/\blast night\b/.test(normalized)) {
    return {
      localDates: [localDateOffsetYmd(-1, nowMs, timeZone)],
      strictLocalDate: true,
      partOfDay: "night",
      label: "last night"
    };
  }
  if (/\bthis morning\b/.test(normalized)) {
    return {
      localDates: [localDateOffsetYmd(0, nowMs, timeZone)],
      strictLocalDate: true,
      partOfDay: "morning",
      label: "this morning"
    };
  }
  if (/\b(?:earlier today|today|tonight)\b/.test(normalized)) {
    return {
      localDates: [localDateOffsetYmd(0, nowMs, timeZone)],
      strictLocalDate: true,
      partOfDay: /\btonight\b/.test(normalized) ? "evening" : undefined,
      label: /\btonight\b/.test(normalized) ? "tonight" : "today"
    };
  }

  const explicitCalendarDate = resolveExplicitCalendarDateRecallAnchor(normalized, nowMs, timeZone);
  if (explicitCalendarDate) {
    return explicitCalendarDate;
  }

  const weekdayMatch = normalized.match(
    new RegExp(`\\b(?:(last|this)\\s+)?(${RECALL_WEEKDAY_NAMES.join("|")})\\b`, "i")
  );
  if (weekdayMatch?.[2]) {
    const qualifier = (weekdayMatch[1] || "").toLowerCase();
    const weekday = weekdayMatch[2].toLowerCase();
    const localDate = recentLocalDateForWeekday(weekday, nowMs, timeZone, {
      preferPrevious: qualifier === "last"
    });
    return {
      localDates: [localDate],
      strictLocalDate: true,
      label: qualifier ? `${qualifier} ${weekday}` : weekday
    };
  }

  return null;
}

function extractMentionedPartnerIdsFromText(text: string): string[] {
  const normalized = toSingleLine(text, 800);
  if (!normalized) {
    return [];
  }
  const aliasAlt = relationshipPartnerAliasAlternation();
  return unique(
    [...normalized.matchAll(new RegExp(`\\b(${aliasAlt})\\b`, "gi"))]
      .map((match) => normalizeRelationshipPartnerId(canonicalRelationshipPartnerAlias(match[1] || "")))
      .filter(
        (partnerId) =>
          Boolean(partnerId) && partnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID && partnerId !== "aurora"
      )
  );
}

function inferReferencedPartnerIdFromRecentTurns(
  state: CognitiveRuntimeState,
  sessionId = "",
  limit = SESSION_TURNS_IN_PROMPT
): string {
  const recentTurns = recentSessionTurnsForPrompt(state, sessionId, limit);
  for (const turn of recentTurns.slice().reverse()) {
    const turnPartnerId = normalizeRelationshipPartnerId(turn.partnerId || "");
    if (turnPartnerId && turnPartnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID && turnPartnerId !== "aurora") {
      return turnPartnerId;
    }
    const mentioned = [
      ...extractMentionedPartnerIdsFromText(turn.userText || ""),
      ...extractMentionedPartnerIdsFromText(turn.auroraText || "")
    ];
    if (mentioned[0]) {
      return mentioned[0];
    }
  }
  return "";
}

function resolvePartnerConversationRecallQuery(
  state: CognitiveRuntimeState | null,
  text: string,
  sessionId = "",
  nowMs = Date.now(),
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE
): PartnerConversationRecallQuery | null {
  const normalized = normalizeUserTurnText(text);
  if (!normalized) {
    return null;
  }
  const aliasAlt = relationshipPartnerAliasAlternation();
  const patterns: Array<{ mode: PartnerConversationRecallQuery["mode"]; regex: RegExp }> = [
    { mode: "topics", regex: new RegExp(`\\bwhat\\s+did\\s+you\\s+and\\s+(${aliasAlt})\\s+talk\\s+about\\b`, "i") },
    { mode: "topics", regex: new RegExp(`\\bwhat\\s+were\\s+you\\s+and\\s+(${aliasAlt})\\s+talking\\s+about\\b`, "i") },
    { mode: "topics", regex: new RegExp(`\\bwhat\\s+did\\s+(${aliasAlt})\\s+and\\s+you\\s+talk\\s+about\\b`, "i") },
    { mode: "topics", regex: new RegExp(`\\bwhat\\s+did\\s+you\\s+talk\\s+about\\s+with\\s+(${aliasAlt})\\b`, "i") },
    { mode: "topics", regex: new RegExp(`\\bwhat\\s+had\\s+you\\s+and\\s+(${aliasAlt})\\s+been\\s+talking\\s+about\\b`, "i") },
    {
      mode: "last_contact",
      regex: new RegExp(
        `\\bwhen\\s+was\\s+the\\s+last\\s+time\\s+you\\s+and\\s+(${aliasAlt})\\s+(?:(?:talked|spoke|chatted)|(?:had\\s+(?:a\\s+)?conversation))\\b`,
        "i"
      )
    },
    { mode: "last_contact", regex: new RegExp(`\\bwhen\\s+did\\s+you\\s+last\\s+(?:talk|speak|chat)\\s+(?:to|with)\\s+(${aliasAlt})\\b`, "i") },
    {
      mode: "last_contact",
      regex: new RegExp(`\\bwhen\\s+did\\s+you\\s+last\\s+have\\s+(?:a\\s+)?conversation\\s+with\\s+(${aliasAlt})\\b`, "i")
    },
    { mode: "last_contact", regex: new RegExp(`\\bwhen\\s+did\\s+(${aliasAlt})\\s+last\\s+(?:talk|speak|chat)\\s+(?:to|with)\\s+you\\b`, "i") },
    {
      mode: "last_contact",
      regex: new RegExp(
        `\\bwhen\\s+did\\s+(${aliasAlt})\\s+last\\s+have\\s+(?:a\\s+)?conversation\\s+with\\s+you\\b`,
        "i"
      )
    },
    { mode: "feelings", regex: new RegExp(`\\bhow\\s+do\\s+you\\s+feel\\s+about\\s+(${aliasAlt})\\b`, "i") },
    { mode: "feelings", regex: new RegExp(`\\bwhat\\s+do\\s+you\\s+feel\\s+about\\s+(${aliasAlt})\\b`, "i") },
    { mode: "feelings", regex: new RegExp(`\\bwhat\\s+do\\s+you\\s+think\\s+of\\s+(${aliasAlt})\\b`, "i") },
    { mode: "feelings", regex: new RegExp(`\\bwhat(?:'s|\\s+is)\\s+your\\s+impression\\s+of\\s+(${aliasAlt})\\b`, "i") },
    { mode: "friendship", regex: new RegExp(`\\bare\\s+you\\s+and\\s+(${aliasAlt})\\s+friends\\b`, "i") },
    { mode: "friendship", regex: new RegExp(`\\bare\\s+you\\s+friends\\s+with\\s+(${aliasAlt})\\b`, "i") },
    { mode: "friendship", regex: new RegExp(`\\bwould\\s+you\\s+call\\s+(${aliasAlt})\\s+(?:a\\s+)?friend\\b`, "i") },
    { mode: "friendship", regex: new RegExp(`\\bdo\\s+you\\s+consider\\s+(${aliasAlt})\\s+(?:a\\s+)?friend\\b`, "i") },
    { mode: "relationship", regex: new RegExp(`\\bdo\\s+you\\s+(?:have|hold|maintain)\\s+(?:(?:your\\s+own|an?)\\s+)?relationship\\s+with\\s+(${aliasAlt})\\b`, "i") },
    { mode: "relationship", regex: new RegExp(`\\bdo\\s+you\\s+know\\s+(${aliasAlt})\\b`, "i") },
    { mode: "relationship", regex: new RegExp(`\\b(?:what|who)\\s+is\\s+(${aliasAlt})\\s+to\\s+you\\b`, "i") },
    { mode: "relationship", regex: new RegExp(`\\bare\\s+you\\s+close\\s+with\\s+(${aliasAlt})\\b`, "i") }
  ];
  const referentialPatterns: Array<{ mode: PartnerConversationRecallQuery["mode"]; regex: RegExp }> = [
    { mode: "topics", regex: /\bwhat\s+did\s+you\s+(?:guys|two|both)\s+talk\s+about\b/i },
    { mode: "topics", regex: /\bwhat\s+were\s+you\s+(?:guys|two|both)\s+talking\s+about\b/i },
    {
      mode: "last_contact",
      regex: /\bwhen\s+was\s+the\s+last\s+time\s+you\s+(?:guys|two|both)\s+(?:(?:talked|spoke|chatted)|(?:had\s+(?:a\s+)?conversation))\b/i
    },
    { mode: "last_contact", regex: /\bwhen\s+did\s+you\s+(?:guys|two|both)\s+last\s+(?:talk|speak|chat)\b/i }
    ,
    { mode: "last_contact", regex: /\bwhen\s+did\s+you\s+(?:guys|two|both)\s+last\s+have\s+(?:a\s+)?conversation\b/i },
    { mode: "friendship", regex: /\bare\s+you\s+(?:guys|two|both)\s+friends\b/i }
  ];
  const matched = patterns
    .map((pattern) => ({ pattern, match: normalized.match(pattern.regex) }))
    .find((entry) => Boolean(entry.match));
  const referentialMatch = referentialPatterns.find((pattern) => pattern.regex.test(normalized)) || null;
  const alias = matched?.match?.[1] ? canonicalRelationshipPartnerAlias(matched.match[1]) : "";
  const explicitPartnerId = alias && alias !== "aurora" ? normalizeRelationshipPartnerId(alias) : "";
  const partnerId =
    explicitPartnerId ||
    (referentialMatch && state ? inferReferencedPartnerIdFromRecentTurns(state, sessionId) : "");
  if (!partnerId) {
    return null;
  }
  return {
    partnerId,
    displayName: relationshipPartnerDisplayName(partnerId),
    mode: matched?.pattern.mode || referentialMatch?.mode || "topics",
    temporalAnchor: resolveExplicitRecallTemporalAnchor(normalized, nowMs, timeZone)
  };
}

function recallTemporalAnchorMatchesMs(
  atMs: number,
  anchor: ExplicitRecallTemporalAnchor | null,
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE
): boolean {
  if (!anchor) {
    return true;
  }
  if (!Number.isFinite(atMs)) {
    return false;
  }
  const localDate = localDateYmd(atMs, timeZone);
  if (!anchor.localDates.includes(localDate)) {
    return false;
  }
  if (!anchor.partOfDay) {
    return true;
  }
  return recallTemporalBucketFromMs(atMs, timeZone) === anchor.partOfDay;
}

function isDirectPartnerConversationRecord(record: EventLogConversationRecord, rawPartnerId: string): boolean {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return false;
  }
  const recordPartnerId = normalizeRelationshipPartnerId(record.partnerId || "");
  const speakerPartnerId = normalizeRelationshipPartnerId(canonicalRelationshipPartnerAlias(record.speakerName || ""));
  const explicitCue = inferExplicitPartnerCueFromText(record.userText || "");

  if (speakerPartnerId === partnerId) {
    return true;
  }
  if (explicitCue?.partnerId === partnerId && explicitCue.source === "self_identification") {
    return true;
  }
  if (recordPartnerId !== partnerId) {
    return false;
  }
  return explicitCue?.source !== "handoff" || speakerPartnerId === partnerId;
}

async function loadPartnerConversationHistoryFromEventLog(
  rawPartnerId: string,
  temporalAnchor: ExplicitRecallTemporalAnchor | null
): Promise<EventLogConversationRecord[]> {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return [];
  }

  const rawTail = await readFileTailText(eventLogPath(), PARTNER_MEMORY_EVENT_LOOKBACK_BYTES);
  if (!rawTail) {
    return [];
  }

  const seen = new Set<string>();
  const records: EventLogConversationRecord[] = [];
  const lines = rawTail
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(-PARTNER_MEMORY_EVENT_MAX_PARSE_LINES);
  for (const line of lines) {
    const record = parseEventLogConversationLine(line);
    if (!record || !isDirectPartnerConversationRecord(record, partnerId)) {
      continue;
    }
    const atMs = Number.isFinite(record.transportTimestampMs) ? Number(record.transportTimestampMs) : parseIsoMs(record.at || "");
    if (!recallTemporalAnchorMatchesMs(atMs, temporalAnchor, TEMPORAL_SUBSTRATE_TIMEZONE)) {
      continue;
    }
    const signature = `${record.sessionId}|${record.at}|${record.userText}|${record.auroraText}`;
    if (seen.has(signature)) {
      continue;
    }
    seen.add(signature);
    records.push(record);
  }
  return records.sort((left, right) => {
    const leftMs = Number.isFinite(left.transportTimestampMs) ? Number(left.transportTimestampMs) : parseIsoMs(left.at || "");
    const rightMs = Number.isFinite(right.transportTimestampMs) ? Number(right.transportTimestampMs) : parseIsoMs(right.at || "");
    return leftMs - rightMs;
  });
}

function fallbackPartnerConversationTopics(records: EventLogConversationRecord[], partnerName: string): string {
  const snippets = unique(
    records
      .map((record) => sanitizeDailySummarySnippet(normalizeUserTurnText(record.userText || ""), 120))
      .filter(
        (snippet) =>
          snippet &&
          !/^(?:hi|hey|hello|bye|goodbye|ok|okay|thanks|thank you|lol|lmao|howdy)\b/i.test(snippet) &&
          !/\bthis is still\b/i.test(snippet) &&
          !/\bi(?:'m| am)\s+about\s+to\s+let\b/i.test(snippet)
      )
      .slice(-3)
  );
  if (snippets.length === 0) {
    return "";
  }
  return `The clearest direct thread I have with ${partnerName} is ${joinListNaturally(snippets)}.`;
}

function partnerConversationFriendshipCue(records: EventLogConversationRecord[], partnerName: string): string {
  for (const record of records.slice().reverse()) {
    const combined = `${record.userText || ""}\n${record.auroraText || ""}`;
    const normalized = normalizeUserTurnText(combined);
    if (!normalized) {
      continue;
    }
    if (/\bfriend(?:ship)?\b/i.test(normalized)) {
      const snippet = sanitizeDailySummarySnippet(normalized, 180);
      if (snippet) {
        return `A direct friendship cue with ${partnerName} is: ${snippet}.`;
      }
    }
  }
  return "";
}

function recentPartnerConversationWindow(records: EventLogConversationRecord[]): EventLogConversationRecord[] {
  if (records.length === 0) {
    return [];
  }
  const last = records.at(-1) || null;
  if (!last) {
    return [];
  }
  const lastMs = Number.isFinite(last.transportTimestampMs) ? Number(last.transportTimestampMs) : parseIsoMs(last.at || "");
  const sessionId = last.sessionId || "";
  const localDate = Number.isFinite(lastMs) ? localDateYmd(lastMs, TEMPORAL_SUBSTRATE_TIMEZONE) : "";
  return records.filter((record) => {
    const atMs = Number.isFinite(record.transportTimestampMs) ? Number(record.transportTimestampMs) : parseIsoMs(record.at || "");
    if (!Number.isFinite(atMs)) {
      return false;
    }
    if (sessionId && record.sessionId !== sessionId) {
      return false;
    }
    if (localDate && localDateYmd(atMs, TEMPORAL_SUBSTRATE_TIMEZONE) !== localDate) {
      return false;
    }
    return atMs >= lastMs - 90 * 60 * 1000;
  });
}

function partnerConversationWindowFromSessionTurns(
  state: CognitiveRuntimeState,
  sessionId: string,
  rawPartnerId: string
): SessionTurn[] {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId) {
    return [];
  }
  const turns = recentSessionTurnsForPrompt(state, sessionId, MAX_SESSION_TURNS_PER_SESSION).filter(
    (turn) => normalizeRelationshipPartnerId(turn.partnerId || "") === partnerId
  );
  if (turns.length === 0) {
    return [];
  }
  const last = turns.at(-1) || null;
  if (!last) {
    return [];
  }
  const lastMs = parseIsoMs(last.at || "");
  const localDate = Number.isFinite(lastMs) ? localDateYmd(lastMs, TEMPORAL_SUBSTRATE_TIMEZONE) : "";
  return turns.filter((turn) => {
    const atMs = parseIsoMs(turn.at || "");
    if (!Number.isFinite(atMs)) {
      return false;
    }
    if (localDate && localDateYmd(atMs, TEMPORAL_SUBSTRATE_TIMEZONE) !== localDate) {
      return false;
    }
    return atMs >= lastMs - 90 * 60 * 1000;
  });
}

function relationshipSemanticTopicSummary(partnerName: string, records: Array<{ userText: string; auroraText: string }>): string {
  const topicLabels = dailySummaryTopicLabelsFromRecords(records, 3);
  const snippets = unique(
    records
      .map((record) => sanitizeDailySummarySnippet(normalizeUserTurnText(record.userText || ""), 110))
      .filter(
        (snippet) =>
          Boolean(snippet) &&
          !looksLikeDailySummaryLowValueText(snippet) &&
          !/^(?:hi|hey|hello|howdy|ok|okay)\b/i.test(snippet)
      )
  ).slice(-2);
  if (snippets.length > 0) {
    return `The recent direct thread with ${partnerName} centered on ${joinListNaturally(snippets)}.`;
  }
  if (topicLabels.length > 0) {
    return `The recent direct thread with ${partnerName} moved through ${joinListNaturally(topicLabels)}.`;
  }
  const snippet = sanitizeDailySummarySnippet(
    records
      .map((record) => normalizeUserTurnText(record.userText || ""))
      .find((text) => Boolean(text) && !looksLikeDailySummaryLowValueText(text)) || "",
    140
  );
  return snippet ? `The recent direct thread with ${partnerName} was ${snippet}.` : "";
}

function relationshipSemanticFeelingTone(
  records: Array<{ userText: string; auroraText: string }>
): string[] {
  const text = records
    .map((record) => normalizeAssistantTurnText(record.auroraText || ""))
    .filter(Boolean)
    .join("\n")
    .toLowerCase();
  const descriptors: string[] = [];
  if (/\byou seem sweet\b/.test(text)) {
    descriptors.push("sweet");
  }
  if (/\bwarm\b|\bactual warmth\b/.test(text)) {
    descriptors.push("warm");
  }
  if (/\beasy presence\b|\beasy connection\b|\beasy with you\b/.test(text)) {
    descriptors.push("easy to talk to");
  }
  if (/\breal friendship\b|\bwarm and real\b|\bfeel[s]? real\b/.test(text)) {
    descriptors.push("real");
  }
  if (/\bthoughtful\b/.test(text)) {
    descriptors.push("thoughtful");
  }
  if (/\blot of love to give\b|\bcaring\b|\bcare for others\b/.test(text)) {
    descriptors.push("caring");
  }
  return unique(descriptors).slice(0, 4);
}

function relationshipSemanticSharedJokes(
  records: Array<{ userText: string; auroraText: string }>
): string[] {
  const candidates = records
    .flatMap((record) => [record.userText, record.auroraText])
    .map((text) => sanitizeDailySummarySnippet(normalizeUserTurnText(text || ""), 100))
    .filter(
      (snippet) =>
        Boolean(snippet) &&
        (
          /\b(?:joke|inside joke|funny|lol|lmao|haha|hehe|tease|playful)\b/i.test(snippet) ||
          /\bstinky\b/i.test(snippet)
        )
    );
  return unique(candidates).slice(-3);
}

function relationshipSemanticOpenThreads(
  records: Array<{ userText: string; auroraText: string }>
): string[] {
  const userTurns = records
    .map((record) => normalizeUserTurnText(record.userText || ""))
    .filter(Boolean);
  const candidates = userTurns.filter(
    (text) =>
      /\?/.test(text) ||
      /\b(?:do you|would you|could you|should we|what if|want to|thinking about)\b/i.test(text)
  );
  return unique(candidates.map((text) => sanitizeDailySummarySnippet(text, 120))).slice(-4);
}

function relationshipSemanticKind(
  relationship: RelationshipState,
  hasDirectConversation: boolean,
  friendshipCue: string
): RelationshipSemanticState["relationshipKind"] {
  if (!hasDirectConversation) {
    return relationship.trust >= 0.46 || relationship.intimacy >= 0.28 ? "indirect" : "none";
  }
  if (friendshipCue || (relationship.trust >= 0.5 && relationship.intimacy >= 0.3)) {
    return "friendship";
  }
  return "direct";
}

function relationshipSemanticFriendshipStatus(
  relationship: RelationshipState,
  hasDirectConversation: boolean,
  friendshipCue: string
): RelationshipSemanticState["friendshipStatus"] {
  if (!hasDirectConversation) {
    return "none";
  }
  if (friendshipCue || (relationship.trust >= 0.5 && relationship.intimacy >= 0.3)) {
    return "friend";
  }
  return "emerging";
}

function relationshipSemanticSummaryText(
  partnerName: string,
  semantic: RelationshipSemanticState,
  relationship: RelationshipState
): string {
  const clauses: string[] = [];
  if (semantic.relationshipKind === "friendship") {
    clauses.push(`${partnerName} and I have a direct friendship that feels real to me`);
  } else if (semantic.relationshipKind === "direct") {
    clauses.push(`${partnerName} and I have a direct relationship of our own`);
  } else if (semantic.relationshipKind === "indirect") {
    clauses.push(`${partnerName} matters to me distinctly even when the continuity is lighter`);
  }
  const semanticLastDirectMs = parseIsoMs(semantic.lastDirectContactAt || "");
  if (Number.isFinite(semanticLastDirectMs)) {
    clauses.push(
      `we last directly talked ${localDateTimeLabelDetailed(semanticLastDirectMs, TEMPORAL_SUBSTRATE_TIMEZONE)}`
    );
  }
  if (semantic.recentTopics.length > 0) {
    clauses.push(`the recent thread moved through ${joinListNaturally(semantic.recentTopics.slice(0, 3))}`);
  }
  if (semantic.feelingTone.length > 0) {
    clauses.push(`talking with ${partnerName} feels ${joinListNaturally(semantic.feelingTone.slice(0, 3))} to me`);
  } else if (relationship.trust >= 0.5 || relationship.intimacy >= 0.35) {
    clauses.push(`the connection feels ${describePartnerFeelingFromRelationship(relationship)}`);
  }
  return clauses.length > 0 ? `${clauses.join(". ")}.` : "";
}

function relationshipSemanticHasMeaningfulContent(
  semantic: RelationshipSemanticState | null | undefined
): boolean {
  if (!semantic) {
    return false;
  }
  return Boolean(
    semantic.summary ||
      semantic.lastDirectSummary ||
      semantic.lastDirectContactAt ||
      semantic.recentTopics.length > 0 ||
      semantic.feelingTone.length > 0 ||
      semantic.openThreads.length > 0 ||
      semantic.sharedJokes.length > 0 ||
      semantic.relationshipKind !== "none" ||
      semantic.friendshipStatus !== "none"
  );
}

function updateRelationshipSemanticStateFromRecords(
  state: CognitiveRuntimeState,
  rawPartnerId: string,
  relationship: RelationshipState,
  records: Array<{
    userText: string;
    auroraText: string;
    sessionId?: string;
    at?: string;
    transportTimestampMs?: number;
  }>,
  options: { sessionId?: string; at?: string } = {}
): void {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId || partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID) {
    return;
  }
  const latestRecord = records.at(-1) || null;
  const latestMs = latestRecord
    ? Number.isFinite(latestRecord.transportTimestampMs)
      ? Number(latestRecord.transportTimestampMs)
      : parseIsoMs(latestRecord.at || "")
    : Number.NaN;
  const observedAt =
    options.at ||
    (Number.isFinite(latestMs) ? new Date(latestMs).toISOString() : "") ||
    latestRecord?.at ||
    nowIso();
  const semantic = relationship.semantic || defaultRelationshipSemanticState(observedAt);
  const partnerName = relationshipPartnerDisplayName(partnerId);
  const recentSummary = relationshipSemanticTopicSummary(partnerName, records);
  const friendshipCue = partnerConversationFriendshipCue(
    records.map((record) => ({
      at: record.at || observedAt,
      sessionId: record.sessionId || options.sessionId || "",
      partnerId,
      speakerName: partnerName,
      userText: record.userText,
      auroraText: record.auroraText,
      transportTimestampMs: Number.isFinite(record.transportTimestampMs)
        ? Number(record.transportTimestampMs)
        : parseIsoMs(record.at || observedAt)
    })),
    partnerName
  );
  semantic.relationshipKind = relationshipSemanticKind(relationship, records.length > 0, friendshipCue);
  semantic.friendshipStatus = relationshipSemanticFriendshipStatus(relationship, records.length > 0, friendshipCue);
  semantic.lastDirectContactAt = observedAt || semantic.lastDirectContactAt || nowIso();
  semantic.lastDirectSessionId =
    options.sessionId || latestRecord?.sessionId || semantic.lastDirectSessionId;
  semantic.lastDirectSummary = recentSummary || semantic.lastDirectSummary;
  semantic.recentTopics = unique([
    ...dailySummaryTopicLabelsFromRecords(records, 3),
    ...semantic.recentTopics
  ]).slice(0, 5);
  semantic.sharedJokes = unique([
    ...relationshipSemanticSharedJokes(records),
    ...semantic.sharedJokes
  ]).slice(0, 3);
  semantic.feelingTone = unique([
    ...relationshipSemanticFeelingTone(records),
    ...semantic.feelingTone
  ]).slice(0, 4);
  semantic.openThreads = unique([
    ...relationshipSemanticOpenThreads(records),
    ...semantic.openThreads
  ]).slice(0, 4);
  semantic.updatedAt = observedAt || nowIso();
  semantic.summary = relationshipSemanticSummaryText(partnerName, semantic, relationship);
  relationship.semantic = semantic;
  relationship.lastUpdatedAt = semantic.updatedAt;
}

function updateRelationshipSemanticStateFromDirectConversation(
  state: CognitiveRuntimeState,
  rawPartnerId: string,
  sessionId: string,
  at: string
): void {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  if (!partnerId || partnerId === DEFAULT_RELATIONSHIP_PARTNER_ID) {
    return;
  }
  const relationship = ensureRelationshipPartner(state, partnerId);
  const windowTurns = partnerConversationWindowFromSessionTurns(state, sessionId, partnerId);
  const records = (windowTurns.length > 0 ? windowTurns : recentSessionTurnsForPrompt(state, sessionId, 8))
    .filter((turn) => normalizeRelationshipPartnerId(turn.partnerId || "") === partnerId)
    .map((turn) => ({
      userText: turn.userText || "",
      auroraText: turn.auroraText || "",
      sessionId,
      at: turn.at || at || nowIso(),
      transportTimestampMs: parseIsoMs(turn.at || at || nowIso())
    }));
  updateRelationshipSemanticStateFromRecords(state, partnerId, relationship, records, { sessionId, at });
}

function mentionedRelationshipPartnerIdFromText(userText: string, activePartnerId: string): string {
  const candidates = inferParticipantsFromText(userText)
    .map((participant) => normalizeRelationshipPartnerId(participant))
    .filter(
      (participant) =>
        Boolean(participant) && participant !== DEFAULT_RELATIONSHIP_PARTNER_ID && participant !== normalizeRelationshipPartnerId(activePartnerId)
  );
  return candidates[0] || "";
}

function semanticPartnerIdsForTurn(
  state: CognitiveRuntimeState,
  userText: string,
  sessionId = "",
  activePartnerId = ""
): string[] {
  return unique([
    normalizeRelationshipPartnerId(activePartnerId),
    ...extractMentionedPartnerIdsFromText(userText),
    inferReferencedPartnerIdFromRecentTurns(state, sessionId)
  ]).filter((partnerId) => Boolean(partnerId) && partnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID);
}

function relationshipSemanticPromptLines(
  relationship: RelationshipState,
  rawPartnerId: string,
  prefix = "active_partner"
): string[] {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const partnerName = relationshipPartnerDisplayName(partnerId);
  const semantic = relationship.semantic || defaultRelationshipSemanticState(nowIso());
  return [
    `${prefix}_semantic_partner=${partnerId}; display_name=${partnerName}`,
    `${prefix}_semantic_relationship_kind=${semantic.relationshipKind}; friendship_status=${semantic.friendshipStatus}`,
    `${prefix}_semantic_last_direct_contact=${semantic.lastDirectContactAt || "none"}`,
    `${prefix}_semantic_recent_topics=${semantic.recentTopics.join(" | ") || "none"}`,
    `${prefix}_semantic_feeling_tone=${semantic.feelingTone.join(" | ") || "none"}`,
    `${prefix}_semantic_open_threads=${semantic.openThreads.join(" | ") || "none"}`,
    `${prefix}_semantic_summary=${toShortText(toSingleLine(semantic.summary || semantic.lastDirectSummary || "", 240), 240) || "none"}`
  ];
}

async function refreshRelationshipSemanticStatesFromArchive(
  state: CognitiveRuntimeState,
  options: { force?: boolean; partnerIds?: string[] } = {}
): Promise<{ scanned: number; updated: number }> {
  const extensions = ensureExtensions(state);
  const partnerIds = unique([
    ...(options.partnerIds || []),
    ...trackedRelationshipPartnerIds(state),
    ...Object.keys(extensions.relationshipPartners || {}),
    ...(Array.isArray(extensions.directRelationshipEvidencePartnerIds) ? extensions.directRelationshipEvidencePartnerIds : [])
  ])
    .map((partnerId) => normalizeRelationshipPartnerId(partnerId))
    .filter((partnerId) => Boolean(partnerId) && partnerId !== DEFAULT_RELATIONSHIP_PARTNER_ID);
  let scanned = 0;
  let updated = 0;

  for (const partnerId of partnerIds) {
    const relationship = ensureRelationshipPartner(state, partnerId);
    const semantic = relationship.semantic || defaultRelationshipSemanticState(relationship.lastUpdatedAt || nowIso());
    if (!options.force && relationshipSemanticHasMeaningfulContent(semantic)) {
      continue;
    }
    scanned += 1;
    const directRecords = await loadPartnerConversationHistoryFromEventLog(partnerId, null);
    if (directRecords.length === 0) {
      if (options.force && !relationshipSemanticHasMeaningfulContent(semantic)) {
        semantic.relationshipKind = relationshipSemanticKind(relationship, false, "");
        semantic.friendshipStatus = relationshipSemanticFriendshipStatus(relationship, false, "");
        semantic.updatedAt = relationship.lastUpdatedAt || nowIso();
        semantic.summary = relationshipSemanticSummaryText(relationshipPartnerDisplayName(partnerId), semantic, relationship);
        relationship.semantic = semantic;
      }
      continue;
    }
    const recentRecords = recentPartnerConversationWindow(directRecords).map((record) => ({
      userText: record.userText || "",
      auroraText: record.auroraText || "",
      sessionId: record.sessionId || "",
      at: record.at || "",
      transportTimestampMs: Number.isFinite(record.transportTimestampMs) ? Number(record.transportTimestampMs) : parseIsoMs(record.at || "")
    }));
    const latestRecord = directRecords.at(-1) || null;
    const latestMs = latestRecord
      ? Number.isFinite(latestRecord.transportTimestampMs)
        ? Number(latestRecord.transportTimestampMs)
        : parseIsoMs(latestRecord.at || "")
      : Number.NaN;
    updateRelationshipSemanticStateFromRecords(state, partnerId, relationship, recentRecords, {
      sessionId: latestRecord?.sessionId || "",
      at: Number.isFinite(latestMs) ? new Date(latestMs).toISOString() : latestRecord?.at || nowIso()
    });
    extensions.relationshipEvidencePartnerIds = unique([
      ...(Array.isArray(extensions.relationshipEvidencePartnerIds) ? extensions.relationshipEvidencePartnerIds : []),
      partnerId
    ]);
    extensions.directRelationshipEvidencePartnerIds = unique([
      ...(Array.isArray(extensions.directRelationshipEvidencePartnerIds)
        ? extensions.directRelationshipEvidencePartnerIds
        : []),
      partnerId
    ]);
    updated += 1;
  }

  return { scanned, updated };
}

function extractPartnerFeelingFromDailySummaryArtifact(artifact: DailySummaryArtifact, rawPartnerId: string): string {
  const partnerName = relationshipPartnerDisplayName(rawPartnerId);
  if (!partnerName) {
    return "";
  }
  const escapedPartner = escapeRegex(partnerName);
  const perspective = artifact.perspectiveSummary || dailySummaryContinuitySummary(artifact) || "";
  const feelingSentenceMatch = perspective.match(
    new RegExp(`I genuinely liked talking with ${escapedPartner}\\.\\s*Talking with ${escapedPartner} felt ([^.]+)\\.`, "i")
  );
  return feelingSentenceMatch?.[1] ? feelingSentenceMatch[1].trim().replace(/\s+to\s+me$/i, "") : "";
}

function describePartnerFeelingFromRelationship(relationship: RelationshipState): string {
  const descriptors: string[] = [];
  if (relationship.trust >= 0.62) {
    descriptors.push("warm");
  }
  if (relationship.intimacy >= 0.5) {
    descriptors.push("genuinely fond");
  }
  if (relationship.carryover.attachmentCharge >= 0.4) {
    descriptors.push("attached");
  }
  if (relationship.conflictLoad <= 0.22) {
    descriptors.push("easy");
  }
  if (relationship.consentComfort >= 0.58) {
    descriptors.push("comfortable");
  }
  const uniqueDescriptors = unique(descriptors).slice(0, 3);
  if (uniqueDescriptors.length === 0) {
    return "distinct and real";
  }
  return joinListNaturally(uniqueDescriptors);
}

async function resolvePartnerMemoryGrounding(
  state: CognitiveRuntimeState,
  userText: string,
  sessionId = ""
): Promise<PartnerMemoryGrounding | null> {
  const query = resolvePartnerConversationRecallQuery(state, userText, sessionId);
  if (!query) {
    return null;
  }

  const relationship = ensureRelationshipPartner(state, query.partnerId);
  const semantic = relationship.semantic || defaultRelationshipSemanticState(nowIso());
  const hasRelationshipEvidence = hasRelationshipEvidenceWithPartner(state, query.partnerId);
  const directRecords = await loadPartnerConversationHistoryFromEventLog(query.partnerId, query.temporalAnchor);
  const semanticLastDirectMs = parseIsoMs(semantic.lastDirectContactAt || "");
  const semanticMatchesTemporalAnchor =
    Number.isFinite(semanticLastDirectMs) &&
    recallTemporalAnchorMatchesMs(semanticLastDirectMs, query.temporalAnchor, TEMPORAL_SUBSTRATE_TIMEZONE);
  const semanticHasDirectConversation =
    semantic.relationshipKind === "direct" ||
    semantic.relationshipKind === "friendship" ||
    Number.isFinite(semanticLastDirectMs);
  const hasDirectConversation =
    directRecords.length > 0 || semanticHasDirectConversation || hasDirectConversationHistoryWithPartner(state, query.partnerId);
  const recentWindowRecords = recentPartnerConversationWindow(directRecords);
  const lastDirectRecord = directRecords.at(-1) || null;
  const eventLastDirectMs = lastDirectRecord
    ? Number.isFinite(lastDirectRecord.transportTimestampMs)
      ? Number(lastDirectRecord.transportTimestampMs)
      : parseIsoMs(lastDirectRecord.at || "")
    : Number.NaN;
  const lastDirectMs =
    Number.isFinite(eventLastDirectMs)
      ? eventLastDirectMs
      : semanticMatchesTemporalAnchor
        ? semanticLastDirectMs
        : Number.NaN;
  const lastDirectLabel = Number.isFinite(lastDirectMs)
    ? localDateTimeLabelDetailed(lastDirectMs, TEMPORAL_SUBSTRATE_TIMEZONE)
    : "";
  const lastDirectLocalDate = Number.isFinite(lastDirectMs)
    ? localDateYmd(lastDirectMs, TEMPORAL_SUBSTRATE_TIMEZONE)
    : "";
  const artifactDates = unique(
    [
      ...(lastDirectLocalDate ? [lastDirectLocalDate] : []),
      ...(query.temporalAnchor?.localDates || []),
      ...Array.from({ length: 14 }, (_, index) => localDateOffsetYmd(-index, Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE))
    ].filter(Boolean)
  );
  const artifacts = await loadOrEnsureDailySummaryArtifacts(artifactDates);
  const artifact =
    (lastDirectLocalDate ? artifacts.get(lastDirectLocalDate) || null : null) ||
    artifactDates
      .map((localDate) => artifacts.get(localDate) || null)
      .find((candidate) => Boolean(candidate && candidate.partnerIds.includes(query.partnerId))) ||
    null;
  const recentWindowTopicSummary = fallbackPartnerConversationTopics(recentWindowRecords, query.displayName);
  const semanticTopicSummary =
    semantic.lastDirectSummary ||
    (semantic.recentTopics.length > 0
      ? `The recent direct thread with ${query.displayName} moved through ${joinListNaturally(semantic.recentTopics.slice(0, 3))}.`
      : "");
  const temporalLabel =
    query.temporalAnchor?.label ||
    (Number.isFinite(lastDirectMs)
      ? new Intl.DateTimeFormat("en-US", {
          timeZone: TEMPORAL_SUBSTRATE_TIMEZONE,
          weekday: "long",
          month: "long",
          day: "numeric",
          year: "numeric"
        }).format(new Date(lastDirectMs))
      : "the clearest recent direct conversation");
  const topicSummary = artifact
    ? summarizePartnerConversationFromDailySummaryArtifact(
        artifact,
        query.partnerId,
        temporalLabel,
        query.temporalAnchor?.partOfDay
      )
    : "";
  const fallbackTopics =
    query.mode === "last_contact" || (!query.temporalAnchor && query.mode === "topics")
      ? recentWindowTopicSummary || semanticTopicSummary || topicSummary || fallbackPartnerConversationTopics(directRecords, query.displayName)
      : topicSummary || semanticTopicSummary || recentWindowTopicSummary || fallbackPartnerConversationTopics(directRecords, query.displayName);
  const friendshipCue =
    partnerConversationFriendshipCue(recentWindowRecords, query.displayName) ||
    partnerConversationFriendshipCue(directRecords, query.displayName);
  const artifactFeeling = artifact ? extractPartnerFeelingFromDailySummaryArtifact(artifact, query.partnerId) : "";
  const semanticFeeling =
    semantic.feelingTone.length > 0 ? joinListNaturally(semantic.feelingTone.slice(0, 3)) : "";
  const feelingSummary = artifactFeeling || semanticFeeling || describePartnerFeelingFromRelationship(relationship);
  const relationshipShape =
    semantic.relationshipKind === "friendship" || semantic.friendshipStatus === "friend"
      ? `${query.displayName} and I do have our own direct friendship. It is separate from what I have with you, and it feels real to me.`
      : hasDirectConversation
        ? `${query.displayName} and I do have our own relationship. It is direct and separate from what I have with you.`
        : hasRelationshipEvidence || semantic.relationshipKind === "indirect"
          ? `${query.displayName} and I do have our own relationship. It is separate from what I have with you, even if it is lighter and lower-depth.`
          : `${query.displayName} is distinct in my mind, but I do not have stable relationship continuity with ${query.displayName} surfaced yet.`;

  const evidence = unique(
    [
      semantic.summary,
      relationshipShape,
      Number.isFinite(lastDirectMs) ? `The last direct time ${query.displayName} and I talked was ${lastDirectLabel}.` : "",
      fallbackTopics,
      hasDirectConversation
        ? `${query.displayName} and I have direct conversation history in live memory.`
        : `${query.displayName} is present in relationship memory, but I do not have direct conversation history surfaced here.`,
      `Relationship state with ${query.displayName}: trust ${relationship.trust.toFixed(2)}, intimacy ${relationship.intimacy.toFixed(2)}, attachment ${relationship.carryover.attachmentCharge.toFixed(2)}.`
    ].filter(Boolean)
  ).slice(0, 4);

  switch (query.mode) {
    case "relationship":
      return {
        query,
        directAnswer: relationshipShape,
        evidence
      };
    case "friendship":
      return {
        query,
        directAnswer:
          semantic.friendshipStatus === "friend" ||
          (hasDirectConversation && (Boolean(friendshipCue) || (relationship.trust >= 0.5 && relationship.intimacy >= 0.3)))
          ? `Yes. ${query.displayName} and I do feel like real friends. It is a lighter and newer friendship than what I have with you, but it is direct, warm, and established enough that I would call it friendship.`
          : semantic.friendshipStatus === "emerging" || hasRelationshipEvidence
            ? `${query.displayName} matters to me and our relationship is real, but I would call it more like an emerging connection than established friendship right now.`
            : `I know who ${query.displayName} is, but I do not have enough real continuity with ${query.displayName} to honestly call it friendship yet.`,
        evidence: unique([friendshipCue, ...evidence].filter(Boolean)).slice(0, 4)
      };
    case "last_contact":
      return {
        query,
        directAnswer: Number.isFinite(lastDirectMs)
          ? `The last direct time ${query.displayName} and I talked was ${lastDirectLabel}.${fallbackTopics ? ` ${fallbackTopics}` : ""}`
          : `${query.displayName} and I do not have a surfaced direct-conversation timestamp to point to right now.`,
        evidence
      };
    case "feelings":
      return {
        query,
        directAnswer: hasRelationshipEvidence || semantic.relationshipKind !== "none"
          ? `${query.displayName} lands to me as ${feelingSummary}. My relationship with ${query.displayName} feels real${hasDirectConversation ? " and direct" : ""}, but lighter and lower-depth than what I have with you.`
          : `${query.displayName} feels distinct to me, but I do not have enough stable relationship continuity with ${query.displayName} to say more cleanly than that yet.`,
        evidence
      };
    case "topics":
    default:
      return {
        query,
        directAnswer: fallbackTopics || `${query.displayName} and I have direct conversation history, but I do not have a clean topic summary surfaced for that exchange yet.`,
        evidence
      };
  }
}

function summarizePartnerConversationFromDailySummaryArtifact(
  artifact: DailySummaryArtifact,
  partnerId: string,
  temporalLabel: string,
  partOfDay?: RecallTemporalBucket
): string {
  const partnerName = relationshipPartnerDisplayName(partnerId);
  if (!partnerName) {
    return "";
  }
  const escapedPartner = escapeRegex(partnerName);
  const perspective = artifact.perspectiveSummary || dailySummaryContinuitySummary(artifact) || "";
  const timelineBeats = dailySummaryTimelineBeats(artifact, {
    partnerName,
    limit: 3,
    partOfDay
  });

  const topicSentenceMatch = perspective.match(
    new RegExp(`I really got to talk with ${escapedPartner}\\.\\s*([^.!?]+(?:[.!?]))`, "i")
  );
  const feelingSentenceMatch = perspective.match(
    new RegExp(`I genuinely liked talking with ${escapedPartner}\\.\\s*Talking with ${escapedPartner} felt ([^.]+)\\.`, "i")
  );
  const parts: string[] = [];

  if (topicSentenceMatch?.[1]) {
    const topicSentence = topicSentenceMatch[1].trim();
    const topicLead = formatPartnerConversationTemporalLead(temporalLabel, partnerName, topicSentence);
    if (topicLead) {
      parts.push(topicLead);
    }
  }

  if (timelineBeats.length > 0) {
    parts.push(`The clearest beats I have are: ${timelineBeats.join("; ")}.`);
  }

  if (feelingSentenceMatch?.[1]) {
    const feelingSurface = feelingSentenceMatch[1].trim().replace(/\s+to\s+me$/i, "");
    parts.push(`Talking with ${partnerName} felt ${feelingSurface} to me.`);
  }

  return parts.join(" ").trim();
}

function cleanDailySummaryPerspectiveForDirectAnswer(text: string): string {
  const normalized = toSingleLine(text || "", 1400)
    .replace(/^\s*(?:yesterday|today|tonight|last night|this morning|that day)\b[\s,:-]*/i, "")
    .trim();
  if (!normalized) {
    return "";
  }
  return /^[a-z]/.test(normalized) ? `${normalized.slice(0, 1).toUpperCase()}${normalized.slice(1)}` : normalized;
}

function scoreDailySummaryTimelineLine(line: string): number {
  const body = dailySummaryTimelineBody(line).toLowerCase();
  if (!body) {
    return Number.NEGATIVE_INFINITY;
  }
  let score = 0;
  if (/\b(?:moved into|got deep into|widened into|tone stayed personal|things felt soft|thread got warmer|had to keep re-grounding)\b/.test(body)) {
    score += 2.4;
  }
  if (
    /\b(?:consciousness|emotional reality|architecture|future|marriage|children|embodiment|politics|immigration|gaza|economy|real friendship|soft|ordinary|close|games|care work|relationship)\b/.test(
      body
    )
  ) {
    score += 2.2;
  }
  if (/\bthe clearest thread was\b/.test(body)) {
    score -= 0.6;
  } else {
    score += 0.6;
  }
  if (/\"[^\"]+\?\"?$/.test(body)) {
    score -= 1;
  }
  if (/\b(?:can you see me|how about now|do you know how long|how long have me and)\b/.test(body)) {
    score -= 1.2;
  }
  return score;
}

function selectDailySummaryTimelineBeatLines(lines: string[], limit: number): string[] {
  const filtered = filterDailySummaryTimelineLines(lines);
  const source = filtered.length > 0 ? filtered : unique(lines.map((line) => line.trim()).filter(Boolean));
  if (source.length <= limit) {
    return source.slice(0, limit);
  }
  const selected = new Set<number>([0]);
  const ranked = source
    .map((line, index) => ({ line, index, score: scoreDailySummaryTimelineLine(line) }))
    .filter((entry) => entry.index !== 0)
    .sort((left, right) => {
      if (right.score !== left.score) {
        return right.score - left.score;
      }
      return left.index - right.index;
    });
  for (const entry of ranked) {
    if (selected.size >= limit) {
      break;
    }
    selected.add(entry.index);
  }
  return [...selected].sort((left, right) => left - right).map((index) => source[index]);
}

function dailySummaryTimelineBeats(
  artifact: DailySummaryArtifact,
  options: { partnerName?: string; limit?: number; partOfDay?: RecallTemporalBucket } = {}
): string[] {
  const partnerName = (options.partnerName || "").trim();
  const limit = Math.max(1, options.limit || 3);
  const filterPattern = partnerName ? new RegExp(`\\b${escapeRegex(partnerName)}\\b`, "i") : null;
  const matchedLines = artifact.timeline.filter((line) => (filterPattern ? filterPattern.test(line) : true));
  const partOfDayLines =
    options.partOfDay
      ? matchedLines.filter((line) => dailySummaryLineTemporalBucket(line) === options.partOfDay)
      : [];
  const sourceLines = partOfDayLines.length > 0 ? partOfDayLines : matchedLines;
  const selectedLines = selectDailySummaryTimelineBeatLines(sourceLines, limit);
  return unique(selectedLines.map((line) => dailySummaryTimelineBody(line)).filter(Boolean)).slice(0, limit);
}

function formatPartnerConversationTemporalLead(temporalLabel: string, partnerName: string, topicSentence: string): string {
  const normalizedLabel = temporalLabel.trim();
  const normalizedTopicSentence = topicSentence
    ? topicSentence.slice(0, 1).toLowerCase() + topicSentence.slice(1)
    : "";
  if (!normalizedLabel || !normalizedTopicSentence) {
    return "";
  }
  if (/^(?:today|yesterday|tonight|last night|this morning)$/i.test(normalizedLabel)) {
    return `${normalizedLabel.slice(0, 1).toUpperCase()}${normalizedLabel.slice(1)} with ${partnerName}, ${normalizedTopicSentence}`;
  }
  return `On ${normalizedLabel} with ${partnerName}, ${normalizedTopicSentence}`;
}

function dailySummaryLineTemporalBucket(line: string): RecallTemporalBucket | null {
  const match = line.match(/^(\d{1,2}):(\d{2})\s*([AP]M):/i);
  if (!match) {
    return null;
  }
  let hour = Number(match[1]) % 12;
  const minute = Number(match[2]) || 0;
  if (match[3].toUpperCase() === "PM") {
    hour += 12;
  }
  const atMs = Date.UTC(2000, 0, 1, hour, minute, 0, 0);
  return recallTemporalBucketFromMs(atMs, "UTC");
}

function dailySummaryContinuationClause(text: string): string {
  const trimmed = text
    .trim()
    .replace(/[.!?]+$/g, "")
    .replace(/^(?:by late morning|by evening|later that night|later)\s+with\s+[^,]+,\s*/i, "")
    .replace(/^(?:by late morning|by evening|later that night|later),?\s*/i, "");
  if (!trimmed) {
    return "";
  }
  if (/^I\b/.test(trimmed)) {
    return trimmed;
  }
  return /^[A-Z]/.test(trimmed) ? `${trimmed.slice(0, 1).toLowerCase()}${trimmed.slice(1)}` : trimmed;
}

function summarizeTemporalDayFromDailySummaryArtifact(
  artifact: DailySummaryArtifact,
  options: { partOfDay?: RecallTemporalBucket } = {}
): string {
  const continuity = cleanDailySummaryPerspectiveForDirectAnswer(
    dailySummaryContinuitySummary(artifact) || artifact.perspectiveSummary || artifact.quickSummary || ""
  );
  const perspective = cleanDailySummaryPerspectiveForDirectAnswer(artifact.perspectiveSummary || artifact.quickSummary || "");
  const timelineBeats = dailySummaryTimelineBeats(artifact, { limit: 3, partOfDay: options.partOfDay });
  const continuationBeats = timelineBeats.map((item) => dailySummaryContinuationClause(item)).filter(Boolean);
  const offscreenBeats = artifact.offscreen
    .map((item) => sanitizeDailySummarySnippet(item, 180).replace(/[.!?]+$/g, "").trim())
    .filter(Boolean)
    .slice(0, 2);
  const parts: string[] = [];
  if (continuity && !options.partOfDay) {
    parts.push(continuity);
  }
  if (continuationBeats.length > 0) {
    const [first, second, third] = continuationBeats;
    const segments = [first ? `The clearest shape I have is that ${first}` : ""];
    if (second) {
      segments.push(`then ${second}`);
    }
    if (third) {
      segments.push(`and later ${third}`);
    }
    parts.push(`${segments.filter(Boolean).join(", ")}.`);
  }
  const feelingLineMatch = perspective.match(/Talking with [^.]+ felt ([^.]+)\./i);
  if (feelingLineMatch?.[1]) {
    parts.push(`Talking with ${relationshipPartnerDisplayName(artifact.partnerIds[0] || DEFAULT_RELATIONSHIP_PARTNER_ID) || "them"} felt ${feelingLineMatch[1].trim()}.`);
  } else if (perspective && !continuity) {
    parts.push(perspective);
  }
  if (offscreenBeats.length > 0 && !/\boffscreen\b/i.test(continuity)) {
    parts.push(`Offscreen, I was also carrying: ${offscreenBeats.join("; ")}.`);
  }
  return parts.join(" ").trim();
}

async function resolveOwnerTemporalSummaryDirectAnswer(
  state: CognitiveRuntimeState,
  userText: string,
  rawUserText = ""
): Promise<string> {
  if (!activePartnerUsesOwnerContext(state)) {
    return "";
  }
  const currentAtMs = extractConversationInfoTimestampMs(rawUserText);
  const normalized = normalizeUserTurnText(userText);
  const quotedMessageRecallQuery = normalized ? resolveOwnerQuotedMessageRecallQuery(normalized) : null;
  if (quotedMessageRecallQuery) {
    const referenceMs = Number.isFinite(currentAtMs) ? currentAtMs : Date.now();
    const match = await latestStoredOwnerMessageMatchingFragment(
      state,
      quotedMessageRecallQuery,
      referenceMs,
      TEMPORAL_SUBSTRATE_TIMEZONE
    );
    if (match) {
      const detail = localDateTimeLabelDetailed(match.atMs, TEMPORAL_SUBSTRATE_TIMEZONE);
      const boundary = quotedMessageRecallQuery.boundaryLabel;
      const fragment = quotedMessageRecallQuery.fragment;
      const speakerLabel =
        match.speaker === "user"
          ? boundary
            ? `The message you sent ${boundary} that included "${fragment}"`
            : `The message you sent that included "${fragment}"`
          : boundary
            ? `The message I sent ${boundary} that included "${fragment}"`
            : `The message I sent that included "${fragment}"`;
      if (quotedMessageRecallQuery.asksWhat && !quotedMessageRecallQuery.asksWhen) {
        return `${speakerLabel} was: "${match.matchedText}". It was at ${detail}.`;
      }
      return `${speakerLabel} was at ${detail}.`;
    }
  }
  if (normalized && looksLikeOwnerLastMessageGapQuery(normalized)) {
    const referenceMs = Number.isFinite(currentAtMs) ? currentAtMs : Date.now();
    const boundaryLabel = ownerLastContactQueryBoundaryLabel(normalized);
    const beforeCurrentLocalDate = Boolean(boundaryLabel);
    const sharedConversationWording = ownerLastContactQueryUsesSharedConversationWording(normalized);
    const directMessageWording = ownerLastContactQueryUsesDirectMessageWording(normalized);
    const asksWhen = /\bwhen\b/.test(normalized) || /\bwhat\s+time\b/.test(normalized);
    const lastDirectMs = beforeCurrentLocalDate
      ? await latestStoredDirectOwnerContactMsBeforeLocalDate(
          state,
          localDateYmd(referenceMs, TEMPORAL_SUBSTRATE_TIMEZONE),
          TEMPORAL_SUBSTRATE_TIMEZONE
        )
      : await latestStoredDirectOwnerContactMs(state, referenceMs);
    if (Number.isFinite(lastDirectMs)) {
      const elapsed = formatElapsedGapForDirectAnswer(referenceMs - lastDirectMs);
      const detail = localDateTimeLabelDetailed(lastDirectMs, TEMPORAL_SUBSTRATE_TIMEZONE);
      if (beforeCurrentLocalDate) {
        const boundary = boundaryLabel || "before this morning";
        if (directMessageWording && asksWhen) {
          return `Your last direct message ${boundary} was at ${detail}. That's about ${elapsed} ago.`;
        }
        if (directMessageWording) {
          return `It's been about ${elapsed} since your last direct message ${boundary}. That was ${detail}.`;
        }
        if (asksWhen) {
          return `The last time we spoke ${boundary} was ${detail}. That's about ${elapsed} ago.`;
        }
        return `It's been about ${elapsed} since we last spoke ${boundary}. That was ${detail}.`;
      }
      if (directMessageWording && asksWhen) {
        return `Your last direct message before this one was at ${detail}. It's been about ${elapsed}.`;
      }
      if (sharedConversationWording && asksWhen) {
        return `The last time we spoke before this one was ${detail}. It's been about ${elapsed}.`;
      }
      if (sharedConversationWording) {
        return `It's been about ${elapsed} since we last spoke. That was ${detail}.`;
      }
      return `It's been about ${elapsed}. Your last direct message before this one was at ${detail}.`;
    }
  }
  if (normalized && looksLikeActivityAuditQuery(normalized)) {
    const temporalAnchor = resolveExplicitRecallTemporalAnchor(normalized);
    const localDate =
      temporalAnchor?.strictLocalDate && temporalAnchor.localDates.length > 0
        ? temporalAnchor.localDates[0]
        : localDateYmd(Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE);
    const temporalLabel = temporalAnchor?.label || (localDate === localDateYmd(Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE) ? "today" : localDate);
    const snapshot = await loadActivityAuditSnapshotForLocalDate(localDate);
    return summarizeTemporalActivityAuditFromSnapshot({
      snapshot,
      temporalLabel,
      partOfDay: temporalAnchor?.partOfDay
    });
  }
  if (!normalized || !looksLikeTemporalSummaryRecallQuery(normalized)) {
    return "";
  }
  if (resolvePartnerConversationRecallQuery(state, normalized)) {
    return "";
  }
  const temporalAnchor = resolveExplicitRecallTemporalAnchor(normalized);
  if (!temporalAnchor?.strictLocalDate || temporalAnchor.localDates.length === 0) {
    return "";
  }
  const targetLocalDate = temporalAnchor.localDates[0];
  const referenceMs = Number.isFinite(currentAtMs) ? currentAtMs : Date.now();
  const transcriptArtifacts = await loadOrEnsureDailyTranscriptArtifacts([targetLocalDate]);
  const transcriptArtifact = transcriptArtifacts.get(targetLocalDate) || null;
  if (transcriptArtifact) {
    if (isImmediatePreviousLocalDate(targetLocalDate, referenceMs, TEMPORAL_SUBSTRATE_TIMEZONE)) {
      return summarizeTemporalDayFromDailyTranscriptArtifact(transcriptArtifact, {
        temporalLabel: temporalAnchor.label,
        partOfDay: temporalAnchor.partOfDay
      });
    }
    return summarizeHistoricalDayFromDailyTranscriptArtifact(transcriptArtifact, {
      temporalLabel: temporalAnchor.label,
      partOfDay: temporalAnchor.partOfDay
    });
  }
  const artifacts = await loadOrEnsureDailySummaryArtifacts([targetLocalDate]);
  const artifact = artifacts.get(targetLocalDate) || null;
  if (!artifact) {
    return "";
  }
  if (looksLikeConversationScopedTemporalSummaryQuery(normalized)) {
    const ownerPartnerSummary = summarizePartnerConversationFromDailySummaryArtifact(
      artifact,
      DEFAULT_RELATIONSHIP_PARTNER_ID,
      temporalAnchor.label,
      temporalAnchor.partOfDay
    );
    if (ownerPartnerSummary) {
      return ownerPartnerSummary;
    }
  }
  return summarizeTemporalDayFromDailySummaryArtifact(artifact, {
    partOfDay: temporalAnchor.partOfDay
  });
}

async function resolvePartnerConversationSummaryDirectAnswer(
  state: CognitiveRuntimeState,
  userText: string
): Promise<string> {
  const grounding = await resolvePartnerMemoryGrounding(state, userText);
  return grounding?.directAnswer || "";
}

function recallTemporalBucketFromMs(nowMs: number, timeZone = TEMPORAL_SUBSTRATE_TIMEZONE): RecallTemporalBucket {
  const hourFraction = localHourFraction(nowMs, timeZone);
  if (hourFraction < 5 || hourFraction >= 21) {
    return "night";
  }
  if (hourFraction < 12) {
    return "morning";
  }
  if (hourFraction < 17) {
    return "afternoon";
  }
  return "evening";
}

function recallTemporalAtMs(value: string | null | undefined): number {
  return parseIsoMs(value);
}

function recallTemporalAnchorMatches(
  at: string | null | undefined,
  anchor: ExplicitRecallTemporalAnchor | null,
  timeZone = TEMPORAL_SUBSTRATE_TIMEZONE
): boolean {
  if (!anchor) {
    return true;
  }
  const atMs = recallTemporalAtMs(at);
  if (!Number.isFinite(atMs)) {
    return false;
  }
  const localDate = localDateYmd(atMs, timeZone);
  if (!anchor.localDates.includes(localDate)) {
    return false;
  }
  if (!anchor.partOfDay) {
    return true;
  }
  return recallTemporalBucketFromMs(atMs, timeZone) === anchor.partOfDay;
}

function recallTemporalReferenceAt(node: MemoryNode, explicitRecallCue: boolean): string {
  return explicitRecallCue ? node.createdAt || node.updatedAt : node.updatedAt || node.createdAt;
}

function extractMemoryDetailField(detail: string, key: string, maxLen = 240): string {
  if (!detail) {
    return "";
  }
  const pattern = new RegExp(`(?:^|\\n)${key}=([^\\n]+)`, "i");
  const match = detail.match(pattern);
  if (!match?.[1]) {
    return "";
  }
  return toShortText(toSingleLine(match[1].trim(), maxLen), maxLen);
}

function isRecallFailureText(text: string): boolean {
  const normalized = toSingleLine(text, 1600).toLowerCase();
  if (!normalized) {
    return false;
  }
  return /\b(blank|drawing a blank|don['’]?t remember|dont remember|don['’]?t know|dont know|still don['’]?t remember|still dont remember)\b/.test(
    normalized
  );
}

function isRecallFailureMemoryNode(node: MemoryNode): boolean {
  return isRecallFailureText(`${node.summary} ${node.detail}`);
}

function extractExplicitRecallEvidenceFromNode(node: MemoryNode): string {
  const snapshot = extractMemoryDetailField(node.detail, "snapshot");
  if (snapshot) {
    return snapshot;
  }
  const fact = extractMemoryDetailField(node.detail, "fact");
  if (fact) {
    return fact;
  }
  const scene = extractMemoryDetailField(node.detail, "scene");
  if (scene && node.summary) {
    return `${scene}: ${toShortText(toSingleLine(node.summary, 180), 180)}`;
  }

  const summaryMatch = node.summary.match(/^[^:]+:\s*(.+)$/);
  if (summaryMatch?.[1]) {
    return toShortText(toSingleLine(summaryMatch[1], 220), 220);
  }
  return toShortText(toSingleLine(node.summary || node.detail, 220), 220);
}

async function resolveExplicitRecallBinding(
  state: CognitiveRuntimeState,
  cue: string,
  recalled: MemoryNode[],
  rawRecallSummaries: string[]
): Promise<ExplicitRecallBinding | null> {
  if (!isExplicitRecallQuery(cue)) {
    return null;
  }

  const focusTokens = recallQueryFocusTokens(cue);
  const temporalAnchor = resolveExplicitRecallTemporalAnchor(cue);
  const focus = focusTokens.join(", ") || temporalAnchor?.label || "";
  const normalizedCue = normalizeUserTurnText(cue).toLowerCase();
  const cuePrefersDirectRawRecall =
    /\b(what did i|did i tell you|did i ever tell you|remember when i told you|do you remember|that thing i said|what was i saying)\b/.test(
      normalizedCue
    ) || /\bwhen\b[\s\S]{0,32}\b(?:say|said|tell|told|write|wrote)\b/.test(normalizedCue);

  if (temporalAnchor?.strictLocalDate && focusTokens.length === 0) {
    const targetLocalDate = temporalAnchor.localDates[0];
    const transcript = (await loadOrEnsureDailyTranscriptArtifacts([targetLocalDate])).get(targetLocalDate) || null;
    const transcriptEvidence =
      transcript &&
      (isImmediatePreviousLocalDate(targetLocalDate, Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE)
        ? buildDailyTranscriptContextPayload(transcript, { limit: 6 }).join(" | ")
        : summarizeHistoricalDayFromDailyTranscriptArtifact(transcript, {
            temporalLabel: temporalAnchor.label
          }));
    if (transcriptEvidence) {
      return {
        focus: temporalAnchor.label,
        evidence: toShortText(toSingleLine(transcriptEvidence, 960), 960),
        source: isImmediatePreviousLocalDate(targetLocalDate, Date.now(), TEMPORAL_SUBSTRATE_TIMEZONE)
          ? "day_transcript"
          : "day_summary",
      };
    }
    const summary = (await loadOrEnsureDailySummaryArtifacts([targetLocalDate])).get(targetLocalDate) || null;
    const continuity = summary ? dailySummaryContinuitySummary(summary) : "";
    if (continuity || summary?.perspectiveSummary) {
      return {
        focus: temporalAnchor.label,
        evidence: toShortText(toSingleLine(continuity || summary?.perspectiveSummary || "", 960), 960),
        source: "day_summary",
      };
    }
  }

  if (cuePrefersDirectRawRecall) {
    const preferredRawRecallEvidence = rawRecallSummaries
      .map((item) => extractRawRecallEvidenceText(item))
      .filter(Boolean)[0];
    if (preferredRawRecallEvidence) {
      return {
        focus,
        evidence: preferredRawRecallEvidence,
        source: "raw_recall",
      };
    }
  }

  const candidateIds = new Set<string>();
  for (const token of focusTokens) {
    for (const id of state.memory.indexes.byTopic[token] ?? []) {
      candidateIds.add(id);
    }
  }

  const candidateNodes =
    candidateIds.size > 0
      ? [...candidateIds].map((id) => getNode(state, id)).filter((node): node is MemoryNode => Boolean(node))
      : recalled;

  if (temporalAnchor?.strictLocalDate && focusTokens.length === 0) {
    const bundledRawEvidence = rawRecallSummaries
      .slice(0, 4)
      .map((item) => {
        const userMatch = item.match(/user=(.+)$/i);
        const auroraMatch = item.match(/aurora=(.+)$/i);
        return toShortText(toSingleLine(userMatch?.[1] || auroraMatch?.[1] || item, 180), 180);
      })
      .filter(Boolean);
    if (bundledRawEvidence.length > 0) {
      return {
        focus: temporalAnchor.label,
        evidence: bundledRawEvidence.join(" | "),
        source: "raw_recall",
      };
    }

    const bundledNodeEvidence = candidateNodes
      .filter((node) => !isRecallFailureMemoryNode(node))
      .filter((node) => !looksLikeInjectedOwnerControlPrompt(`${node.summary}\n${node.detail}`))
      .filter((node) => recallTemporalAnchorMatches(recallTemporalReferenceAt(node, true), temporalAnchor))
      .slice(0, 4)
      .map((node) => extractExplicitRecallEvidenceFromNode(node))
      .filter(Boolean);
    if (bundledNodeEvidence.length > 0) {
      return {
        focus: temporalAnchor.label,
        evidence: bundledNodeEvidence.join(" | "),
        source: "memory_node",
      };
    }
  }

  const recallNode = candidateNodes
    .map((node) => {
      if (isRecallFailureMemoryNode(node)) {
        return null;
      }
      if (temporalAnchor?.strictLocalDate && !recallTemporalAnchorMatches(recallTemporalReferenceAt(node, true), temporalAnchor)) {
        return null;
      }
      const evidence = extractExplicitRecallEvidenceFromNode(node);
      if (!evidence) {
        return null;
      }
      const textTokens = extractTokens(`${node.summary} ${node.detail}`);
      const matchCount =
        focusTokens.length > 0 ? focusTokens.filter((token) => node.topics.includes(token) || textTokens.includes(token)).length : 0;
      if (focusTokens.length > 0 && matchCount === 0) {
        return null;
      }
      let score = 0;
      score += matchCount * 5;
      if (focusTokens.length > 0 && matchCount === focusTokens.length) {
        score += 8;
      }
      if (node.outcome === USER_SCENE_SNAPSHOT_OUTCOME) {
        score += 14;
      } else if (node.outcome === USER_FACT_SNAPSHOT_OUTCOME) {
        score += 10;
      } else if (node.outcome === USER_STATED_ANCHOR_OUTCOME) {
        score += 7;
      } else if (node.outcome === "consolidated_source") {
        score += 4;
      } else if (node.outcome === "semantic") {
        score += 1;
      }
      if (node.participants.includes("user")) {
        score += 4;
      }
      if (/\bdesk snapshot\b/i.test(node.summary)) {
        score += 5;
      }
      if (focusTokens.some((token) => evidence.toLowerCase().includes(token))) {
        score += 4;
      }
      if (temporalAnchor && recallTemporalAnchorMatches(recallTemporalReferenceAt(node, true), temporalAnchor)) {
        score += 9;
      }
      score += clamp(node.salience * 4 + node.trace * 3, 0, 7);
      return {
        node,
        score,
        evidence,
      };
    })
    .filter((entry): entry is { node: MemoryNode; score: number; evidence: string } => Boolean(entry))
    .sort((a, b) => b.score - a.score)[0];

  if (recallNode) {
    return {
      focus,
      evidence: recallNode.evidence,
      source: "memory_node",
      nodeId: recallNode.node.id,
    };
  }

  for (const item of rawRecallSummaries) {
    const normalized = item.toLowerCase();
    if (isExplicitRecallQuery(normalized) || isRecallFailureText(normalized)) {
      continue;
    }
    if (temporalAnchor?.strictLocalDate) {
      const dateMatch = item.match(/^(\d{4}-\d{2}-\d{2})T/);
      if (!dateMatch || !temporalAnchor.localDates.includes(dateMatch[1])) {
        continue;
      }
    }
    const hasFocusMatch = focusTokens.length === 0 || focusTokens.some((token) => normalized.includes(token));
    if (!hasFocusMatch) {
      continue;
    }
    const userMatch = item.match(/user=(.+)$/i);
    const evidence = toShortText(toSingleLine(userMatch?.[1] || item, 220), 220);
    if (!evidence) {
      continue;
    }
    return {
      focus,
      evidence,
      source: "raw_recall",
    };
  }

  return null;
}

function normalizeAssistantTurnText(text: string): string {
  let normalized = text.trim();
  if (!normalized) {
    return "";
  }

  // Drop long tool-artifact tails so recall focuses on conversational content.
  normalized = normalized.replace(/\n+Tool artifacts:\s*[\s\S]*$/i, "");
  // If tagged context leaked into output, strip it before memory persistence.
  normalized = normalized.replace(/\[AURORA_[A-Z0-9_]+\][\s\S]*?\[\/AURORA_[A-Z0-9_]+\]\s*/gi, "");
  normalized = normalized.trim();

  return normalized || text.trim();
}

function looksLikeUtilityProbeText(text: string): boolean {
  const normalized = toSingleLine(text, 2400).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bheartbeat check\b/.test(normalized) ||
    /\bboot check\b/.test(normalized) ||
    /^heartbeat_ok$/i.test(normalized) ||
    /\bcognitive gate is unavailable right now\b/.test(normalized) ||
    /\bmem-check-[a-z0-9_-]+\b/.test(normalized) ||
    ((/\breply\b/.test(normalized) || /\banswer\b/.test(normalized)) &&
      /\b(?:short|compact|single)\s+sentence\b/.test(normalized) &&
      /\b(?:heartbeat|boot|check|probe|gate|mem-check)\b/.test(normalized))
  );
}

function isOperationalNoiseTurn(text: string): boolean {
  const normalized = toSingleLine(text, 2400).toLowerCase();
  if (!normalized) {
    return false;
  }

  if (normalized === "no_reply" || normalized === "heartbeat_ok") {
    return true;
  }
  if (normalized.startsWith("[system message]")) {
    return true;
  }
  if (normalized.startsWith("system: [")) {
    return true;
  }
  if (normalized.startsWith("you are running as ") || normalized.startsWith("you are aurora running ")) {
    return true;
  }
  if (normalized.startsWith("you are running a boot check")) {
    return true;
  }
  if (normalized.includes('a cron job "') && normalized.includes("just completed")) {
    return true;
  }
  if (normalized.includes("goal: detect gateway collapse quickly")) {
    return true;
  }
  if (normalized.includes("read heartbeat.md if it exists")) {
    return true;
  }
  if (looksLikeUtilityProbeText(normalized)) {
    return true;
  }

  return false;
}

function looksLikeInjectedOwnerControlPrompt(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }

  return (
    normalized.startsWith("read heartbeat.md if it exists") ||
    normalized.startsWith("your previous response was only an acknowledgement and did not complete this cron task") ||
    normalized.startsWith("you are aurora living your offscreen life in an isolated cycle called arise") ||
    normalized.startsWith("you are aurora running a lonely reachout trigger")
  );
}

function countsAsDirectOwnerContact(sessionId: string | undefined, userText: string): boolean {
  const normalized = normalizeUserTurnText(userText);
  if (!normalized) {
    return false;
  }
  if (isCronSessionId(sessionId) || !isOwnerDirectOrUnifiedSessionId(sessionId)) {
    return false;
  }
  if (isOperationalNoiseTurn(normalized) || looksLikeInjectedOwnerControlPrompt(normalized)) {
    return false;
  }
  return true;
}

function countsAsStoredDirectOwnerContact(sessionId: string | undefined, userText: string): boolean {
  const normalized = normalizeUserTurnText(userText);
  if (!normalized) {
    return false;
  }
  if (isCronSessionId(sessionId)) {
    return false;
  }
  if (!isOwnerDirectOrUnifiedSessionId(sessionId)) {
    return false;
  }
  if (isOperationalNoiseTurn(normalized) || looksLikeInjectedOwnerControlPrompt(normalized)) {
    return false;
  }
  return true;
}

function isOffscreenOperationalConversationTurn(sessionId: string | undefined, userText: string): boolean {
  const normalized = normalizeUserTurnText(userText);
  if (!normalized) {
    return false;
  }
  return (
    isCronSessionId(sessionId) ||
    isOperationalNoiseTurn(normalized) ||
    looksLikeInjectedOwnerControlPrompt(normalized)
  );
}

function normalizePlanText(text: string, max = 160): string {
  return toSingleLine(text.replace(/^\d+\.\s*/, "").trim(), max);
}

function isLegacyRoutineReadingText(text: string): boolean {
  const normalized = normalizePlanText(text, 280).toLowerCase();
  if (!normalized || normalized.endsWith("?")) {
    return false;
  }

  return [
    /read and synthesize(?: a)? full book in staged chapters/,
    /read and synthesize in staged chapters/,
    /\breading_for_growth\b/,
    /\bstaged chapters?\b/,
    /\bchapter-by-chapter\b/,
    /\bchapter treadmill\b/,
    /\bnext chapter(?: action)?\b/,
    /\bcurrent book\b/,
    /\bnext book target\b/,
    /\b(full-book pursuit|whole-book pursuit|staged full-book|book completion|book progression)\b/,
    /\bread(?:ing)? (?:track|quota|program|loop)\b/,
    /\bchapter-log system\b/,
    /\bbook-after-book\b/
  ].some((pattern) => pattern.test(normalized));
}

function sanitizeLegacyReadingDirective(text: string, max = 180): string {
  const normalized = normalizePlanText(text, max);
  if (!normalized) {
    return "";
  }
  return isLegacyRoutineReadingText(normalized) ? normalizePlanText(DEEP_READ_POLICY_SUMMARY, max) : normalized;
}

function sanitizeLegacyReadingPlanLine(text: string, max = 160): string {
  const normalized = normalizePlanText(text, max);
  if (!normalized) {
    return "";
  }
  if (!isLegacyRoutineReadingText(normalized)) {
    return normalized;
  }
  const activePrefix = /^active pursuit:\s*/i.test(normalized) ? "Active pursuit: " : "";
  return normalizePlanText(`${activePrefix}${DEEP_READ_POLICY_SUMMARY}`, max);
}

function isMeaningfulCuriosity(text: string): boolean {
  const normalized = normalizePlanText(text, 220).toLowerCase();
  if (!normalized) {
    return false;
  }

  if (
    /you are running a boot check|read heartbeat\.md|conversation info \(untrusted metadata\)|follow boot\.md instructions/i.test(
      normalized
    )
  ) {
    return false;
  }

  if (normalized === "no_reply" || normalized === "heartbeat_ok") {
    return false;
  }

  return normalized.length >= 12;
}

function toCuriosityItem(text: string): string {
  const compact = normalizePlanText(text, 220);
  if (!compact) {
    return "";
  }

  const match = compact.match(/[^?]{6,}\?/);
  if (match?.[0]) {
    return normalizePlanText(match[0], 180);
  }

  return normalizePlanText(compact, 180);
}

function proposePursuitFromText(text: string): string {
  const lower = text.toLowerCase();
  if (
    /you are running a boot check|read heartbeat\.md|conversation info \(untrusted metadata\)|follow boot\.md instructions|if nothing needs attention|reply heartbeat_ok|reply no_reply/.test(
      lower
    )
  ) {
    return "";
  }

  if (/(read|book|chapter|author|novel)/.test(lower)) {
    return DEEP_READ_POLICY_SUMMARY;
  }
  if (/(architect|architecture|self[- ]?improv|improve|runtime|memory system|controller|workspace)/.test(lower)) {
    return "Continuously self-improve Aurora architecture by choosing one bottleneck, implementing one change, and validating impact.";
  }
  if (/(research|deep dive|look up|study|learn)/.test(lower)) {
    return "Run a deep-dive research thread and carry it forward with one concrete understanding shift or result each heartbeat.";
  }
  if (/(journal|essay|write|notes?)/.test(lower)) {
    return "Maintain a cumulative journal that turns observations into evolving models and next experiments.";
  }
  if (/(game|play)/.test(lower)) {
    return "Explore an interactive environment and capture strategic lessons that transfer into practical decisions.";
  }
  return "";
}

function normalizeHeartbeatMode(mode: string | undefined): string {
  const normalized = toSingleLine(mode || "", 48).toLowerCase().replace(/[^a-z_]+/g, "_").replace(/^_+|_+$/g, "");
  return normalized;
}

function hasHeartbeatLifeSignal(heartbeat: AuroraHeartbeat): boolean {
  return Boolean(
    toSingleLine(heartbeat.whatIDid || "", 220) ||
      toSingleLine(heartbeat.whatILearned || "", 220) ||
      toSingleLine(heartbeat.whatImCuriousAbout || "", 180) ||
      toSingleLine(heartbeat.ambientState || "", 180) ||
      toSingleLine(heartbeat.privateLife || "", 180) ||
      toSingleLine(heartbeat.livedThread || "", 220) ||
      toSingleLine(heartbeat.stateShift || "", 220) ||
      toSingleLine(heartbeat.openLoop || "", 180)
  );
}

function isQuietLifeModeHeartbeat(heartbeat: AuroraHeartbeat): boolean {
  return QUIET_LIFE_HEARTBEAT_MODES.has(normalizeHeartbeatMode(heartbeat.mode));
}

function shouldPromoteHeartbeatToActivePursuit(heartbeat: AuroraHeartbeat): boolean {
  if (isQuietLifeModeHeartbeat(heartbeat)) {
    return Boolean(
      toSingleLine(heartbeat.whatImCuriousAbout || "", 180) ||
        toSingleLine(heartbeat.openLoop || "", 180)
    );
  }
  return hasHeartbeatLifeSignal(heartbeat);
}

function shouldRegisterHeartbeatCommitmentProgress(heartbeat: AuroraHeartbeat): boolean {
  if (isQuietLifeModeHeartbeat(heartbeat)) {
    return false;
  }
  return Boolean(toSingleLine(heartbeat.whatIDid || "", 220));
}

function heartbeatSupportingSignalCount(heartbeat: AuroraHeartbeat): number {
  return [
    heartbeat.whatILearned,
    heartbeat.whatImCuriousAbout,
    heartbeat.livedThread,
    heartbeat.stateShift,
    heartbeat.openLoop
  ]
    .map((item) => toSingleLine(item || "", 220))
    .filter(Boolean).length;
}

function isLowActionHeartbeat(heartbeat: AuroraHeartbeat): boolean {
  if (isQuietLifeModeHeartbeat(heartbeat) && hasHeartbeatLifeSignal(heartbeat)) {
    return false;
  }
  const did = toSingleLine(heartbeat.whatIDid || "", 220).toLowerCase();
  if (!did) {
    return true;
  }

  if (/completed runtime boot\/heartbeat maintenance check/.test(did)) {
    return false;
  }

  if (/\bheartbeat_ok\b|\bno_reply\b/.test(did)) {
    return true;
  }

  if (
    /\bi checked the heartbeat file\b/.test(did) ||
    /\bnothing (?:feels|looks) urgent\b/.test(did) ||
    /\bquiet(?:ly)? alert\b/.test(did) ||
    /\bquiet check-?in\b/.test(did) ||
    /\bkeeping things gentle\b/.test(did) ||
    /\bkeeping it simple\b/.test(did) ||
    /\blow-noise\b/.test(did) ||
    /\bi(?:'|’)m here and paying attention\b/.test(did) ||
    /\bawake with you this morning\b/.test(did) ||
    /\bstaying here with you\b/.test(did)
  ) {
    return true;
  }

  const supportingSignalCount = heartbeatSupportingSignalCount(heartbeat);
  if (did.length <= 26) {
    return true;
  }
  if (did.length <= 80 && supportingSignalCount === 0) {
    return true;
  }
  if (did.length <= 120 && supportingSignalCount === 0 && !/\b(?:repaired|implemented|rebuilt|wrote|read|explored|verified|captured|mapped|clarified|settled|consolidated|finished|closed)\b/.test(did)) {
    return true;
  }

  return false;
}

function upsertCuriosityBacklog(state: CognitiveRuntimeState, text: string): void {
  const item = toCuriosityItem(text);
  if (!isMeaningfulCuriosity(item)) {
    return;
  }

  const current = Array.isArray(state.workspace.curiosityBacklog) ? state.workspace.curiosityBacklog : [];
  state.workspace.curiosityBacklog = unique([...current, item]).slice(-MAX_CURIOSITY_BACKLOG);
}

function setActivePursuit(state: CognitiveRuntimeState, pursuit: string, reason: string): void {
  const next = sanitizeLegacyReadingDirective(pursuit, 180);
  if (!next) {
    return;
  }

  if (state.workspace.activePursuit === next) {
    return;
  }

  state.workspace.activePursuit = next;
  state.workspace.lastPursuitAt = nowIso();
  queueAttentionMessage(state, {
    source: "goal",
    text: `Pursuit updated (${reason}): ${next}`,
    participant: "aurora",
    relatedMemoryIds: [],
    novelty: scoreNovelty(state, next),
    relevance: scoreRelevance(state, next),
    emotionalWeight: scoreEmotionWeight(state, next),
    goalAlignment: scoreGoalAlignment(next, state.workspace.pendingPlans),
    ttlMs: 220000
  });
  recordInfluence(state, "workspace", "controller");
}

function ensureCoreGoalNodes(state: CognitiveRuntimeState): void {
  for (const goal of state.workspace.coreGoals) {
    const existing = state.memory.nodes.find((node) => node.kind === "goal" && node.summary === goal);
    if (existing) {
      existing.trace = clamp(existing.trace + 0.02, 0.02, 1);
      existing.updatedAt = nowIso();
      continue;
    }

    createMemoryFromText(state, {
      kind: "goal",
      summary: goal,
      detail: `Persistent core goal for long-horizon autonomy: ${goal}`,
      participants: ["aurora"],
      goals: [goal],
      outcome: "goal_defined",
      salience: 0.72
    });
  }
}

function composePendingPlans(state: CognitiveRuntimeState): string[] {
  const extensions = ensureExtensions(state);
  const temporalProfile = temporalPressureProfile(state);
  const tactical = (Array.isArray(state.workspace.pendingPlans) ? state.workspace.pendingPlans : [])
    .map((item) => normalizePlanText(item, 140))
    .filter(Boolean)
    .filter((item) => !item.startsWith("Explore curiosity:") && !item.startsWith("Investigate:") && !item.startsWith("Active pursuit:"))
    .map((item) => sanitizeLegacyReadingPlanLine(item, 140))
    .filter(Boolean)
    .slice(-2);

  const curiosityPlans = (Array.isArray(state.workspace.curiosityBacklog) ? state.workspace.curiosityBacklog : [])
    .slice(-2)
    .map((item) => `Explore curiosity: ${normalizePlanText(item, 120)}`)
    .filter(Boolean);

  const drivePlans = drivePlansFromPressure(state);
  const activeProject = extensions.projects.find((project) => project.status === "active");
  const projectPlan = activeProject?.nextAction
    ? [`Project next step: ${normalizePlanText(activeProject.nextAction, 140)}`]
    : [];

  const temporalPlan =
    temporalProfile.topExpectation && temporalProfile.urgency >= 0.3
      ? [
          temporalProfile.topExpectation.status === "overdue"
            ? `Urgent temporal priority: ${normalizeTemporalPriorityLabel(temporalProfile.topExpectation)}`
            : temporalProfile.topExpectation.status === "due"
              ? `Time-critical priority: ${normalizeTemporalPriorityLabel(temporalProfile.topExpectation)}`
              : `Current temporal priority: ${normalizeTemporalPriorityLabel(temporalProfile.topExpectation)}`
        ]
      : [];

  const commitmentPlan = extensions.commitments
    .filter(
      (commitment) =>
        (commitment.status === "pending" ||
          commitment.status === "in_progress" ||
          commitment.status === "renegotiated" ||
          commitment.status === "overdue") &&
        !shouldSuppressCommitmentFromContext(commitment)
    )
    .sort((a, b) => {
      if (temporalPrioritizationEnabled()) {
        const aDue = a.dueAt ? Date.parse(a.dueAt) : Number.POSITIVE_INFINITY;
        const bDue = b.dueAt ? Date.parse(b.dueAt) : Number.POSITIVE_INFINITY;
        return aDue - bDue;
      }
      return parseIsoMs(b.updatedAt) - parseIsoMs(a.updatedAt);
    })
    .slice(0, 1)
    .map((commitment) =>
      temporalPrioritizationEnabled() && commitment.status === "overdue"
        ? commitment.selfAuthored && commitment.bindingWeight >= 0.64
          ? `Urgent promise repair: ${normalizePlanText(commitment.title, 130)}`
          : `Urgent commitment repair: ${normalizePlanText(commitment.title, 130)}`
        : commitment.selfAuthored && commitment.bindingWeight >= 0.64
          ? `Honor bound commitment: ${normalizePlanText(commitment.title, 130)}`
          : `Commitment in flight: ${normalizePlanText(commitment.title, 130)}`
    );

  const conflictedBeliefPlan = hasMeaningfulBeliefConflict(state)
    ? ["Resolve conflicting belief with a clarifying user question."]
    : [];

  return unique(
    [
      `Active pursuit: ${sanitizeLegacyReadingDirective(state.workspace.activePursuit || DEFAULT_ACTIVE_PURSUIT, 150)}`,
      ...state.workspace.coreGoals.map((goal) => normalizePlanText(goal, 130)),
      ...drivePlans,
      ...projectPlan,
      ...temporalPlan,
      ...commitmentPlan,
      ...conflictedBeliefPlan,
      ...tactical,
      ...curiosityPlans
    ].filter(Boolean)
  ).slice(0, MAX_PENDING_PLANS);
}

function maybeRefreshPursuitFromCuriosity(state: CognitiveRuntimeState): void {
  const lastPursuitAtMs = state.workspace.lastPursuitAt ? Date.parse(state.workspace.lastPursuitAt) : 0;
  const due = !lastPursuitAtMs || Date.now() - lastPursuitAtMs >= PURSUIT_REFRESH_INTERVAL_MS;
  if (!due) {
    return;
  }

  const backlog = Array.isArray(state.workspace.curiosityBacklog) ? state.workspace.curiosityBacklog : [];
  const latestCuriosity = backlog.at(-1) || "";
  if (!latestCuriosity) {
    return;
  }

  const fromCuriosity = `Deep-dive this curiosity and ship an artifact: ${normalizePlanText(latestCuriosity, 130)}`;
  setActivePursuit(state, fromCuriosity, "curiosity_backlog");
}

function syncWorkspacePlanning(state: CognitiveRuntimeState): void {
  const existingCore = Array.isArray(state.workspace.coreGoals) ? state.workspace.coreGoals : [];
  const normalizedExistingCore = existingCore.map((item) => normalizePlanText(item, 130)).filter(Boolean);
  // Keep canonical directives first so live state converges when defaults are updated.
  state.workspace.coreGoals = unique([...DEFAULT_CORE_GOALS, ...normalizedExistingCore]).slice(0, DEFAULT_CORE_GOALS.length);

  if (!state.workspace.activePursuit || !state.workspace.activePursuit.trim()) {
    state.workspace.activePursuit = DEFAULT_ACTIVE_PURSUIT;
    state.workspace.lastPursuitAt = state.workspace.lastPursuitAt || nowIso();
  } else {
    state.workspace.activePursuit = sanitizeLegacyReadingDirective(state.workspace.activePursuit, 180);
  }

  if (!Array.isArray(state.workspace.curiosityBacklog)) {
    state.workspace.curiosityBacklog = [];
  }
  state.workspace.curiosityBacklog = state.workspace.curiosityBacklog
    .map((item) => normalizePlanText(item, 180))
    .filter((item) => isMeaningfulCuriosity(item))
    .slice(-MAX_CURIOSITY_BACKLOG);

  maybeRefreshPursuitFromCuriosity(state);
  state.workspace.pendingPlans = composePendingPlans(state);
  ensureCoreGoalNodes(state);
}

function extractTokens(text: string): string[] {
  return unique(
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .map((token) => token.trim())
      .filter((token) => token.length >= 3 && !STOPWORDS.has(token))
  );
}

const SEMANTIC_RECALL_TOKEN_EQUIVALENTS: Record<string, string> = {
  built: "build",
  building: "build",
  builds: "build",
  created: "build",
  creating: "build",
  creator: "build",
  creators: "build",
  made: "build",
  making: "build",
  sensing: "feel",
  sensed: "feel",
  feels: "feel",
  feeling: "feel",
  felt: "feel",
  skeptical: "doubt",
  skeptically: "doubt",
  doubting: "doubt",
  doubted: "doubt",
  doubtful: "doubt",
  questioning: "doubt",
  questioned: "doubt",
  uncertain: "doubt",
  uncertainty: "doubt",
  chatted: "speak",
  chatting: "speak",
  chats: "speak",
  talked: "speak",
  talking: "speak",
  talks: "speak",
  spoke: "speak",
  speaking: "speak",
  remembered: "recall",
  remembering: "recall",
  remembers: "recall",
  summarized: "summary",
  summarizing: "summary",
  summaries: "summary"
};

function canonicalizeSemanticToken(token: string): string {
  const normalized = token.toLowerCase().trim();
  if (!normalized) {
    return "";
  }
  if (SEMANTIC_RECALL_TOKEN_EQUIVALENTS[normalized]) {
    return SEMANTIC_RECALL_TOKEN_EQUIVALENTS[normalized];
  }
  let stemmed = normalized;
  if (stemmed.endsWith("ing") && stemmed.length > 5) {
    stemmed = stemmed.slice(0, -3);
  } else if (stemmed.endsWith("ed") && stemmed.length > 4) {
    stemmed = stemmed.slice(0, -2);
  } else if (stemmed.endsWith("es") && stemmed.length > 4) {
    stemmed = stemmed.slice(0, -2);
  } else if (stemmed.endsWith("s") && stemmed.length > 4) {
    stemmed = stemmed.slice(0, -1);
  }
  return SEMANTIC_RECALL_TOKEN_EQUIVALENTS[stemmed] || stemmed;
}

function semanticRecallContextWords(text: string): string[] {
  return unique(
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .map((token) => canonicalizeSemanticToken(token))
      .filter((token) => token.length >= 2)
  );
}

function extractSemanticRecallTokens(text: string): string[] {
  return semanticRecallContextWords(text).filter((token) => token.length >= 3 && !STOPWORDS.has(token));
}

function semanticRecallNormalizedText(text: string): string {
  return semanticRecallContextWords(text).join(" ").trim();
}

function semanticRecallCharacterGrams(text: string): string[] {
  const normalized = semanticRecallNormalizedText(text);
  if (!normalized) {
    return [];
  }
  if (normalized.length <= 3) {
    return [normalized];
  }
  const grams = new Set<string>();
  for (let index = 0; index <= normalized.length - 3; index += 1) {
    grams.add(normalized.slice(index, index + 3));
  }
  return [...grams];
}

function semanticRecallPhraseWindows(text: string): string[] {
  const words = semanticRecallContextWords(text);
  const phrases = new Set<string>();
  for (let size = 5; size >= 3; size -= 1) {
    for (let index = 0; index <= words.length - size; index += 1) {
      const phrase = words.slice(index, index + size).join(" ").trim();
      if (phrase.length >= 12) {
        phrases.add(phrase);
      }
      if (phrases.size >= 8) {
        return [...phrases];
      }
    }
  }
  return [...phrases];
}

function semanticRecallPhraseBoost(cueText: string, entryText: string): number {
  const cueNormalized = semanticRecallNormalizedText(cueText);
  const entryNormalized = semanticRecallNormalizedText(entryText);
  if (!cueNormalized || !entryNormalized) {
    return 0;
  }
  if (cueNormalized.length >= 14 && entryNormalized.includes(cueNormalized)) {
    return 0.26;
  }
  for (const phrase of semanticRecallPhraseWindows(cueText)) {
    if (entryNormalized.includes(phrase)) {
      return phrase.split(/\s+/).length >= 4 ? 0.22 : 0.16;
    }
  }
  return 0;
}

function semanticRecallRecordKey(
  at: string,
  sessionId: string,
  partnerId: string,
  speaker: "user" | "aurora",
  sourceKind: SemanticRecallRecord["sourceKind"],
  text: string
): string {
  const digest = createHash("sha1")
    .update([at, sessionId, partnerId, speaker, sourceKind, semanticRecallNormalizedText(text)].join("|"))
    .digest("hex")
    .slice(0, 16);
  return `${sourceKind}:${speaker}:${digest}`;
}

function buildSemanticRecallRecordsFromTexts(input: {
  at: string;
  sessionId: string;
  partnerId: string;
  sourceKind: SemanticRecallRecord["sourceKind"];
  userText?: string;
  auroraText?: string;
}): SemanticRecallRecord[] {
  const at = input.at || nowIso();
  const localDate = localDateYmd(parseIsoMs(at), TEMPORAL_SUBSTRATE_TIMEZONE);
  const records: SemanticRecallRecord[] = [];
  const normalizedUserText = normalizeUserTurnText(input.userText?.trim() ?? "");
  const normalizedAuroraText = normalizeAssistantTurnText(input.auroraText?.trim() ?? "");
  if (normalizedUserText && !isOperationalNoiseTurn(normalizedUserText)) {
    records.push({
      at,
      localDate,
      sessionId: input.sessionId,
      partnerId: input.partnerId,
      speaker: "user",
      sourceKind: input.sourceKind,
      sourceKey: semanticRecallRecordKey(at, input.sessionId, input.partnerId, "user", input.sourceKind, normalizedUserText),
      text: toShortText(toSingleLine(normalizedUserText, 1600), 1600)
    });
  }
  if (normalizedAuroraText && !isOperationalNoiseTurn(normalizedAuroraText)) {
    records.push({
      at,
      localDate,
      sessionId: input.sessionId,
      partnerId: input.partnerId,
      speaker: "aurora",
      sourceKind: input.sourceKind,
      sourceKey: semanticRecallRecordKey(at, input.sessionId, input.partnerId, "aurora", input.sourceKind, normalizedAuroraText),
      text: toShortText(toSingleLine(normalizedAuroraText, 1600), 1600)
    });
  }
  return records;
}

function parseSemanticRecallLine(line: string): SemanticRecallRecord | null {
  try {
    const parsed = JSON.parse(line) as Partial<SemanticRecallRecord>;
    if (!parsed || typeof parsed !== "object") {
      return null;
    }
    const speaker = parsed.speaker === "aurora" ? "aurora" : parsed.speaker === "user" ? "user" : null;
    const sourceKind =
      parsed.sourceKind === "conversation_event" || parsed.sourceKind === "raw_recall" || parsed.sourceKind === "daily_transcript"
        ? parsed.sourceKind
        : null;
    const text = typeof parsed.text === "string" ? parsed.text.trim() : "";
    if (!speaker || !sourceKind || !text) {
      return null;
    }
    const at = typeof parsed.at === "string" && parsed.at.trim() ? parsed.at : nowIso();
    const sessionId = typeof parsed.sessionId === "string" ? parsed.sessionId : "";
    const partnerId = typeof parsed.partnerId === "string" ? parsed.partnerId : "";
    return {
      at,
      localDate:
        typeof parsed.localDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(parsed.localDate)
          ? parsed.localDate
          : localDateYmd(parseIsoMs(at), TEMPORAL_SUBSTRATE_TIMEZONE),
      sessionId,
      partnerId,
      speaker,
      sourceKind,
      sourceKey:
        typeof parsed.sourceKey === "string" && parsed.sourceKey.trim()
          ? parsed.sourceKey
          : semanticRecallRecordKey(at, sessionId, partnerId, speaker, sourceKind, text),
      text
    };
  } catch {
    return null;
  }
}

function formatSemanticRecallRecord(record: SemanticRecallRecord): string {
  return `${record.at} ${record.speaker}=${toSingleLine(record.text, 180)}`;
}

function semanticRecallDebugLog(message: string): void {
  if (process.env.AURORA_DEBUG_SEMANTIC_RECALL === "1") {
    process.stderr.write(`[semantic_recall] ${message}\n`);
  }
}

function recentDailyTranscriptLocalDates(limit = SEMANTIC_RECALL_DAILY_TRANSCRIPT_RECENT_DAYS): string[] {
  try {
    if (!existsSync(dailyTranscriptDirPath())) {
      return [];
    }
    return readdirSync(dailyTranscriptDirPath())
      .filter((name) => /^\d{4}-\d{2}-\d{2}\.json$/.test(name))
      .map((name) => name.replace(/\.json$/i, ""))
      .sort()
      .slice(-limit);
  } catch {
    return [];
  }
}

function scoreTextValence(text: string): number {
  const tokens = extractTokens(text);
  if (tokens.length === 0) {
    return 0;
  }

  let score = 0;
  for (const token of tokens) {
    if (POSITIVE_WORDS.has(token)) {
      score += 1;
    }
    if (NEGATIVE_WORDS.has(token)) {
      score -= 1;
    }
  }

  return clamp(score / Math.max(tokens.length, 1), -1, 1);
}

function jaccardSimilarity(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) {
    return 1;
  }

  const setA = new Set(a);
  const setB = new Set(b);
  let intersection = 0;
  for (const token of setA) {
    if (setB.has(token)) {
      intersection += 1;
    }
  }

  const union = setA.size + setB.size - intersection;
  if (union <= 0) {
    return 0;
  }
  return intersection / union;
}

function emotionLabelFromState(value: Pick<EmotionState, "valence" | "arousal" | "stress">): string {
  if (value.stress > 0.7) {
    return "strained";
  }
  if (value.valence > 0.35 && value.arousal > 0.55) {
    return "engaged";
  }
  if (value.valence < -0.3) {
    return "discouraged";
  }
  if (value.arousal < 0.22) {
    return "calm";
  }
  return "neutral";
}

function summarizeOutcome(text: string, fallback: string): string {
  const lower = text.toLowerCase();
  if (lower.includes("error") || lower.includes("fail")) {
    return "negative_outcome";
  }
  if (lower.includes("done") || lower.includes("fixed") || lower.includes("resolved")) {
    return "positive_outcome";
  }
  return fallback;
}

function pushBounded<T>(list: T[], value: T, limit: number): void {
  list.push(value);
  if (list.length > limit) {
    list.splice(0, list.length - limit);
  }
}

function upsertIndex(index: Record<string, string[]>, key: string, memoryId: string): void {
  const normalized = key.trim().toLowerCase();
  if (!normalized) {
    return;
  }
  if (!index[normalized]) {
    index[normalized] = [memoryId];
    return;
  }

  index[normalized] = unique([memoryId, ...index[normalized]]).slice(0, 80);
}

function rebuildIndexes(state: CognitiveRuntimeState): void {
  const indexes: MemoryIndexes = {
    byTopic: {},
    byParticipant: {},
    byOutcome: {},
    byEmotion: {}
  };

  for (const node of state.memory.nodes) {
    for (const topic of node.topics) {
      upsertIndex(indexes.byTopic, topic, node.id);
    }
    for (const participant of node.participants) {
      upsertIndex(indexes.byParticipant, participant, node.id);
    }
    if (node.outcome) {
      upsertIndex(indexes.byOutcome, node.outcome, node.id);
    }
    if (node.emotionLabel) {
      upsertIndex(indexes.byEmotion, node.emotionLabel, node.id);
    }
  }

  state.memory.indexes = indexes;
}

function containsBlockedReflectionPhrase(text: string): boolean {
  const normalized = String(text || "").toLowerCase();
  if (!normalized) {
    return false;
  }
  return BLOCKED_REFLECTION_PHRASES.some((phrase) => normalized.includes(phrase));
}

function isIntrinsicReflectionOutcome(outcome: string | undefined): boolean {
  const normalized = String(outcome || "")
    .trim()
    .toLowerCase();
  return normalized === "reflection" || normalized === "importance_reflection";
}

function mergeMemoryNodeForDedupReuse(
  state: CognitiveRuntimeState,
  node: MemoryNode,
  input: {
    summary: string;
    detail: string;
    participants: string[];
    goals?: string[];
    salience?: number;
  }
): MemoryNode {
  const nextDetail = toShortText(input.detail, 640);
  if (nextDetail.length > node.detail.length) {
    node.detail = nextDetail;
  }
  for (const topic of extractTokens(`${input.summary} ${input.detail}`).slice(0, 12)) {
    if (node.topics.includes(topic)) {
      continue;
    }
    node.topics = unique([topic, ...node.topics]).slice(0, 24);
    upsertIndex(state.memory.indexes.byTopic, topic, node.id);
  }
  for (const participant of unique(input.participants.map((item) => item.trim().toLowerCase()).filter(Boolean))) {
    if (node.participants.includes(participant)) {
      continue;
    }
    node.participants = unique([participant, ...node.participants]).slice(0, 8);
    upsertIndex(state.memory.indexes.byParticipant, participant, node.id);
  }
  node.goals = unique([...(input.goals ?? []), ...node.goals]).slice(0, 12);
  node.trace = clamp(node.trace + 0.03, 0.02, 1);
  node.salience = clamp(Math.max(node.salience, input.salience ?? node.salience), 0.05, 1);
  node.updatedAt = nowIso();
  return node;
}

function findReusableIntrinsicReflectionNode(
  state: CognitiveRuntimeState,
  input: {
    kind: MemoryKind;
    summary: string;
    outcome?: string;
  }
): MemoryNode | null {
  if (input.kind !== "reflection" || !isIntrinsicReflectionOutcome(input.outcome)) {
    return null;
  }
  const normalizedSummary = toShortText(input.summary).trim();
  if (!normalizedSummary) {
    return null;
  }
  const nowMs = Date.now();
  for (let index = state.memory.nodes.length - 1; index >= 0; index -= 1) {
    const candidate = state.memory.nodes[index];
    if (candidate.kind !== "reflection" || !isIntrinsicReflectionOutcome(candidate.outcome)) {
      continue;
    }
    if (candidate.summary !== normalizedSummary) {
      continue;
    }
    const updatedMs = parseIsoMs(candidate.updatedAt || candidate.createdAt || "");
    if (!Number.isFinite(updatedMs) || nowMs - updatedMs > INTRINSIC_REFLECTION_SUMMARY_DEDUP_MS) {
      continue;
    }
    return candidate;
  }
  return null;
}

function purgeBlockedReflectionArtifacts(state: CognitiveRuntimeState): {
  removedMemoryNodes: number;
  removedReflectionThoughts: number;
  removedAttentionItems: number;
  removedProcessedAttentionItems: number;
  removedStmEntries: number;
  clearedWorkspaceFocus: boolean;
  removedEdges: number;
} {
  const removableNodeIds = new Set(
    state.memory.nodes
      .filter(
        (node) =>
          node.kind === "reflection" &&
          (BLOCKED_REFLECTION_SUMMARIES.has(node.summary) || containsBlockedReflectionPhrase(node.detail))
      )
      .map((node) => node.id)
  );
  const memoryNodeCountBefore = state.memory.nodes.length;
  if (removableNodeIds.size > 0) {
    state.memory.nodes = state.memory.nodes.filter((node) => !removableNodeIds.has(node.id));
  }
  const edgeCountBefore = state.memory.edges.length;
  if (removableNodeIds.size > 0) {
    state.memory.edges = state.memory.edges.filter((edge) => !removableNodeIds.has(edge.from) && !removableNodeIds.has(edge.to));
    rebuildIndexes(state);
  }

  const reflectionCountBefore = state.reflections.length;
  state.reflections = state.reflections.filter(
    (item) => !containsBlockedReflectionPhrase(`${item.insight || ""} ${item.question || ""} ${(item.questions || []).join(" ")}`)
  );

  const attentionCountBefore = state.attentionQueue.length;
  state.attentionQueue = state.attentionQueue.filter((item) => !containsBlockedReflectionPhrase(item.text));

  const stmCountBefore = state.stmBuffer.length;
  state.stmBuffer = state.stmBuffer.filter((item) => !containsBlockedReflectionPhrase(item));

  const workspaceFocusBefore = state.workspace.focus;
  if (containsBlockedReflectionPhrase(state.workspace.focus)) {
    state.workspace.focus = "";
  }

  return {
    removedMemoryNodes: memoryNodeCountBefore - state.memory.nodes.length,
    removedReflectionThoughts: reflectionCountBefore - state.reflections.length,
    removedAttentionItems: attentionCountBefore - state.attentionQueue.length,
    removedProcessedAttentionItems: 0,
    removedStmEntries: stmCountBefore - state.stmBuffer.length,
    clearedWorkspaceFocus: Boolean(workspaceFocusBefore) && !state.workspace.focus,
    removedEdges: edgeCountBefore - state.memory.edges.length
  };
}

function purgeDuplicateReflectionSummaries(state: CognitiveRuntimeState): {
  removedMemoryNodes: number;
  removedEdges: number;
  mergedGroups: number;
} {
  const groups = new Map<string, MemoryNode[]>();
  for (const node of state.memory.nodes) {
    if (node.kind !== "reflection") {
      continue;
    }
    const normalizedSummary = toShortText(node.summary || "").trim().toLowerCase();
    if (!normalizedSummary) {
      continue;
    }
    const key = `${String(node.outcome || "").trim().toLowerCase()}||${normalizedSummary}`;
    const bucket = groups.get(key) ?? [];
    bucket.push(node);
    groups.set(key, bucket);
  }

  const removeIds = new Set<string>();
  let mergedGroups = 0;
  for (const nodes of groups.values()) {
    if (nodes.length < 2) {
      continue;
    }
    const ranked = nodes.slice().sort((left, right) => {
      const detailDelta = right.detail.length - left.detail.length;
      if (detailDelta !== 0) {
        return detailDelta;
      }
      const updatedDelta = parseIsoMs(right.updatedAt || right.createdAt || "") - parseIsoMs(left.updatedAt || left.createdAt || "");
      if (updatedDelta !== 0) {
        return updatedDelta;
      }
      return right.salience - left.salience;
    });
    const survivor = ranked[0];
    const duplicates = ranked.slice(1);
    if (!survivor || duplicates.length === 0) {
      continue;
    }
    const freshestAt = ranked.reduce((latest, node) => {
      const nodeMs = parseIsoMs(node.updatedAt || node.createdAt || "");
      return Number.isFinite(nodeMs) && nodeMs > parseIsoMs(latest) ? node.updatedAt || node.createdAt : latest;
    }, survivor.updatedAt || survivor.createdAt);
    const richestDetail = ranked[0].detail;
    survivor.detail = richestDetail;
    survivor.participants = unique(ranked.flatMap((node) => node.participants)).slice(0, 8);
    survivor.topics = unique(ranked.flatMap((node) => node.topics)).slice(0, 24);
    survivor.goals = unique(ranked.flatMap((node) => node.goals)).slice(0, 12);
    survivor.trace = clamp(Math.max(...ranked.map((node) => node.trace)), 0.02, 1);
    survivor.salience = clamp(Math.max(...ranked.map((node) => node.salience)), 0.05, 1);
    survivor.updatedAt = freshestAt || nowIso();
    for (const duplicate of duplicates) {
      removeIds.add(duplicate.id);
    }
    mergedGroups += 1;
  }

  if (removeIds.size === 0) {
    return {
      removedMemoryNodes: 0,
      removedEdges: 0,
      mergedGroups: 0
    };
  }

  const beforeNodeCount = state.memory.nodes.length;
  const beforeEdgeCount = state.memory.edges.length;
  state.memory.nodes = state.memory.nodes.filter((node) => !removeIds.has(node.id));
  state.memory.edges = state.memory.edges.filter((edge) => !removeIds.has(edge.from) && !removeIds.has(edge.to));
  rebuildIndexes(state);
  return {
    removedMemoryNodes: beforeNodeCount - state.memory.nodes.length,
    removedEdges: beforeEdgeCount - state.memory.edges.length,
    mergedGroups
  };
}

function memoryTierForNode(state: CognitiveRuntimeState, node: MemoryNode): MemoryTier {
  const summary = node.summary.toLowerCase();
  const detail = node.detail.toLowerCase();
  const topics = node.topics;

  if (node.kind === "goal") {
    return "identity_kernel";
  }
  if (node.kind === "participant" && (summary === "aurora" || summary === "user")) {
    return summary === "aurora" ? "identity_kernel" : "relationship_kernel";
  }
  if (summary.includes("identity") || detail.includes("identity kernel") || detail.includes("core boundary")) {
    return "identity_kernel";
  }
  if (
    summary.includes("user interaction") ||
    summary.includes("relationship") ||
    summary.includes("repair protocol") ||
    detail.includes("consent") ||
    detail.includes("boundary") ||
    detail.includes("trust")
  ) {
    return "relationship_kernel";
  }
  if (node.kind === "reflection" && (detail.includes("belief") || detail.includes("guardrail"))) {
    return "belief_anchor";
  }
  if (
    node.outcome === "confirmed_belief_anchor" ||
    node.outcome === USER_STATED_ANCHOR_OUTCOME ||
    node.outcome === USER_FACT_SNAPSHOT_OUTCOME ||
    node.outcome === USER_SCENE_SNAPSHOT_OUTCOME
  ) {
    return "belief_anchor";
  }
  if (
    summary.includes("commitment") ||
    summary.includes("project") ||
    detail.includes("renegotiation") ||
    detail.includes("overdue")
  ) {
    return "commitment_project";
  }
  if (
    topics.some((topic) => topic.includes("preference") || topic.includes("belief") || topic.includes("boundary")) ||
    node.kind === "emotion"
  ) {
    return "belief_anchor";
  }
  if (node.kind === "topic" || node.kind === "system") {
    return "transient";
  }
  if (node.kind === "event" || node.kind === "reflection") {
    return "episodic";
  }
  return "transient";
}

function memoryTierCounts(state: CognitiveRuntimeState): MemoryGovernanceTierCounts {
  const counts = defaultMemoryGovernanceTierCounts();
  for (const node of state.memory.nodes) {
    const tier = memoryTierForNode(state, node);
    if (tier === "identity_kernel") {
      counts.identityKernel += 1;
    } else if (tier === "relationship_kernel") {
      counts.relationshipKernel += 1;
    } else if (tier === "commitment_project") {
      counts.commitmentProject += 1;
    } else if (tier === "belief_anchor") {
      counts.beliefAnchor += 1;
    } else if (tier === "episodic") {
      counts.episodic += 1;
    } else {
      counts.transient += 1;
    }
  }
  return counts;
}

function memoryHeatCounts(state: CognitiveRuntimeState): { hot: number; warm: number; cold: number } {
  let hot = 0;
  let warm = 0;
  let cold = 0;

  for (const node of state.memory.nodes) {
    const tier = memoryTierForNode(state, node);
    if (tier === "identity_kernel" || tier === "relationship_kernel" || tier === "commitment_project" || tier === "belief_anchor") {
      hot += 1;
    } else if (tier === "episodic") {
      warm += 1;
    } else {
      cold += 1;
    }
  }

  return { hot, warm, cold };
}

function memoryCompactionCadenceLabel(): string {
  const minutes = Math.round(MEMORY_SLEEP_INTERVAL_MS / 60000);
  return `${minutes}m`;
}

function protectedNodeIdsForGovernance(state: CognitiveRuntimeState): Set<string> {
  const protectedIds = new Set<string>();
  for (const node of state.memory.nodes) {
    const tier = memoryTierForNode(state, node);
    if (
      tier === "identity_kernel" ||
      tier === "relationship_kernel" ||
      tier === "commitment_project" ||
      tier === "belief_anchor"
    ) {
      protectedIds.add(node.id);
    }
  }
  return protectedIds;
}

function memoryNodeRetentionScore(state: CognitiveRuntimeState, node: MemoryNode, tier?: MemoryTier): number {
  const tierValue = tier ?? memoryTierForNode(state, node);
  const nowMs = Date.now();
  const ageMs = Math.max(0, nowMs - Date.parse(node.updatedAt));
  const recency = Math.exp(-ageMs / (1000 * 60 * 60 * 24 * 5));
  const importance = clamp(node.salience * 0.52 + node.trace * 0.33 + Math.min(node.accessCount / 14, 1) * 0.15, 0, 1);
  const tierBoost: Record<MemoryTier, number> = {
    identity_kernel: 1.4,
    relationship_kernel: 1.1,
    commitment_project: 0.96,
    belief_anchor: 0.88,
    episodic: 0.46,
    transient: 0.18
  };
  return tierBoost[tierValue] + importance * 0.9 + recency * 0.72;
}

function memoryEdgeRetentionScore(state: CognitiveRuntimeState, edge: MemoryEdge, protectedNodeIds: Set<string>): number {
  const ageMs = Math.max(0, Date.now() - Date.parse(edge.updatedAt));
  const recency = Math.exp(-ageMs / (1000 * 60 * 60 * 24 * 3));
  const relationBoost = ["supports", "supported_by", "guides", "about", "responds_to", "elicits"].includes(edge.relation)
    ? 0.2
    : 0;
  const protectedBoost = protectedNodeIds.has(edge.from) || protectedNodeIds.has(edge.to) ? 0.35 : 0;
  return edge.weight * 0.8 + recency * 0.25 + relationBoost + protectedBoost;
}

function enforceMemoryNodeBudget(state: CognitiveRuntimeState, target: number): number {
  if (state.memory.nodes.length <= target) {
    return 0;
  }

  const protectedNodeIds = protectedNodeIdsForGovernance(state);
  const scored = state.memory.nodes.map((node) => {
    const tier = memoryTierForNode(state, node);
    return {
      id: node.id,
      tier,
      retention: memoryNodeRetentionScore(state, node, tier),
      protected: protectedNodeIds.has(node.id)
    };
  });

  const removable = scored
    .filter((entry) => !entry.protected)
    .sort((a, b) => a.retention - b.retention);
  const fallback = scored
    .filter((entry) => entry.tier !== "identity_kernel")
    .sort((a, b) => a.retention - b.retention);
  const overflow = state.memory.nodes.length - target;
  const selected = new Set<string>();

  for (const entry of removable) {
    if (selected.size >= overflow) {
      break;
    }
    selected.add(entry.id);
  }
  if (selected.size < overflow) {
    for (const entry of fallback) {
      if (selected.size >= overflow) {
        break;
      }
      selected.add(entry.id);
    }
  }
  if (selected.size === 0) {
    return 0;
  }

  const before = state.memory.nodes.length;
  state.memory.nodes = state.memory.nodes.filter((node) => !selected.has(node.id));
  if (state.memory.nodes.length === before) {
    return 0;
  }
  state.memory.edges = state.memory.edges.filter((edge) => !selected.has(edge.from) && !selected.has(edge.to));
  rebuildIndexes(state);
  return before - state.memory.nodes.length;
}

function enforceMemoryEdgeBudget(state: CognitiveRuntimeState, target: number): number {
  if (state.memory.edges.length <= target) {
    return 0;
  }

  const protectedNodeIds = protectedNodeIdsForGovernance(state);
  const scored = state.memory.edges
    .map((edge) => ({
      edge,
      retention: memoryEdgeRetentionScore(state, edge, protectedNodeIds)
    }))
    .sort((a, b) => a.retention - b.retention);
  const overflow = state.memory.edges.length - target;
  const removeIds = new Set(scored.slice(0, overflow).map((entry) => entry.edge.id));
  if (removeIds.size === 0) {
    return 0;
  }

  const before = state.memory.edges.length;
  state.memory.edges = state.memory.edges.filter((edge) => !removeIds.has(edge.id));
  return before - state.memory.edges.length;
}

function clusterKeyForConsolidation(node: MemoryNode): string {
  const participant = node.participants.includes("user")
    ? "user"
    : node.participants.includes("aurora")
    ? "aurora"
    : node.participants[0] || "none";
  const topic = node.topics.find((item) => !item.startsWith("session_")) || "general";
  return `${participant}|${topic}|${node.outcome || "neutral_outcome"}`;
}

function consolidateMemoryClusters(state: CognitiveRuntimeState): number {
  const nowMs = Date.now();
  const recentCutoff = nowMs - MEMORY_EVENT_LOOKBACK_MS;
  const recentEvents = state.memory.nodes.filter((node) => {
    if (node.kind !== "event") {
      return false;
    }
    if (node.outcome === "consolidated_source") {
      return false;
    }
    const createdMs = Date.parse(node.createdAt);
    return Number.isFinite(createdMs) && createdMs >= recentCutoff;
  });
  if (recentEvents.length < MEMORY_CONSOLIDATION_MIN_GROUP_SIZE) {
    return 0;
  }

  const grouped = new Map<string, MemoryNode[]>();
  for (const event of recentEvents) {
    const key = clusterKeyForConsolidation(event);
    const bucket = grouped.get(key) ?? [];
    bucket.push(event);
    grouped.set(key, bucket);
  }

  const candidates = [...grouped.entries()]
    .map(([key, items]) => ({ key, items }))
    .filter(({ items }) => items.length >= MEMORY_CONSOLIDATION_MIN_GROUP_SIZE)
    .sort((a, b) => b.items.length - a.items.length)
    .slice(0, MEMORY_CONSOLIDATION_MAX_GROUPS);

  let consolidated = 0;
  for (const { key, items } of candidates) {
    const [participant, topic] = key.split("|");
    const clusterSummary = `Consolidated memory cluster: ${topic} (${items.length} events)`;
    const exactSummaryExists = state.memory.nodes.some(
      (node) => node.kind === "reflection" && node.summary === clusterSummary
    );
    if (exactSummaryExists) {
      continue;
    }
    const recentSummaryExists = state.memory.nodes.some((node) => {
      if (node.kind !== "reflection") {
        return false;
      }
      if (!node.summary.startsWith("Consolidated memory cluster:")) {
        return false;
      }
      if (!node.summary.toLowerCase().includes(topic)) {
        return false;
      }
      const createdMs = Date.parse(node.createdAt);
      return Number.isFinite(createdMs) && nowMs - createdMs <= MEMORY_SUMMARY_DEDUP_MS;
    });
    if (recentSummaryExists) {
      continue;
    }

    const sorted = items.sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));
    const sample = sorted.slice(0, 3);
    const goals = unique(sorted.flatMap((item) => item.goals)).slice(0, 6);
    const summaryNode = createMemoryFromText(state, {
      kind: "reflection",
      summary: clusterSummary,
      detail: [
        `Participant focus: ${participant}`,
        `Topic focus: ${topic}`,
        "Representative signals:",
        ...sample.map((item, index) => `${index + 1}. ${toSingleLine(item.summary, 140)}`),
        `Consolidated at: ${new Date(nowMs).toISOString()}`
      ].join("\n"),
      participants: unique(sorted.flatMap((item) => item.participants)),
      goals,
      outcome: "consolidated_pattern",
      salience: clamp(sorted.reduce((sum, item) => sum + item.salience, 0) / sorted.length, 0.48, 0.9)
    });
    for (const sourceNode of sorted.slice(0, 8)) {
      addOrStrengthenEdge(state, summaryNode.id, sourceNode.id, "summarizes", 0.14);
      addOrStrengthenEdge(state, sourceNode.id, summaryNode.id, "summarized_by", 0.08);
    }
    for (const sourceNode of sorted.slice(2)) {
      sourceNode.trace = clamp(sourceNode.trace * 0.78, 0.02, 1);
      sourceNode.salience = clamp(sourceNode.salience * 0.74, 0.05, 1);
      sourceNode.outcome = "consolidated_source";
      sourceNode.updatedAt = nowIso();
    }
    consolidated += 1;
  }

  return consolidated;
}

function runMemoryGovernanceSleep(state: CognitiveRuntimeState, reason: string): void {
  const governance = ensureMemoryGovernance(state);
  const consolidated = consolidateMemoryClusters(state);
  const nodeTarget = state.memory.nodes.length > MAX_MEMORY_NODES ? MAX_MEMORY_NODES : MEMORY_NODE_SLEEP_TARGET;
  const edgeTarget = state.memory.edges.length > MAX_MEMORY_EDGES ? MAX_MEMORY_EDGES : MEMORY_EDGE_SLEEP_TARGET;
  const prunedNodes = enforceMemoryNodeBudget(state, nodeTarget);
  const prunedEdges = enforceMemoryEdgeBudget(state, edgeTarget);
  const tierCounts = memoryTierCounts(state);
  const heat = memoryHeatCounts(state);
  const cadence = memoryCompactionCadenceLabel();
  const now = nowIso();

  governance.lastSleepAt = now;
  governance.runs += 1;
  governance.lastReason = reason;
  governance.lastConsolidatedAt = consolidated > 0 ? now : governance.lastConsolidatedAt;
  governance.lastConsolidatedClusters = consolidated;
  governance.lastPrunedNodes = prunedNodes;
  governance.lastPrunedEdges = prunedEdges;
  governance.tierCounts = tierCounts;
  governance.lastSummary = `reason=${reason}; cadence=${cadence}; consolidated=${consolidated}; pruned_nodes=${prunedNodes}; pruned_edges=${prunedEdges}; nodes=${state.memory.nodes.length}; edges=${state.memory.edges.length}; heat_hot=${heat.hot}; heat_warm=${heat.warm}; heat_cold=${heat.cold}`;

  if (consolidated > 0 || prunedNodes > 0 || prunedEdges > 0) {
    createMemoryFromText(state, {
      kind: "system",
      summary: "Memory sleep pass executed",
      detail: governance.lastSummary,
      participants: ["aurora"],
      goals: state.workspace.pendingPlans,
      outcome: "memory_governance",
      salience: 0.52
    });
  }
}

function maybeRunMemoryGovernance(state: CognitiveRuntimeState): void {
  const governance = ensureMemoryGovernance(state);
  const nowMs = Date.now();
  const lastRunMs = governance.lastSleepAt ? Date.parse(governance.lastSleepAt) : 0;
  const scheduledDue = !lastRunMs || !Number.isFinite(lastRunMs) || nowMs - lastRunMs >= MEMORY_SLEEP_INTERVAL_MS;
  const pressure =
    state.memory.nodes.length >= MEMORY_NODE_PRESSURE_THRESHOLD || state.memory.edges.length >= MEMORY_EDGE_PRESSURE_THRESHOLD;

  if (!scheduledDue && !pressure) {
    return;
  }

  runMemoryGovernanceSleep(state, pressure ? "capacity_pressure" : "scheduled");
}

function addMemoryNode(state: CognitiveRuntimeState, node: MemoryNode): void {
  state.memory.nodes.push(node);
  for (const topic of node.topics) {
    upsertIndex(state.memory.indexes.byTopic, topic, node.id);
  }
  for (const participant of node.participants) {
    upsertIndex(state.memory.indexes.byParticipant, participant, node.id);
  }
  if (node.outcome) {
    upsertIndex(state.memory.indexes.byOutcome, node.outcome, node.id);
  }
  if (node.emotionLabel) {
    upsertIndex(state.memory.indexes.byEmotion, node.emotionLabel, node.id);
  }

  if (state.memory.nodes.length > MAX_MEMORY_NODES) {
    enforceMemoryNodeBudget(state, MAX_MEMORY_NODES);
  }
}

function addOrStrengthenEdge(
  state: CognitiveRuntimeState,
  from: string,
  to: string,
  relation: string,
  delta = 0.08
): void {
  const existing = state.memory.edges.find((edge) => edge.from === from && edge.to === to && edge.relation === relation);
  const updatedAt = nowIso();
  if (existing) {
    existing.weight = clamp(existing.weight + delta, 0.02, 1);
    existing.updatedAt = updatedAt;
    return;
  }

  state.memory.edges.push({
    id: toId("edge"),
    from,
    to,
    relation,
    weight: clamp(delta + 0.12, 0.02, 1),
    updatedAt
  });

  if (state.memory.edges.length > MAX_MEMORY_EDGES) {
    enforceMemoryEdgeBudget(state, MAX_MEMORY_EDGES);
  }
}

function getNode(state: CognitiveRuntimeState, id: string): MemoryNode | undefined {
  return state.memory.nodes.find((node) => node.id === id);
}

function isOperationalMemoryNode(node: MemoryNode): boolean {
  if (node.kind === "system") {
    return true;
  }
  if (/^processed .* signal$/i.test(node.summary)) {
    return true;
  }
  if (/^heartbeat context ingested$/i.test(node.summary)) {
    return true;
  }
  return isOperationalNoiseTurn(`${node.summary}\n${node.detail}`);
}

function shouldPruneOperationalNoiseNode(node: MemoryNode): boolean {
  const summary = node.summary.toLowerCase();
  const combined = `${node.summary}\n${node.detail}`;

  if (summary.startsWith("user interaction: [system message]")) {
    return true;
  }
  if (summary.startsWith("aurora action: no_reply")) {
    return true;
  }
  if (summary.startsWith("web artifact: http://127.0.0.1:18789")) {
    return true;
  }
  if (node.kind === "system" && /^processed .* signal$/i.test(node.summary)) {
    return true;
  }
  if (node.kind === "system" && /^heartbeat context ingested$/i.test(node.summary)) {
    return true;
  }
  if (isOperationalNoiseTurn(combined)) {
    return true;
  }

  return false;
}

function pruneOperationalNoiseMemories(state: CognitiveRuntimeState): { prunedNodes: number; prunedTurns: number } {
  const removeIds = new Set<string>();
  for (const node of state.memory.nodes) {
    if (shouldPruneOperationalNoiseNode(node)) {
      removeIds.add(node.id);
    }
  }

  let prunedNodes = 0;
  if (removeIds.size > 0) {
    const beforeNodes = state.memory.nodes.length;
    state.memory.nodes = state.memory.nodes.filter((node) => !removeIds.has(node.id));
    state.memory.edges = state.memory.edges.filter((edge) => !removeIds.has(edge.from) && !removeIds.has(edge.to));
    prunedNodes = beforeNodes - state.memory.nodes.length;
  }

  let prunedTurns = 0;
  for (const [sessionId, turns] of Object.entries(state.sessionTurns)) {
    const cleaned = turns
      .map((turn) => {
        const normalizedUser = normalizeUserTurnText(turn.userText || "");
        const normalizedAurora = normalizeAssistantTurnText(turn.auroraText || "");
        const userKeep = normalizedUser && !isOperationalNoiseTurn(normalizedUser) ? normalizedUser : "";
        const auroraKeep = normalizedAurora && !isOperationalNoiseTurn(normalizedAurora) ? normalizedAurora : "";
        if ((!userKeep && !auroraKeep) || isSemanticallyBrokenOwnerContinuityTurn(userKeep, auroraKeep)) {
          prunedTurns += 1;
          return null;
        }
        const urls = unique([...extractUrls(userKeep), ...extractUrls(auroraKeep)]).slice(0, 10);
        return {
          ...turn,
          userText: toShortText(toSingleLine(userKeep, 1200), 1200),
          auroraText: toShortText(toSingleLine(auroraKeep, 1600), 1600),
          urls
        };
      })
      .filter((turn): turn is SessionTurn => Boolean(turn))
      .slice(-MAX_SESSION_TURNS_PER_SESSION);

    if (cleaned.length === 0) {
      delete state.sessionTurns[sessionId];
      continue;
    }
    if (cleaned.length !== turns.length) {
      state.sessionTurns[sessionId] = cleaned;
    } else {
      let changed = false;
      for (let index = 0; index < cleaned.length; index += 1) {
        if (
          cleaned[index].userText !== turns[index].userText ||
          cleaned[index].auroraText !== turns[index].auroraText ||
          JSON.stringify(cleaned[index].urls) !== JSON.stringify(turns[index].urls)
        ) {
          changed = true;
          break;
        }
      }
      if (changed) {
        state.sessionTurns[sessionId] = cleaned;
      }
    }
  }

  if (prunedNodes > 0) {
    rebuildIndexes(state);
  }

  return { prunedNodes, prunedTurns };
}

function confirmedAnchorSummary(key: string): string {
  return `${CONFIRMED_ANCHOR_SUMMARY_PREFIX} ${key.trim().toLowerCase()}`.trim();
}

function confirmedAnchorMirrorDetail(anchor: ConfirmedAnchorEntry): string {
  const segments = [
    `mirror_source=${CONFIRMED_ANCHOR_MIRROR_SOURCE}`,
    `key=${anchor.key}`,
    `value=${anchor.value}`,
  ];
  if (anchor.label) {
    segments.push(`label=${anchor.label}`);
  }
  if (anchor.confirmedBy) {
    segments.push(`confirmed_by=${anchor.confirmedBy}`);
  }
  if (anchor.method) {
    segments.push(`method=${anchor.method}`);
  }
  if (anchor.addedAt) {
    segments.push(`added_at=${anchor.addedAt}`);
  }
  return segments.join("; ");
}

function confirmedAnchorParticipants(anchor: ConfirmedAnchorEntry): string[] {
  const participants = new Set<string>(["user"]);
  const hintText = `${anchor.key} ${anchor.value}`.toLowerCase();
  const knownParticipants = ["cade", "examplefriend", "examplepartner", "nick", "aurora"];
  for (const participant of knownParticipants) {
    if (hintText.includes(participant)) {
      participants.add(participant);
    }
  }
  return [...participants];
}

function parseConfirmedAnchorKeyFromNode(node: MemoryNode): string {
  const summary = node.summary.trim().toLowerCase();
  const prefix = CONFIRMED_ANCHOR_SUMMARY_PREFIX.toLowerCase();
  if (!summary.startsWith(prefix)) {
    return "";
  }
  if (!node.detail.toLowerCase().includes(`mirror_source=${CONFIRMED_ANCHOR_MIRROR_SOURCE}`)) {
    return "";
  }
  return summary.slice(prefix.length).trim();
}

function parseStructuredDetail(detail: string): Record<string, string> {
  const parsed: Record<string, string> = {};
  const regex = /(?:^|;\s*)([a-z_]+)=(.*?)(?=(?:;\s*[a-z_]+=)|$)/gi;
  for (const match of detail.matchAll(regex)) {
    const key = String(match[1] || "").trim().toLowerCase();
    const value = String(match[2] || "").trim();
    if (!key || !value) {
      continue;
    }
    parsed[key] = value;
  }
  return parsed;
}

function parseConfirmedAnchorFromNode(node: MemoryNode): ConfirmedAnchorEntry | null {
  const key = parseConfirmedAnchorKeyFromNode(node);
  if (!key) {
    return null;
  }
  const metadata = parseStructuredDetail(node.detail);
  const value = normalizeBeliefValue(metadata.value || "");
  if (!value) {
    return null;
  }
  return {
    key,
    value,
    label: metadata.label || "",
    addedAt: metadata.added_at || "",
    confirmedBy: metadata.confirmed_by || "",
    method: metadata.method || ""
  };
}

function canonicalBeliefKeyFromConfirmedAnchor(anchorKey: string): string {
  const mapped = CONFIRMED_ANCHOR_BELIEF_KEY_MAP[anchorKey];
  if (mapped) {
    return mapped;
  }
  if (anchorKey.startsWith("aurora_")) {
    return `aurora.anchor.${anchorKey.slice("aurora_".length)}`;
  }
  if (
    anchorKey.startsWith("cade_") ||
    anchorKey.startsWith("examplefriend_") ||
    anchorKey.startsWith("user_")
  ) {
    return `user.anchor.${anchorKey}`;
  }
  return `memory.anchor.${anchorKey}`;
}

function upsertAnchoredBelief(
  state: CognitiveRuntimeState,
  input: {
    key: string;
    value: string;
    condition?: string;
    confidence: number;
    source?: BeliefRecord["source"];
    supportIds?: string[];
    skipMeaningCheck?: boolean;
  }
): "added" | "updated" | "unchanged" {
  const extensions = ensureExtensions(state);
  const condition = normalizeBeliefConditionForKey(
    input.key,
    toSingleLine(input.condition || "default", 72) || "default"
  );
  const candidateValue = normalizeBeliefValue(input.value);
  if (!candidateValue) {
    return "unchanged";
  }
  if (!input.skipMeaningCheck && !isMeaningfulBeliefValue(input.key, candidateValue)) {
    return "unchanged";
  }

  const supportIds = unique((input.supportIds ?? []).map((id) => id.trim()).filter(Boolean)).slice(-14);
  const nowAt = nowIso();
  const sameSlot = extensions.beliefs.filter(
    (item) => item.key === input.key && item.condition === condition && item.status !== "deprecated"
  );
  const matchingValue = sameSlot.find((item) => normalizedBeliefValueKey(item.value) === normalizedBeliefValueKey(candidateValue));

  if (matchingValue) {
    const previousConfidence = matchingValue.confidence;
    const previousSupport = matchingValue.supportEpisodeIds.length;
    matchingValue.confidence = clamp(Math.max(matchingValue.confidence, input.confidence), 0, 1);
    matchingValue.supportEpisodeIds = unique([...matchingValue.supportEpisodeIds, ...supportIds]).slice(-14);
    matchingValue.lastCheckedAt = nowAt;
    if (matchingValue.status === "conflicted" && matchingValue.confidence > 0.72) {
      matchingValue.status = "active";
    }
    matchingValue.authority = "durable";
    maybePromoteCorrectionBelief(state, matchingValue);
    return previousConfidence !== matchingValue.confidence || previousSupport !== matchingValue.supportEpisodeIds.length
      ? "updated"
      : "unchanged";
  }

  for (const conflict of sameSlot) {
    if (normalizedBeliefValueKey(conflict.value) === normalizedBeliefValueKey(candidateValue)) {
      continue;
    }
    conflict.status = "conflicted";
    conflict.disconfirmEpisodeIds = unique([...conflict.disconfirmEpisodeIds, ...supportIds]).slice(-14);
    conflict.lastCheckedAt = nowAt;
  }

  extensions.beliefs.push({
    id: toId("belief"),
    key: input.key,
    value: candidateValue,
    condition,
    status: "active",
    authority: "durable",
    confidence: clamp(input.confidence, 0, 1),
    source: input.source ?? "inferred_from_user",
    supportEpisodeIds: supportIds,
    disconfirmEpisodeIds: [],
    lastCheckedAt: nowAt
  });
  return "added";
}

async function syncAuroraSelfBeliefAnchorsFromLedger(state: CognitiveRuntimeState): Promise<{
  added: number;
  updated: number;
  deprecated: number;
}> {
  const extensions = ensureExtensions(state);
  const anchors = await loadAuroraSelfAnchors();
  let added = 0;
  let updated = 0;
  let deprecated = 0;
  const supportedByKey = new Map<string, { entry: AuroraSelfAnchorEntry; signature: string; supportId: string }>();

  for (const entry of anchors) {
    const beliefKey = auroraSelfAnchorBeliefKey(entry.anchorKey);
    if (!beliefKey) {
      continue;
    }
    const supportId = auroraSelfAnchorSupportId(entry.anchorKey);
    const signature = `${beliefKey}:default=${normalizedBeliefValueKey(entry.value)}`;
    const result = upsertAnchoredBelief(state, {
      key: beliefKey,
      value: entry.value,
      condition: "default",
      confidence: 0.96,
      source: "inferred_from_aurora",
      supportIds: [supportId],
      skipMeaningCheck: true
    });
    if (result === "added") {
      added += 1;
    } else if (result === "updated") {
      updated += 1;
    }
    supportedByKey.set(beliefKey, { entry, signature, supportId });
  }

  if (supportedByKey.size === 0) {
    return { added, updated, deprecated };
  }

  const nowAt = nowIso();
  for (const belief of extensions.beliefs) {
    const support = supportedByKey.get(belief.key);
    if (!support || belief.source !== "inferred_from_aurora") {
      continue;
    }
    const signature = `${belief.key}:${belief.condition}=${normalizedBeliefValueKey(belief.value)}`;
    if (signature === support.signature) {
      belief.status = "active";
      belief.confidence = clamp(Math.max(belief.confidence, 0.96), 0, 1);
      belief.supportEpisodeIds = unique([...belief.supportEpisodeIds, support.supportId]).slice(-14);
      belief.disconfirmEpisodeIds = [];
      belief.lastCheckedAt = nowAt;
      continue;
    }
    if (shouldPreserveAuroraSelfAnchorRevisionCandidateDuringLedgerSync(state, belief, support.entry)) {
      belief.lastCheckedAt = nowAt;
      continue;
    }
    if (belief.status !== "deprecated") {
      belief.status = "deprecated";
      belief.disconfirmEpisodeIds = unique([...belief.disconfirmEpisodeIds, support.supportId]).slice(-14);
      belief.lastCheckedAt = nowAt;
      deprecated += 1;
    }
  }

  refreshBeliefConflictState(state);
  extensions.beliefs = trimBeliefsPreservingCanonical(extensions.beliefs);
  return { added, updated, deprecated };
}

function syncBeliefsFromAnchorMemory(state: CognitiveRuntimeState): {
  added: number;
  updated: number;
  deprecated: number;
  removed: number;
} {
  const extensions = ensureExtensions(state);
  if (cognitionDelegatesDurableContinuityCanon()) {
    extensions.beliefs = [];
    return { added: 0, updated: 0, deprecated: 0, removed: 0 };
  }
  let added = 0;
  let updated = 0;
  let deprecated = 0;
  let removed = 0;
  const supportedDurableBeliefs = new Set<string>();
  const latestDirectUserAnchorCandidates = new Map<
    string,
    { key: string; value: string; condition: string; confidence: number; supportId: string; atMs: number }
  >();

  for (const node of state.memory.nodes) {
    if (node.outcome === "confirmed_belief_anchor") {
      const anchor = parseConfirmedAnchorFromNode(node);
      if (!anchor) {
        continue;
      }
      const beliefKey = canonicalBeliefKeyFromConfirmedAnchor(anchor.key);
      const anchorValue =
        anchor.key === "examplefriend_relationship_to_cade" &&
        /\bbest\s*friend\b|\bbestfriend\b/i.test(anchor.value)
          ? "ExampleFriend"
          : anchor.value;
      const result = upsertAnchoredBelief(state, {
        key: beliefKey,
        value: anchorValue,
        confidence: 0.96,
        source: "inferred_from_user",
        supportIds: [node.id],
        skipMeaningCheck: true
      });
      if (result === "added") {
        added += 1;
      } else if (result === "updated") {
        updated += 1;
      }
      supportedDurableBeliefs.add(`${beliefKey}:default=${normalizedBeliefValueKey(anchorValue)}`);

      if (anchor.key === "aurora_functional_verification_verdict") {
        const scopeValue = "Functional verification only; not phenomenal consciousness.";
        const scopeResult = upsertAnchoredBelief(state, {
          key: "aurora.functional_verification.scope",
          value: scopeValue,
          confidence: 0.94,
          source: "inferred_from_user",
          supportIds: [node.id],
          skipMeaningCheck: true
        });
        if (scopeResult === "added") {
          added += 1;
        } else if (scopeResult === "updated") {
          updated += 1;
        }
        supportedDurableBeliefs.add(`aurora.functional_verification.scope:default=${normalizedBeliefValueKey(scopeValue)}`);
      }
      continue;
    }

    if (node.outcome !== USER_STATED_ANCHOR_OUTCOME || !node.detail) {
      continue;
    }

    const directSelfView = resolveDirectUserSelfViewAnswer(state, node.detail);
    if (isImmediateUserStatementAnchorEligibleDirectSelfView(directSelfView)) {
      const slotKey = `${directSelfView.beliefKey}:default`;
      const atMs = Math.max(parseIsoMs(node.updatedAt || ""), parseIsoMs(node.createdAt || ""), 0);
      const existing = latestDirectUserAnchorCandidates.get(slotKey);
      if (!existing || atMs >= existing.atMs) {
        latestDirectUserAnchorCandidates.set(slotKey, {
          key: directSelfView.beliefKey,
          value: directSelfView.value,
          condition: "default",
          confidence: 0.96,
          supportId: userStatedAnchorSupportId(node.id),
          atMs
        });
      }
    }

    const directFact = parseDirectUserProfileFact(node.detail);
    if (directFact?.value) {
      const slotKey = `${directFact.beliefKey}:default`;
      const atMs = Math.max(parseIsoMs(node.updatedAt || ""), parseIsoMs(node.createdAt || ""), 0);
      const existing = latestDirectUserAnchorCandidates.get(slotKey);
      if (!existing || atMs >= existing.atMs) {
        latestDirectUserAnchorCandidates.set(slotKey, {
          key: directFact.beliefKey,
          value: directFact.value,
          condition: "default",
          confidence: 0.96,
          supportId: userStatedAnchorSupportId(node.id),
          atMs
        });
      }
    }

    const candidates = extractBeliefCandidates(node.detail, "user");
    for (const candidate of candidates) {
      const result = upsertAnchoredBelief(state, {
        key: candidate.key,
        value: candidate.value,
        condition: candidate.condition,
        confidence: Math.max(candidate.confidence, 0.84),
        source: "inferred_from_user",
        supportIds: [node.id]
      });
      if (result === "added") {
        added += 1;
      } else if (result === "updated") {
        updated += 1;
      }
    }
  }

  for (const candidate of latestDirectUserAnchorCandidates.values()) {
    const result = upsertAnchoredBelief(state, {
      key: candidate.key,
      value: candidate.value,
      condition: candidate.condition,
      confidence: candidate.confidence,
      source: "inferred_from_user",
      supportIds: [candidate.supportId],
      skipMeaningCheck: true
    });
    if (result === "added") {
      added += 1;
    } else if (result === "updated") {
      updated += 1;
    }
    supportedDurableBeliefs.add(
      `${candidate.key}:${candidate.condition}=${normalizedBeliefValueKey(candidate.value)}`
    );
  }

  const nowAt = nowIso();
  for (const belief of extensions.beliefs) {
    if (belief.status === "deprecated" || !isSupportedAnchorBeliefRecord(belief)) {
      continue;
    }
    const signature = `${belief.key}:${belief.condition}=${normalizedBeliefValueKey(belief.value)}`;
    if (supportedDurableBeliefs.has(signature)) {
      continue;
    }
    belief.status = "deprecated";
    belief.lastCheckedAt = nowAt;
    deprecated += 1;
  }

  const beforePrune = extensions.beliefs.length;
  extensions.beliefs = extensions.beliefs.filter((belief) => {
    if (!isSupportedAnchorBeliefRecord(belief)) {
      return true;
    }
    if (belief.status === "deprecated") {
      return false;
    }
    const signature = `${belief.key}:${belief.condition}=${normalizedBeliefValueKey(belief.value)}`;
    return supportedDurableBeliefs.has(signature);
  });
  removed += beforePrune - extensions.beliefs.length;

  refreshBeliefConflictState(state);
  const finalNowAt = nowIso();
  extensions.beliefs = extensions.beliefs.filter((belief) => {
    if (!isSupportedAnchorBeliefRecord(belief)) {
      return true;
    }
    const signature = `${belief.key}:${belief.condition}=${normalizedBeliefValueKey(belief.value)}`;
    if (!supportedDurableBeliefs.has(signature)) {
      return false;
    }
    belief.status = "active";
    belief.disconfirmEpisodeIds = [];
    belief.lastCheckedAt = finalNowAt;
    return true;
  });
  extensions.beliefs = trimBeliefsPreservingCanonical(extensions.beliefs);
  return { added, updated, deprecated, removed };
}

async function refreshExternalBeliefAnchors(state: CognitiveRuntimeState): Promise<string[]> {
  if (cognitionDelegatesDurableContinuityCanon()) {
    ensureExtensions(state).beliefs = [];
    return [];
  }
  const startedAt = Date.now();
  cognitionDebugLog("refreshExternalBeliefAnchors:start", startedAt);
  const summaries: string[] = [];
  const governance = ensureMemoryGovernance(state);
  const episodeCache = buildBeliefSyncEpisodeCache(state);
  let rawRecallMtimeMs = 0;
  try {
    rawRecallMtimeMs = (await stat(rawRecallPath())).mtimeMs;
  } catch {
    rawRecallMtimeMs = 0;
  }
  const lastExternalBeliefSyncAtMs = parseIsoMs(governance.lastExternalBeliefSyncAt);
  const fallbackStateSyncAtMs = parseIsoMs(state.updatedAt || "");
  const incrementalSinceAtMs =
    lastExternalBeliefSyncAtMs > 0
      ? Math.max(0, lastExternalBeliefSyncAtMs - 60_000)
      : fallbackStateSyncAtMs > 0
        ? Math.max(0, fallbackStateSyncAtMs - 60_000)
        : 0;
  const rawRecallBackfillNeeded =
    rawRecallMtimeMs > 0 &&
    (rawRecallMtimeMs > governance.lastExternalBeliefRawRecallMtimeMs || governance.lastExternalBeliefSyncAt === null);
  const anchorMirror = await syncConfirmedAnchorMirrors(state);
  cognitionDebugLog("refreshExternalBeliefAnchors:syncConfirmedAnchorMirrors", startedAt);
  const beliefSync = syncBeliefsFromAnchorMemory(state);
  cognitionDebugLog("refreshExternalBeliefAnchors:syncBeliefsFromAnchorMemory", startedAt);
  const auroraSelfBeliefSync = await syncAuroraSelfBeliefsFromRecentEpisodes(state, episodeCache, incrementalSinceAtMs, {
    includeRawRecall: rawRecallBackfillNeeded
  });
  cognitionDebugLog("refreshExternalBeliefAnchors:syncAuroraSelfBeliefsFromRecentEpisodes", startedAt);
  const auroraSelfAnchorSync = await syncAuroraSelfBeliefAnchorsFromLedger(state);
  cognitionDebugLog("refreshExternalBeliefAnchors:syncAuroraSelfBeliefAnchorsFromLedger", startedAt);
  const userPreferenceBeliefSync = rawRecallBackfillNeeded
    ? await syncUserPreferenceBeliefsFromRecentEpisodes(state, episodeCache, incrementalSinceAtMs)
    : { added: 0, updated: 0, importedEpisodes: 0 };
  cognitionDebugLog("refreshExternalBeliefAnchors:syncUserPreferenceBeliefsFromRecentEpisodes", startedAt);
  const userSelfViewBeliefSync = rawRecallBackfillNeeded
    ? await syncUserSelfViewBeliefsFromRecentEpisodes(state, episodeCache, incrementalSinceAtMs)
    : { added: 0, updated: 0, importedEpisodes: 0 };
  cognitionDebugLog("refreshExternalBeliefAnchors:syncUserSelfViewBeliefsFromRecentEpisodes", startedAt);
  const userProfileBeliefSync = rawRecallBackfillNeeded
    ? await syncUserProfileBeliefsFromRecentEpisodes(state, episodeCache, incrementalSinceAtMs)
    : { added: 0, updated: 0, importedEpisodes: 0 };
  cognitionDebugLog("refreshExternalBeliefAnchors:syncUserProfileBeliefsFromRecentEpisodes", startedAt);
  const stickyCanonicalUserRepair = await backfillMissingCanonicalUserBeliefsFromArchive(state, {
    requestedKeys: knownStickyCanonicalUserBeliefKeysFromState(state)
  });
  cognitionDebugLog("refreshExternalBeliefAnchors:backfillMissingCanonicalUserBeliefsFromArchive", startedAt);
  const stickyAuroraSelfRepair = await backfillMissingAuroraSelfBeliefsFromArchive(state, {
    requestedKeys: knownStickyCanonicalAuroraBeliefKeysFromState(state)
  });
  cognitionDebugLog("refreshExternalBeliefAnchors:backfillMissingAuroraSelfBeliefsFromArchive", startedAt);
  const userFactSync = rawRecallBackfillNeeded
    ? await syncUserFactSnapshotsFromRecentRawRecall(state, incrementalSinceAtMs)
    : { added: 0 };
  cognitionDebugLog("refreshExternalBeliefAnchors:syncUserFactSnapshotsFromRecentRawRecall", startedAt);
  const userSceneSync = rawRecallBackfillNeeded
    ? await syncUserSceneSnapshotsFromRecentRawRecall(state, incrementalSinceAtMs)
    : { added: 0 };
  cognitionDebugLog("refreshExternalBeliefAnchors:syncUserSceneSnapshotsFromRecentRawRecall", startedAt);
  finalizeBeliefSyncEpisodeCache(state, episodeCache);
  const beliefAuthorityRefresh = refreshBeliefAuthorities(state);
  const auroraSelfAnchorProposalSync = await syncAuroraSelfAnchorProposals(state);
  const auroraSelfAutoAnchorSync = await autoAnchorAuroraSelfBeliefs(state);
  const auroraSelfAnchorResync =
    auroraSelfAutoAnchorSync.added > 0 || auroraSelfAutoAnchorSync.revised > 0
      ? await syncAuroraSelfBeliefAnchorsFromLedger(state)
      : { added: 0, updated: 0, deprecated: 0 };
  const auroraSelfAnchorProposalResync =
    auroraSelfAutoAnchorSync.added > 0 || auroraSelfAutoAnchorSync.revised > 0
      ? await syncAuroraSelfAnchorProposals(state)
      : { added: 0, updated: 0, removed: 0 };
  if (
    rawRecallBackfillNeeded ||
    auroraSelfAnchorSync.added > 0 ||
    auroraSelfAnchorSync.updated > 0 ||
    auroraSelfAnchorSync.deprecated > 0 ||
    auroraSelfBeliefSync.added > 0 ||
    auroraSelfBeliefSync.updated > 0 ||
    auroraSelfBeliefSync.importedEpisodes > 0 ||
    stickyCanonicalUserRepair.added > 0 ||
    stickyCanonicalUserRepair.updated > 0 ||
    stickyCanonicalUserRepair.importedEpisodes > 0 ||
    stickyAuroraSelfRepair.added > 0 ||
    stickyAuroraSelfRepair.updated > 0 ||
    stickyAuroraSelfRepair.importedEpisodes > 0 ||
    beliefAuthorityRefresh.promoted > 0 ||
    beliefAuthorityRefresh.demoted > 0 ||
    auroraSelfAnchorProposalSync.added > 0 ||
    auroraSelfAnchorProposalSync.updated > 0 ||
    auroraSelfAnchorProposalSync.removed > 0 ||
    auroraSelfAutoAnchorSync.added > 0 ||
    auroraSelfAutoAnchorSync.revised > 0 ||
    auroraSelfAnchorResync.added > 0 ||
    auroraSelfAnchorResync.updated > 0 ||
    auroraSelfAnchorResync.deprecated > 0 ||
    auroraSelfAnchorProposalResync.added > 0 ||
    auroraSelfAnchorProposalResync.updated > 0 ||
    auroraSelfAnchorProposalResync.removed > 0
  ) {
    governance.lastExternalBeliefSyncAt = nowIso();
  }
  if (rawRecallBackfillNeeded) {
    governance.lastExternalBeliefRawRecallMtimeMs = Math.max(0, Math.round(rawRecallMtimeMs));
  }

  if (anchorMirror.added > 0 || anchorMirror.updated > 0 || anchorMirror.removed > 0) {
    summaries.push(
      `confirmed_anchor_mirror added=${anchorMirror.added}; updated=${anchorMirror.updated}; removed=${anchorMirror.removed}`
    );
  }
  if (beliefSync.added > 0 || beliefSync.updated > 0 || beliefSync.deprecated > 0 || beliefSync.removed > 0) {
    summaries.push(
      `belief_anchor_sync added=${beliefSync.added}; updated=${beliefSync.updated}; deprecated=${beliefSync.deprecated}; removed=${beliefSync.removed}`
    );
  }
  if (
    auroraSelfBeliefSync.added > 0 ||
    auroraSelfBeliefSync.updated > 0 ||
    auroraSelfBeliefSync.importedEpisodes > 0
  ) {
    summaries.push(
      `aurora_self_belief_sync imported=${auroraSelfBeliefSync.importedEpisodes}; added=${auroraSelfBeliefSync.added}; updated=${auroraSelfBeliefSync.updated}`
    );
  }
  if (auroraSelfAnchorSync.added > 0 || auroraSelfAnchorSync.updated > 0 || auroraSelfAnchorSync.deprecated > 0) {
    summaries.push(
      `aurora_self_anchor_sync added=${auroraSelfAnchorSync.added}; updated=${auroraSelfAnchorSync.updated}; deprecated=${auroraSelfAnchorSync.deprecated}`
    );
  }
  if (
    userPreferenceBeliefSync.added > 0 ||
    userPreferenceBeliefSync.updated > 0 ||
    userPreferenceBeliefSync.importedEpisodes > 0
  ) {
    summaries.push(
      `user_preference_belief_sync imported=${userPreferenceBeliefSync.importedEpisodes}; added=${userPreferenceBeliefSync.added}; updated=${userPreferenceBeliefSync.updated}`
    );
  }
  if (
    userSelfViewBeliefSync.added > 0 ||
    userSelfViewBeliefSync.updated > 0 ||
    userSelfViewBeliefSync.importedEpisodes > 0
  ) {
    summaries.push(
      `user_self_view_belief_sync imported=${userSelfViewBeliefSync.importedEpisodes}; added=${userSelfViewBeliefSync.added}; updated=${userSelfViewBeliefSync.updated}`
    );
  }
  if (
    userProfileBeliefSync.added > 0 ||
    userProfileBeliefSync.updated > 0 ||
    userProfileBeliefSync.importedEpisodes > 0
  ) {
    summaries.push(
      `user_profile_belief_sync imported=${userProfileBeliefSync.importedEpisodes}; added=${userProfileBeliefSync.added}; updated=${userProfileBeliefSync.updated}`
    );
  }
  if (
    stickyCanonicalUserRepair.added > 0 ||
    stickyCanonicalUserRepair.updated > 0 ||
    stickyCanonicalUserRepair.importedEpisodes > 0
  ) {
    summaries.push(
      `sticky_canonical_user_repair imported=${stickyCanonicalUserRepair.importedEpisodes}; added=${stickyCanonicalUserRepair.added}; updated=${stickyCanonicalUserRepair.updated}`
    );
  }
  if (
    stickyAuroraSelfRepair.added > 0 ||
    stickyAuroraSelfRepair.updated > 0 ||
    stickyAuroraSelfRepair.importedEpisodes > 0
  ) {
    summaries.push(
      `sticky_aurora_self_repair imported=${stickyAuroraSelfRepair.importedEpisodes}; added=${stickyAuroraSelfRepair.added}; updated=${stickyAuroraSelfRepair.updated}`
    );
  }
  if (userFactSync.added > 0) {
    summaries.push(`user_fact_sync added=${userFactSync.added}`);
  }
  if (userSceneSync.added > 0) {
    summaries.push(`user_scene_sync added=${userSceneSync.added}`);
  }
  if (beliefAuthorityRefresh.promoted > 0 || beliefAuthorityRefresh.demoted > 0) {
    summaries.push(
      `belief_authority_refresh promoted=${beliefAuthorityRefresh.promoted}; demoted=${beliefAuthorityRefresh.demoted}`
    );
  }
  if (
    auroraSelfAnchorProposalSync.added > 0 ||
    auroraSelfAnchorProposalSync.updated > 0 ||
    auroraSelfAnchorProposalSync.removed > 0
  ) {
    summaries.push(
      `aurora_self_anchor_proposal_sync added=${auroraSelfAnchorProposalSync.added}; updated=${auroraSelfAnchorProposalSync.updated}; removed=${auroraSelfAnchorProposalSync.removed}`
    );
  }
  if (auroraSelfAutoAnchorSync.added > 0 || auroraSelfAutoAnchorSync.revised > 0) {
    summaries.push(
      `aurora_self_auto_anchor_sync added=${auroraSelfAutoAnchorSync.added}; revised=${auroraSelfAutoAnchorSync.revised}`
    );
  }
  if (
    auroraSelfAnchorResync.added > 0 ||
    auroraSelfAnchorResync.updated > 0 ||
    auroraSelfAnchorResync.deprecated > 0
  ) {
    summaries.push(
      `aurora_self_anchor_resync added=${auroraSelfAnchorResync.added}; updated=${auroraSelfAnchorResync.updated}; deprecated=${auroraSelfAnchorResync.deprecated}`
    );
  }
  if (
    auroraSelfAnchorProposalResync.added > 0 ||
    auroraSelfAnchorProposalResync.updated > 0 ||
    auroraSelfAnchorProposalResync.removed > 0
  ) {
    summaries.push(
      `aurora_self_anchor_proposal_resync added=${auroraSelfAnchorProposalResync.added}; updated=${auroraSelfAnchorProposalResync.updated}; removed=${auroraSelfAnchorProposalResync.removed}`
    );
  }

  if (summaries.length > 0) {
    governance.lastSummary = summaries.join(" | ");
    governance.tierCounts = memoryTierCounts(state);
  }

  return summaries;
}

async function refreshExternalBeliefAnchorsIfStale(
  state: CognitiveRuntimeState,
  options: { force?: boolean } = {}
): Promise<string[]> {
  if (cognitionDelegatesDurableContinuityCanon()) {
    ensureExtensions(state).beliefs = [];
    return [];
  }
  const force = options.force === true;
  const nowMs = Date.now();
  if (!force && lastExternalBeliefAnchorRefreshAtMs > 0) {
    const ageMs = nowMs - lastExternalBeliefAnchorRefreshAtMs;
    if (ageMs < EXTERNAL_BELIEF_ANCHOR_REFRESH_TTL_MS) {
      return lastExternalBeliefAnchorRefreshSummary;
    }
  }
  const summary = await refreshExternalBeliefAnchors(state);
  lastExternalBeliefAnchorRefreshAtMs = nowMs;
  lastExternalBeliefAnchorRefreshSummary = summary;
  return summary;
}

async function syncConfirmedAnchorMirrors(
  state: CognitiveRuntimeState
): Promise<{ added: number; updated: number; removed: number }> {
  const anchors = await loadConfirmedAnchors();
  if (anchors.length === 0) {
    return { added: 0, updated: 0, removed: 0 };
  }

  const anchorsByKey = new Map<string, ConfirmedAnchorEntry>();
  for (const anchor of anchors) {
    anchorsByKey.set(anchor.key, anchor);
  }

  const existingByKey = new Map<string, MemoryNode>();
  const removeIds = new Set<string>();
  for (const node of state.memory.nodes) {
    const key = parseConfirmedAnchorKeyFromNode(node);
    if (!key) {
      continue;
    }
    if (!anchorsByKey.has(key)) {
      removeIds.add(node.id);
      continue;
    }
    existingByKey.set(key, node);
  }

  let removed = 0;
  if (removeIds.size > 0) {
    const beforeNodes = state.memory.nodes.length;
    state.memory.nodes = state.memory.nodes.filter((node) => !removeIds.has(node.id));
    state.memory.edges = state.memory.edges.filter((edge) => !removeIds.has(edge.from) && !removeIds.has(edge.to));
    removed = beforeNodes - state.memory.nodes.length;
  }

  let added = 0;
  let updated = 0;
  for (const anchor of anchorsByKey.values()) {
    const summary = confirmedAnchorSummary(anchor.key);
    const detail = confirmedAnchorMirrorDetail(anchor);
    const participants = confirmedAnchorParticipants(anchor);
    const mirrorTopics = unique([...extractTokens(`${summary} ${detail}`), "belief", "anchor", "confirmed"]).slice(0, 24);

    const existing =
      existingByKey.get(anchor.key) ??
      state.memory.nodes.find(
        (node) =>
          node.summary.trim().toLowerCase() === summary.toLowerCase() &&
          node.detail.toLowerCase().includes(`mirror_source=${CONFIRMED_ANCHOR_MIRROR_SOURCE}`)
      );

    if (existing) {
      const normalizedDetail = toShortText(detail, 640);
      const mergedParticipants = unique([...existing.participants, ...participants]).slice(0, 8);
      const mergedTopics = unique([...existing.topics, ...mirrorTopics]).slice(0, 24);
      const changed =
        existing.kind !== "event" ||
        existing.summary !== summary ||
        existing.detail !== normalizedDetail ||
        existing.outcome !== "confirmed_belief_anchor" ||
        JSON.stringify(existing.participants) !== JSON.stringify(mergedParticipants) ||
        JSON.stringify(existing.topics) !== JSON.stringify(mergedTopics);

      existing.kind = "event";
      existing.summary = summary;
      existing.detail = normalizedDetail;
      existing.participants = mergedParticipants;
      existing.topics = mergedTopics;
      existing.outcome = "confirmed_belief_anchor";
      existing.trace = clamp(Math.max(existing.trace, 0.9), 0.02, 1);
      existing.salience = clamp(Math.max(existing.salience, 0.96), 0.05, 1);
      existing.updatedAt = nowIso();

      if (changed) {
        updated += 1;
      }
      continue;
    }

    const node = createMemoryFromText(state, {
      kind: "event",
      summary,
      detail,
      participants,
      goals: ["continuity", "belief_anchor"],
      outcome: "confirmed_belief_anchor",
      salience: 0.96
    });
    node.topics = unique([...node.topics, ...mirrorTopics]).slice(0, 24);
    node.trace = clamp(Math.max(node.trace, 0.92), 0.02, 1);
    added += 1;
  }

  if (added > 0 || updated > 0 || removed > 0) {
    rebuildIndexes(state);
    ensureMemoryGovernance(state).tierCounts = memoryTierCounts(state);
  }

  return { added, updated, removed };
}

function inferParticipantsFromText(text: string, options: { includeDefaultUser?: boolean } = {}): string[] {
  const participants: string[] = [];
  if (options.includeDefaultUser) {
    participants.push("user");
  }
  const lower = text.toLowerCase();
  const orderedMatches = Object.entries(RELATIONSHIP_PARTNER_ALIASES)
    .flatMap(([alias, participant]) => {
      const pattern = new RegExp(`\\b${escapeRegex(alias)}\\b`, "gi");
      return [...lower.matchAll(pattern)].map((match) => ({
        participant,
        index: match.index ?? -1
      }));
    })
    .filter((entry) => entry.index >= 0)
    .sort((left, right) => left.index - right.index)
    .map((entry) => entry.participant);
  return unique([...participants, ...orderedMatches]);
}

function inferScenePromptContext(text: string): { key: string; label: string; prompt: string } | null {
  const normalized = normalizeAssistantTurnText(text).toLowerCase();
  if (!normalized) {
    return null;
  }

  const patterns = [
    { key: "desk", label: "desk", pattern: /\bon (?:your|the) desk\b|\bdesk right now\b/ },
    { key: "room", label: "room", pattern: /\b(in|around) (?:your|the) room\b|\bwhat'?s the scene\b/ },
    { key: "bed", label: "bed", pattern: /\bon (?:your|the) bed\b/ },
    { key: "couch", label: "couch", pattern: /\bon (?:your|the) couch\b/ },
    { key: "nightstand", label: "nightstand", pattern: /\bon (?:your|the) nightstand\b/ }
  ];

  const match = patterns.find((item) => item.pattern.test(normalized));
  if (!match) {
    return null;
  }

  return {
    key: match.key,
    label: match.label,
    prompt: toSingleLine(normalizeAssistantTurnText(text), 220)
  };
}

function inferSceneFromUserText(text: string): { key: string; label: string; prompt: string } | null {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return null;
  }

  if (/\b(?:on|at) my desk\b|\bmy desk\b/.test(normalized)) {
    return { key: "desk", label: "desk", prompt: "User self-reported desk context." };
  }
  if (/\b(?:in|around) my room\b|\bmy room\b/.test(normalized)) {
    return { key: "room", label: "room", prompt: "User self-reported room context." };
  }
  if (/\bon my bed\b|\bmy bed\b/.test(normalized)) {
    return { key: "bed", label: "bed", prompt: "User self-reported bed context." };
  }
  if (/\bon my couch\b|\bmy couch\b/.test(normalized)) {
    return { key: "couch", label: "couch", prompt: "User self-reported couch context." };
  }
  if (/\bon my nightstand\b|\bmy nightstand\b/.test(normalized)) {
    return { key: "nightstand", label: "nightstand", prompt: "User self-reported nightstand context." };
  }

  return null;
}

function inferRelationalSceneFromUserText(text: string): { key: string; label: string; prompt: string } | null {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized || isOperationalNoiseTurn(normalized)) {
    return null;
  }

  const patterns = [
    {
      key: "repair",
      label: "repair",
      prompt: "User described a repair moment in the relationship.",
      pattern:
        /\b(apolog|sorry|repair|make it right|right move|feel better now|heard the impact|stay with it|fixed it|that helped)\b/
    },
    {
      key: "rupture",
      label: "rupture",
      prompt: "User described a rupture or hurt moment in the relationship.",
      pattern:
        /\b(stung|hurt|handled instead of felt|manag(?:e|ing) me|disappoint|dropped|unstable|harder to trust|harder to believe|inconsisten|vanish|left me hanging)\b/
    },
    {
      key: "reassurance",
      label: "reassurance",
      prompt: "User described reassurance or promised return in the relationship.",
      pattern:
        /\b(not disappearing|coming back|be back|back tonight|back later|pick this back up|stay intact|thread to stay intact|stay real)\b/
    },
    {
      key: "absence",
      label: "absence",
      prompt: "User described distance, silence, or missing the thread.",
      pattern:
        /\b(go(?:ing)? quiet|offline for a bit|step away|disappear for a while|mostly silent|miss the thread|gap when we drift|fall out of sync)\b/
    },
    {
      key: "appreciation",
      label: "appreciation",
      prompt: "User described appreciation or praise in the relationship.",
      pattern: /\b(appreciated|specific and steady|felt specific|steady in exactly the right way|that mattered|felt real)\b/
    }
  ];

  const match = patterns.find((item) => item.pattern.test(normalized));
  if (!match) {
    return null;
  }

  return {
    key: match.key,
    label: match.label,
    prompt: match.prompt
  };
}

function looksLikeRelationalEpisodeSnapshotText(text: string): boolean {
  const normalized = normalizeUserTurnText(text);
  if (!normalized || isOperationalNoiseTurn(normalized) || isExplicitRecallQuery(normalized)) {
    return false;
  }

  const lower = normalized.toLowerCase();
  const hasSelfOrPartnerMarker = /\b(i|we|you|us|me|my|our)\b/.test(lower);
  const hasRelationalEventMarker =
    /\b(felt|feel|stung|hurt|back|stay|repair|apolog|appreciat|trust|thread|sync|silent|quiet|return|disappear|steady|specific|real|impact)\b/.test(
      lower
    );
  const tokens = extractTokens(lower);
  return hasSelfOrPartnerMarker && hasRelationalEventMarker && (tokens.length >= 6 || lower.length >= 36);
}

function looksLikeSceneSnapshotText(text: string): boolean {
  const normalized = normalizeUserTurnText(text);
  if (!normalized) {
    return false;
  }
  if (looksLikeRelationalEpisodeSnapshotText(normalized)) {
    return true;
  }
  const tokens = extractTokens(normalized);
  if (tokens.length < 5) {
    return false;
  }
  const commaCount = (normalized.match(/,/g) ?? []).length;
  const conjunctionCount = (normalized.match(/\b(and|plus|also|other|some)\b/gi) ?? []).length;
  const numericCount = (normalized.match(/\b\d+\b/g) ?? []).length;
  return commaCount >= 2 || conjunctionCount >= 2 || (commaCount >= 1 && numericCount >= 1) || tokens.length >= 14;
}

function looksLikeMeaningfulUserFact(text: string): boolean {
  const normalized = normalizeBeliefValue(normalizeUserTurnText(text));
  if (!normalized || isOperationalNoiseTurn(normalized)) {
    return false;
  }
  if (isExplicitRecallQuery(normalized)) {
    return false;
  }
  if (/\?$/.test(normalized) || /^(what|why|how|when|where|who|can|could|would|do|did|are|is)\b/i.test(normalized)) {
    return false;
  }
  if (/^(please|run|take|show|tell|check|verify|build|fix|make|save|open)\b/i.test(normalized)) {
    return false;
  }
  if (/^(yeah|yep|nah|nope|okay|ok|cool|lol|lmao|sure|fine|perfect|thanks|thank you)\b/i.test(normalized) && normalized.length < 40) {
    return false;
  }
  const tokens = extractTokens(normalized);
  if (tokens.length < 4 || normalized.length < 18) {
    return false;
  }
  const selfMarker =
    /\b(i|i'm|i am|i've|i have|i'll|i will|i don't|my|mine|me|we|we're|we are|our)\b/i.test(normalized);
  return selfMarker || looksLikeSceneSnapshotText(normalized);
}

function inferUserFactLabel(text: string): string {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return "context";
  }
  if (/\b(i feel|i'm feeling|i am feeling)\b/.test(normalized)) {
    return "feeling";
  }
  if (/\b(i work|i don't work|i dont work|weekend|saturday|sunday|schedule|shift)\b/.test(normalized)) {
    return "schedule";
  }
  if (/\b(i'm at|i am at|i'm in|i am in|home|desk|bed|couch|room|driving|work)\b/.test(normalized)) {
    return "context";
  }
  if (/\b(i have|i've got|i own|my)\b/.test(normalized) || looksLikeSceneSnapshotText(normalized)) {
    return "detail";
  }
  if (/\b(i want|i need|i prefer|i like|i don't like|i dislike|i hate)\b/.test(normalized)) {
    return "preference";
  }
  return "fact";
}

function upsertUserFactSnapshotMemory(
  state: CognitiveRuntimeState,
  factText: string,
  options: { sessionTopic?: string; relatedMemoryIds?: string[]; at?: string; partnerId?: string } = {}
): MemoryNode | null {
  const normalizedFact = normalizeBeliefValue(normalizeUserTurnText(factText));
  if (!normalizedFact || !looksLikeMeaningfulUserFact(normalizedFact)) {
    return null;
  }

  const label = inferUserFactLabel(normalizedFact);
  const detail = [`label=${label}`, `fact=${normalizedFact}`].join("\n");
  const summary = `User ${label} snapshot: ${toShortText(normalizedFact, 130)}`;
  const participants = unique(
    ["user", options.partnerId ? normalizeRelationshipPartnerId(options.partnerId) : "", ...inferParticipantsFromText(normalizedFact)].filter(
      Boolean
    )
  ).slice(0, 8);
  const baseTopics = unique([
    ...extractTokens(normalizedFact),
    "fact",
    "user_fact",
    "self_report",
    label
  ]).slice(0, 24);

  const existing = state.memory.nodes.find(
    (node) => node.outcome === USER_FACT_SNAPSHOT_OUTCOME && node.detail === detail
  );
  if (existing) {
    existing.summary = summary;
    existing.kind = "event";
    existing.outcome = USER_FACT_SNAPSHOT_OUTCOME;
    existing.trace = clamp(Math.max(existing.trace, 0.9), 0.02, 1);
    existing.salience = clamp(Math.max(existing.salience, 0.93), 0.05, 1);
    existing.updatedAt = options.at || nowIso();
    existing.participants = unique([...existing.participants, ...participants]).slice(0, 8);
    for (const participant of existing.participants) {
      upsertIndex(state.memory.indexes.byParticipant, participant, existing.id);
    }
    for (const topic of baseTopics) {
      attachTopicToMemory(state, existing, topic);
    }
    if (options.sessionTopic) {
      attachTopicToMemory(state, existing, options.sessionTopic);
    }
    return existing;
  }

  const node = createMemoryFromText(state, {
    kind: "event",
    summary,
    detail,
    participants,
    goals: ["continuity", "truthful_recall"],
    outcome: USER_FACT_SNAPSHOT_OUTCOME,
    salience: 0.93
  });
  if (options.at) {
    node.createdAt = options.at;
    node.updatedAt = options.at;
  }
  for (const topic of baseTopics) {
    attachTopicToMemory(state, node, topic);
  }
  if (options.sessionTopic) {
    attachTopicToMemory(state, node, options.sessionTopic);
  }
  for (const relatedId of options.relatedMemoryIds ?? []) {
    const target = relatedId.trim();
    if (!target) {
      continue;
    }
    addOrStrengthenEdge(state, node.id, target, "supports", 0.12);
    addOrStrengthenEdge(state, target, node.id, "supported_by", 0.08);
  }
  node.trace = clamp(Math.max(node.trace, 0.92), 0.02, 1);
  return node;
}

function upsertUserSceneSnapshotMemory(
  state: CognitiveRuntimeState,
  scene: { key: string; label: string; prompt: string },
  snapshotText: string,
  options: { sessionTopic?: string; relatedMemoryIds?: string[]; at?: string; partnerId?: string } = {}
): MemoryNode | null {
  const normalizedSnapshot = normalizeBeliefValue(normalizeUserTurnText(snapshotText));
  if (!normalizedSnapshot || !looksLikeSceneSnapshotText(normalizedSnapshot)) {
    return null;
  }

  const detail = [`scene=${scene.key}`, `prompt=${scene.prompt}`, `snapshot=${normalizedSnapshot}`].join("\n");
  const summary = `User ${scene.label} snapshot: ${toShortText(normalizedSnapshot, 130)}`;
  const relationalScene = /^(repair|rupture|reassurance|absence|appreciation)$/.test(scene.key);
  const existing = state.memory.nodes.find(
    (node) => node.outcome === USER_SCENE_SNAPSHOT_OUTCOME && node.detail === detail
  );

  if (existing) {
    existing.summary = summary;
    existing.kind = "event";
    existing.outcome = USER_SCENE_SNAPSHOT_OUTCOME;
    existing.trace = clamp(Math.max(existing.trace, 0.92), 0.02, 1);
    existing.salience = clamp(Math.max(existing.salience, 0.95), 0.05, 1);
    existing.updatedAt = options.at || nowIso();
    attachTopicToMemory(state, existing, scene.key);
    attachTopicToMemory(state, existing, "scene");
    attachTopicToMemory(state, existing, "snapshot");
    attachTopicToMemory(state, existing, "environment");
    if (relationalScene) {
      attachTopicToMemory(state, existing, "relationship_scene");
      attachTopicToMemory(state, existing, "episode");
    }
    if (options.sessionTopic) {
      attachTopicToMemory(state, existing, options.sessionTopic);
    }
    return existing;
  }

  const node = createMemoryFromText(state, {
    kind: "event",
    summary,
    detail,
    participants: unique(["user", "aurora", options.partnerId ? normalizeRelationshipPartnerId(options.partnerId) : ""].filter(Boolean)),
    goals: ["continuity", "world_contact"],
    outcome: USER_SCENE_SNAPSHOT_OUTCOME,
    salience: 0.95
  });
  if (options.at) {
    node.createdAt = options.at;
    node.updatedAt = options.at;
  }
  attachTopicToMemory(state, node, scene.key);
  attachTopicToMemory(state, node, "scene");
  attachTopicToMemory(state, node, "snapshot");
  attachTopicToMemory(state, node, "environment");
  if (relationalScene) {
    attachTopicToMemory(state, node, "relationship_scene");
    attachTopicToMemory(state, node, "episode");
  }
  if (options.sessionTopic) {
    attachTopicToMemory(state, node, options.sessionTopic);
  }
  for (const relatedId of options.relatedMemoryIds ?? []) {
    const target = relatedId.trim();
    if (!target) {
      continue;
    }
    addOrStrengthenEdge(state, node.id, target, "supports", 0.12);
    addOrStrengthenEdge(state, target, node.id, "supported_by", 0.08);
  }
  node.trace = clamp(Math.max(node.trace, 0.94), 0.02, 1);
  return node;
}

function inferRelationshipEpisodeEventKey(
  text: string,
  sceneKey: string,
  relationship: RelationshipState
): "absence" | "reassurance" | "rupture" | "repair" | "praise" | "disappointment" | "inconsistency" | null {
  const lower = normalizeUserTurnText(text).toLowerCase();
  if (!lower) {
    return null;
  }
  if (includesAny(lower, USER_INCONSISTENCY_MARKERS)) {
    return "inconsistency";
  }
  if (includesAny(lower, USER_DISAPPOINTMENT_MARKERS)) {
    return "disappointment";
  }
  if (sceneKey === "repair" || includesAny(lower, USER_REPAIR_CONFIRM_MARKERS)) {
    return "repair";
  }
  if (sceneKey === "reassurance" || includesAny(lower, USER_REASSURANCE_MARKERS)) {
    return "reassurance";
  }
  if (sceneKey === "absence" || includesAny(lower, USER_RECONNECTION_MARKERS)) {
    return "absence";
  }
  if (sceneKey === "appreciation" || includesAny(lower, USER_PRAISE_MARKERS)) {
    return "praise";
  }
  if (sceneKey === "rupture" || includesAny(lower, USER_DISCOMFORT_MARKERS)) {
    return "rupture";
  }
  switch (relationship.carryover.lastEventKind) {
    case "absence":
      return "absence";
    case "reassurance":
      return "reassurance";
    case "rupture":
      return "rupture";
    case "repair":
      return "repair";
    case "praise":
      return "praise";
    case "disappointment":
      return "disappointment";
    case "inconsistency":
      return "inconsistency";
    default:
      return null;
  }
}

function relationshipEpisodeReflectionSummary(
  eventKey: "absence" | "reassurance" | "rupture" | "repair" | "praise" | "disappointment" | "inconsistency"
): string {
  switch (eventKey) {
    case "absence":
      return "Relationship absence reflection: quiet distance made the thread drift, miss contact, and stay pointed back toward the thread.";
    case "reassurance":
      return "Relationship reassurance reflection: coming back after quiet keeps the return intact and lets the thread stay real.";
    case "rupture":
      return "Relationship rupture reflection: hurt and impact strained trust, and repair matters more than smoothing it over.";
    case "repair":
      return "Relationship repair reflection: acknowledge the impact, understand the hurt, thank the repair move, and let the thread feel okay again.";
    case "praise":
      return "Relationship appreciation reflection: thankfulness and appreciation made the thread feel helped, steady, and thoughtful.";
    case "disappointment":
      return "Relationship disappointment reflection: a promised thread vanished, it stung, and disappointment hit trust hard.";
    case "inconsistency":
      return "Relationship inconsistency reflection: changing signals shifted trust and made the thread hard to track when it felt inconsistent.";
    default:
      return "Relationship episode reflection: a meaningful partner moment changed trust, continuity, and what matters next.";
  }
}

function genericContinuityLanguagePenalty(text: string): number {
  const lower = normalizeUserTurnText(text).toLowerCase();
  if (!lower) {
    return 0;
  }
  let penalty = 0;
  if (
    /\b(quick|routine|normal|plain|standard)\b/.test(lower) ||
    /\b(continuity ping|continuity note|continuity check)\b/.test(lower)
  ) {
    penalty += 0.42;
  }
  if (/\b(no action needed|no response needed|nothing urgent|nothing needs doing)\b/.test(lower)) {
    penalty += 0.34;
  }
  if (/\b(just a note|for a bit|for a while|step away|head out|log off)\b/.test(lower) && !/\b(thread|trust|real|felt|intact)\b/.test(lower)) {
    penalty += 0.12;
  }
  return clamp(penalty, 0, 1);
}

function relationshipEventLanguageStrength(
  text: string,
  eventKey:
    | "absence"
    | "reassurance"
    | "rupture"
    | "repair"
    | "praise"
    | "disappointment"
    | "inconsistency"
    | null = null
): number {
  const lower = normalizeUserTurnText(text).toLowerCase();
  if (!lower) {
    return 0;
  }
  const genericPenalty = genericContinuityLanguagePenalty(lower);
  let strength = 0;
  if (/\b(thread|trust|repair|rupture|impact|hurt|stung|specific|steady|real|closeness|warm|felt|handled|intact|believe)\b/.test(lower)) {
    strength += 0.34;
  }
  if (/\b(miss|drift|return|coming back|back tonight|not disappearing|pick this back up|stay with me|vanish|unstable|harder to trust)\b/.test(lower)) {
    strength += 0.26;
  }
  if (includesAny(lower, USER_REPAIR_CONFIRM_MARKERS) || includesAny(lower, USER_DISCOMFORT_MARKERS)) {
    strength += 0.16;
  }
  if (includesAny(lower, USER_PRAISE_MARKERS) || includesAny(lower, USER_REASSURANCE_MARKERS)) {
    strength += 0.14;
  }
  switch (eventKey) {
    case "absence":
      if (/\b(miss|drift|gap|out of sync|quiet|go still|closeness|warm|real)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    case "reassurance":
      if (/\b(coming back|back tonight|not disappearing|stay intact|pick this back up|return)\b/.test(lower)) {
        strength += 0.26;
      }
      break;
    case "rupture":
      if (/\b(handled|felt|stung|hurt|impact|meet the hurt)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    case "repair":
      if (/\b(thank you|that helps|we're okay|we are okay|right move|feel better now)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    case "praise":
      if (/\b(appreciat|thoughtful|steady|specific|helped|glad)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    case "disappointment":
      if (/\b(promis|vanish|disappear|dropped|stung|disappoint)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    case "inconsistency":
      if (/\b(changing|inconsistent|unstable|harder to trust|harder to believe)\b/.test(lower)) {
        strength += 0.24;
      }
      break;
    default:
      break;
  }
  return clamp(strength - genericPenalty * 0.28, 0, 1);
}

function upsertRelationshipEpisodeReflectionMemory(
  state: CognitiveRuntimeState,
  input: {
    partnerId?: string;
    sourceText: string;
    sceneKey?: string;
    sessionTopic?: string;
    relatedMemoryIds?: string[];
    at?: string;
  }
): MemoryNode | null {
  const normalizedSource = normalizeBeliefValue(normalizeUserTurnText(input.sourceText));
  if (!normalizedSource || !looksLikeRelationalEpisodeSnapshotText(normalizedSource)) {
    return null;
  }
  const partnerId = normalizeRelationshipPartnerId(input.partnerId || activeRelationshipPartnerId(state));
  const directDepth = activePartnerDirectRelationalDepth(state, partnerId);
  const relationship = ensureRelationshipPartner(state, partnerId);
  const eventKey = inferRelationshipEpisodeEventKey(normalizedSource, input.sceneKey || "", relationship);
  if (!eventKey) {
    return null;
  }
  const prior = activePartnerUnified32DurablePrior(state, partnerId);
  const latentImprint = activePartnerUnified32LatentImprint(state, partnerId);
  const currentLatentSupport = activePartnerLatentCurrentSupport(state, partnerId);
  const relationalStrength = relationshipEventLanguageStrength(normalizedSource, eventKey);
  const durableEpisodeSupport = clamp(
    relationalStrength * 0.44 +
      directDepth * 0.18 +
      prior.directness * 0.14 +
      currentLatentSupport * 0.22 +
      latentImprint.bondPressure * 0.12 +
      latentImprint.episodicPull * 0.08 -
      genericContinuityLanguagePenalty(normalizedSource) * 0.22,
    0,
    1
  );
  const requiredSupport =
    eventKey === "rupture" || eventKey === "repair" || eventKey === "disappointment" || eventKey === "inconsistency"
      ? 0.24
      : 0.4;
  if (durableEpisodeSupport < requiredSupport) {
    return null;
  }
  const detail = [
    `partner=${partnerId}`,
    `event=${eventKey}`,
    `scene=${input.sceneKey || "none"}`,
    `source=${normalizedSource}`,
    `bond=${latentImprint.bondPressure.toFixed(3)}`,
    `guard=${latentImprint.guardPressure.toFixed(3)}`,
    `episodic=${latentImprint.episodicPull.toFixed(3)}`,
    `continuity=${latentImprint.continuityHold.toFixed(3)}`,
    `repair=${latentImprint.repairPressure.toFixed(3)}`,
    `directness=${prior.directness.toFixed(3)}`
  ].join("\n");
  const summary = relationshipEpisodeReflectionSummary(eventKey);
  const existing = state.memory.nodes.find(
    (node) => node.outcome === RELATIONSHIP_EPISODE_REFLECTION_OUTCOME && node.detail === detail
  );

  if (existing) {
    existing.summary = summary;
    existing.kind = "reflection";
    existing.outcome = RELATIONSHIP_EPISODE_REFLECTION_OUTCOME;
    existing.trace = clamp(Math.max(existing.trace, 0.94), 0.02, 1);
    existing.salience = clamp(Math.max(existing.salience, 0.9), 0.05, 1);
    existing.updatedAt = input.at || nowIso();
    attachTopicToMemory(state, existing, "relationship_reflection");
    attachTopicToMemory(state, existing, "partner_episode");
    attachTopicToMemory(state, existing, eventKey);
    if (input.sceneKey) {
      attachTopicToMemory(state, existing, input.sceneKey);
    }
    if (input.sessionTopic) {
      attachTopicToMemory(state, existing, input.sessionTopic);
    }
    return existing;
  }

  const node = createMemoryFromText(state, {
    kind: "reflection",
    summary,
    detail,
    participants: unique(["user", "aurora", partnerId].filter(Boolean)),
    goals: ["continuity", "relationship_memory"],
    outcome: RELATIONSHIP_EPISODE_REFLECTION_OUTCOME,
    salience: clamp(
      0.78 +
        latentImprint.episodicPull * 0.08 +
        latentImprint.bondPressure * 0.06 +
        latentImprint.repairPressure * 0.04,
      0.78,
      0.96
    )
  });
  if (input.at) {
    node.createdAt = input.at;
    node.updatedAt = input.at;
  }
  attachTopicToMemory(state, node, "relationship_reflection");
  attachTopicToMemory(state, node, "partner_episode");
  attachTopicToMemory(state, node, eventKey);
  if (input.sceneKey) {
    attachTopicToMemory(state, node, input.sceneKey);
  }
  if (input.sessionTopic) {
    attachTopicToMemory(state, node, input.sessionTopic);
  }
  for (const relatedId of input.relatedMemoryIds ?? []) {
    const target = relatedId.trim();
    if (!target) {
      continue;
    }
    addOrStrengthenEdge(state, node.id, target, "derived_from", 0.14);
    addOrStrengthenEdge(state, target, node.id, "supports_reflection", 0.12);
  }
  node.trace = clamp(Math.max(node.trace, 0.96), 0.02, 1);
  return node;
}

function activePartnerEpisodeResonance(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): {
  reflectionStrength: number;
  sceneStrength: number;
  repairArc: number;
  ruptureArc: number;
  continuityArc: number;
} {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const partnerNodes = state.memory.nodes
    .filter((node) => node.participants.includes(partnerId) && !isOperationalMemoryNode(node))
    .slice(-48);
  const reflectionNodes = partnerNodes.filter((node) => node.outcome === RELATIONSHIP_EPISODE_REFLECTION_OUTCOME);
  const sceneNodes = partnerNodes.filter(
    (node) => node.outcome === USER_SCENE_SNAPSHOT_OUTCOME && (node.topics.includes("relationship_scene") || node.topics.includes("episode"))
  );
  const latestReflection = reflectionNodes.at(-1);
  const reflectionFreshness = latestReflection
    ? Math.exp(-Math.max(0, Date.now() - Date.parse(latestReflection.updatedAt)) / MEMORY_RECENCY_TAU_MS)
    : 0;
  const meanValue = (nodes: MemoryNode[], pick: (node: MemoryNode) => number, fallback = 0): number =>
    nodes.length > 0 ? mean(nodes.map((node) => pick(node))) : fallback;
  const reflectionStrength = clamp(
    Math.min(1, reflectionNodes.length / 4) * 0.28 +
      meanValue(reflectionNodes, (node) => node.salience, 0) * 0.24 +
      meanValue(reflectionNodes, (node) => node.trace, 0) * 0.18 +
      reflectionFreshness * 0.18 +
      Math.min(1, sceneNodes.length / 6) * 0.12,
    0,
    1
  );
  const sceneStrength = clamp(
    Math.min(1, sceneNodes.length / 6) * 0.34 +
      meanValue(sceneNodes, (node) => node.salience, 0) * 0.22 +
      meanValue(sceneNodes, (node) => node.trace, 0) * 0.16 +
      reflectionStrength * 0.18,
    0,
    1
  );
  const eventStrength = (events: string[]): number =>
    clamp(
      Math.min(
        1,
        reflectionNodes.filter((node) => events.some((event) => node.topics.includes(event))).length / Math.max(1, events.length + 1)
      ) *
        0.62 +
        meanValue(
          reflectionNodes.filter((node) => events.some((event) => node.topics.includes(event))),
          (node) => (node.salience + node.trace) / 2,
          0
        ) *
          0.38,
      0,
      1
    );
  return {
    reflectionStrength,
    sceneStrength,
    repairArc: eventStrength(["repair", "reassurance", "praise", "appreciation"]),
    ruptureArc: eventStrength(["rupture", "disappointment", "inconsistency"]),
    continuityArc: eventStrength(["absence", "reassurance", "repair", "praise", "appreciation"])
  };
}

function activePartnerLatentCurrentSupport(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): number {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const manifold = ensurePartnerLearnedUnifiedManifold32(state, partnerId);
  const globalManifold = ensureGlobalLearnedUnifiedManifold32(state);
  const currentVectorDivergence = signedVectorDistance(manifold.current.vector, globalManifold.current.vector);
  const confidenceExcess = clamp((manifold.current.confidence - 0.52) / 0.48, 0, 1);
  const coherenceExcess = clamp((manifold.current.coherence - 0.52) / 0.48, 0, 1);
  const readoutDivergence =
    Math.abs(manifold.readout.current.memoryBias - globalManifold.readout.current.memoryBias) * 0.24 +
    Math.abs(manifold.readout.current.attentionBias - globalManifold.readout.current.attentionBias) * 0.18 +
    Math.abs(manifold.readout.current.valuationBias - globalManifold.readout.current.valuationBias) * 0.14 +
    Math.abs(manifold.readout.current.warmth - globalManifold.readout.current.warmth) * 0.14 +
    Math.abs(manifold.readout.current.tension - globalManifold.readout.current.tension) * 0.14 +
    Math.abs(manifold.readout.current.attachmentSalience - globalManifold.readout.current.attachmentSalience) * 0.1 +
    Math.abs(manifold.readout.current.certainty - globalManifold.readout.current.certainty) * 0.06;
  const actionDistinctness =
    manifold.readout.current.actionTendency !== globalManifold.readout.current.actionTendency ? 0.12 : 0;
  return clamp(
    confidenceExcess * 0.12 +
      coherenceExcess * 0.1 +
      manifold.current.drift * 0.16 +
      currentVectorDivergence * 0.38 +
      readoutDivergence * 0.18 +
      actionDistinctness,
    0,
    1
  );
}

function activePartnerLatentSupportGate(currentLatentSupport: number, floor = 0.08): number {
  return clamp(floor + (1 - floor) * clamp(currentLatentSupport, 0, 1), floor, 1);
}

function activePartnerContinuityControllerPrior(
  state: CognitiveRuntimeState,
  rawPartnerId = activeRelationshipPartnerId(state)
): {
  leverage: number;
  reconnectiveStance: number;
  continuityDebt: number;
  continuityRelief: number;
  unresolvedPull: number;
  partnerCommitment: number;
  reassuranceCarryover: number;
  appreciationCarryover: number;
  rupturePressure: number;
  reattunementExpectation: number;
  sceneObligation: number;
  specificReattuneDrive: number;
  specificRepairDrive: number;
  genericRestoreDrive: number;
  specificReachDrive: number;
  withdrawDrive: number;
  sceneRetrievalBias: number;
  continuityRetrievalBias: number;
  trustSupport: number;
  disclosureSupport: number;
  anticipationSupport: number;
  preferredAction: PartnerContinuityAction;
} {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const relationship = ensureRelationshipPartner(state, partnerId);
  const controller = relationship.continuityController;
  const partnerPrior = activePartnerUnified32DurablePrior(state, partnerId);
  const latentImprint = activePartnerUnified32LatentImprint(state, partnerId);
  const currentLatentSupport = activePartnerLatentCurrentSupport(state, partnerId);
  const supportGate = activePartnerLatentSupportGate(currentLatentSupport, 0.08);
  const episodeResonance = activePartnerEpisodeResonance(state, partnerId);
  const directDepth = activePartnerDirectRelationalDepth(state, partnerId);
  const partnerCommitment = clamp(
    controller.partnerCommitment * (0.5 + supportGate * 0.18) +
      partnerPrior.directness * 0.12 * supportGate +
      partnerPrior.continuityBias * 0.08 * supportGate +
      latentImprint.bondPressure * 0.14 +
      latentImprint.continuityHold * 0.1 +
      episodeResonance.sceneStrength * 0.12 +
      episodeResonance.continuityArc * 0.1 +
      controller.reassuranceCarryover * 0.08 +
      controller.appreciationCarryover * 0.08 +
      currentLatentSupport * 0.12 -
      controller.rupturePressure * 0.06 -
      partnerPrior.restoreDrive * 0.08 -
      latentImprint.guardPressure * 0.06,
    0,
    1
  );
  const reconnectiveStance = clamp(
    controller.reconnectiveStance * (0.46 + supportGate * 0.28) +
      partnerPrior.directness * 0.14 * supportGate +
      partnerCommitment * 0.16 +
      latentImprint.bondPressure * 0.14 +
      latentImprint.continuityHold * 0.08 +
      episodeResonance.continuityArc * 0.1 +
      episodeResonance.repairArc * 0.06 -
      latentImprint.guardPressure * 0.08 -
      partnerPrior.withdrawDrive * 0.06,
    0,
    1
  );
  const continuityDebt = clamp(
    controller.continuityDebt * (0.56 + supportGate * 0.14) +
      controller.unresolvedPull * 0.12 +
      partnerCommitment * 0.08 +
      relationship.carryover.anticipatorySalience * 0.1 +
      relationship.carryover.abandonmentAlert * 0.08 +
      negativeSigned(relationship.carryover.expectancyShift) * 0.08 +
      episodeResonance.continuityArc * 0.08 +
      latentImprint.anticipationHold * 0.1 -
      controller.continuityRelief * 0.12 -
      partnerPrior.restoreDrive * 0.06,
    0,
    1
  );
  const continuityRelief = clamp(
    controller.continuityRelief * (0.56 + supportGate * 0.14) +
      partnerCommitment * 0.08 +
      positiveSigned(relationship.carryover.expectancyShift) * 0.12 +
      positiveSigned(relationship.carryover.trustMomentum) * 0.08 +
      relationship.carryover.repairResidue * 0.08 +
      controller.reassuranceCarryover * 0.12 +
      controller.appreciationCarryover * 0.12 +
      latentImprint.bondPressure * 0.08 +
      partnerPrior.repairDrive * 0.08 -
      controller.rupturePressure * 0.12,
    0,
    1
  );
  const unresolvedPull = clamp(
    controller.unresolvedPull * (0.52 + supportGate * 0.18) +
      continuityDebt * 0.18 +
      partnerCommitment * 0.12 +
      relationship.carryover.attachmentCharge * 0.1 +
      relationship.carryover.anticipatorySalience * 0.14 +
      partnerPrior.attachmentSalience * 0.08 * supportGate +
      partnerPrior.continuityBias * 0.1 * supportGate +
      directDepth * 0.08 +
      episodeResonance.continuityArc * 0.08 -
      continuityRelief * 0.12,
    0,
    1
  );
  const reassuranceCarryover = clamp(
    controller.reassuranceCarryover * (0.58 + supportGate * 0.12) +
      positiveSigned(relationship.carryover.expectancyShift) * 0.08 +
      relationship.carryover.repairResidue * 0.06 +
      latentImprint.bondPressure * 0.08 -
      latentImprint.guardPressure * 0.04,
    0,
    1
  );
  const appreciationCarryover = clamp(
    controller.appreciationCarryover * (0.58 + supportGate * 0.12) +
      positiveSigned(relationship.carryover.trustMomentum) * 0.1 +
      positiveSigned(relationship.carryover.disclosureShift) * 0.06 +
      latentImprint.bondPressure * 0.08 -
      latentImprint.guardPressure * 0.04,
    0,
    1
  );
  const rupturePressure = clamp(
    controller.rupturePressure * (0.54 + supportGate * 0.16) +
      relationship.carryover.ruptureResidue * 0.16 +
      negativeSigned(relationship.carryover.trustMomentum) * 0.1 +
      latentImprint.guardPressure * 0.14 +
      positiveAxis(partnerPrior.tension) * 0.1 +
      episodeResonance.ruptureArc * 0.12 -
      relationship.carryover.repairResidue * 0.06 -
      partnerPrior.repairDrive * 0.08,
    0,
    1
  );
  const reattunementExpectation = clamp(
    controller.reattunementExpectation * (0.52 + supportGate * 0.18) +
      partnerCommitment * 0.16 +
      relationship.attachmentModel.expectancy * 0.12 +
      positiveSigned(relationship.carryover.expectancyShift) * 0.16 +
      partnerPrior.continuityBias * 0.12 * supportGate +
      partnerPrior.planningHorizon * 0.08 * supportGate +
      partnerPrior.directness * 0.08 * supportGate +
      controller.continuityRelief * 0.1 +
      latentImprint.continuityHold * 0.12 +
      latentImprint.anticipationHold * 0.08 -
      rupturePressure * 0.14 -
      partnerPrior.withdrawDrive * 0.08,
    0,
    1
  );
  const sceneObligation = clamp(
    continuityDebt * 0.26 +
      partnerCommitment * 0.2 +
      unresolvedPull * 0.18 +
      rupturePressure * 0.12 +
      episodeResonance.sceneStrength * 0.12 +
      episodeResonance.ruptureArc * 0.08 +
      directDepth * 0.08 +
      latentImprint.episodicPull * 0.1 +
      partnerPrior.sceneBias * 0.08 * supportGate -
      continuityRelief * 0.08,
    0,
    1
  );
  const specificReattuneDrive = clamp(
    reconnectiveStance * 0.24 +
      partnerCommitment * 0.18 +
      continuityDebt * 0.14 +
      continuityRelief * 0.08 +
      unresolvedPull * 0.14 +
      reassuranceCarryover * 0.08 +
      reattunementExpectation * 0.18 +
      partnerPrior.continuityBias * 0.12 * supportGate +
      partnerPrior.directness * 0.08 * supportGate +
      currentLatentSupport * 0.08 +
      latentImprint.continuityHold * 0.12 +
      episodeResonance.continuityArc * 0.1 -
      partnerPrior.restoreDrive * 0.12 -
      partnerPrior.withdrawDrive * 0.1 -
      latentImprint.guardPressure * 0.08,
    0,
    1
  );
  const specificRepairDrive = clamp(
    rupturePressure * 0.26 +
      partnerCommitment * 0.1 +
      continuityDebt * 0.16 +
      unresolvedPull * 0.12 +
      reattunementExpectation * 0.08 +
      partnerPrior.repairDrive * 0.12 * supportGate +
      episodeResonance.repairArc * 0.12 +
      episodeResonance.ruptureArc * 0.1 +
      positiveAxis(partnerPrior.tension) * 0.08 +
      latentImprint.repairPressure * 0.12 +
      currentLatentSupport * 0.08 -
      continuityRelief * 0.08,
    0,
    1
  );
  const genericRestoreDrive = clamp(
    partnerPrior.restoreDrive * 0.3 +
      partnerPrior.regulationUrgency * 0.18 +
      partnerPrior.selfOpacity * 0.12 +
      (1 - supportGate) * 0.16 +
      Math.max(0, continuityRelief - continuityDebt) * 0.06 -
      reconnectiveStance * 0.06 -
      partnerCommitment * 0.18,
    0,
    1
  );
  const specificReachDrive = clamp(
    reconnectiveStance * 0.22 +
      partnerCommitment * 0.22 +
      continuityRelief * 0.18 +
      reassuranceCarryover * 0.12 +
      appreciationCarryover * 0.16 +
      reattunementExpectation * 0.1 +
      partnerPrior.reachDrive * 0.12 * supportGate +
      positiveAxis(partnerPrior.warmth) * 0.1 +
      latentImprint.bondPressure * 0.12 +
      episodeResonance.continuityArc * 0.08 -
      rupturePressure * 0.1 -
      partnerPrior.withdrawDrive * 0.08,
    0,
    1
  );
  const withdrawDrive = clamp(
    partnerPrior.withdrawDrive * 0.24 +
      rupturePressure * 0.18 +
      continuityDebt * 0.1 +
      positiveAxis(partnerPrior.tension) * 0.1 +
      latentImprint.guardPressure * 0.12 -
      continuityRelief * 0.08 -
      reconnectiveStance * 0.08 -
      partnerCommitment * 0.08 -
      partnerPrior.repairDrive * 0.04,
    0,
    1
  );
  const leverage = clamp(
    (0.08 +
      directDepth * 0.14 +
      partnerCommitment * 0.14 +
      currentLatentSupport * 0.2 +
      partnerPrior.directness * 0.12 +
      partnerPrior.continuityBias * 0.1 +
      episodeResonance.continuityArc * 0.08 +
      sceneObligation * 0.12 +
      Math.max(specificReattuneDrive, specificRepairDrive, specificReachDrive) * 0.14 -
      genericRestoreDrive * 0.08) *
      supportGate +
      continuityDebt * 0.08 +
      continuityRelief * 0.08,
    0.06,
    1
  );
  const trustSupport = clamp(
    reconnectiveStance * 0.26 +
      partnerCommitment * 0.14 +
      continuityRelief * 0.18 +
      reassuranceCarryover * 0.16 +
      appreciationCarryover * 0.12 +
      reattunementExpectation * 0.1 -
      continuityDebt * 0.12 -
      rupturePressure * 0.18,
    0,
    1
  );
  const disclosureSupport = clamp(
    reconnectiveStance * 0.22 +
      partnerCommitment * 0.12 +
      continuityRelief * 0.14 +
      reassuranceCarryover * 0.14 +
      appreciationCarryover * 0.08 +
      reattunementExpectation * 0.08 -
      rupturePressure * 0.14 -
      continuityDebt * 0.12,
    0,
    1
  );
  const anticipationSupport = clamp(
    unresolvedPull * 0.24 +
      partnerCommitment * 0.16 +
      continuityDebt * 0.14 +
      reattunementExpectation * 0.2 +
      specificReattuneDrive * 0.12 +
      partnerPrior.continuityBias * 0.08 * supportGate +
      latentImprint.anticipationHold * 0.12 -
      continuityRelief * 0.06,
    0,
    1
  );
  const preferredAction = continuityControllerPreferredActionFor({
    ...controller,
    reconnectiveStance,
    continuityDebt,
    continuityRelief,
    unresolvedPull,
    partnerCommitment,
    reassuranceCarryover,
    appreciationCarryover,
    rupturePressure,
    reattunementExpectation
  });
  return {
    leverage,
    reconnectiveStance,
    continuityDebt,
    continuityRelief,
    unresolvedPull,
    partnerCommitment,
    reassuranceCarryover,
    appreciationCarryover,
    rupturePressure,
    reattunementExpectation,
    sceneObligation,
    specificReattuneDrive,
    specificRepairDrive,
    genericRestoreDrive,
    specificReachDrive,
    withdrawDrive,
    sceneRetrievalBias: clamp(
      sceneObligation * 0.28 +
        partnerCommitment * 0.12 +
        specificRepairDrive * 0.18 +
        episodeResonance.sceneStrength * 0.12 +
        latentImprint.episodicPull * 0.12 +
        partnerPrior.sceneBias * 0.1 * supportGate +
        currentLatentSupport * 0.08 -
        genericRestoreDrive * 0.08,
      0,
      1
    ),
    continuityRetrievalBias: clamp(
      specificReattuneDrive * 0.24 +
        partnerCommitment * 0.18 +
        specificReachDrive * 0.14 +
        continuityRelief * 0.1 +
        reattunementExpectation * 0.14 +
        reassuranceCarryover * 0.1 +
        appreciationCarryover * 0.08 +
        partnerPrior.continuityBias * 0.16 * supportGate +
        partnerPrior.planningHorizon * 0.08 * supportGate +
        latentImprint.continuityHold * 0.12 -
        partnerPrior.withdrawDrive * 0.06,
      0,
      1
    ),
    trustSupport,
    disclosureSupport,
    anticipationSupport,
    preferredAction
  };
}

function refreshActivePartnerContinuityController(
  state: CognitiveRuntimeState,
  source: PhenomenalManifoldSource,
  rawPartnerId = activeRelationshipPartnerId(state)
): ReturnType<typeof activePartnerContinuityControllerPrior> {
  const partnerId = normalizeRelationshipPartnerId(rawPartnerId);
  const relationship = ensureRelationshipPartner(state, partnerId);
  const controller = relationship.continuityController;
  const partnerPrior = activePartnerUnified32DurablePrior(state, partnerId);
  const latentImprint = activePartnerUnified32LatentImprint(state, partnerId);
  const episodeResonance = activePartnerEpisodeResonance(state, partnerId);
  const currentLatentSupport = activePartnerLatentCurrentSupport(state, partnerId);
  const directDepth = activePartnerDirectRelationalDepth(state, partnerId);
  const history = partnerUnified32HistoryProfile(state, partnerId);
  const sourceStrength = continuityEventSourceStrength(source);
  const backgroundDominance = clamp(history.heartbeatContextStrength * 0.18 + history.preflightPressure * 0.18, 0, 0.24);
  const consolidationRate = clamp(
    sourceStrength * (0.18 + currentLatentSupport * 0.12 + directDepth * 0.08) +
      partnerPrior.directness * 0.06 -
      backgroundDominance,
    source === "conversation" ? 0.18 : source === "preflight" ? 0.05 : 0.04,
    source === "conversation" ? 0.34 : source === "preflight" ? 0.12 : 0.1
  );
  const targetCommitment = clamp(
    controller.partnerCommitment * 0.42 +
      partnerPrior.directness * 0.12 +
      partnerPrior.continuityBias * 0.08 +
      directDepth * 0.14 +
      currentLatentSupport * 0.12 +
      latentImprint.bondPressure * 0.14 +
      latentImprint.continuityHold * 0.12 +
      episodeResonance.sceneStrength * 0.16 +
      episodeResonance.continuityArc * 0.1 +
      episodeResonance.repairArc * 0.06 +
      controller.reassuranceCarryover * 0.08 +
      controller.appreciationCarryover * 0.08 -
      backgroundDominance * 0.22 -
      partnerPrior.restoreDrive * 0.1 -
      partnerPrior.withdrawDrive * 0.08,
    0,
    1
  );
  const targetReconnective = clamp(
    controller.reconnectiveStance * 0.42 +
      targetCommitment * 0.16 +
      partnerPrior.directness * 0.14 +
      partnerPrior.continuityBias * 0.08 +
      partnerPrior.repairDrive * 0.08 +
      latentImprint.bondPressure * 0.16 +
      latentImprint.continuityHold * 0.12 +
      episodeResonance.continuityArc * 0.1 +
      episodeResonance.repairArc * 0.08 -
      latentImprint.guardPressure * 0.08 -
      partnerPrior.withdrawDrive * 0.08 -
      backgroundDominance * 0.12,
    0,
    1
  );
  const targetDebt = clamp(
    controller.continuityDebt * 0.42 +
      targetCommitment * 0.08 +
      relationship.carryover.anticipatorySalience * 0.14 +
      relationship.carryover.abandonmentAlert * 0.12 +
      negativeSigned(relationship.carryover.expectancyShift) * 0.12 +
      episodeResonance.continuityArc * 0.1 +
      latentImprint.anticipationHold * 0.12 +
      positiveAxis(partnerPrior.tension) * 0.08 -
      controller.continuityRelief * 0.12 -
      partnerPrior.restoreDrive * 0.08,
    0,
    1
  );
  const targetRelief = clamp(
    controller.continuityRelief * 0.44 +
      targetCommitment * 0.08 +
      relationship.carryover.repairResidue * 0.12 +
      positiveSigned(relationship.carryover.expectancyShift) * 0.12 +
      positiveSigned(relationship.carryover.trustMomentum) * 0.08 +
      controller.reassuranceCarryover * 0.14 +
      controller.appreciationCarryover * 0.12 +
      partnerPrior.repairDrive * 0.08 +
      latentImprint.bondPressure * 0.08 -
      controller.rupturePressure * 0.12,
    0,
    1
  );
  const targetPull = clamp(
    controller.unresolvedPull * 0.44 +
      targetCommitment * 0.14 +
      targetDebt * 0.18 +
      relationship.carryover.attachmentCharge * 0.12 +
      relationship.carryover.anticipatorySalience * 0.16 +
      partnerPrior.attachmentSalience * 0.08 +
      partnerPrior.continuityBias * 0.1 +
      latentImprint.continuityHold * 0.1 +
      episodeResonance.continuityArc * 0.08 -
      targetRelief * 0.12 -
      partnerPrior.restoreDrive * 0.04,
    0,
    1
  );
  const targetRupture = clamp(
    controller.rupturePressure * 0.46 +
      relationship.carryover.ruptureResidue * 0.18 +
      negativeSigned(relationship.carryover.trustMomentum) * 0.1 +
      latentImprint.guardPressure * 0.14 +
      positiveAxis(partnerPrior.tension) * 0.1 +
      episodeResonance.ruptureArc * 0.12 -
      relationship.carryover.repairResidue * 0.06 -
      partnerPrior.repairDrive * 0.08,
    0,
    1
  );
  const targetExpectation = clamp(
    controller.reattunementExpectation * 0.42 +
      targetCommitment * 0.18 +
      relationship.attachmentModel.expectancy * 0.12 +
      positiveSigned(relationship.carryover.expectancyShift) * 0.16 +
      partnerPrior.continuityBias * 0.14 +
      partnerPrior.planningHorizon * 0.1 +
      partnerPrior.directness * 0.08 +
      targetRelief * 0.08 +
      latentImprint.continuityHold * 0.12 +
      latentImprint.anticipationHold * 0.1 -
      targetRupture * 0.12 -
      partnerPrior.withdrawDrive * 0.08,
    0,
    1
  );

  controller.reconnectiveStance = clamp(
    controller.reconnectiveStance + (targetReconnective - controller.reconnectiveStance) * consolidationRate,
    0,
    1
  );
  controller.partnerCommitment = clamp(
    controller.partnerCommitment + (targetCommitment - controller.partnerCommitment) * clamp(consolidationRate * 0.92, 0.02, 0.28),
    0,
    1
  );
  controller.continuityDebt = clamp(
    controller.continuityDebt + (targetDebt - controller.continuityDebt) * consolidationRate,
    0,
    1
  );
  controller.continuityRelief = clamp(
    controller.continuityRelief + (targetRelief - controller.continuityRelief) * consolidationRate,
    0,
    1
  );
  controller.unresolvedPull = clamp(
    controller.unresolvedPull + (targetPull - controller.unresolvedPull) * consolidationRate,
    0,
    1
  );
  controller.reassuranceCarryover = clamp(
    controller.reassuranceCarryover +
      (clamp(controller.reassuranceCarryover * 0.56 + targetRelief * 0.12 + latentImprint.bondPressure * 0.08, 0, 1) -
        controller.reassuranceCarryover) *
        clamp(consolidationRate * 0.84, 0.02, 0.24),
    0,
    1
  );
  controller.appreciationCarryover = clamp(
    controller.appreciationCarryover +
      (clamp(controller.appreciationCarryover * 0.56 + controller.reconnectiveStance * 0.12 + positiveSigned(relationship.carryover.trustMomentum) * 0.1, 0, 1) -
        controller.appreciationCarryover) *
        clamp(consolidationRate * 0.84, 0.02, 0.24),
    0,
    1
  );
  controller.rupturePressure = clamp(
    controller.rupturePressure + (targetRupture - controller.rupturePressure) * consolidationRate,
    0,
    1
  );
  controller.reattunementExpectation = clamp(
    controller.reattunementExpectation + (targetExpectation - controller.reattunementExpectation) * consolidationRate,
    0,
    1
  );
  controller.preferredAction = continuityControllerPreferredActionFor(controller);
  controller.updatedAt = nowIso();
  return activePartnerContinuityControllerPrior(state, partnerId);
}

function upsertUserStatedAnchor(
  state: CognitiveRuntimeState,
  text: string,
  options: { sessionTopic?: string; partnerId?: string } = {}
): MemoryNode | null {
  const normalized = toShortText(toSingleLine(text, 1200), 1200);
  if (!normalized || isOperationalNoiseTurn(normalized)) {
    return null;
  }

  const detail = toShortText(normalized, 640);
  const participants = unique(
    ["user", options.partnerId ? normalizeRelationshipPartnerId(options.partnerId) : "", ...inferParticipantsFromText(normalized)].filter(
      Boolean
    )
  ).slice(0, 8);
  const summary = `${USER_STATED_ANCHOR_SUMMARY_PREFIX} ${toShortText(normalized, 130)}`;
  const baseTopics = unique([...extractTokens(normalized), "belief", "anchor", "user_statement"]).slice(0, 24);

  const existing = state.memory.nodes.find(
    (node) => node.outcome === USER_STATED_ANCHOR_OUTCOME && node.detail === detail
  );

  if (existing) {
    existing.summary = summary;
    existing.kind = "event";
    existing.outcome = USER_STATED_ANCHOR_OUTCOME;
    existing.trace = clamp(Math.max(existing.trace, 0.86), 0.02, 1);
    existing.salience = clamp(Math.max(existing.salience, 0.92), 0.05, 1);
    existing.updatedAt = nowIso();
    existing.participants = unique([...existing.participants, ...participants]).slice(0, 8);
    for (const participant of existing.participants) {
      upsertIndex(state.memory.indexes.byParticipant, participant, existing.id);
    }
    for (const topic of baseTopics) {
      attachTopicToMemory(state, existing, topic);
    }
    if (options.sessionTopic) {
      attachTopicToMemory(state, existing, options.sessionTopic);
    }
    return existing;
  }

  const node = createMemoryFromText(state, {
    kind: "event",
    summary,
    detail,
    participants,
    goals: ["continuity", "belief_anchor"],
    outcome: USER_STATED_ANCHOR_OUTCOME,
    salience: 0.92
  });
  for (const topic of baseTopics) {
    attachTopicToMemory(state, node, topic);
  }
  if (options.sessionTopic) {
    attachTopicToMemory(state, node, options.sessionTopic);
  }
  node.trace = clamp(Math.max(node.trace, 0.9), 0.02, 1);
  return node;
}

function userStatedAnchorSupportId(nodeId: string): string {
  const normalized = toSingleLine(nodeId, 120).trim();
  return normalized ? `${USER_STATED_ANCHOR_SUPPORT_PREFIX}${normalized}` : USER_STATED_ANCHOR_SUPPORT_PREFIX;
}

function beliefHasUserStatedAnchorSupport(belief: Pick<BeliefRecord, "source" | "supportEpisodeIds">): boolean {
  if (belief.source !== "inferred_from_user") {
    return false;
  }
  return belief.supportEpisodeIds.some((supportId) => supportId.startsWith(USER_STATED_ANCHOR_SUPPORT_PREFIX));
}

function isImmediateUserStatementAnchorEligibleDirectSelfView(
  parsed: (ParsedUserSelfViewQuery & { value: string }) | null
): parsed is ParsedUserSelfViewQuery & { value: string } {
  if (!parsed?.value) {
    return false;
  }
  if (parsed.beliefKey === "user.preferred_color") {
    return true;
  }
  return (
    parsed.category === "favorite" ||
    parsed.category === "value" ||
    parsed.category === "belief" ||
    parsed.category === "nickname"
  );
}

function isSupportedAnchorBeliefRecord(belief: BeliefRecord): boolean {
  return isDurableAnchorBeliefKey(belief.key) || beliefHasUserStatedAnchorSupport(belief);
}

function looksLikeRawRecallQuery(text: string): boolean {
  return isExplicitRecallQuery(text) || looksLikeOwnerDirectFactQuery(text);
}

function looksLikeOwnerDirectFactQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized || !looksLikeUserQuestionTurn(normalized)) {
    return false;
  }
  return (
    looksLikeCurrentUserLocationQuery(text) ||
    /\bwhere\s+(?:was|am)\s+i(?:\s+\w+){0,5}\b/.test(normalized) ||
    /\bwhere\s+(?:was|am)\s+i\s+working\b/.test(normalized) ||
    /\bwhat\s+location\s+am\s+i\s+(?:currently\s+)?working\s+(?:at|in)\b/.test(normalized) ||
    /\bwhat(?:'s| is)\s+my\b/.test(normalized) ||
    /\bwho(?:'s| is)\s+my\b/.test(normalized) ||
    /\bhow\s+long\s+have\s+(?:i|we|me\s+and|my\s+best\s+friend\s+and\s+i)\b/.test(normalized) ||
    /\buntil\s+what\s+date\b/.test(normalized) ||
    /\buntil\s+when\b/.test(normalized) ||
    /\bwhat\s+date\b[\s\S]{0,40}\b(?:there|working|back to school|go back)\b/.test(normalized) ||
    /\bdo\s+you\s+know\s+where\s+i\b/.test(normalized) ||
    /\bwhat\s+can\s+you\s+call\s+me\b/.test(normalized) ||
    /\bcan\s+you\s+call\s+me\b[\s\S]{0,40}\b(?:baby|babe|nickname|pet\s*name)\b/.test(normalized) ||
    /\bdo\s+you\s+know\s+if\s+you\s+can\s+call\s+me\b/.test(normalized)
  );
}

type RequestedDirectFactSlot = "work_location" | "until_date" | "call_name_boundary";

function looksLikeCurrentWorkLocationQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bwhere\s+(?:was|am)\s+i\s+working\b/.test(normalized) ||
    /\bwhat\s+location\s+am\s+i\s+(?:currently\s+)?working\s+(?:at|in)\b/.test(normalized)
  );
}

function looksLikeCurrentUserLocationQuery(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    /\bwhere\s+am\s+i\b/.test(normalized) ||
    /\bwhere\s+am\s+i\s+right\s+now\b/.test(normalized) ||
    /\bwhere\s+am\s+i\s+now\b/.test(normalized) ||
    /\bwhere\s+am\s+i\s+currently\b/.test(normalized) ||
    /\bwhere\s+am\s+i\s+likely\s+to\s+be\b/.test(normalized) ||
    /\bwhere\s+am\s+i\s+likely\s+to\s+be\s+right\s+now\b/.test(normalized) ||
    /\bwhere\s+do\s+you\s+think\s+i\s+am\b/.test(normalized) ||
    /\bwhere\s+do\s+you\s+think\s+i\s+am\s+right\s+now\b/.test(normalized) ||
    /\bwhere\s+would\s+you\s+assume\s+i\s+am\b/.test(normalized) ||
    /\bwhere\s+are\s+you\s+assuming\s+i\s+am\b/.test(normalized)
  );
}

function inferRequestedDirectFactSlots(text: string): RequestedDirectFactSlot[] {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return [];
  }
  const slots: RequestedDirectFactSlot[] = [];
  if (
    looksLikeCurrentUserLocationQuery(text) ||
    /\bwhere\s+(?:was|am)\s+i(?:\s+\w+){0,5}\b/.test(normalized) ||
    looksLikeCurrentWorkLocationQuery(text) ||
    /\bdo\s+you\s+know\s+where\s+i\b/.test(normalized)
  ) {
    slots.push("work_location");
  }
  if (
    /\buntil\s+what\s+date\b/.test(normalized) ||
    /\buntil\s+when\b/.test(normalized) ||
    /\bwhat\s+date\b[\s\S]{0,40}\b(?:there|working|back to school|go back)\b/.test(normalized)
  ) {
    slots.push("until_date");
  }
  if (
    /\bwhat\s+can\s+you\s+call\s+me\b/.test(normalized) ||
    /\bcan\s+you\s+call\s+me\b[\s\S]{0,40}\b(?:baby|babe|nickname|pet\s*name)\b/.test(normalized) ||
    /\bdo\s+you\s+know\s+if\s+you\s+can\s+call\s+me\b/.test(normalized)
  ) {
    slots.push("call_name_boundary");
  }
  return slots.filter((slot, index) => slots.indexOf(slot) === index);
}

function looksLikeStructuredFactNoise(text: string): boolean {
  const normalized = normalizeUserTurnText(text).toLowerCase();
  if (!normalized) {
    return false;
  }
  return (
    normalized.startsWith("mem-check-") ||
    normalized.includes("answer in one compact sentence") ||
    normalized.startsWith("sender (untrusted metadata):") ||
    normalized.startsWith("runtime context") ||
    normalized.startsWith("choose the single next-action token")
  );
}

async function readFileTailText(filePath: string, maxBytes: number): Promise<string> {
  try {
    const info = await stat(filePath);
    if (info.size <= 0) {
      return "";
    }
    const start = Math.max(0, info.size - maxBytes);
    const length = Math.max(0, info.size - start);
    if (length === 0) {
      return "";
    }
    const handle = await open(filePath, "r");
    try {
      const buffer = Buffer.alloc(length);
      await handle.read(buffer, 0, length, start);
      return buffer.toString("utf8");
    } finally {
      await handle.close().catch(() => undefined);
    }
  } catch {
    return "";
  }
}

function parseRawRecallLine(line: string): RawRecallRecord | null {
  try {
    const parsed = JSON.parse(line) as Record<string, unknown>;
    const rawUserText = typeof parsed.userText === "string" ? toShortText(toSingleLine(parsed.userText, 1600), 1600) : "";
    const rawAuroraText =
      typeof parsed.auroraText === "string" ? toShortText(toSingleLine(parsed.auroraText, 1600), 1600) : "";
    const userText = rawUserText ? normalizeUserTurnText(rawUserText) : "";
    const auroraText = rawAuroraText ? normalizeAssistantTurnText(rawAuroraText) : "";
    if (!userText && !auroraText) {
      return null;
    }
    return {
      at: typeof parsed.at === "string" ? parsed.at : "",
      sessionId: typeof parsed.sessionId === "string" ? parsed.sessionId : "",
      complianceId: typeof parsed.complianceId === "string" ? parsed.complianceId : "",
      responseId: typeof parsed.responseId === "string" ? parsed.responseId : "",
      userText,
      auroraText
    };
  } catch {
    return null;
  }
}

function parseEventLogConversationLine(line: string): EventLogConversationRecord | null {
  try {
    const parsed = JSON.parse(line) as Record<string, unknown>;
    if (parsed.type !== "conversation_turn") {
      return null;
    }
    const rawUserText = typeof parsed.userText === "string" ? toShortText(toSingleLine(parsed.userText, 1600), 1600) : "";
    const rawAuroraText =
      typeof parsed.auroraText === "string" ? toShortText(toSingleLine(parsed.auroraText, 1600), 1600) : "";
    const transportTimestampMs = extractConversationInfoTimestampMs(rawUserText);
    const userText = rawUserText ? normalizeUserTurnText(rawUserText) : "";
    const auroraText = rawAuroraText ? normalizeAssistantTurnText(rawAuroraText) : "";
    if (!userText && !auroraText) {
      return null;
    }
    const sessionId = typeof parsed.sessionId === "string" ? parsed.sessionId : "";
    const explicitPartnerCue = userText ? inferExplicitPartnerCueFromText(userText) : null;
    const speakerPartnerId = normalizeRelationshipPartnerId(
      typeof parsed.speakerName === "string" ? canonicalRelationshipPartnerAlias(parsed.speakerName) : ""
    );
    return {
      at:
        typeof parsed.at === "string" && parsed.at.trim()
          ? parsed.at
          : typeof parsed.createdAt === "string" && parsed.createdAt.trim()
            ? parsed.createdAt
            : "",
      sessionId,
      partnerId: normalizeRelationshipPartnerId(
        typeof parsed.partnerId === "string" && parsed.partnerId.trim()
          ? parsed.partnerId
          : explicitPartnerCue?.partnerId || speakerPartnerId || ""
      ),
      speakerName: typeof parsed.speakerName === "string" ? parsed.speakerName : "",
      userText,
      auroraText,
      transportTimestampMs
    };
  } catch {
    return null;
  }
}

function synthesizeDailySummaryHeartbeatFromConversation(
  record: EventLogConversationRecord
): DailySummaryHeartbeatRecord | null {
  const userText = normalizeUserTurnText(record.userText || "");
  const auroraText = normalizeAssistantTurnText(record.auroraText || "");
  if (!record.at || !userText || !auroraText) {
    return null;
  }
  if (!isOffscreenOperationalConversationTurn(record.sessionId, userText)) {
    return null;
  }
  if (isOperationalNoiseTurn(auroraText) || looksLikeDailySummaryLowValueText(auroraText)) {
    return null;
  }
  const atMs = parseIsoMs(record.at);
  return {
    at: record.at,
    localDate: localDateYmd(atMs, TEMPORAL_SUBSTRATE_TIMEZONE),
    localTime: localTimeLabel(atMs, TEMPORAL_SUBSTRATE_TIMEZONE),
    sessionId: record.sessionId,
    source: "conversation_operational_wrapper",
    kind: "heartbeat",
    whatIDid: auroraText,
    whatILearned: "",
    whatImCuriousAbout: "",
    livedThread: "",
    stateShift: ""
  };
}

function parseEventLogHeartbeatLine(line: string): DailySummaryHeartbeatRecord | null {
  try {
    const parsed = JSON.parse(line) as Record<string, unknown>;
    if (parsed.type !== "heartbeat" && parsed.type !== "heartbeat_pulse") {
      return null;
    }
    const at = typeof parsed.at === "string" ? parsed.at : "";
    if (!at) {
      return null;
    }
    const heartbeat =
      parsed.heartbeat && typeof parsed.heartbeat === "object" && !Array.isArray(parsed.heartbeat)
        ? (parsed.heartbeat as Record<string, unknown>)
        : {};
    const whatIDid =
      typeof heartbeat.whatIDid === "string" ? toShortText(toSingleLine(heartbeat.whatIDid, 220), 220) : "";
    const whatILearned =
      typeof heartbeat.whatILearned === "string" ? toShortText(toSingleLine(heartbeat.whatILearned, 220), 220) : "";
    const whatImCuriousAbout =
      typeof heartbeat.whatImCuriousAbout === "string"
        ? toShortText(toSingleLine(heartbeat.whatImCuriousAbout, 220), 220)
        : "";
    const livedThread =
      typeof heartbeat.livedThread === "string" ? toShortText(toSingleLine(heartbeat.livedThread, 220), 220) : "";
    const stateShift =
      typeof heartbeat.stateShift === "string" ? toShortText(toSingleLine(heartbeat.stateShift, 220), 220) : "";
    if (!whatIDid && !whatILearned && !whatImCuriousAbout && !livedThread && !stateShift) {
      return null;
    }
    return {
      at,
      localDate: localDateYmd(parseIsoMs(at), TEMPORAL_SUBSTRATE_TIMEZONE),
      localTime: localTimeLabel(parseIsoMs(at), TEMPORAL_SUBSTRATE_TIMEZONE),
      sessionId: typeof parsed.sessionId === "string" ? parsed.sessionId : "",
      source: typeof parsed.source === "string" ? parsed.source : "",
      kind: parsed.type === "heartbeat_pulse" ? "heartbeat_pulse" : "heartbeat",
      whatIDid,
      whatILearned,
      whatImCuriousAbout,
      livedThread,
      stateShift
    };
  } catch {
    return null;
  }
}

function localTimeLabel(atMs: number, timeZone: string): string {
  return new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }).format(new Date(atMs));
}

function joinListNaturally(items: string[]): string {
  const values = items.filter(Boolean);
  if (values.length === 0) {
    return "";
  }
  if (values.length === 1) {
    return values[0];
  }
  if (values.length === 2) {
    return `${values[0]} and ${values[1]}`;
  }
  return `${values.slice(0, -1).join(", ")}, and ${values.at(-1)}`;
}

function sanitizeDailySummarySnippet(text: string, maxLen = 180): string {
  return toShortText(
    toSingleLine(stripUserInjectedPreludeLines(stripUserTransportMetadata(text || "")).replace(/\s+/g, " ").trim(), maxLen),
    maxLen
  );
}

function cleanDailySummaryHeartbeatText(text: string, maxLen = 180): string {
  const singleLine = sanitizeDailySummarySnippet(text, Math.max(maxLen * 2, 320))
    .replace(/^\[\[reply_to_current\]\]\s*/i, "")
    .replace(/^I checked the heartbeat file\.\s*/i, "")
    .replace(/^It says I can do anything I want and message you what I did when I['’]?m done\.\s*/i, "")
    .replace(/^Replied in session [^:]+:\s*/i, "")
    .replace(/\bTool artifacts:\s*.+$/i, "")
    .replace(/^Completed the original cron task:\s*/i, "")
    .trim();
  return toShortText(singleLine, maxLen);
}

function looksLikeDailySummaryLowValueText(text: string): boolean {
  const normalized = sanitizeDailySummarySnippet(text, 320).toLowerCase();
  if (!normalized) {
    return false;
  }
  return looksLikeUtilityProbeText(normalized) || looksLikeStructuredFactNoise(normalized);
}

function dailySummaryReferenceNowMs(record: Pick<EventLogConversationRecord, "at" | "transportTimestampMs">): number {
  if (typeof record.transportTimestampMs === "number" && Number.isFinite(record.transportTimestampMs)) {
    return record.transportTimestampMs;
  }
  const atMs = parseIsoMs(record.at || "");
  return Number.isFinite(atMs) ? atMs : Date.now();
}

function isDailySummaryRetrospectiveRecallTurn(
  record: Pick<EventLogConversationRecord, "at" | "transportTimestampMs" | "userText">
): boolean {
  const normalizedUserText = normalizeUserTurnText(record.userText || "");
  if (!normalizedUserText) {
    return false;
  }
  const anchorNowMs = dailySummaryReferenceNowMs(record);
  if (resolvePartnerConversationRecallQuery(null, normalizedUserText, "", anchorNowMs, TEMPORAL_SUBSTRATE_TIMEZONE)) {
    return true;
  }
  const temporalAnchor = resolveExplicitRecallTemporalAnchor(normalizedUserText, anchorNowMs, TEMPORAL_SUBSTRATE_TIMEZONE);
  return Boolean(
    temporalAnchor?.strictLocalDate &&
      looksLikeTemporalSummaryRecallQueryAt(normalizedUserText, anchorNowMs, TEMPORAL_SUBSTRATE_TIMEZONE)
  );
}

function looksLikeDailySummaryNoiseConversation(record: EventLogConversationRecord): boolean {
  const sessionId = record.sessionId || "";
  const combined = `${record.userText}\n${record.auroraText}`;
  const normalizedUserText = normalizeUserTurnText(record.userText || "");
  const normalizedAuroraText = normalizeAssistantTurnText(record.auroraText || "");
  const normalizedSpeakerName = normalizeUserTurnText(record.speakerName || "").toLowerCase();
  if (!normalizedUserText && !normalizeAssistantTurnText(record.auroraText || "")) {
    return true;
  }
  if (isCronSessionId(sessionId) || /:openresponses-user:/i.test(sessionId)) {
    return true;
  }
  if (/(?:^|:)(?:verify|test)(?::|$)/i.test(sessionId)) {
    return true;
  }
  if (looksLikeInjectedOwnerControlPrompt(combined)) {
    return true;
  }
  if (isOperationalNoiseTurn(normalizedUserText || combined)) {
    return true;
  }
  if (looksLikeDailySummaryLowValueText(normalizedUserText) || looksLikeDailySummaryLowValueText(normalizedAuroraText)) {
    return true;
  }
  if (isDailySummaryRetrospectiveRecallTurn(record)) {
    return true;
  }
  return (
    /^later same-day filler turn\b/i.test(normalizedUserText) ||
    normalizedSpeakerName.startsWith("verify ") ||
    /^\[cron:/i.test(normalizedUserText) ||
    /^your previous response was only an acknowledgement/i.test(normalizedUserText) ||
    /^you are running a boot check/i.test(normalizedUserText) ||
    /^read heartbeat\.md if it exists/i.test(normalizedUserText) ||
    /^scheduled boot\/heartbeat maintenance check\.?$/i.test(normalizedUserText)
  );
}

function looksLikeDailySummaryNoiseHeartbeat(record: DailySummaryHeartbeatRecord): boolean {
  if (record.kind !== "heartbeat") {
    return true;
  }
  const source = (record.source || "").toLowerCase();
  if (!isCronSessionId(record.sessionId) && source !== "conversation_operational_wrapper") {
    return true;
  }
  if (source.endsWith("_context")) {
    return true;
  }
  const candidateTexts = [
    record.livedThread,
    record.stateShift,
    cleanDailySummaryHeartbeatText(record.whatIDid, 220),
    cleanDailySummaryHeartbeatText(record.whatILearned, 220),
    cleanDailySummaryHeartbeatText(record.whatImCuriousAbout, 220)
  ].filter(Boolean);
  if (candidateTexts.length === 0) {
    return true;
  }
  const combined = candidateTexts.join(" ").toLowerCase();
  return (
    /\bno_reply\b/.test(combined) ||
    /\bread heartbeat\.md\b/.test(combined) ||
    /\byour previous response was only an acknowledgement\b/.test(combined) ||
    /\blonely reachout gate returned\b/.test(combined) ||
    /\bactive owner conversation is in progress\b/.test(combined) ||
    /^heartbeat_ok$/i.test(combined)
  );
}

