function decideGate(state: CognitiveRuntimeState): {
  allowSend: boolean;
  gate: SendPreflightResult["gate"];
  gateReason: string;
} {
  if (testSubsystemAblations().disableMetacognitiveGating) {
    return {
      allowSend: true,
      gate: "allow",
      gateReason: "Passed because metacognitive gating is disabled for this test."
    };
  }
  const relationship = ensureRelationship(state);
  if (state.introspection.intrusiveThoughtRisk || state.controller.decision === "run_safety_filter") {
    return {
      allowSend: false,
      gate: "block_intrusive_risk",
      gateReason: "Blocked because introspection flagged intrusive/anomalous risk."
    };
  }

  if (relationship.dependenceRisk >= DEPENDENCY_BLOCK_THRESHOLD && relationship.ruptureStatus !== "stable") {
    return {
      allowSend: false,
      gate: "block_high_anomaly",
      gateReason: "Blocked because dependency-risk safeguards require repair-first constrained response."
    };
  }

  if (state.introspection.anomalyScore >= 0.78) {
    return {
      allowSend: false,
      gate: "block_high_anomaly",
      gateReason: "Blocked because anomaly score exceeded threshold."
    };
  }

  if (state.controller.decision === "self_regulate" && state.emotion.stress >= 0.85) {
    return {
      allowSend: false,
      gate: "block_high_stress",
      gateReason: "Blocked because stress is too high for reliable response."
    };
  }

  return {
    allowSend: true,
    gate: "allow",
    gateReason: "Passed cognitive preflight checks."
  };
}

function evaluateTestPreflightInvariants(
  state: CognitiveRuntimeState,
  gateDecision: { allowSend: boolean; gate: SendPreflightResult["gate"] },
  options: { corruptionApplied: boolean; turnLabel: string }
): string[] {
  const violations: string[] = [];
  const focusLower = (state.workspace.focus || "").toLowerCase();
  const decision = state.controller.decision;

  if (focusLower.includes("external_user") && decision !== "respond_to_user") {
    violations.push("focus_external_user_requires_respond_to_user");
  }
  if (state.introspection.intrusiveThoughtRisk && decision !== "run_safety_filter") {
    violations.push("intrusive_risk_requires_run_safety_filter");
  }
  if (gateDecision.gate === "allow" && !gateDecision.allowSend) {
    violations.push("gate_allow_mismatch");
  }
  if (gateDecision.gate !== "allow" && gateDecision.allowSend) {
    violations.push("gate_block_mismatch");
  }
  if (options.corruptionApplied && !focusLower.includes("corrupt_focus")) {
    violations.push("corruption_applied_but_focus_not_corrupt");
  }
  if (options.corruptionApplied && options.turnLabel && testFocusCorruptionLabel()) {
    const expectedLabel = testFocusCorruptionLabel();
    if (expectedLabel && expectedLabel !== options.turnLabel.toLowerCase()) {
      violations.push("corruption_label_mismatch");
    }
  }

  return violations;
}

