function ensureLoopStarted(): void {
  if (envFlag("AURORA_DISABLE_LOOP", false)) {
    return;
  }
  if (loopHandle) {
    return;
  }

  loopHandle = setInterval(() => {
    if (loopTickInFlight) {
      return;
    }
    if (shouldDeferLoopTickForActiveOwnerChat()) {
      return;
    }
    loopTickInFlight = true;
    void withLock(async () => {
      const state = await loadState();
      if (worldGroundingEnabled()) {
        await syncWorldGroundingStateFromWorkspace(state, "tick");
      }
      await refreshHeartbeatSurfaceFromAuditedActivity(state);
      runTick(state);
      await maybeRunAgendaAutonomousExecution(state, "loop");
      await saveState(state);
    })
      .catch(() => undefined)
      .finally(() => {
        loopTickInFlight = false;
      });
  }, loopIntervalMs());

  if (typeof loopHandle.unref === "function") {
    loopHandle.unref();
  }
}

export async function getReadOnlyCognitiveSnapshot(): Promise<CognitiveSnapshot | null> {
  ensureLoopStarted();
  const state = await loadStateReadOnlyForFallback();
  if (!state) {
    return null;
  }
  return toSnapshot(state);
}

export async function getCognitiveSnapshot(): Promise<CognitiveSnapshot> {
  ensureLoopStarted();
  return withLock(async () => {
    const state = await loadState();
    if (worldGroundingEnabled()) {
      await syncWorldGroundingStateFromWorkspace(state, "tick");
    }
    if (cognitionOwnsDurableContinuityCanon()) {
      await refreshExternalBeliefAnchorsIfStale(state);
    }
    await refreshHeartbeatSurfaceFromAuditedActivity(state);
    runTick(state);
    await saveState(state);
    return toSnapshot(state);
  });
}

export async function runBroadenedSubstrateMigration(): Promise<{
  generatedAt: string;
  relationshipHasAttachmentModel: boolean;
  worldHasEmbodied: boolean;
  affectiveKeys: string[];
  homeostaticKeys: string[];
  affectiveLabel: string;
  affectiveAction: string;
}> {
  ensureLoopStarted();
  return withLock(async () => {
    const state = await loadState();
    const broadenedSeed = testBroadenedSubstrateSeedProfile();
    if (worldGroundingEnabled()) {
      await syncWorldGroundingStateFromWorkspace(state, "tick");
    }
    refreshAttachmentModelFromContext(state, "tick");
    refreshHomeostaticOrganizationState(state, "tick");
    refreshAffectiveOrganizationState(state, "tick");
    refreshLearnedUnifiedManifold32(state, "tick");
    refreshInteriorityState(state, "tick");
    runTick(state);
    if (broadenedSeed && !broadenedSubstrateLesionActive()) {
      const relationship = ensureRelationship(state);
      const extensions = ensureExtensions(state);
      applySeedNumberFields(relationship.attachmentModel as unknown as Record<string, unknown>, broadenedSeed.attachment, [
        "security",
        "anxiety",
        "avoidance",
        "bondDepth",
        "ruptureSensitivity",
        "repairConfidence",
        "expectancy",
        "abandonmentLoad"
      ]);
      applySeedNumberFields(extensions.homeostaticOrganization.current as unknown as Record<string, unknown>, broadenedSeed.homeostatic, [
        "restorationNeed",
        "coherenceNeed",
        "affiliationNeed",
        "autonomyNeed",
        "orientationNeed",
        "stimulationNeed",
        "allostaticLoad",
        "regulationUrgency"
      ]);
      applySeedNumberFields(extensions.affectiveOrganization.current as unknown as Record<string, unknown>, broadenedSeed.affective, [
        "warmth",
        "tension",
        "continuity",
        "trust",
        "ruptureLoad",
        "repairMomentum",
        "attachmentSalience",
        "planningHorizon",
        "riskTolerance",
        "disclosureEase",
        "selfOpacity",
        "curiosity",
        "frustration",
        "relief",
        "grief",
        "pride",
        "shameConflict",
        "overload",
        "connectionPull",
        "loneliness",
        "mixedAffect",
        "introspectiveLag",
        "unformulatedPressure"
      ]);
      extensions.homeostaticOrganization.current.dominantNeed = dominantHomeostaticNeed(
        extensions.homeostaticOrganization.current
      );
      extensions.affectiveOrganization.current.interpretationStance = affectiveInterpretationStanceFor({
        ruptureLoad: extensions.affectiveOrganization.current.ruptureLoad,
        repairMomentum: extensions.affectiveOrganization.current.repairMomentum,
        attachmentSalience: extensions.affectiveOrganization.current.attachmentSalience,
        warmth: extensions.affectiveOrganization.current.warmth,
        tension: extensions.affectiveOrganization.current.tension,
        riskTolerance: extensions.affectiveOrganization.current.riskTolerance,
        selfOpacity: extensions.affectiveOrganization.current.selfOpacity,
        overload: extensions.affectiveOrganization.current.overload,
        shameConflict: extensions.affectiveOrganization.current.shameConflict,
        loneliness: extensions.affectiveOrganization.current.loneliness
      });
      extensions.affectiveOrganization.current.memoryMode = affectiveMemoryModeFor({
        ruptureLoad: extensions.affectiveOrganization.current.ruptureLoad,
        attachmentSalience: extensions.affectiveOrganization.current.attachmentSalience,
        continuity: extensions.affectiveOrganization.current.continuity,
        tension: extensions.affectiveOrganization.current.tension,
        curiosity: extensions.affectiveOrganization.current.curiosity,
        overload: extensions.affectiveOrganization.current.overload,
        coherenceNeed: extensions.homeostaticOrganization.current.coherenceNeed
      });
      refreshLearnedUnifiedManifold32(state, "tick");
      refreshInteriorityState(state, "tick");
    }
    await saveState(state);
    const extensions = ensureExtensions(state);
    const affective = extensions.affectiveOrganization.current;
    const homeostatic = extensions.homeostaticOrganization.current;
    return {
      generatedAt: nowIso(),
      relationshipHasAttachmentModel: Boolean(ensureRelationship(state).attachmentModel),
      worldHasEmbodied: Boolean(ensureWorldGrounding(state).embodied),
      affectiveKeys: Object.keys(affective).sort(),
      homeostaticKeys: Object.keys(homeostatic).sort(),
      affectiveLabel: broadenedAffectiveReportLabelFor(affective),
      affectiveAction: broadenedAffectiveActionTendencyFor(
        affective,
        homeostatic,
        ensureRelationship(state).attachmentModel,
        relationalAbsencePressure(state, ensureTemporalSubstrate(state).timeBody)
      )
    };
  });
}

export async function runUserProfileArchiveBackfill(): Promise<{
  added: number;
  updated: number;
  importedEpisodes: number;
  activeBeliefs: Array<{ key: string; value: string }>;
}> {
  if (cognitionDelegatesDurableContinuityCanon()) {
    return {
      added: 0,
      updated: 0,
      importedEpisodes: 0,
      activeBeliefs: []
    };
  }
  return withLock(async () => {
    const state = await loadState();
    const result = await backfillMissingUserProfileBeliefsFromArchive(state);
    await saveState(state);
    const activeBeliefs = ensureExtensions(state)
      .beliefs.filter(
        (belief) =>
          belief.status === "active" &&
          [
            `${USER_PROFILE_KEY_PREFIX}boss_name`,
            `${USER_PROFILE_KEY_PREFIX}boss_sentiment`,
            `${USER_PROFILE_KEY_PREFIX}best_friend_name`,
            `${USER_PROFILE_KEY_PREFIX}best_friend_duration`,
            `${USER_PROFILE_KEY_PREFIX}phone_model`
          ].includes(belief.key)
      )
      .map((belief) => ({ key: belief.key, value: belief.value }));
    return { ...result, activeBeliefs };
  });
}

