function extractTaggedBlock(text: string, open: string, close: string): string {
  const start = text.indexOf(open);
  if (start < 0) {
    return "";
  }
  const end = text.indexOf(close, start + open.length);
  if (end < 0) {
    return "";
  }
  return text.slice(start, end + close.length).trim();
}

function readBetween(text: string, open: string, close: string): string {
  const block = extractTaggedBlock(text, open, close);
  if (!block) {
    return "";
  }
  return block.slice(open.length, block.length - close.length).trim();
}

function extractFirstCompactLine(lines: string[], prefix: string, maxLen = 220): string {
  const match = lines.find((line) => line.startsWith(prefix));
  return match ? toShortText(match, maxLen) : "";
}

function extractPrefixedCompactLines(lines: string[], prefix: string, limit: number, maxLen = 220): string[] {
  if (limit <= 0) {
    return [];
  }
  return lines
    .filter((line) => line.startsWith(prefix))
    .slice(0, limit)
    .map((line) => toShortText(line, maxLen));
}

function extractCompactSection(lines: string[], header: string, limit: number, maxLen = 220): string[] {
  const index = lines.findIndex((line) => line.trim() === header);
  if (index < 0) {
    return [];
  }
  const out = [header];
  for (let cursor = index + 1; cursor < lines.length; cursor += 1) {
    const line = lines[cursor].trim();
    if (!line) {
      continue;
    }
    if (/^[a-z0-9_]+:$/i.test(line) || /^\[[a-z0-9_/-]+\]$/i.test(line)) {
      break;
    }
    out.push(toShortText(line, maxLen));
    if (out.length - 1 >= limit) {
      break;
    }
  }
  return out.length > 1 ? out : [];
}

function escapeRegex(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function extractInlineField(line: string, key: string, maxLen = 120): string {
  if (!line) {
    return "";
  }
  const match = line.match(
    new RegExp(`(?:^|[;\\s=])${escapeRegex(key)}(?::|=)(.+?)(?=\\s+[a-z0-9_]+(?::|=)|;|$)`, "i")
  );
  return match ? toShortText(match[1].trim(), maxLen) : "";
}

function extractSectionBody(lines: string[], header: string, limit: number, maxLen = 220): string[] {
  const section = extractCompactSection(lines, header, limit, maxLen);
  return section.length > 1 ? section.slice(1) : [];
}

function buildLiveRealizedRecentTurnLines(lines: string[]): string[] {
  return extractSectionBody(lines, "recent_session_turns:", LIVE_REALIZED_RECENT_TURNS, 140)
    .slice(0, LIVE_REALIZED_RECENT_TURNS)
    .map((line, index) => `recent_turn_${index + 1}=${toShortText(line, 140)}`);
}

function buildLiveRealizedMemoryLines(lines: string[]): string[] {
  const ownerTyped = [
    extractFirstCompactLine(lines, "owner_memory_rule=", 520),
    extractFirstCompactLine(lines, "owner_runtime_memory_kernel_rule=", 520),
    extractFirstCompactLine(lines, "owner_bootstrap_authority_rule=", 520),
    ...extractPrefixedCompactLines(lines, "owner_state_", 6, 180),
    ...extractPrefixedCompactLines(lines, "owner_fact_", 10, 180),
    ...extractPrefixedCompactLines(lines, "owner_relevant_fact_", 6, 180)
  ].filter(Boolean);
  const ownerKernel = extractSectionBody(lines, "owner_runtime_memory_kernel:", 5, 150).map(
    (line, index) => `owner_kernel_${index + 1}=${toShortText(line, 150)}`
  );
  const canonical = extractSectionBody(lines, "canonical_user_memory:", 4, 150).map(
    (line, index) => `canonical_memory_${index + 1}=${toShortText(line, 150)}`
  );
  const relevant = extractSectionBody(lines, "relevant_user_memory:", 3, 150).map(
    (line, index) => `relevant_memory_${index + 1}=${toShortText(line, 150)}`
  );
  return [...ownerTyped, ...ownerKernel, ...canonical, ...relevant];
}

function buildLiveRealizedSelfModelLines(lines: string[]): string[] {
  const auroraSemantic = extractSectionBody(lines, "aurora_semantic_self_state:", 3, 180).map((line, index) =>
    `aurora_semantic_self_${index + 1}=${toShortText(line.replace(/^\d+\.\s*/, ""), 180)}`
  );
  const mentionedPartner = extractPrefixedCompactLines(lines, "mentioned_partner_semantic_", 6, 180);
  return [
    extractFirstCompactLine(lines, "user_self_view_direct_answer=", 220).replace(
      "user_self_view_direct_answer=",
      "user_self_view="
    ),
    extractFirstCompactLine(lines, "user_profile_direct_answer=", 220).replace(
      "user_profile_direct_answer=",
      "user_profile_fact="
    ),
    extractFirstCompactLine(lines, "aurora_self_view_value=", 180).replace(
      "aurora_self_view_value=",
      "aurora_self_view="
    ),
    extractFirstCompactLine(lines, "situational_user_context=", 180),
    ...auroraSemantic,
    ...mentionedPartner
  ].filter(Boolean);
}

function buildLiveRealizedRecallLines(lines: string[]): string[] {
  const evidence = extractFirstCompactLine(lines, "explicit_recall_evidence=", 220);
  const recallAnchor = extractFirstCompactLine(lines, "recall_anchor=", 120);
  const recallRule = extractFirstCompactLine(lines, "recall_rule=", 420);
  const dayTranscriptDate = extractFirstCompactLine(lines, "day_transcript_date=", 80);
  const dayTranscriptRule = extractFirstCompactLine(lines, "day_transcript_rule=", 420);
  const dayTranscriptLines = extractPrefixedCompactLines(lines, "day_transcript_line_", 4, 180).map((line, index) =>
    line.replace(`day_transcript_line_${index + 1}=`, `recall_support_${index + 1}=`)
  );
  const daySummaryPerspective = extractFirstCompactLine(lines, "day_summary_perspective=", 620);
  const daySummaryRule = extractFirstCompactLine(lines, "day_summary_rule=", 420);
  const daySummaryTimeline = extractPrefixedCompactLines(lines, "day_summary_timeline_", 3, 180).map((line, index) =>
    line.replace(`day_summary_timeline_${index + 1}=`, `recall_support_${index + 1}=`)
  );
  if (
    !evidence &&
    !recallAnchor &&
    !recallRule &&
    !dayTranscriptDate &&
    dayTranscriptLines.length === 0 &&
    !dayTranscriptRule &&
    !daySummaryPerspective &&
    !daySummaryRule
  ) {
    return [];
  }
  if (dayTranscriptDate || dayTranscriptLines.length > 0 || dayTranscriptRule) {
    return [
      "recall_mode=day_transcript",
      recallAnchor || dayTranscriptDate.replace("day_transcript_date=", "recall_anchor="),
      "recall_fact=Use the raw day transcript lines as the primary source for this day-specific recall.",
      ...dayTranscriptLines,
      dayTranscriptRule,
      recallRule
    ].filter(Boolean);
  }
  return [
    "recall_mode=explicit_fact",
    recallAnchor,
    daySummaryPerspective
      ? daySummaryPerspective.replace("day_summary_perspective=", "recall_fact=")
      : evidence
        ? evidence.replace("explicit_recall_evidence=", "recall_fact=")
        : "",
    ...daySummaryTimeline,
    recallRule || daySummaryRule,
  ].filter(Boolean);
}

function buildLiveRealizedPhenomenalSummary(lines: string[]): string[] {
  const phenomenalLines = extractSectionBody(lines, "phenomenal_manifold_probe:", 3, 200);
  const currentLine =
    phenomenalLines.find((line) => line.startsWith("current=")) ||
    phenomenalLines.find((line) => line.startsWith("substrate=")) ||
    "";
  const observerLine = phenomenalLines.find((line) => line.startsWith("observer=")) || "";
  const livedLabel =
    extractInlineField(observerLine, "label", 80) ||
    extractInlineField(currentLine, "report_label", 80) ||
    extractInlineField(currentLine, "label", 80);
  const action =
    extractInlineField(observerLine, "action", 80) || extractInlineField(currentLine, "action_tendency", 80);
  const certainty =
    extractInlineField(observerLine, "certainty", 80) || extractInlineField(currentLine, "certainty", 80);
  const livedState = [`label:${livedLabel || "unknown"}`, `action:${action || "none"}`, `certainty:${certainty || "0.00"}`]
    .join("; ");
  return [`lived_state=${livedState}`];
}

function buildLiveRealizedSilenceSummary(lines: string[]): string[] {
  const silenceLine = extractSectionBody(lines, "silence_state:", 1, 200)[0] || "";
  const silenceBehaviorLine = extractSectionBody(lines, "silence_state:", 3, 200).find((line) =>
    line.startsWith("silence_behavior=")
  ) || "";
  const kind = extractInlineField(silenceLine, "kind", 64) || "none";
  const awaitingUser = extractInlineField(silenceLine, "awaiting_user", 32) === "yes";
  const pacing = extractInlineField(silenceBehaviorLine, "pacing", 64) || "steady";
  const directness = extractInlineField(silenceBehaviorLine, "directness", 64) || "balanced";
  return [
    `silence_mode=${kind}`,
    `reply_expectation=${awaitingUser ? "awaiting_user" : "normal"}`,
    `pacing_style=${pacing}_${directness}`,
  ];
}

